from config import Config
from logger import logger

_DB_CRED_FERNET = None


def _persist_db_cred_key(key: str) -> None:
    """Append the generated CATMAN_DB_CRED_KEY to .env so it survives restarts."""
    try:
        env_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".env")
        lines: list[str] = []
        if os.path.exists(env_path):
            with open(env_path, "r", encoding="utf-8") as f:
                lines = f.readlines()
        lines.append(f"\nCATMAN_DB_CRED_KEY={key}\n")
        with open(env_path, "w", encoding="utf-8") as f:
            f.writelines(lines)
    except Exception:
        logger.exception("failed to persist CATMAN_DB_CRED_KEY")


def _get_db_cred_fernet():
    """Fernet cipher used to encrypt/decrypt per-company Postgres passwords
    stored in public.companies.db_password_enc. Key lives in CATMAN_DB_CRED_KEY
    (.env); generated once on first use if missing."""
    global _DB_CRED_FERNET
    if _DB_CRED_FERNET is not None:
        return _DB_CRED_FERNET
    from cryptography.fernet import Fernet

    key = (os.getenv("CATMAN_DB_CRED_KEY") or "").strip()
    if not key:
        key = Fernet.generate_key().decode("ascii")
        _persist_db_cred_key(key)
        os.environ["CATMAN_DB_CRED_KEY"] = key
    _DB_CRED_FERNET = Fernet(key.encode("ascii"))
    return _DB_CRED_FERNET


def _resolve_packaging_goods_item_index(
    items: list[Any],
    pack_comment: str,
    line_key_raw: Any,
) -> int:
    """Індекс позиції в orders.data.items для рядка journal goods; fallback за product_name ↔ comment."""
    n = len(items)
    parsed = -1
    if line_key_raw is not None and str(line_key_raw).strip() != "":
        try:
            parsed = int(str(line_key_raw).strip())
        except (TypeError, ValueError):
            parsed = -1
    if 0 <= parsed < n:
        return parsed
    pc = str(pack_comment or "").strip().lower()
    if pc:
        for i, it in enumerate(items):
            if not isinstance(it, dict):
                continue
            pn = str(it.get("product_name") or "").strip().lower()
            if not pn:
                continue
            if pn == pc or pn in pc or pc in pn:
                return i
    if n == 1:
        return 0
    return -1


_CACHE_MISS = object()  # sentinel — a cached value can legitimately be [] / None / False


class DataManager:
    """
    Data access layer.

    Supports two modes:
    - HTTP client to a backend API (default)
    - Direct Postgres mode (when DATABASE_URL / CATMAN_DATABASE_URL is set)

    Goal for now: allow superadmin to log in and bootstrap data locally even
    without a FastAPI backend.
    """

    def __init__(self, base_url: str | None = None, timeout_s: float = 2.0):
        self.base_url = (
            base_url
            or getattr(Config, "CATMAN_API_BASE_URL", "")
            or "http://127.0.0.1:8000"
        ).rstrip("/")
        self._http = httpx.Client(timeout=timeout_s)
        self._pg_dsn = (
            os.getenv("CATMAN_DATABASE_URL")
            or os.getenv("DATABASE_URL")
            or os.getenv("POSTGRES_DSN")
            or ""
        ).strip()
        # General connection — companies, managers, licensing and other shared
        # cross-company tables. Always the same physical database (CATMAN_DATABASE_URL).
        # Cached per-thread in _general_pg_conns for the same reason as
        # _company_conns below (see _general_pg()). _general_pg_conn keeps
        # pointing at the most-recently-created one, kept only so
        # _ensure_general_schema()/the tmp_dm migration helper can still read
        # a single connection attribute without a signature change.
        self._general_pg_conn: psycopg.Connection | None = None
        self._general_pg_conns: dict[int, psycopg.Connection] = {}
        self._general_pg_conns_last_used: dict[int, float] = {}
        self._general_schema_ready: bool = False
        # Per-company connections — each company has its OWN dedicated Postgres
        # database (connection info stored in public.companies on the general DB).
        # Cached by "company_id::manager_id::t<thread-id>" so switching companies
        # within one process is cheap AND concurrent background threads (tab
        # rebuilds via asyncio.to_thread) never share a single psycopg
        # connection — sharing one across threads let their queries interleave
        # on the same socket and hang indefinitely under load (see _pg()).
        self._company_conns: dict[str, psycopg.Connection] = {}
        # Last-use timestamp per _pg() cache key — lets us cheaply detect a
        # connection the server silently dropped while idle (cloud Postgres
        # idle timeout, laptop sleep/resume, network blip) before handing it
        # to a caller, instead of the caller's first query blowing up with
        # "server closed the connection unexpectedly".
        self._company_conns_last_used: dict[str, float] = {}
        # Guards _ensure_company_schema/_backfill_owner_tables so only the
        # FIRST thread to open a connection for a given company runs the DDL
        # bootstrap batch — every other concurrent background thread (tab
        # rebuilds via asyncio.to_thread, see _company_conns above) just gets
        # its own connection without re-running the same ALTER/CREATE INDEX
        # statements. Without this, several threads opening their first
        # per-thread connection at once (e.g. multiple views loading right
        # after login) each ran the full DDL batch concurrently and Postgres
        # deadlocked on the shared tables (observed as repeated
        # DeadlockDetected errors + very slow/hung startup).
        self._schema_bootstrap_lock = threading.Lock()
        self._schema_bootstrapped_companies: set[str] = set()
        self._timeout_s = float(timeout_s)
        # Active company — set via set_company() after login. self._pg() resolves
        # to this company's own dedicated database.
        self._active_company_id: str = ""
        self._active_company_name: str = ""
        # Active manager — only meaningful for Компанія-Локал (multiple
        # managers sharing one company_id, each with their OWN isolated local
        # cluster; see manager_local_db / _resolve_company_dsn).
        self._active_manager_id: str = ""
        # Session-scoped in-memory cache for expensive, rarely-changing queries.
        # Keyed by arbitrary string; values never expire during the process lifetime.
        self._session_cache: dict = {}

    def _cached_list(self, cache_key: str, force_refresh: bool, fetch_fn):
        """Session-scoped cache-aside helper for expensive reference-data
        reads (products/suppliers/packaging/etc). Values persist for the
        life of this DataManager instance and are cleared explicitly by the
        matching invalidate_*_cache() call after a write — not TTL-based, so
        there's no staleness window, but every write path touching this data
        MUST call the matching invalidator (see invalidate_products_cache,
        invalidate_suppliers_cache, invalidate_packaging_cache).

        Added because, over a remote (non-localhost) Postgres connection,
        re-fetching the same reference list on every tab switch/dialog open
        costs a real network round trip each time instead of a free local
        socket call."""
        if not force_refresh:
            cached = self._session_cache.get(cache_key, _CACHE_MISS)
            if cached is not _CACHE_MISS:
                return cached
        value = fetch_fn()
        self._session_cache[cache_key] = value
        return value

    def _invalidate_mgr_scope_cache(self, company_id: str) -> None:
        """Clear cached _get_manager_visible_scope_context() results for this
        company. That context bakes in entity_owners-derived id sets (orders,
        packaging, schedule groups) at compute time, so anything created
        after it was cached stays invisible to its own creator until this is
        cleared — otherwise only an app restart (fresh, empty cache) fixes it."""
        cid = str(company_id or "").strip()
        if not cid:
            return
        prefix = f"mgr_scope_{cid}_"
        for k in [k for k in self._session_cache if k.startswith(prefix)]:
            self._session_cache.pop(k, None)

    def _invalidate_product_scope_cache(self, company_id: str) -> None:
        """Clear manager-scope AND get_products() cache entries for this
        company after add/update/delete."""
        cid = str(company_id or "").strip()
        prefix = f"mgr_scope_{cid}_"
        stale = [
            k
            for k in self._session_cache
            if k.startswith(prefix) or k.startswith(f"products_{cid}_")
        ]
        for k in stale:
            self._session_cache.pop(k, None)

    def invalidate_products_cache(self, company_id: str) -> None:
        """Full product-related session-cache flush for this company.

        Clears both manager-scope entries (mgr_scope_*) and the catalog-nodes
        snapshot (catalog_nodes_*) so that the very next get_products() call
        rebuilds everything from the database — even when called immediately
        after add_product() without a restart.
        """
        cid = str(company_id or "").strip()
        if not cid:
            return
        stale = [
            k
            for k in list(self._session_cache)
            if k.startswith(f"mgr_scope_{cid}_")
            or k.startswith(f"catalog_nodes_{cid}")
            or k.startswith(f"products_{cid}_")
        ]
        for k in stale:
            self._session_cache.pop(k, None)

    def invalidate_suppliers_cache(self, company_id: str) -> None:
        """Clear the cached get_suppliers() result for this company."""
        cid = str(company_id or "").strip()
        if not cid:
            return
        prefix = f"suppliers_{cid}_"
        for k in [k for k in self._session_cache if k.startswith(prefix)]:
            self._session_cache.pop(k, None)

    def invalidate_packaging_cache(self, company_id: str) -> None:
        """Clear the cached get_packaging() result for this company.

        Also clears mgr_scope_* — _get_manager_visible_scope_context() caches
        packaging_ids (derived partly from entity_owners), so without this a
        newly-created packaging stays invisible to its creator until the
        cached scope context expires (i.e. an app restart)."""
        cid = str(company_id or "").strip()
        if not cid:
            return
        stale = [
            k
            for k in self._session_cache
            if k.startswith(f"packaging_{cid}_") or k.startswith(f"mgr_scope_{cid}_")
        ]
        for k in stale:
            self._session_cache.pop(k, None)

    def invalidate_categories_cache(self, company_id: str) -> None:
        """Clear the cached get_accessible_categories() result for this
        company (also covers catalog_nodes_* since a catalog change usually
        means the node tree changed too)."""
        cid = str(company_id or "").strip()
        if not cid:
            return
        stale = [
            k
            for k in self._session_cache
            if k.startswith(f"acc_categories_{cid}_")
            or k.startswith(f"catalog_nodes_{cid}")
        ]
        for k in stale:
            self._session_cache.pop(k, None)

    def close(self) -> None:
        with contextlib.suppress(Exception):
            self._http.close()
        for _conn in list(self._general_pg_conns.values()):
            with contextlib.suppress(Exception):
                _conn.close()
        self._general_pg_conns.clear()
        self._general_pg_conn = None
        for _conn in list(self._company_conns.values()):
            with contextlib.suppress(Exception):
                _conn.close()
        self._company_conns.clear()

    # ----------------- mode -----------------
    def _use_postgres(self) -> bool:
        return bool(self._pg_dsn)

    @staticmethod
    def _encrypt_db_password(plain: str) -> str:
        plain = str(plain or "")
        if not plain:
            return ""
        return _get_db_cred_fernet().encrypt(plain.encode("utf-8")).decode("ascii")

    @staticmethod
    def _decrypt_db_password(enc: str) -> str:
        enc = str(enc or "").strip()
        if not enc:
            return ""
        try:
            return _get_db_cred_fernet().decrypt(enc.encode("ascii")).decode("utf-8")
        except Exception:
            logger.exception("failed to decrypt company db password")
            return ""

    @staticmethod
    def _write_backup_manifest(dump_file: str, data: dict) -> None:
        """Write a small sidecar JSON next to a .dump file (same basename,
        .json extension) so import can show a friendly "this is a backup of
        X from Y" check instead of a raw Postgres error. Best-effort — a
        missing/unreadable manifest must never block restore."""
        manifest_path = os.path.splitext(dump_file)[0] + ".json"
        try:
            with open(manifest_path, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception:
            logger.exception("failed to write backup manifest for %s", dump_file)

    @staticmethod
    def _read_backup_manifest(dump_file: str) -> dict | None:
        manifest_path = os.path.splitext(dump_file)[0] + ".json"
        try:
            with open(manifest_path, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None

    @staticmethod
    def _build_dsn(
        host: str, port: Any, dbname: str, user: str, password: str, sslmode: str = ""
    ) -> str:
        from urllib.parse import quote_plus

        host = str(host or "").strip() or "127.0.0.1"
        try:
            port_i = int(port) if port else 5432
        except (TypeError, ValueError):
            port_i = 5432
        user_q = quote_plus(str(user or "").strip() or "postgres")
        pw_q = quote_plus(str(password or ""))
        dsn = f"postgresql://{user_q}:{pw_q}@{host}:{port_i}/{dbname}"
        if sslmode:
            dsn += f"?sslmode={sslmode}"
        return dsn

    def get_general_db_location(self) -> dict:
        """Live host/port/db_name/is_local for the GENERAL database, parsed
        straight from the DSN actually in use (self._pg_dsn) — never a
        separately stored/stale copy, so it always matches reality whether
        `.env` or the superadmin UI was the last thing to change it. The
        GSM parser's own tables live in this same database (see
        _ensure_general_schema), so this location covers it too."""
        from urllib.parse import urlparse

        dsn = str(self._pg_dsn or "").strip()
        if not dsn:
            return {"host": "", "port": 0, "db_name": "", "is_local": True}
        parsed = urlparse(dsn)
        host = parsed.hostname or "127.0.0.1"
        return {
            "host": host,
            "port": parsed.port or 5432,
            "db_name": (parsed.path or "").lstrip("/"),
            "is_local": host in ("127.0.0.1", "localhost", "::1"),
        }

    def _general_pg(self) -> psycopg.Connection:
        """Connection to the GENERAL database — companies, managers, licensing
        and other shared cross-company tables (CATMAN_DATABASE_URL).

        Cached per-thread (same reasoning as _pg()): GSM Parser lives
        entirely on this database and runs frequent concurrent background
        sync/scrape queries via asyncio.to_thread — a single connection
        shared across those threads let their queries interleave on one
        socket and hang under load instead of just running one after another.
        """
        if not self._use_postgres():
            raise RuntimeError("Postgres mode is not enabled (missing DATABASE_URL)")
        tid = threading.get_ident()
        conn = self._general_pg_conns.get(tid)
        if conn is not None and not conn.closed:
            # See _pg()'s matching check — a connection idle long enough may
            # have been silently dropped server-side.
            last_used = self._general_pg_conns_last_used.get(tid, 0.0)
            if (time.monotonic() - last_used) > 30.0:
                try:
                    conn.execute("SELECT 1")
                except Exception:
                    with contextlib.suppress(Exception):
                        conn.close()
                    conn = None
                    self._general_pg_conns.pop(tid, None)
        if conn is None or conn.closed:
            conn = psycopg.connect(
                self._pg_dsn,
                autocommit=True,
                row_factory=dict_row,
                connect_timeout=10,
            )
            self._general_pg_conns[tid] = conn
            # Kept in sync so _ensure_general_schema() (and the tmp_dm
            # migration helper) can keep reading a single attribute — schema
            # bootstrap is idempotent DDL, so it's harmless if two threads'
            # first connections race to set this.
            self._general_pg_conn = conn
            self._general_schema_ready = False
        if not self._general_schema_ready:
            try:
                self._ensure_general_schema()
                self._general_schema_ready = True
            except Exception:
                logger.exception("_ensure_general_schema failed")
        self._general_pg_conns_last_used[tid] = time.monotonic()
        return conn

    def _evict_general_connections(self) -> None:
        """Close and forget every cached general-DB connection (across every
        thread). Must run whenever the general DB's DSN changes (e.g. Local
        <-> VPS switch, restore-from-backup) — otherwise some other thread's
        already-cached connection keeps silently pointing at the old
        database instead of picking up the new one."""
        for conn in list(self._general_pg_conns.values()):
            with contextlib.suppress(Exception):
                conn.close()
        self._general_pg_conns.clear()
        self._general_pg_conn = None
        self._general_schema_ready = False

    def _resolve_manager_local_dsn(self, manager_id: str) -> str | None:
        """If this manager has their OWN local Postgres cluster registered
        (manager_local_db — populated only by merge_managers_into_company for
        Компанія-Локал), return its DSN. Returns None otherwise, so callers
        fall back to the company-row-based resolution unchanged."""
        mid = str(manager_id or "").strip()
        if not mid:
            return None
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT db_host, db_port, db_name, db_user, db_password_enc "
                "FROM public.manager_local_db WHERE manager_id=%s",
                (mid,),
            )
            row = cur.fetchone()
        if not row:
            return None
        password = self._decrypt_db_password(row.get("db_password_enc") or "")
        return self._build_dsn(
            row.get("db_host") or "127.0.0.1",
            row.get("db_port") or 5432,
            row["db_name"],
            row.get("db_user") or "postgres",
            password,
        )

    def _resolve_company_dsn(self, company_id: str) -> str:
        """Look up company_id's own dedicated database connection info from
        public.companies (general DB) and build a DSN for it.

        If the ACTIVE MANAGER (self._active_manager_id) has their own
        registered local cluster (manager_local_db), that takes priority —
        needed for Компанія-Локал, where several managers share one
        company_id for login/billing but each keeps their OWN isolated local
        Postgres on their OWN machine ("127.0.0.1" only means something on
        the machine it's running on, so one companies-row DSN can't describe
        everyone). Falls back to the company row exactly as before when no
        such per-manager override exists (VPS companies, solo individuals).
        """
        cid = str(company_id or "").strip()
        if not cid:
            raise RuntimeError("No active company selected")
        manager_dsn = self._resolve_manager_local_dsn(self._active_manager_id)
        if manager_dsn:
            return manager_dsn
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT db_host, db_port, db_name, db_user, db_password_enc, db_sslmode, "
                "db_pending FROM public.companies WHERE id=%s",
                (cid,),
            )
            row = cur.fetchone()
        if row and bool(row.get("db_pending")):
            raise RuntimeError(
                "Компанія очікує на адресу VPS — суперадмін ще не вказав, де "
                "зберігати дані цієї компанії. Збереження недоступне, поки "
                "адресу не буде вказано."
            )
        if not row or not str(row.get("db_name") or "").strip():
            raise RuntimeError(
                f"Company {cid} has no dedicated database configured (db_name empty)"
            )
        password = self._decrypt_db_password(row.get("db_password_enc") or "")
        return self._build_dsn(
            row.get("db_host") or "127.0.0.1",
            row.get("db_port") or 5432,
            row["db_name"],
            row.get("db_user") or "postgres",
            password,
            row.get("db_sslmode") or "",
        )

    def set_company(
        self, company_id: str, company_name: str = "", manager_id: str = ""
    ) -> None:
        """
        Set the active company (call after login or when superadmin switches company).

        The actual connection to this company's own dedicated database is opened
        lazily by _pg() (and cached in self._company_conns per company+thread).

        Pass empty string to reset to "no active company" (superadmin general-only mode).

        manager_id should be the logged-in user's OWN manager id (their
        natural "this is my account" login, not superadmin/admin switching
        into someone else's company) — it only has an effect when that
        manager has a manager_local_db row (Компанія-Локал merge), otherwise
        resolution is identical to before this parameter existed.
        """
        cid = str(company_id or "").strip()
        self._active_company_id = cid
        self._active_manager_id = str(manager_id or "").strip()
        if company_name:
            self._active_company_name = str(company_name).strip()
        elif not cid:
            self._active_company_name = ""
        logger.info("[DB] active company -> %s", cid or "(none)")

    def _pg(self) -> psycopg.Connection:
        """Connection to the ACTIVE COMPANY's own dedicated database.

        Cached per (company, manager, thread). A single shared connection
        used to be reused across every thread — but background tab rebuilds
        (Home/Orders/etc.) run concurrently via asyncio.to_thread, and a
        psycopg/libpq connection isn't safe for concurrent queries from
        multiple threads at once: interleaved requests on the same socket
        could desync the wire protocol and leave a thread blocked forever
        waiting on a response that was already consumed elsewhere — this is
        what surfaced as "build_sync timed out after 60s" under load (e.g.
        while saving triggers several background refreshes at once). One
        connection per thread removes the sharing entirely.
        """
        if not self._use_postgres():
            raise RuntimeError("Postgres mode is not enabled (missing DATABASE_URL)")
        cid = self._active_company_id
        if not cid:
            raise RuntimeError("No active company selected — call set_company() first")
        # Компанія-Локал: several managers share one company_id but each has
        # their own isolated cluster, so the cache key must disambiguate them.
        tid = threading.get_ident()
        cache_key = (
            f"{cid}::{self._active_manager_id}::t{tid}"
            if self._active_manager_id
            else f"{cid}::t{tid}"
        )
        conn = self._company_conns.get(cache_key)
        if conn is not None and not conn.closed:
            # A connection idle for a while may have been silently dropped by
            # the server (idle timeout, machine sleep/resume) while psycopg's
            # own `.closed` flag still reads False — that only flips true
            # *after* a query fails on it. Ping once before handing out a
            # connection that's been sitting unused, so that failure (and the
            # reconnect) happens here instead of surfacing as an unhandled
            # OperationalError in whatever UI action runs the next query.
            last_used = self._company_conns_last_used.get(cache_key, 0.0)
            if (time.monotonic() - last_used) > 30.0:
                try:
                    conn.execute("SELECT 1")
                except Exception:
                    with contextlib.suppress(Exception):
                        conn.close()
                    conn = None
                    self._company_conns.pop(cache_key, None)
        if conn is None or conn.closed:
            dsn = self._resolve_company_dsn(cid)
            conn = psycopg.connect(dsn, autocommit=True, row_factory=dict_row)
            self._company_conns[cache_key] = conn
            with self._schema_bootstrap_lock:
                needs_bootstrap = cid not in self._schema_bootstrapped_companies
                if needs_bootstrap:
                    self._schema_bootstrapped_companies.add(cid)
            if needs_bootstrap:
                try:
                    self._ensure_company_schema(conn)
                    self._backfill_owner_tables(conn)
                except Exception:
                    logger.exception(
                        "company schema bootstrap failed for cid=%s (later DDL may be skipped)",
                        cid,
                    )
                    with self._schema_bootstrap_lock:
                        self._schema_bootstrapped_companies.discard(cid)
        self._company_conns_last_used[cache_key] = time.monotonic()
        return conn

    def _evict_company_connections(self, company_id: str) -> None:
        """Close and forget every cached connection for a company — across
        every manager/thread variant of the _pg() cache key. Must be called
        before DROP DATABASE (Postgres refuses with open sessions) and after
        repointing a company at a new DSN/host, otherwise a stale connection
        to the old database lingers in some other thread's cache slot."""
        cid = str(company_id or "").strip()
        if not cid:
            return
        stale_keys = [
            k
            for k in list(self._company_conns.keys())
            if k == cid or k.startswith(f"{cid}::")
        ]
        for k in stale_keys:
            conn = self._company_conns.pop(k, None)
            if conn is not None:
                with contextlib.suppress(Exception):
                    conn.close()
        # Force the next _pg() call to re-run schema bootstrap: after
        # DROP DATABASE or repointing to a new DSN/host, the physical target
        # is different (or gone) and can't be assumed already-bootstrapped.
        with self._schema_bootstrap_lock:
            self._schema_bootstrapped_companies.discard(cid)

    @staticmethod
    def _ddl_packaging_supply_tables() -> list[str]:
        """
        Packaging supply journal — standalone so we can replay if core bootstrap partly failed.
        """
        return [
            """
            CREATE TABLE IF NOT EXISTS packaging_supply_contexts (
              id character varying NOT NULL,
              company_id character varying NOT NULL,
              region_id character varying NOT NULL,
              packaging_id character varying NOT NULL,
              packaging_supplier_id character varying NOT NULL DEFAULT '',
              goods_supplier_id character varying NOT NULL DEFAULT '',
              linked_product_ids jsonb NOT NULL DEFAULT '[]'::jsonb,
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (id),
              UNIQUE (company_id, region_id, packaging_id, goods_supplier_id)
            );
            """,
            "CREATE INDEX IF NOT EXISTS ix_packaging_supply_ctx_company_region ON packaging_supply_contexts (company_id, region_id);",
            "CREATE INDEX IF NOT EXISTS ix_packaging_supply_ctx_packaging ON packaging_supply_contexts (packaging_id);",
            """
            CREATE TABLE IF NOT EXISTS packaging_supply_openings (
              context_id character varying NOT NULL,
              stock_packaging_supplier_qty numeric NOT NULL DEFAULT 0,
              stock_goods_supplier_qty numeric NOT NULL DEFAULT 0,
              balance_amount numeric NOT NULL DEFAULT 0,
              balance_currency character varying(8) NOT NULL DEFAULT 'USD',
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (context_id)
            );
            """,
            """
            CREATE TABLE IF NOT EXISTS packaging_supply_orders (
              id character varying NOT NULL,
              context_id character varying NOT NULL,
              seq_no integer NOT NULL,
              order_date date,
              qty_ordered numeric NOT NULL DEFAULT 0,
              status character varying(32) NOT NULL DEFAULT 'production',
              cost_amount numeric,
              paid_amount numeric NOT NULL DEFAULT 0,
              shipped_goods_supplier_qty numeric NOT NULL DEFAULT 0,
              zp_1c text,
              invoice_no text,
              comment text,
              row_kind character varying(32) NOT NULL DEFAULT 'supply',
              linked_order_id character varying,
              linked_order_line_key character varying,
              created_at timestamp without time zone NOT NULL,
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (id)
            );
            """,
            "            CREATE INDEX IF NOT EXISTS ix_packaging_supply_orders_ctx ON packaging_supply_orders (context_id);",
            "CREATE INDEX IF NOT EXISTS ix_packaging_supply_orders_date ON packaging_supply_orders (order_date);",
            "ALTER TABLE packaging_supply_openings ADD COLUMN IF NOT EXISTS opening_shipped_goods_qty numeric NOT NULL DEFAULT 0;",
            "ALTER TABLE packaging_supply_openings ADD COLUMN IF NOT EXISTS balance_paid_amount numeric NOT NULL DEFAULT 0;",
            "ALTER TABLE packaging_supply_openings ADD COLUMN IF NOT EXISTS comment text NOT NULL DEFAULT '';",
        ]

    def _ensure_packaging_supply_tables(self) -> None:
        if not self._use_postgres():
            return
        conn = self._pg()
        try:
            with conn.cursor() as cur:
                for stmt in self._ddl_packaging_supply_tables():
                    cur.execute(stmt)
        except Exception:
            logger.exception("ensure_packaging_supply_tables failed")
            raise

    def _pg_with_packaging_supply_schema(self):
        conn = self._pg()
        self._ensure_packaging_supply_tables()
        return conn

    def _ensure_general_schema(self) -> None:
        """
        Bootstrap the GENERAL database: companies/managers plus other shared,
        cross-company tables (app update policy, GSM parser dataset, ...).
        Runs once per process against the general connection (_general_pg()).
        """
        conn = self._general_pg_conn
        if conn is None:
            return
        ddl = [
            # Add meta to companies for profile/extensions without new tables
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS meta jsonb NOT NULL DEFAULT '{}'::jsonb;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS updated_at timestamp without time zone;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS schema_name character varying;",
            # Per-company dedicated database connection info (each company = own Postgres DB).
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_host character varying;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_port integer;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_name character varying;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_user character varying;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_password_enc text;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_sslmode character varying;",
            # Account kind / storage mode / per-company tariff (user-count limit).
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS account_kind character varying NOT NULL DEFAULT 'company';",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS storage_mode character varying NOT NULL DEFAULT 'vps';",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS max_users integer NOT NULL DEFAULT 0;",
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS is_blocked boolean NOT NULL DEFAULT FALSE;",
            # VPS company created with no server address yet chosen at creation
            # time (superadmin picks the dedicated host later) — while pending,
            # db_host/db_port/db_name/db_user stay empty and _resolve_company_dsn
            # refuses to connect, so nothing can be saved for this company.
            "ALTER TABLE public.companies ADD COLUMN IF NOT EXISTS db_pending boolean NOT NULL DEFAULT FALSE;",
            # Denormalized from companies.account_kind at manager-creation time so a
            # partial unique index can enforce email uniqueness among individual
            # accounts only, without touching the existing per-company email/phone
            # rules used by the company registration flow.
            "ALTER TABLE public.managers ADD COLUMN IF NOT EXISTS account_kind character varying NOT NULL DEFAULT 'company';",
            "CREATE UNIQUE INDEX IF NOT EXISTS ux_managers_email_individual ON public.managers (lower(trim(email))) WHERE account_kind = 'individual';",
            """
            CREATE TABLE IF NOT EXISTS public.app_update_policy (
              id character varying NOT NULL,
              policy jsonb NOT NULL,
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (id)
            );
            """,
            # Superadmin backup/restore lock — while a row exists, login is
            # refused and active sessions are force-logged-out (see
            # is_backup_locked/_acquire_backup_lock). company_id NULL = global
            # (affects every company, used for the shared general/GSM
            # backups); a concrete company_id scopes it to just that
            # company's own dedicated DB backup. NOT part of
            # _GENERAL_BACKUP_TABLES on purpose — must never round-trip
            # through a backup file itself.
            """
            CREATE TABLE IF NOT EXISTS public.system_backup_locks (
              id serial PRIMARY KEY,
              company_id character varying NULL,
              reason text NOT NULL DEFAULT '',
              started_at timestamp without time zone NOT NULL DEFAULT now()
            );
            """,
            # Live progress log of the current/most recent GSM parser run.
            # Single row ('current'), overwritten at run start and appended
            # to per log line — lets the desktop UI's "Логи" tab show live
            # progress even when the parser is actually running on a
            # different machine (the VPS scheduler), since a local file
            # written there isn't visible from here.
            """
            CREATE TABLE IF NOT EXISTS public.gsm_parser_run_log (
              id character varying NOT NULL DEFAULT 'current',
              content text NOT NULL DEFAULT '',
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (id)
            );
            """,
            # GSM Parser parsed devices (global parser dataset)
            """
            CREATE TABLE IF NOT EXISTS public.gsm_parser_devices (
              id character varying NOT NULL,
              source character varying(32) NOT NULL,
              brand character varying(128) NOT NULL,
              device_type character varying(64) NOT NULL DEFAULT '',
              model_name character varying(255) NOT NULL,
              model_key character varying(255) NOT NULL,
              source_url text NOT NULL DEFAULT '',
              image_url text NOT NULL DEFAULT '',
              specs jsonb NOT NULL DEFAULT '{}'::jsonb,
              last_seen_at timestamp without time zone NOT NULL,
              created_at timestamp without time zone NOT NULL,
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (id)
            );
            """,
            "CREATE UNIQUE INDEX IF NOT EXISTS ux_gsm_parser_devices_source_model_key ON public.gsm_parser_devices USING btree (source, model_key);",
            "CREATE INDEX IF NOT EXISTS ix_gsm_parser_devices_brand ON public.gsm_parser_devices USING btree (brand);",
            "CREATE INDEX IF NOT EXISTS ix_gsm_parser_devices_device_type ON public.gsm_parser_devices USING btree (device_type);",
            # GSM Parser field-level change history
            """
            CREATE TABLE IF NOT EXISTS public.gsm_parser_change_history (
              id character varying NOT NULL,
              device_id character varying NOT NULL,
              source character varying(32) NOT NULL,
              field_key character varying(128) NOT NULL,
              old_value text,
              new_value text,
              changed_at timestamp without time zone NOT NULL,
              run_id character varying(64) NOT NULL DEFAULT '',
              meta jsonb NOT NULL DEFAULT '{}'::jsonb,
              PRIMARY KEY (id)
            );
            """,
            "CREATE INDEX IF NOT EXISTS ix_gsm_parser_change_history_device_id ON public.gsm_parser_change_history USING btree (device_id);",
            "CREATE INDEX IF NOT EXISTS ix_gsm_parser_change_history_changed_at ON public.gsm_parser_change_history USING btree (changed_at);",
            "CREATE INDEX IF NOT EXISTS ix_gsm_parser_change_history_field_key ON public.gsm_parser_change_history USING btree (field_key);",
            "ALTER TABLE public.managers ADD COLUMN IF NOT EXISTS is_blocked boolean NOT NULL DEFAULT FALSE;",
            "ALTER TABLE public.gsm_parser_devices ADD COLUMN IF NOT EXISTS device_order integer NOT NULL DEFAULT 0;",
            "CREATE INDEX IF NOT EXISTS ix_gsm_parser_devices_order ON public.gsm_parser_devices USING btree (brand, device_order);",
            # Global GSM Parser config (company_id='__global__' row) — shared across all companies.
            """
            CREATE TABLE IF NOT EXISTS public.company_extensions (
              company_id character varying NOT NULL,
              ext_key character varying(64) NOT NULL,
              state jsonb NOT NULL,
              updated_at timestamp without time zone NOT NULL,
              PRIMARY KEY (company_id, ext_key)
            );
            """,
            # Per-manager local Postgres cluster connection info. Only used
            # when 2+ managers share one company_id but each has their OWN
            # isolated local cluster on their OWN machine (Компанія-Локал
            # merge, see merge_managers_into_company) — "127.0.0.1:port" is
            # only meaningful on the machine it's running on, so a single
            # companies.db_host/db_port row cannot describe "everyone's own
            # separate device." _resolve_company_dsn() checks this table
            # first (keyed by the ACTIVE manager, not the company) and only
            # falls back to companies.db_* when no row exists here — so a
            # solo individual/VPS company needs zero rows here and behaves
            # exactly as before this table existed.
            """
            CREATE TABLE IF NOT EXISTS public.manager_local_db (
              manager_id character varying NOT NULL,
              db_host character varying NOT NULL,
              db_port integer NOT NULL,
              db_name character varying NOT NULL,
              db_user character varying NOT NULL,
              db_password_enc text NOT NULL,
              created_at timestamp without time zone NOT NULL,
              PRIMARY KEY (manager_id)
            );
            """,
            # Telegram bot tokens (leads/support/registrations), shared across
            # any machine running the Superadmin dashboard or the standalone
            # CatMan SupAdm mini-app — see [[project_telegram_site_bot]].
            # token_enc uses the same Fernet key as companies.db_password_enc
            # (_encrypt_db_password/_decrypt_db_password are generic string
            # encrypt/decrypt despite the name).
            """
            CREATE TABLE IF NOT EXISTS public.bot_config (
              bot_name character varying NOT NULL,
              token_enc text NOT NULL,
              owner_chat_id bigint NOT NULL,
              PRIMARY KEY (bot_name)
            );
            """,
            # Mirror of every Telegram leads/support conversation, written by
            # Telegram Боти/forward_bot.py so the Superadmin dashboard (and
            # CatMan SupAdm) can show/reply to them without touching Telegram
            # directly on every read.
            """
            CREATE TABLE IF NOT EXISTS public.bot_conversations (
              id bigserial NOT NULL,
              bot_name character varying NOT NULL,
              tg_user_id bigint NOT NULL,
              tg_username character varying,
              tg_full_name character varying,
              direction character varying NOT NULL,
              message_text text NOT NULL,
              is_read boolean NOT NULL DEFAULT FALSE,
              created_at timestamp without time zone NOT NULL DEFAULT now(),
              PRIMARY KEY (id)
            );
            """,
            "CREATE INDEX IF NOT EXISTS ix_bot_conversations_thread ON public.bot_conversations USING btree (bot_name, tg_user_id, created_at);",
            "CREATE INDEX IF NOT EXISTS ix_bot_conversations_unread ON public.bot_conversations USING btree (bot_name, is_read) WHERE direction = 'in';",
        ]
        with conn.cursor() as cur:
            # All of these are static (no %s params), so they can be sent as
            # one multi-statement batch via the simple query protocol instead
            # of one execute() round trip per statement — this list has
            # dozens of entries and runs on every new general-DB connection
            # (once per process, but that "once" used to cost a full second+
            # of pure round-trip latency over a remote Postgres connection).
            cur.execute("\n".join(ddl))

