    def _sync_product_references(
        self,
        company_id: str,
        product_id: str,
        *,
        product_name: str | None = None,
        deleted: bool = False,
    ) -> None:
        if not self._use_postgres():
            return
        cid = str(company_id or "").strip()
        pid = str(product_id or "").strip()
        if not cid or not pid:
            return
        now = self._now_ts()
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute("SELECT id, data FROM orders WHERE company_id=%s", (cid,))
                rows = cur.fetchall() or []
                for r in rows:
                    if not isinstance(r, dict) or not r.get("id"):
                        continue
                    data = r.get("data") if isinstance(r.get("data"), dict) else {}
                    items = (
                        data.get("items") if isinstance(data.get("items"), list) else []
                    )
                    changed = False
                    for it in items:
                        if not isinstance(it, dict):
                            continue
                        if str(it.get("product_id") or "").strip() != pid:
                            continue
                        if deleted:
                            if str(it.get("product_id") or "").strip():
                                it["product_id"] = ""
                                changed = True
                            if it.get("product_name") not in (None, ""):
                                it["product_name"] = ""
                                changed = True
                        else:
                            if (
                                product_name is not None
                                and it.get("product_name") != product_name
                            ):
                                it["product_name"] = product_name
                                changed = True
                    if changed:
                        data["items"] = items
                        cur.execute(
                            "UPDATE orders SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                            (psycopg.types.json.Jsonb(data), now, str(r.get("id"))),
                        )

