    def _default_catalog_levels(self) -> list[dict]:
        """
        UI expects `catalog_config.levels` to be a list so it can render level config rows.
        Keep 6 positions for universal hierarchy; user can disable unused ones later.
        """
        levels = []
        for pos in range(1, 7):
            levels.append(
                {"position": pos, "title": f"Рівень {pos}", "enabled": (pos <= 2)}
            )
        return levels

    def _pulse(
        self, company_id: str, scope: str, changed_by: str | None = None
    ) -> None:
        """
        Record a sync pulse so dashboards refresh without navigation.
        Scopes are defined in Dashboard/_sync_scopes and SuperAdminDashboard/_sync_scopes.
        """
        if not self._use_postgres():
            return
        cid = str(company_id or "").strip()
        sc = str(scope or "").strip()
        if not cid or not sc:
            return
        actor = str(changed_by or "").strip() or "system"
        # Use a strictly monotonic integer timestamp per (company_id, scope).
        # UI compares pulses with ">" so duplicates in the same second must be avoided.
        # This runs after nearly every write in the app — collapsed from
        # SELECT-then-INSERT (2 round trips) into one INSERT...SELECT so the
        # "next timestamp" is computed server-side in the same round trip.
        now_sec = int(time.time())
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.sync_pulses (id, company_id, scope, ts, changed_by)
                    SELECT %s, %s, %s, GREATEST(COALESCE(MAX(ts), 0) + 1, %s), %s
                    FROM public.sync_pulses
                    WHERE company_id=%s AND scope=%s
                    """,
                    (uuid.uuid4().hex, cid, sc, now_sec, actor, cid, sc),
                )
        # Safety net: every write path pulses its scope(s), so hooking
        # cache invalidation here guarantees the products/suppliers/
        # packaging session caches never go stale — even from a mutation
        # site that isn't one of the explicit invalidate_*_cache() calls.
        if sc == "products":
            self._invalidate_product_scope_cache(cid)
        elif sc == "suppliers":
            self.invalidate_suppliers_cache(cid)
        elif sc == "packaging":
            self.invalidate_packaging_cache(cid)
        elif sc == "catalog":
            self.invalidate_categories_cache(cid)
        elif sc == "extensions":
            self._session_cache.pop(f"gsm_enabled_{cid}", None)
            stale = [
                k
                for k in self._session_cache
                if k.startswith(f"eff_features_{cid}_")
            ]
            for k in stale:
                self._session_cache.pop(k, None)

    def _get_company_id_by_name(self, name: str) -> str | None:
        """Look up a real (multi-user) company by name. Individual accounts
        (account_kind='individual') use a server-generated placeholder name
        and are deliberately excluded here so a company registration can
        never collide onto someone's personal placeholder."""
        name = (name or "").strip()
        if not name:
            return None
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                SELECT id FROM public.companies
                WHERE lower(trim(name)) = lower(trim(%s)) AND account_kind = 'company'
                ORDER BY created_at ASC NULLS LAST
                LIMIT 1
                """,
                (name,),
            )
            row = cur.fetchone()
        return str(row["id"]) if row and row.get("id") else None

    @staticmethod
    def _build_company_db_name(company_id: str, company_name: str = "") -> str:
        """Compute a Postgres database name for a NEW company (used only at
        creation time; stored in companies.db_name and never recomputed)."""
        import re as _re

        cid = (
            str(company_id or "").strip().replace("-", "")[:16] or uuid.uuid4().hex[:16]
        )
        ascii_name = _re.sub(r"[^\x00-\x7F]", "", company_name or "")
        slug = _re.sub(r"[^a-z0-9]+", "_", ascii_name.lower()).strip("_")[:30]
        return f"catman_{slug}_{cid}" if slug else f"catman_company_{cid}"

    def _server_maintenance_dsn(self) -> str:
        """DSN for CREATE/DROP DATABASE — same server/credentials as the general
        database, connected to the 'postgres' maintenance database."""
        from urllib.parse import urlparse

        parsed = urlparse(self._pg_dsn)
        return self._build_dsn(
            parsed.hostname or "127.0.0.1",
            parsed.port or 5432,
            "postgres",
            parsed.username or "postgres",
            parsed.password or "",
        )

    def _provision_company_database(
        self, db_name: str, template: str | None = None
    ) -> None:
        """CREATE a brand-new dedicated Postgres database for a company.
        If `template` is given, does an instant full copy via
        CREATE DATABASE ... TEMPLATE (requires no other sessions on the template,
        so we close our own cached connection to it and ask Postgres to
        terminate any others first)."""
        db_name = str(db_name or "").strip()
        if not db_name:
            raise ValueError("db_name is required")
        template = str(template or "").strip()
        maint_conn = psycopg.connect(
            self._server_maintenance_dsn(), autocommit=True, row_factory=dict_row
        )
        try:
            if template:
                for cid, conn in list(self._company_conns.items()):
                    if getattr(conn.info, "dbname", "") == template:
                        with contextlib.suppress(Exception):
                            conn.close()
                        del self._company_conns[cid]
                with maint_conn.cursor() as cur:
                    cur.execute(
                        "SELECT pg_terminate_backend(pid) FROM pg_stat_activity "
                        "WHERE datname=%s AND pid <> pg_backend_pid()",
                        (template,),
                    )
                    cur.execute(f'CREATE DATABASE "{db_name}" TEMPLATE "{template}"')
            else:
                with maint_conn.cursor() as cur:
                    cur.execute(f'CREATE DATABASE "{db_name}"')
        finally:
            maint_conn.close()

    def _provision_company_database_at(
        self, host: str, port: int, user: str, password: str, db_name: str
    ) -> None:
        """Like _provision_company_database, but against an admin-specified
        dedicated VPS (superadmin-entered host/port/credentials) instead of
        the app's own shared general-DB server. No template-copy support —
        this is only ever used for a brand-new, empty company database."""
        db_name = str(db_name or "").strip()
        if not db_name:
            raise ValueError("db_name is required")
        maint_dsn = self._build_dsn(host, port, "postgres", user, password)
        maint_conn = psycopg.connect(maint_dsn, autocommit=True, row_factory=dict_row)
        try:
            with maint_conn.cursor() as cur:
                cur.execute(f'CREATE DATABASE "{db_name}"')
        finally:
            maint_conn.close()

    def _drop_company_database(self, db_name: str) -> None:
        db_name = str(db_name or "").strip()
        if not db_name:
            return
        maint_conn = psycopg.connect(
            self._server_maintenance_dsn(), autocommit=True, row_factory=dict_row
        )
        try:
            with maint_conn.cursor() as cur:
                cur.execute(
                    "SELECT pg_terminate_backend(pid) FROM pg_stat_activity "
                    "WHERE datname=%s AND pid <> pg_backend_pid()",
                    (db_name,),
                )
                cur.execute(f'DROP DATABASE IF EXISTS "{db_name}"')
        finally:
            maint_conn.close()

    def create_company(
        self,
        name: str,
        copy_from_company_id: str | None = None,
        account_kind: str = "company",
        storage_mode: str = "vps",
        vps_conn: dict | None = None,
        allow_pending: bool = False,
    ) -> str:
        """Create a company with its OWN dedicated Postgres database.

        Pass copy_from_company_id to provision the new database as an instant
        full copy of another company's database (Postgres CREATE DATABASE ...
        TEMPLATE) — used for spinning up the Test company from ItSellOpt's data.
        Only valid for storage_mode='vps' (a local cluster has no shared
        server to template-clone from).

        account_kind='individual' marks this as a de-facto one-person company
        (solo self-registration) rather than a real multi-user company; see
        save_individual_setup().

        storage_mode='local' provisions an isolated, auto-managed local
        Postgres cluster on this machine (see local_pg_manager.py) instead of
        a database on the shared VPS server. _resolve_company_dsn()/_pg()
        need no changes either way — they only read back whatever
        db_host/db_port/db_name/db_user this function writes.

        storage_mode='vps' with vps_conn={"host","port","user","password"}
        provisions the database on that admin-specified dedicated server
        instead of the shared general-DB server.

        By default (allow_pending=False), storage_mode='vps' with no vps_conn
        keeps the original behaviour: auto-provision on the app's own shared
        general-DB server — this is what self-registration and company-admin
        company creation must keep doing unconditionally.
        Pass allow_pending=True (superadmin-only company-creation dialogs) to
        instead create the row as db_pending=True when no vps_conn is given —
        no database is provisioned, and every attempt to read/write company
        data fails until a superadmin fills in the address later via
        set_company_vps_address().
        """
        if not self._use_postgres():
            return str(self._post("/companies/create", {"name": name}) or "")
        account_kind = "individual" if account_kind == "individual" else "company"
        storage_mode = "local" if storage_mode == "local" else "vps"
        name = (name or "").strip() or "Компанія"
        cid = uuid.uuid4().hex

        copy_from_company_id = str(copy_from_company_id or "").strip()
        db_pending = False
        if storage_mode == "local":
            if copy_from_company_id:
                raise ValueError(
                    "copy_from_company_id is not supported for storage_mode='local'"
                )
            import secrets

            import local_pg_manager

            db_password = secrets.token_urlsafe(24)
            db_host, db_port, db_name, db_user = local_pg_manager.ensure_started(
                cid, db_password
            )
        elif vps_conn and str(vps_conn.get("host") or "").strip():
            db_name = self._build_company_db_name(cid, name)
            db_host = str(vps_conn.get("host") or "").strip()
            db_port = int(vps_conn.get("port") or 5432)
            db_user = str(vps_conn.get("user") or "postgres").strip() or "postgres"
            db_password = str(vps_conn.get("password") or "")
            self._provision_company_database_at(
                db_host, db_port, db_user, db_password, db_name
            )
        elif allow_pending and not copy_from_company_id:
            # VPS chosen, but no dedicated address given yet — create the
            # company row as a locked placeholder; nothing can be saved for
            # it until a superadmin supplies an address.
            db_pending = True
            db_name = ""
            db_host = ""
            db_port = None
            db_user = ""
            db_password = ""
        else:
            db_name = self._build_company_db_name(cid, name)

            template_db_name = ""
            if copy_from_company_id:
                with self._general_pg().cursor() as cur:
                    cur.execute(
                        "SELECT db_name FROM public.companies WHERE id=%s LIMIT 1",
                        (copy_from_company_id,),
                    )
                    row = cur.fetchone()
                    template_db_name = str((row or {}).get("db_name") or "").strip()

            self._provision_company_database(db_name, template=template_db_name or None)

            from urllib.parse import urlparse

            parsed = urlparse(self._pg_dsn)
            db_host = parsed.hostname or "127.0.0.1"
            db_port = parsed.port or 5432
            db_user = parsed.username or "postgres"
            db_password = parsed.password or ""

        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.companies
                    (id, name, created_at, meta, updated_at,
                     db_host, db_port, db_name, db_user, db_password_enc, db_sslmode,
                     account_kind, storage_mode, db_pending)
                VALUES (%s, %s, %s, %s::jsonb, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    cid,
                    name,
                    self._now_ts(),
                    psycopg.types.json.Jsonb({}),
                    self._now_ts(),
                    db_host,
                    db_port,
                    db_name,
                    db_user,
                    self._encrypt_db_password(db_password),
                    "",
                    account_kind,
                    storage_mode,
                    db_pending,
                ),
            )

        self.set_company(cid, name)
        if not db_pending:
            self._pg()  # bootstrap/verify tables now so create_company() returns a ready company
        self._pulse(cid, "company")
        return cid

    def set_company_vps_address(
        self, company_id: str, host: str, port, user: str, password: str
    ) -> tuple[bool, str]:
        """Superadmin supplies the dedicated VPS address for a company that
        was created with storage_mode='vps' and no address yet (db_pending).
        Provisions the database on that server and unlocks the company.
        Only valid while the company is still pending — an already-live VPS
        company has real data and re-pointing it to a different server needs
        a dump/restore migration, not this (see migrate_company_local_to_vps
        for the equivalent local->vps pattern that would need to be mirrored
        for a future vps->vps move)."""
        company_id = str(company_id or "").strip()
        host = str(host or "").strip()
        if not company_id or not host:
            return False, "Вкажіть адресу сервера"
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT name, storage_mode, db_pending FROM public.companies WHERE id=%s",
                (company_id,),
            )
            row = cur.fetchone()
        if not row:
            return False, "Компанію не знайдено"
        if str(row.get("storage_mode") or "") != "vps" or not bool(row.get("db_pending")):
            return False, "Компанія вже має налаштовану базу даних"

        db_name = self._build_company_db_name(company_id, str(row.get("name") or ""))
        db_port = int(port or 5432)
        db_user = str(user or "postgres").strip() or "postgres"
        db_password = str(password or "")
        try:
            self._provision_company_database_at(
                host, db_port, db_user, db_password, db_name
            )
        except Exception as exc:
            logger.exception(
                "set_company_vps_address: provisioning failed company_id=%s", company_id
            )
            return False, f"Не вдалося створити базу на вказаному сервері: {exc}"

        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                UPDATE public.companies
                SET db_host=%s, db_port=%s, db_name=%s, db_user=%s,
                    db_password_enc=%s, db_pending=FALSE, updated_at=%s
                WHERE id=%s
                """,
                (
                    host, db_port, db_name, db_user,
                    self._encrypt_db_password(db_password),
                    self._now_ts(), company_id,
                ),
            )

        # Bootstrap the fresh database's schema — briefly borrow the active
        # company slot to do it, then restore whatever the caller (usually a
        # superadmin session not scoped to this company) had active.
        prev_cid = self._active_company_id
        prev_mid = self._active_manager_id
        prev_name = self._active_company_name
        try:
            self.set_company(company_id, str(row.get("name") or ""))
            self._pg()
        except Exception:
            logger.exception(
                "set_company_vps_address: schema bootstrap failed company_id=%s", company_id
            )
        finally:
            self._active_company_id = prev_cid
            self._active_manager_id = prev_mid
            self._active_company_name = prev_name

        self._pulse(company_id, "company")
        return True, ""

    def migrate_company_local_to_vps(self, company_id: str) -> tuple[bool, str]:
        """Upgrade a Локал company/individual to VPS storage: pg_dump the
        local cluster's database, pg_restore it into a freshly provisioned
        VPS-hosted database, then flip storage_mode. Not a rewrite of the
        business schema — same DDL, same data, just a different host.

        Failure at any step leaves the company on its still-intact local
        cluster (storage_mode untouched) and drops the half-created VPS
        database — a failed migration must be a no-op, never data loss.
        The local cluster itself is NOT deleted on success; it's left in
        place as a safety-net backup (retention/cleanup is a manual/future
        concern, not automatic).
        """
        import pg_migration_tools

        company_id = str(company_id or "").strip()
        if not company_id:
            return False, "Компанію не знайдено"
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT name, storage_mode, db_host, db_port, db_name, db_user, db_password_enc "
                "FROM public.companies WHERE id=%s",
                (company_id,),
            )
            row = cur.fetchone()
        if not row:
            return False, "Компанію не знайдено"
        if str(row.get("storage_mode") or "") != "local":
            return False, "Компанія вже не в локальному режимі"

        old_host = str(row.get("db_host") or "127.0.0.1")
        old_port = int(row.get("db_port") or 0)
        old_db_name = str(row.get("db_name") or "postgres")
        old_user = str(row.get("db_user") or "postgres")
        old_password = self._decrypt_db_password(row.get("db_password_enc") or "")
        company_name = str(row.get("name") or "Компанія")

        new_db_name = self._build_company_db_name(company_id, company_name)
        dump_path = None
        try:
            self._provision_company_database(new_db_name)

            from urllib.parse import urlparse

            parsed = urlparse(self._pg_dsn)
            new_host = parsed.hostname or "127.0.0.1"
            new_port = parsed.port or 5432
            new_user = parsed.username or "postgres"
            new_password = parsed.password or ""

            dump_path = pg_migration_tools.dump_to_temp_file(
                host=old_host, port=old_port, user=old_user,
                password=old_password, dbname=old_db_name,
            )
            pg_migration_tools.restore_database(
                host=new_host, port=new_port, user=new_user,
                password=new_password, dbname=new_db_name,
                input_file=dump_path,
            )

            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    UPDATE public.companies
                    SET storage_mode='vps', db_host=%s, db_port=%s, db_name=%s,
                        db_user=%s, db_password_enc=%s, db_sslmode='', updated_at=%s
                    WHERE id=%s
                    """,
                    (
                        new_host, new_port, new_db_name, new_user,
                        self._encrypt_db_password(new_password),
                        self._now_ts(), company_id,
                    ),
                )
            self._evict_company_connections(company_id)
            self._pulse(company_id, "company")
            logger.info(
                "migrate_company_local_to_vps: success company_id=%s new_db=%s",
                company_id, new_db_name,
            )
            return True, ""
        except Exception as exc:
            logger.exception("migrate_company_local_to_vps failed company_id=%s", company_id)
            with contextlib.suppress(Exception):
                self._drop_company_database(new_db_name)
            return False, f"Помилка міграції: {exc}"
        finally:
            if dump_path:
                with contextlib.suppress(OSError):
                    os.remove(dump_path)

    def _get_company_db_conn_info(
        self, company_id: str, manager_id: str = ""
    ) -> dict | None:
        """Shared lookup used by export/import_company_backup — same
        host/port/db_name/user/password columns as _resolve_company_dsn, but
        returned as separate fields since pg_migration_tools takes them
        individually (not a DSN string).

        manager_id should be the CURRENTLY LOGGED-IN manager's own id —
        checked against manager_local_db first (Компанія-Локал merge, see
        merge_managers_into_company/_resolve_manager_local_dsn), since in
        that mode several managers share one company_id but each has their
        OWN isolated cluster; without this, backup/restore would silently
        operate on whichever manager's cluster happens to be the target
        company's row instead of the logged-in user's own data."""
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT name, account_kind FROM public.companies WHERE id=%s",
                (str(company_id or "").strip(),),
            )
            crow = cur.fetchone()
        if not crow:
            return None
        name = str(crow.get("name") or "")
        account_kind = str(crow.get("account_kind") or "company")

        manager_dsn_row = None
        mid = str(manager_id or "").strip()
        if mid:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT db_host, db_port, db_name, db_user, db_password_enc "
                    "FROM public.manager_local_db WHERE manager_id=%s",
                    (mid,),
                )
                manager_dsn_row = cur.fetchone()
        if manager_dsn_row and str(manager_dsn_row.get("db_name") or "").strip():
            return {
                "name": name,
                "account_kind": account_kind,
                "host": str(manager_dsn_row.get("db_host") or "127.0.0.1"),
                "port": int(manager_dsn_row.get("db_port") or 5432),
                "db_name": str(manager_dsn_row["db_name"]),
                "user": str(manager_dsn_row.get("db_user") or "postgres"),
                "password": self._decrypt_db_password(
                    manager_dsn_row.get("db_password_enc") or ""
                ),
            }

        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT db_host, db_port, db_name, db_user, db_password_enc "
                "FROM public.companies WHERE id=%s",
                (str(company_id or "").strip(),),
            )
            row = cur.fetchone()
        if not row or not str(row.get("db_name") or "").strip():
            return None
        return {
            "name": name,
            "account_kind": account_kind,
            "host": str(row.get("db_host") or "127.0.0.1"),
            "port": int(row.get("db_port") or 5432),
            "db_name": str(row.get("db_name") or ""),
            "user": str(row.get("db_user") or "postgres"),
            "password": self._decrypt_db_password(row.get("db_password_enc") or ""),
        }

    def export_company_backup(
        self, company_id: str, dest_dir: str, manager_id: str = ""
    ) -> tuple[bool, str]:
        """Manual backup (Фаза G): pg_dump the company's own database — works
        for Локал and VPS alike since _get_company_db_conn_info is host-
        agnostic — into dest_dir, plus a small JSON manifest for a friendlier
        check on import. Returns (True, dump_file_path) or (False, error).

        manager_id: pass the logged-in user's own id — required for
        Компанія-Локал (see _get_company_db_conn_info)."""
        import pg_migration_tools

        company_id = str(company_id or "").strip()
        if not company_id:
            return False, "Компанію не знайдено"
        info = self._get_company_db_conn_info(company_id, manager_id)
        if not info:
            return False, "У компанії не налаштована власна база даних"

        dest_dir = str(dest_dir or "").strip()
        if not dest_dir or not os.path.isdir(dest_dir):
            return False, "Вкажіть існуючу теку призначення"
        safe_name = "".join(c if c.isalnum() else "_" for c in info["name"])[:40] or "company"
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        out_path = os.path.join(dest_dir, f"catman_backup_{safe_name}_{stamp}.dump")

        lock_id = self._acquire_backup_lock(company_id, f"Бекап компанії {info['name']}")
        try:
            pg_migration_tools.dump_database(
                host=info["host"], port=info["port"], user=info["user"],
                password=info["password"], dbname=info["db_name"], output_file=out_path,
            )
            self._write_backup_manifest(
                out_path,
                {
                    "company_id": company_id,
                    "company_name": info["name"],
                    "account_kind": info["account_kind"],
                    "created_at": self._now_ts(),
                },
            )
            logger.info("export_company_backup: success company_id=%s -> %s", company_id, out_path)
            return True, out_path
        except Exception as exc:
            logger.exception("export_company_backup failed company_id=%s", company_id)
            with contextlib.suppress(OSError):
                if os.path.exists(out_path):
                    os.remove(out_path)
            return False, f"Помилка збереження бекапу: {exc}"
        finally:
            self._release_backup_lock(lock_id)

    def read_backup_manifest(self, dump_file: str) -> dict | None:
        return self._read_backup_manifest(dump_file)

    def import_company_backup(
        self, company_id: str, input_file: str, manager_id: str = ""
    ) -> tuple[bool, str]:
        """Manual restore (Фаза G): pg_restore a .dump file into the
        company's own database, in place. Destructive — overwrites current
        data (pg_migration_tools.restore_database uses --clean --if-exists).
        Caller (UI) must show an explicit confirmation before calling this.

        manager_id: pass the logged-in user's own id — required for
        Компанія-Локал (see _get_company_db_conn_info)."""
        import pg_migration_tools

        company_id = str(company_id or "").strip()
        manager_id = str(manager_id or "").strip()
        input_file = str(input_file or "").strip()
        if not input_file or not os.path.isfile(input_file):
            return False, "Файл бекапу не знайдено"
        info = self._get_company_db_conn_info(company_id, manager_id)
        if not info:
            return False, "У компанії не налаштована власна база даних"

        lock_id = self._acquire_backup_lock(company_id, f"Відновлення компанії {info['name']}")
        try:
            pg_migration_tools.restore_database(
                host=info["host"], port=info["port"], user=info["user"],
                password=info["password"], dbname=info["db_name"], input_file=input_file,
            )
            # Cache key is composite (company_id::manager_id::thread) for
            # Компанія-Локал and per-thread connections (see _pg()) — evict
            # every cached variant so the next _pg() call reconnects fresh.
            self._evict_company_connections(company_id)
            self._pulse(company_id, "company")
            logger.info("import_company_backup: success company_id=%s <- %s", company_id, input_file)
            return True, ""
        except Exception as exc:
            logger.exception("import_company_backup failed company_id=%s", company_id)
            return False, f"Помилка відновлення бекапу: {exc}"
        finally:
            self._release_backup_lock(lock_id)

    # Global tables that live in the general DB alongside companies/managers
    # but are NOT gsm_parser_* (device photo blobs) — see
    # project_percompany_database_architecture memory. manager_gsm_parser_permissions
    # is a permission mapping, not device data, so it belongs here even though
    # the name starts with "manager_gsm_parser".
    _GENERAL_BACKUP_TABLES = [
        "companies", "managers", "sync_pulses", "app_update_policy",
        "translation_languages", "translation_keys", "translation_values",
        "user_file_groups", "user_files", "manager_gsm_parser_permissions",
    ]
    _GSM_BACKUP_TABLE_PATTERN = "gsm_parser_*"

    # How long a backup lock stays honored without being explicitly released.
    # Backup/restore always releases its lock in a finally block; this is
    # only a self-heal ceiling in case a process gets killed mid-dump — it
    # must NOT be cleared on ordinary app/process startup, since many other
    # users' app instances reconnect to the general DB (and so would run
    # schema bootstrap) while one single backup is legitimately in progress.
    _BACKUP_LOCK_TTL_SECONDS = 30 * 60

    def _acquire_backup_lock(self, company_id: str | None, reason: str) -> int:
        company_id = str(company_id).strip() if company_id else None
        with self._general_pg().cursor() as cur:
            cur.execute(
                "INSERT INTO public.system_backup_locks (company_id, reason) "
                "VALUES (%s, %s) RETURNING id",
                (company_id, str(reason or "")),
            )
            row = cur.fetchone() or {}
        return int(row.get("id") or 0)

    def _release_backup_lock(self, lock_id: int) -> None:
        if not lock_id:
            return
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM public.system_backup_locks WHERE id=%s", (lock_id,)
                )
        except Exception:
            logger.exception("_release_backup_lock failed lock_id=%s", lock_id)

    def is_backup_locked(self, company_id: str | None) -> bool:
        company_id = str(company_id).strip() if company_id else None
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT 1 FROM public.system_backup_locks "
                "WHERE (company_id IS NULL OR company_id = %s) "
                "AND started_at > now() - make_interval(secs => %s) LIMIT 1",
                (company_id, self._BACKUP_LOCK_TTL_SECONDS),
            )
            return cur.fetchone() is not None

    def _get_general_db_conn_info(self) -> dict:
        from urllib.parse import urlparse

        parsed = urlparse(self._pg_dsn)
        return {
            "host": parsed.hostname or "127.0.0.1",
            "port": parsed.port or 5432,
            "db_name": (parsed.path or "/").lstrip("/") or "postgres",
            "user": parsed.username or "postgres",
            "password": parsed.password or "",
        }

    def _export_general_db_tables(
        self, dest_dir: str, tables: list[str], label: str
    ) -> tuple[bool, str]:
        import pg_migration_tools

        dest_dir = str(dest_dir or "").strip()
        if not dest_dir or not os.path.isdir(dest_dir):
            return False, "Вкажіть існуючу теку призначення"
        info = self._get_general_db_conn_info()
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        out_path = os.path.join(dest_dir, f"catman_{label}_{stamp}.dump")
        lock_id = self._acquire_backup_lock(None, f"Бекап {label}")
        try:
            pg_migration_tools.dump_database_tables(
                host=info["host"], port=info["port"], user=info["user"],
                password=info["password"], dbname=info["db_name"],
                tables=tables, output_file=out_path,
            )
            self._write_backup_manifest(
                out_path, {"kind": label, "tables": tables, "created_at": self._now_ts()}
            )
            logger.info("_export_general_db_tables: success label=%s -> %s", label, out_path)
            return True, out_path
        except Exception as exc:
            logger.exception("_export_general_db_tables failed label=%s", label)
            with contextlib.suppress(OSError):
                if os.path.exists(out_path):
                    os.remove(out_path)
            return False, f"Помилка збереження бекапу: {exc}"
        finally:
            self._release_backup_lock(lock_id)

    def _import_general_db_tables(self, input_file: str, label: str = "general") -> tuple[bool, str]:
        import pg_migration_tools

        input_file = str(input_file or "").strip()
        if not input_file or not os.path.isfile(input_file):
            return False, "Файл бекапу не знайдено"
        info = self._get_general_db_conn_info()
        lock_id = self._acquire_backup_lock(None, f"Відновлення {label}")
        try:
            pg_migration_tools.restore_database(
                host=info["host"], port=info["port"], user=info["user"],
                password=info["password"], dbname=info["db_name"], input_file=input_file,
            )
            self._evict_general_connections()
            logger.info("_import_general_db_tables: success <- %s", input_file)
            return True, ""
        except Exception as exc:
            logger.exception("_import_general_db_tables failed")
            return False, f"Помилка відновлення бекапу: {exc}"
        finally:
            self._release_backup_lock(lock_id)

    def export_general_backup(self, dest_dir: str) -> tuple[bool, str]:
        """Суперадмін-бекап (Фаза H): companies/managers та решта явно
        глобальних таблиць, БЕЗ gsm_parser_* (важкі bytea-фото пристроїв,
        окремий бекап нижче)."""
        return self._export_general_db_tables(dest_dir, self._GENERAL_BACKUP_TABLES, "general")

    def import_general_backup(self, input_file: str) -> tuple[bool, str]:
        return self._import_general_db_tables(input_file, "general")

    def export_gsm_backup(self, dest_dir: str) -> tuple[bool, str]:
        """Суперадмін-бекап (Фаза H): лише gsm_parser_* таблиці з загальної
        БД (окремо від companies/managers через розмір — фото пристроїв)."""
        return self._export_general_db_tables(dest_dir, [self._GSM_BACKUP_TABLE_PATTERN], "gsm_parser")

    def import_gsm_backup(self, input_file: str) -> tuple[bool, str]:
        return self._import_general_db_tables(input_file, "gsm_parser")

    def company_name_exists(
        self, name: str, exclude_company_id: str | None = None
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._get(
                    "/companies/name_exists",
                    {"name": name, "exclude_company_id": exclude_company_id or ""},
                )
                or False
            )
        name = str(name or "").strip()
        if not name:
            return False
        exclude_company_id = str(exclude_company_id or "").strip()
        with self._general_pg().cursor() as cur:
            if exclude_company_id:
                cur.execute(
                    "SELECT 1 FROM public.companies WHERE lower(name)=lower(%s) AND id<>%s LIMIT 1",
                    (name, exclude_company_id),
                )
            else:
                cur.execute(
                    "SELECT 1 FROM public.companies WHERE lower(name)=lower(%s) LIMIT 1",
                    (name,),
                )
            return bool(cur.fetchone())

    def get_company_storage_mode(self, company_id: str) -> str:
        """Live read (not cached in user_data/session) so UI gates that
        depend on Локал/VPS status reflect a just-completed migration
        immediately, without requiring a fresh login."""
        company_id = str(company_id or "").strip()
        if not company_id or not self._use_postgres():
            return "vps"
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT storage_mode FROM public.companies WHERE id=%s", (company_id,)
                )
                row = cur.fetchone()
            return str((row or {}).get("storage_mode") or "vps")
        except Exception:
            return "vps"

    def get_company_local_db_registry(self, company_id: str) -> list[dict]:
        """List each manager's own registered local Postgres cluster for a
        Компанія-Локал company (storage_mode='local') — up to one row per
        employee's own PC/device (see manager_local_db /
        _resolve_manager_local_dsn). A local-mode company has NO single
        address; this is the real list. No passwords returned."""
        company_id = str(company_id or "").strip()
        if not company_id or not self._use_postgres():
            return []
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT m.id AS manager_id, m.full_name, m.email,
                           l.db_host, l.db_port, l.db_name
                    FROM public.manager_local_db l
                    JOIN public.managers m ON m.id = l.manager_id
                    WHERE m.company_id = %s
                    ORDER BY m.full_name ASC
                    """,
                    (company_id,),
                )
                return cur.fetchall() or []
        except Exception:
            return []

    def get_company_db_summary(self, company_id: str, manager_id: str = "") -> dict:
        """Where THIS company's data actually lives right now, using the same
        resolution _resolve_company_dsn()/_pg() use (including the
        per-manager Компанія-Локал override when manager_id is the logged-in
        user's own id) — minus the password. Empty dict if unresolvable."""
        info = self._get_company_db_conn_info(company_id, manager_id)
        if not info:
            return {}
        return {
            "host": info.get("host", ""),
            "port": info.get("port", 0),
            "db_name": info.get("db_name", ""),
            "storage_mode": self.get_company_storage_mode(company_id),
        }

    def set_company_db_connection(
        self,
        company_id: str,
        host: str,
        port,
        db_name: str,
        user: str,
        password: str = "",
        sslmode: str = "",
    ) -> tuple[bool, str]:
        """Superadmin direct edit of a VPS-mode company's dedicated-DB
        connection info (public.companies). Repoints where the app looks
        for that company's data — it does NOT move/copy any data itself
        (use move_company_vps_database() to actually relocate the data too).
        Blank password keeps the currently stored one. Tests connectivity
        before saving so a typo can't lock the company out."""
        company_id = str(company_id or "").strip()
        host = str(host or "").strip()
        db_name = str(db_name or "").strip()
        user = str(user or "").strip() or "postgres"
        if not company_id:
            return False, "Компанію не знайдено"
        if not host or not db_name:
            return False, "Host і назва БД обов'язкові"
        try:
            port_i = int(port) if port else 5432
        except (TypeError, ValueError):
            port_i = 5432

        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT db_password_enc FROM public.companies WHERE id=%s", (company_id,)
            )
            row = cur.fetchone()
        if not row:
            return False, "Компанію не знайдено"

        new_password = str(password or "").strip()
        password_enc = (
            self._encrypt_db_password(new_password)
            if new_password
            else str(row.get("db_password_enc") or "")
        )
        effective_password = (
            new_password if new_password else self._decrypt_db_password(password_enc)
        )

        test_dsn = self._build_dsn(host, port_i, db_name, user, effective_password, sslmode)
        try:
            test_conn = psycopg.connect(test_dsn, autocommit=True, row_factory=dict_row)
            test_conn.close()
        except Exception as exc:
            return False, f"Не вдалося підключитися за новими даними: {exc}"

        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                UPDATE public.companies
                SET db_host=%s, db_port=%s, db_name=%s, db_user=%s,
                    db_password_enc=%s, db_sslmode=%s, updated_at=%s
                WHERE id=%s
                """,
                (host, port_i, db_name, user, password_enc, sslmode, self._now_ts(), company_id),
            )

        self._evict_company_connections(company_id)
        self._pulse(company_id, "company")
        return True, "Збережено"

    def move_company_vps_database(
        self,
        company_id: str,
        target_host: str,
        target_port,
        target_db_name: str,
        target_user: str,
        target_password: str,
        target_sslmode: str = "",
    ) -> tuple[bool, str]:
        """Move a VPS-mode company's dedicated database to a different
        Postgres server (a new VPS, a different provider, etc.): dumps the
        company's CURRENT database, creates+restores it at the target, then
        repoints public.companies at the new location. The old database is
        left untouched as a safety-net backup (same policy as
        migrate_company_local_to_vps — a failed move must be a no-op, never
        data loss).

        Only for storage_mode='vps' companies — a 'local' company has no
        single database (each employee has their own PC/cluster, see
        get_company_local_db_registry) so there is nothing here to move.
        """
        import pg_migration_tools

        company_id = str(company_id or "").strip()
        if not company_id:
            return False, "Компанію не знайдено"
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT name, storage_mode, db_host, db_port, db_name, db_user, db_password_enc "
                "FROM public.companies WHERE id=%s",
                (company_id,),
            )
            row = cur.fetchone()
        if not row:
            return False, "Компанію не знайдено"
        if str(row.get("storage_mode") or "") != "vps":
            return False, "Ця дія доступна лише для компаній у режимі VPS"

        old_host = str(row.get("db_host") or "127.0.0.1")
        old_port = int(row.get("db_port") or 5432)
        old_db_name = str(row.get("db_name") or "")
        old_user = str(row.get("db_user") or "postgres")
        old_password = self._decrypt_db_password(row.get("db_password_enc") or "")
        company_name = str(row.get("name") or "Компанія")

        target_host = str(target_host or "").strip()
        target_db_name = (
            str(target_db_name or "").strip()
            or self._build_company_db_name(company_id, company_name)
        )
        target_user = str(target_user or "").strip() or "postgres"
        try:
            target_port_i = int(target_port) if target_port else 5432
        except (TypeError, ValueError):
            target_port_i = 5432
        if not target_host:
            return False, "Вкажіть адресу нового сервера (host)"
        if (
            target_host == old_host
            and target_port_i == old_port
            and target_db_name == old_db_name
        ):
            return False, "Джерело і призначення однакові"

        maint_dsn = self._build_dsn(
            target_host, target_port_i, "postgres", target_user, target_password, target_sslmode
        )
        dump_path = None
        try:
            maint_conn = psycopg.connect(maint_dsn, autocommit=True, row_factory=dict_row)
            try:
                with maint_conn.cursor() as cur:
                    cur.execute(f'CREATE DATABASE "{target_db_name}"')
            finally:
                maint_conn.close()

            dump_path = pg_migration_tools.dump_to_temp_file(
                host=old_host, port=old_port, user=old_user,
                password=old_password, dbname=old_db_name,
            )
            pg_migration_tools.restore_database(
                host=target_host, port=target_port_i, user=target_user,
                password=target_password, dbname=target_db_name,
                input_file=dump_path,
            )

            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    UPDATE public.companies
                    SET db_host=%s, db_port=%s, db_name=%s, db_user=%s,
                        db_password_enc=%s, db_sslmode=%s, updated_at=%s
                    WHERE id=%s
                    """,
                    (
                        target_host, target_port_i, target_db_name, target_user,
                        self._encrypt_db_password(target_password), target_sslmode,
                        self._now_ts(), company_id,
                    ),
                )
            self._evict_company_connections(company_id)
            self._pulse(company_id, "company")
            logger.info(
                "move_company_vps_database: success company_id=%s -> %s:%s/%s",
                company_id, target_host, target_port_i, target_db_name,
            )
            return True, (
                f"Компанію перенесено на {target_host}:{target_port_i}/{target_db_name}. "
                f"Стара база ({old_host}:{old_port}/{old_db_name}) лишилась як резервна копія."
            )
        except Exception as exc:
            logger.exception("move_company_vps_database failed company_id=%s", company_id)
            return False, f"Помилка перенесення: {exc}"
        finally:
            if dump_path:
                with contextlib.suppress(OSError):
                    os.remove(dump_path)

    def update_company_profile(self, company_id: str, payload: dict) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/companies/update_profile",
                    {"company_id": company_id, **(payload or {})},
                )
                or False
            )
        company_id = str(company_id or "").strip()
        if not company_id or not isinstance(payload, dict):
            return False
        name = str(payload.get("name") or "").strip()
        meta = payload.get("meta")
        sets = []
        params: list[Any] = []
        if name:
            sets.append("name=%s")
            params.append(name)
        if isinstance(meta, dict):
            sets.append("meta=%s::jsonb")
            params.append(psycopg.types.json.Jsonb(meta))
        if "max_users" in payload:
            sets.append("max_users=%s")
            params.append(max(0, int(payload.get("max_users") or 0)))
        sets.append("updated_at=%s")
        params.append(self._now_ts())
        params.append(company_id)
        q = "UPDATE public.companies SET " + ", ".join(sets) + " WHERE id=%s"
        with self._general_pg().cursor() as cur:
            cur.execute(q, params)
        self._pulse(company_id, "company")
        return True

    def delete_company(self, company_id: str) -> bool:
        if not self._use_postgres():
            return bool(
                self._delete("/companies/delete", {"company_id": company_id}) or False
            )
        company_id = str(company_id or "").strip()
        if not company_id:
            return False
        # Look up the dedicated database name (and legacy schema_name for
        # companies created before the per-company-database migration).
        db_name = ""
        sc = ""
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT db_name, schema_name FROM public.companies WHERE id=%s LIMIT 1",
                    (company_id,),
                )
                row = cur.fetchone()
                db_name = str((row or {}).get("db_name") or "").strip()
                sc = str((row or {}).get("schema_name") or "").strip()
        except Exception:
            pass

        # Close and drop any cached connection(s) to this company's own database
        # before dropping it (Postgres refuses DROP DATABASE with open sessions).
        self._evict_company_connections(company_id)

        with self._general_pg().cursor() as cur:
            cur.execute(
                "DELETE FROM public.managers WHERE company_id=%s", (company_id,)
            )
            cur.execute("DELETE FROM public.companies WHERE id=%s", (company_id,))

        if db_name:
            try:
                self._drop_company_database(db_name)
                logger.info("Dropped company database %s", db_name)
            except Exception:
                logger.exception("drop_company_database failed for %s", db_name)

        # Legacy: companies created before the per-company-database migration may
        # still have a schema (with public.* compat views) in the general database.
        if sc and sc.startswith("company_"):
            try:
                with self._general_pg().cursor() as cur:
                    cur.execute(f"DROP SCHEMA IF EXISTS {sc} CASCADE")
                logger.info("Dropped legacy company schema %s", sc)
            except Exception:
                logger.exception("drop_schema failed for %s", sc)
        self._pulse(company_id, "company")
        return True

    def get_all_companies(self, force_refresh: bool | None = None):  # noqa: ARG002
        if not self._use_postgres():
            return self._get("/companies") or []
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT id, name, created_at, account_kind, storage_mode, max_users, is_blocked "
                "FROM public.companies ORDER BY name ASC"
            )
            rows = cur.fetchall() or []
        return rows

    def get_all_companies_db_info(self) -> list[dict]:
        """Real dedicated-DB location per company, read straight from
        public.companies (db_host/db_port/db_name/storage_mode) — no
        password. This is the exact same source _resolve_company_dsn() uses;
        for storage_mode='local' companies these columns are NOT a real
        single address (each employee has their own PC — see
        get_company_local_db_registry), only informational leftovers."""
        if not self._use_postgres():
            return []
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT id, name, storage_mode, db_host, db_port, db_name, db_pending "
                "FROM public.companies ORDER BY name ASC"
            )
            return cur.fetchall() or []

    def set_company_blocked(self, company_id: str, blocked: bool) -> bool:
        """Block/unblock an entire company — blocked companies can't log in
        (any manager, any role) until a superadmin unblocks them again."""
        if not self._use_postgres():
            return bool(
                self._post(
                    "/companies/set_blocked",
                    {"company_id": company_id, "blocked": bool(blocked)},
                )
                or False
            )
        company_id = str(company_id or "").strip()
        if not company_id:
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.companies SET is_blocked=%s, updated_at=%s WHERE id=%s",
                    (bool(blocked), self._now_ts(), company_id),
                )
            self._pulse(company_id, "company")
            return True
        return False

    def create_region_with_defaults(self, company_id: str, name: str) -> str:
        if not self._use_postgres():
            return str(
                self._post(
                    "/regions/create_with_defaults",
                    {"company_id": company_id, "name": name},
                )
                or ""
            )
        rid = uuid.uuid4().hex
        company_id = str(company_id or "").strip()
        name = (name or "").strip() or "Регіон"
        with self._pg().cursor() as cur:
            cur.execute(
                "INSERT INTO regions (id, company_id, name, created_at) VALUES (%s, %s, %s, %s)",
                (rid, company_id, name, self._now_ts()),
            )
        # minimal defaults: create empty tier + empty catalog config
        with contextlib.suppress(Exception):
            self.save_region_price_setup(company_id, rid, name, [])
        with contextlib.suppress(Exception):
            self.get_company_catalog_config(
                company_id, rid
            )  # creates default if absent
        self._pulse(company_id, "company")
        return rid

    def get_company_regions(
        self, company_id: str, force_refresh: bool | None = None
    ):  # noqa: ARG002
        if not self._use_postgres():
            return self._get("/regions", {"company_id": company_id}) or []
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT id, company_id, name, created_at FROM regions WHERE company_id=%s ORDER BY name ASC",
                (str(company_id or "").strip(),),
            )
            rows = cur.fetchall() or []
        return rows

    def region_name_exists(
        self, company_id: str, name: str, exclude_region_id: str | None = None
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._get(
                    "/regions/name_exists",
                    {
                        "company_id": company_id,
                        "name": name,
                        "exclude_region_id": exclude_region_id or "",
                    },
                )
                or False
            )
        company_id = str(company_id or "").strip()
        name = str(name or "").strip()
        exclude_region_id = str(exclude_region_id or "").strip()
        if not company_id or not name:
            return False
        with self._pg().cursor() as cur:
            if exclude_region_id:
                cur.execute(
                    "SELECT 1 FROM regions WHERE company_id=%s AND lower(name)=lower(%s) AND id<>%s LIMIT 1",
                    (company_id, name, exclude_region_id),
                )
            else:
                cur.execute(
                    "SELECT 1 FROM regions WHERE company_id=%s AND lower(name)=lower(%s) LIMIT 1",
                    (company_id, name),
                )
            return bool(cur.fetchone())

    def update_region_name(self, region_id: str, new_name: str) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/regions/update_name", {"region_id": region_id, "name": new_name}
                )
                or False
            )
        region_id = str(region_id or "").strip()
        new_name = str(new_name or "").strip()
        if not region_id or not new_name:
            return False
        company_id = ""
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id FROM regions WHERE id=%s LIMIT 1",
                (region_id,),
            )
            row = cur.fetchone()
            company_id = str((row or {}).get("company_id") or "").strip()
            cur.execute("UPDATE regions SET name=%s WHERE id=%s", (new_name, region_id))
        if company_id:
            self._pulse(company_id, "company")
        return True

    def delete_region_with_prices(self, region_id: str) -> bool:
        if not self._use_postgres():
            return bool(
                self._delete("/regions/delete_with_prices", {"region_id": region_id})
                or False
            )
        region_id = str(region_id or "").strip()
        if not region_id:
            return False
        company_id = ""
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id FROM regions WHERE id=%s LIMIT 1",
                (region_id,),
            )
            row = cur.fetchone()
            company_id = str((row or {}).get("company_id") or "").strip()
            # related tables have FK region_id only in some places; be defensive
            with contextlib.suppress(Exception):
                cur.execute(
                    "DELETE FROM region_price_tiers WHERE region_id=%s",
                    (region_id,),
                )
            with contextlib.suppress(Exception):
                cur.execute(
                    "DELETE FROM delivery_methods WHERE region_id=%s",
                    (region_id,),
                )
            with contextlib.suppress(Exception):
                cur.execute(
                    "DELETE FROM catalog_config WHERE region_id=%s", (region_id,)
                )
            with contextlib.suppress(Exception):
                cur.execute(
                    "DELETE FROM catalog_nodes WHERE region_id=%s", (region_id,)
                )
            cur.execute("DELETE FROM regions WHERE id=%s", (region_id,))
        if company_id:
            self._pulse(company_id, "company")
            self._pulse(company_id, "pricing")
        return True

    def check_can_add_approved_manager(self, company_id: str) -> tuple[bool, str]:
        """Shared max_users tariff-limit gate, used by BOTH choke points that
        can produce an approved manager: set_manager_approval() (approving a
        pending self-registration) and admin-created managers (created
        pre-approved). companies.max_users == 0 means unlimited."""
        company_id = str(company_id or "").strip()
        if not company_id:
            return False, "Компанію не знайдено"
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT max_users FROM public.companies WHERE id=%s", (company_id,)
            )
            row = cur.fetchone()
            max_users = int((row or {}).get("max_users") or 0)
            if max_users <= 0:
                return True, ""
            cur.execute(
                "SELECT COUNT(*) AS n FROM public.managers WHERE company_id=%s AND is_approved=TRUE",
                (company_id,),
            )
            current = int((cur.fetchone() or {}).get("n") or 0)
        if current >= max_users:
            return False, f"Ліміт користувачів компанії вичерпано ({max_users})"
        return True, ""

    def merge_managers_into_company(
        self,
        manager_ids: list[str],
        target_company_id: str,
        new_company_name: str | None = None,
    ) -> tuple[bool, str]:
        """Компанія-Локал regroup (Фаза F, Case 1) — СуперАдмін-only.

        Each merged manager KEEPS their own isolated local Postgres cluster on
        their own machine — this operation changes ONLY login/billing identity
        (managers.company_id, companies.name), never business data. Before
        repointing company_id, each manager's ORIGINAL company's local
        connection info is copied into manager_local_db (keyed by manager_id)
        so _resolve_company_dsn keeps routing them to their own cluster after
        the merge — a single companies-row DSN cannot describe multiple
        people's own separate machines (see _resolve_company_dsn).
        """
        manager_ids = [str(m).strip() for m in (manager_ids or []) if str(m).strip()]
        target_company_id = str(target_company_id or "").strip()
        if not manager_ids or not target_company_id:
            return False, "Не вказано користувачів або цільову компанію"

        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT storage_mode FROM public.companies WHERE id=%s",
                (target_company_id,),
            )
            target = cur.fetchone()
        if not target:
            return False, "Цільову компанію не знайдено"
        if str(target.get("storage_mode") or "") != "local":
            return False, "Застосовується лише до компаній зі storage_mode='local'"

        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT id, company_id, is_approved FROM public.managers WHERE id = ANY(%s)",
                (manager_ids,),
            )
            source_managers = cur.fetchall() or []
        if len(source_managers) != len(manager_ids):
            return False, "Деяких користувачів не знайдено"

        incoming_approved = sum(
            1
            for m in source_managers
            if m.get("is_approved")
            and str(m.get("company_id") or "") != target_company_id
        )
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT COUNT(*) AS n FROM public.managers WHERE company_id=%s AND is_approved=TRUE",
                (target_company_id,),
            )
            current = int((cur.fetchone() or {}).get("n") or 0)
            cur.execute(
                "SELECT max_users FROM public.companies WHERE id=%s", (target_company_id,)
            )
            max_users = int((cur.fetchone() or {}).get("max_users") or 0)
        if max_users > 0 and (current + incoming_approved) > max_users:
            return False, (
                f"Перевищено ліміт користувачів цільової компанії ({max_users}). "
                "Спочатку підвищіть ліміт у налаштуваннях компанії."
            )

        source_company_ids = {
            str(m.get("company_id") or "").strip() for m in source_managers
        }
        source_company_ids.discard(target_company_id)
        source_company_ids.discard("")

        now = self._now_ts()
        try:
            with self._general_pg().cursor() as cur:
                # 1. Snapshot each manager's OWN local connection info before
                #    repointing company_id — otherwise it'd be lost/ambiguous
                #    once several managers share one company_id.
                for m in source_managers:
                    mid = str(m.get("id"))
                    old_cid = str(m.get("company_id") or "").strip()
                    if not old_cid or old_cid == target_company_id:
                        continue
                    cur.execute(
                        "SELECT db_host, db_port, db_name, db_user, db_password_enc "
                        "FROM public.companies WHERE id=%s",
                        (old_cid,),
                    )
                    conn_row = cur.fetchone()
                    if not conn_row or not str(conn_row.get("db_name") or "").strip():
                        continue
                    cur.execute(
                        """
                        INSERT INTO public.manager_local_db
                            (manager_id, db_host, db_port, db_name, db_user, db_password_enc, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s)
                        ON CONFLICT (manager_id) DO UPDATE SET
                            db_host=EXCLUDED.db_host, db_port=EXCLUDED.db_port,
                            db_name=EXCLUDED.db_name, db_user=EXCLUDED.db_user,
                            db_password_enc=EXCLUDED.db_password_enc
                        """,
                        (
                            mid,
                            conn_row.get("db_host") or "127.0.0.1",
                            conn_row.get("db_port") or 5432,
                            conn_row["db_name"],
                            conn_row.get("db_user") or "postgres",
                            conn_row.get("db_password_enc") or "",
                            now,
                        ),
                    )

                # 2. Repoint managers to the target company (denormalized
                #    account_kind must follow — they're a real company now).
                cur.execute(
                    "UPDATE public.managers SET company_id=%s, account_kind='company', "
                    "updated_at=%s WHERE id = ANY(%s)",
                    (target_company_id, now, manager_ids),
                )

                # 3. Target may have started as one merged individual's own
                #    1-person "company" — promote it now that it has others.
                name_sets = ["account_kind='company'", "updated_at=%s"]
                params: list[Any] = [now]
                new_name = str(new_company_name or "").strip()
                if new_name:
                    name_sets.append("name=%s")
                    params.append(new_name)
                params.append(target_company_id)
                cur.execute(
                    f"UPDATE public.companies SET {', '.join(name_sets)} WHERE id=%s",
                    params,
                )

                # 4. Clean up now-empty original company rows (identity only —
                #    their local Postgres clusters are NEVER touched/stopped).
                for old_cid in source_company_ids:
                    cur.execute(
                        "SELECT COUNT(*) AS n FROM public.managers WHERE company_id=%s",
                        (old_cid,),
                    )
                    remaining = int((cur.fetchone() or {}).get("n") or 0)
                    if remaining == 0:
                        cur.execute(
                            "DELETE FROM public.companies WHERE id=%s", (old_cid,)
                        )
        except Exception as exc:
            logger.exception("merge_managers_into_company failed")
            return False, f"Помилка злиття: {exc}"

        self._pulse(target_company_id, "company")
        logger.info(
            "merge_managers_into_company: merged %d managers into company_id=%s",
            len(manager_ids),
            target_company_id,
        )
        return True, ""

    # ------------------------------------------------------------------
    # Фаза F, Case 2 — merge multiple sources' business data into one
    # Компанія-VPS. Owner's explicit scoping decision: ONLY categories/
    # level_nodes (the shared catalog STRUCTURE) ever get deduplicated —
    # every other table (products, suppliers, orders, ...) is carried over
    # untouched, one manager's rows never merge with another's. The only
    # reason products/etc. need ANY rewrite at all is that they reference
    # category/level_node ids by id, and a merged node gets a NEW id.
    # ------------------------------------------------------------------

    def _resolve_manager_business_dsn(self, manager_id: str) -> tuple[str, str]:
        """Returns (dsn, company_id) for this manager's OWN business-data DB
        — checks manager_local_db first (Компанія-Локал merge, Case 1) then
        falls back to their company's row. Unlike _resolve_company_dsn, this
        never touches self._active_company_id/_active_manager_id, so it's
        safe to call for many different managers within one operation
        (Case 2 needs a separate live connection per source simultaneously)."""
        mid = str(manager_id or "").strip()
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT company_id FROM public.managers WHERE id=%s", (mid,)
            )
            row = cur.fetchone()
        if not row:
            raise RuntimeError(f"Manager {mid} не знайдено")
        company_id = str(row.get("company_id") or "")
        manager_dsn = self._resolve_manager_local_dsn(mid)
        if manager_dsn:
            return manager_dsn, company_id
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT db_host, db_port, db_name, db_user, db_password_enc, db_sslmode "
                "FROM public.companies WHERE id=%s",
                (company_id,),
            )
            crow = cur.fetchone()
        if not crow or not str(crow.get("db_name") or "").strip():
            raise RuntimeError(f"У компанії {company_id} немає власної бази даних")
        password = self._decrypt_db_password(crow.get("db_password_enc") or "")
        dsn = self._build_dsn(
            crow.get("db_host") or "127.0.0.1",
            crow.get("db_port") or 5432,
            crow["db_name"],
            crow.get("db_user") or "postgres",
            password,
            crow.get("db_sslmode") or "",
        )
        return dsn, company_id

    def build_category_merge_plan(self, source_manager_ids: list[str]) -> dict:
        """Read-only: fetch every source's FULL categories/level_nodes tree
        for the СуперАдмін manual-review UI. Returns a flat node list (easier
        to render/checkbox in a UI than nested trees) — every node carries
        enough info to reconstruct parent/child relationships:

        {"sources": [{"manager_id","full_name","company_id"}, ...],
         "nodes": [
            {"key": [manager_id, node_id], "kind": "category"|"level"|"supplier",
             "name", "position" (0 for category, 1-6 for level, null for supplier),
             "parent_key": [manager_id, parent_id] or null,
             "category_key": [manager_id, category_id] or null (suppliers)},
            ...
         ]}

        Suppliers are included (as "kind": "supplier") so the СуперАдмін can
        manually merge same-supplier-different-name rows across sources too
        - execute_category_merge treats them the same way as category/level
        groups (one shared new id), just inserted via a dedicated step since
        they're not part of the categories/level_nodes tree. Everything else
        is carried over as-is by execute_category_merge.
        """
        source_manager_ids = [
            str(m).strip() for m in (source_manager_ids or []) if str(m).strip()
        ]
        sources_meta = []
        nodes: list[dict] = []
        for mid in source_manager_ids:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id, full_name, company_id FROM public.managers WHERE id=%s",
                    (mid,),
                )
                mrow = cur.fetchone()
            if not mrow:
                continue
            sources_meta.append(
                {
                    "manager_id": mid,
                    "full_name": mrow.get("full_name"),
                    "company_id": mrow.get("company_id"),
                }
            )
            dsn, _cid = self._resolve_manager_business_dsn(mid)
            conn = psycopg.connect(dsn, autocommit=True, row_factory=dict_row)
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT id, region_id, name FROM categories")
                    cats = cur.fetchall() or []
                    cur.execute(
                        "SELECT id, category_id, position, parent_node_id, name FROM level_nodes"
                    )
                    levels = cur.fetchall() or []
                    cur.execute("SELECT id, region_id, name FROM suppliers")
                    sups = cur.fetchall() or []
                for c in cats:
                    nodes.append(
                        {
                            "key": [mid, c["id"]],
                            "kind": "category",
                            "name": c["name"],
                            "position": 0,
                            "parent_key": None,
                            "category_key": [mid, c["id"]],
                            "region_id": c.get("region_id"),
                        }
                    )
                for lv in levels:
                    parent_raw = str(lv.get("parent_node_id") or "root")
                    parent_key = (
                        None if parent_raw == "root" else [mid, parent_raw]
                    )
                    nodes.append(
                        {
                            "key": [mid, lv["id"]],
                            "kind": "level",
                            "name": lv["name"],
                            "position": lv["position"],
                            "parent_key": parent_key,
                            "category_key": [mid, lv["category_id"]],
                        }
                    )
                for sup in sups:
                    nodes.append(
                        {
                            "key": [mid, sup["id"]],
                            "kind": "supplier",
                            "name": sup["name"],
                            "position": None,
                            "parent_key": None,
                            "category_key": None,
                            "region_id": sup.get("region_id"),
                        }
                    )
            finally:
                conn.close()
        return {"sources": sources_meta, "nodes": nodes}

    def execute_category_merge(
        self,
        source_manager_ids: list[str],
        groups: list[dict],
        target_company_id: str,
        target_region_name: str = "Об'єднаний",
    ) -> tuple[bool, str]:
        """Executes a Case 2 merge decided by the СуперАдмін.

        groups: [{"member_keys": [[manager_id, node_id], ...], "final_name": str}, ...]
        Every node from build_category_merge_plan() NOT listed in any group
        is a "singleton" — copied as-is (original id preserved, since ids are
        globally unique uuids across sources so this can never collide).

        All managers end up under target_company_id (like Case 1, but for a
        VPS target everyone shares the ONE dedicated database directly — no
        manager_local_db routing needed). All sources' business data lands in
        ONE freshly created target region — categories are region-scoped, so
        merging categories across sources requires merging their region too.
        """
        source_manager_ids = [
            str(m).strip() for m in (source_manager_ids or []) if str(m).strip()
        ]
        target_company_id = str(target_company_id or "").strip()
        if not source_manager_ids or not target_company_id:
            return False, "Не вказано джерела або цільову компанію"

        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT storage_mode FROM public.companies WHERE id=%s",
                (target_company_id,),
            )
            target = cur.fetchone()
        if not target:
            return False, "Цільову компанію не знайдено"
        if str(target.get("storage_mode") or "") != "vps":
            return False, "execute_category_merge застосовується лише до storage_mode='vps'"

        plan = self.build_category_merge_plan(source_manager_ids)
        nodes = plan["nodes"]

        # id_map: (manager_id, old_id) -> new_id ; name_map: new_id -> final name
        id_map: dict[tuple, str] = {}
        name_map: dict[str, str] = {}
        for g in groups or []:
            new_id = uuid.uuid4().hex
            for k in g.get("member_keys") or []:
                id_map[tuple(k)] = new_id
            name_map[new_id] = str(g.get("final_name") or "").strip() or "Без назви"
        for n in nodes:
            key = tuple(n["key"])
            if key not in id_map:
                id_map[key] = key[1]  # singleton: keep original id verbatim
                name_map.setdefault(key[1], n["name"])

        now = self._now_ts()
        try:
            # 1. One shared target region for all merged sources' data.
            target_region_id = uuid.uuid4().hex
            with self._pg_for_company(target_company_id).cursor() as tcur:
                tcur.execute(
                    "INSERT INTO regions (id, company_id, name, created_at) VALUES (%s,%s,%s,%s)",
                    (target_region_id, target_company_id, target_region_name, now),
                )

                # 2. Categories first (parent-free), then levels ordered by
                #    position so a level's parent always exists already.
                #    Supplier nodes are handled separately below (step 2b) -
                #    they don't belong in categories/level_nodes.
                inserted_ids: set[str] = set()
                for n in sorted(
                    (n for n in nodes if n["kind"] in ("category", "level")),
                    key=lambda x: (0 if x["kind"] == "category" else 1, x["position"]),
                ):
                    key = tuple(n["key"])
                    new_id = id_map[key]
                    if new_id in inserted_ids:
                        continue
                    inserted_ids.add(new_id)
                    final_name = name_map[new_id]
                    if n["kind"] == "category":
                        tcur.execute(
                            "INSERT INTO categories (id, company_id, region_id, name, data, created_at, updated_at) "
                            "VALUES (%s,%s,%s,%s,%s::jsonb,%s,%s)",
                            (
                                new_id, target_company_id, target_region_id, final_name,
                                psycopg.types.json.Jsonb({}), now, now,
                            ),
                        )
                    else:
                        parent_key = n.get("parent_key")
                        parent_new_id = (
                            "root" if not parent_key else id_map.get(tuple(parent_key), "root")
                        )
                        category_new_id = id_map[tuple(n["category_key"])]
                        tcur.execute(
                            "INSERT INTO level_nodes (id, category_id, position, parent_node_id, name, data, created_at, updated_at) "
                            "VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)",
                            (
                                new_id, category_new_id, n["position"], parent_new_id,
                                final_name, psycopg.types.json.Jsonb({}), now, now,
                            ),
                        )

                # 2b. Suppliers - same id_map/name_map grouping as categories/
                #     levels above, but the plan only carried id/region_id/
                #     name (for the review UI), so full rows are re-fetched
                #     from each source here and merged via the same
                #     fill-missing-fields helper used elsewhere for supplier
                #     merges (_merge_supplier_payload_fill_missing).
                supplier_nodes = [n for n in nodes if n["kind"] == "supplier"]
                supplier_payloads: dict[str, dict] = {}
                for mid in source_manager_ids:
                    src_nodes = [n for n in supplier_nodes if n["key"][0] == mid]
                    if not src_nodes:
                        continue
                    src_dsn, _cid = self._resolve_manager_business_dsn(mid)
                    src_conn = psycopg.connect(
                        src_dsn, autocommit=True, row_factory=dict_row
                    )
                    try:
                        with src_conn.cursor() as scur:
                            scur.execute(
                                "SELECT id, data FROM suppliers WHERE id = ANY(%s)",
                                ([n["key"][1] for n in src_nodes],),
                            )
                            rows_by_id = {
                                str(r["id"]): r for r in (scur.fetchall() or [])
                            }
                    finally:
                        src_conn.close()
                    for n in src_nodes:
                        row = rows_by_id.get(n["key"][1])
                        if not row:
                            continue
                        new_id = id_map[tuple(n["key"])]
                        row_data = (
                            row.get("data")
                            if isinstance(row.get("data"), dict)
                            else {}
                        )
                        if new_id not in supplier_payloads:
                            supplier_payloads[new_id] = row_data
                        else:
                            supplier_payloads[new_id] = (
                                self._merge_supplier_payload_fill_missing(
                                    supplier_payloads[new_id], row_data
                                )
                            )
                for new_id, merged_data in supplier_payloads.items():
                    tcur.execute(
                        "INSERT INTO suppliers (id, company_id, region_id, name, data, created_at, updated_at) "
                        "VALUES (%s,%s,%s,%s,%s::jsonb,%s,%s)",
                        (
                            new_id,
                            target_company_id,
                            target_region_id,
                            name_map.get(new_id, "Постачальник"),
                            psycopg.types.json.Jsonb(merged_data),
                            now,
                            now,
                        ),
                    )

            # 3. Copy every other business table from each source verbatim,
            #    remapping company_id/region_id, and — for products/packaging/
            #    orders — any category_id/catalog_node_id/category_name/
            #    supplier_id references (suppliers are excluded here since
            #    step 2b above already inserted them, merged where grouped).
            EXCLUDED_TABLES = {
                "categories",
                "level_nodes",
                "catalog_nodes",
                "regions",
                "suppliers",
            }
            for mid in source_manager_ids:
                src_dsn, _cid = self._resolve_manager_business_dsn(mid)
                src_conn = psycopg.connect(src_dsn, autocommit=True, row_factory=dict_row)
                try:
                    with src_conn.cursor() as scur:
                        scur.execute(
                            "SELECT table_name FROM information_schema.tables "
                            "WHERE table_schema='public' AND table_type='BASE TABLE'"
                        )
                        table_names = [
                            r["table_name"] for r in (scur.fetchall() or [])
                            if r["table_name"] not in EXCLUDED_TABLES
                        ]
                    for table in table_names:
                        self._copy_merge_table(
                            src_conn, table, mid, target_company_id, target_region_id, id_map, name_map,
                        )
                finally:
                    src_conn.close()

            # 4. Managers move to the target company (VPS — everyone shares
            #    the one dedicated database directly, no per-manager routing).
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.managers SET company_id=%s, account_kind='company', "
                    "updated_at=%s WHERE id = ANY(%s)",
                    (target_company_id, now, source_manager_ids),
                )
        except Exception as exc:
            logger.exception("execute_category_merge failed")
            return False, f"Помилка злиття: {exc}"

        with contextlib.suppress(Exception):
            self.sync_company_catalog_nodes(target_company_id)
        self._pulse(target_company_id, "company")
        logger.info(
            "execute_category_merge: merged %d sources into company_id=%s",
            len(source_manager_ids),
            target_company_id,
        )
        return True, ""

    def _pg_for_company(self, company_id: str) -> psycopg.Connection:
        """Ad-hoc connection to a company's own dedicated DB, independent of
        self._active_company_id — used by execute_category_merge so it never
        disturbs whatever the caller's active session context is."""
        dsn = self._resolve_company_dsn(company_id)
        return psycopg.connect(dsn, autocommit=True, row_factory=dict_row)

    def _copy_merge_table(
        self,
        src_conn: psycopg.Connection,
        table: str,
        source_manager_id: str,
        target_company_id: str,
        target_region_id: str,
        id_map: dict[tuple, str],
        name_map: dict[str, str],
    ) -> None:
        """Copy every row of `table` from src_conn into the target company's
        DB, remapping company_id/region_id columns where present, plus any
        literal category_id/node_id columns (ownership tables like
        category_access/node_owners reference nodes this way). products
        additionally gets its data->>'category_id'/'catalog_node_id'/
        'category_name' rewritten via id_map/name_map (see module docstring
        on execute_category_merge for why only categories/levels merge while
        everything else is a verbatim per-manager copy)."""
        with src_conn.cursor() as scur:
            scur.execute(
                "SELECT column_name FROM information_schema.columns "
                "WHERE table_schema='public' AND table_name=%s",
                (table,),
            )
            columns = [r["column_name"] for r in (scur.fetchall() or [])]
            if not columns:
                return
            scur.execute(f'SELECT * FROM "{table}"')
            rows = scur.fetchall() or []
        if not rows:
            return

        has_company = "company_id" in columns
        has_region = "region_id" in columns
        is_products = table == "products"
        is_packaging = table == "packaging"
        is_orders = table == "orders"

        def _remap_supplier_id(raw_id: Any) -> str | None:
            old_id = str(raw_id or "").strip()
            if not old_id:
                return None
            return id_map.get((source_manager_id, old_id))

        with self._pg_for_company(target_company_id).cursor() as tcur:
            for row in rows:
                values = dict(row)
                if has_company:
                    values["company_id"] = target_company_id
                if has_region:
                    values["region_id"] = target_region_id
                for id_col in (
                    "category_id",
                    "node_id",
                    "parent_node_id",
                    "supplier_id",
                    "goods_supplier_id",
                    "packaging_supplier_id",
                ):
                    if id_col in columns and values.get(id_col):
                        remapped = id_map.get((source_manager_id, str(values[id_col])))
                        if remapped:
                            values[id_col] = remapped
                if is_products and isinstance(values.get("data"), dict):
                    data = dict(values["data"])
                    old_cat = str(data.get("category_id") or "")
                    old_node = str(data.get("catalog_node_id") or "")
                    if old_cat:
                        new_cat = id_map.get((source_manager_id, old_cat))
                        if new_cat:
                            data["category_id"] = new_cat
                            data["category_name"] = name_map.get(new_cat, data.get("category_name"))
                    if old_node:
                        new_node = id_map.get((source_manager_id, old_node))
                        if new_node:
                            data["catalog_node_id"] = new_node
                    new_supplier = _remap_supplier_id(data.get("supplier_id"))
                    if new_supplier:
                        data["supplier_id"] = new_supplier
                    values["data"] = data
                elif is_packaging and isinstance(values.get("data"), dict):
                    data = dict(values["data"])
                    new_supplier = _remap_supplier_id(data.get("supplier_id"))
                    if new_supplier:
                        data["supplier_id"] = new_supplier
                    values["data"] = data
                elif is_orders and isinstance(values.get("data"), dict):
                    data = dict(values["data"])
                    new_supplier = _remap_supplier_id(data.get("supplier_id"))
                    if new_supplier:
                        data["supplier_id"] = new_supplier
                    items = data.get("items")
                    if isinstance(items, list):
                        new_items = []
                        for item in items:
                            if isinstance(item, dict):
                                item = dict(item)
                                new_item_supplier = _remap_supplier_id(
                                    item.get("supplier_id")
                                )
                                if new_item_supplier:
                                    item["supplier_id"] = new_item_supplier
                            new_items.append(item)
                        data["items"] = new_items
                    values["data"] = data
                # Generic: ANY dict/list-valued column (data/meta/config/tiers/
                # state/...) needs an explicit Jsonb wrapper — psycopg won't
                # auto-adapt a bare Python dict/list.
                for col, val in list(values.items()):
                    if isinstance(val, (dict, list)):
                        values[col] = psycopg.types.json.Jsonb(val)

                cols_sql = ", ".join(f'"{c}"' for c in columns)
                placeholders = ", ".join(["%s"] * len(columns))
                tcur.execute(
                    f'INSERT INTO "{table}" ({cols_sql}) VALUES ({placeholders}) '
                    f'ON CONFLICT DO NOTHING',
                    [values.get(c) for c in columns],
                )

    def create_manager(self, payload: dict) -> str:
        """
        payload expects: company_id, full_name, email, phone, password, role (optional)
        Returns manager id.
        """
        if not self._use_postgres():
            return str(self._post("/managers/create", payload) or "")
        company_id = str((payload or {}).get("company_id") or "").strip()
        full_name = str((payload or {}).get("full_name") or "").strip() or "Користувач"
        email = str((payload or {}).get("email") or "").strip().lower()
        phone = str((payload or {}).get("phone") or "").strip()
        password = str((payload or {}).get("password") or "")
        role = self._normalize_role((payload or {}).get("role"))
        if not role:
            role = "manager"
        approved = bool((payload or {}).get("is_approved", True))
        mid = uuid.uuid4().hex
        now = self._now_ts()
        pw_hash = self._hash_password(password)
        meta = {
            # store original label if provided
            "role_label": (payload or {}).get("role") or "",
            # access-control fields will live here (allowed_region_ids, scopes, supervisors, etc.)
        }
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT account_kind FROM public.companies WHERE id=%s", (company_id,)
            )
            row = cur.fetchone()
            account_kind = str((row or {}).get("account_kind") or "company")
            cur.execute(
                """
                INSERT INTO public.managers
                  (id, company_id, full_name, email, phone, role, password_hash, is_approved, meta, created_at, updated_at, account_kind)
                VALUES
                  (%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s,%s)
                """,
                (
                    mid,
                    company_id,
                    full_name,
                    email,
                    phone,
                    role,
                    pw_hash,
                    approved,
                    psycopg.types.json.Jsonb(meta),
                    now,
                    now,
                    account_kind,
                ),
            )
        return mid

    # ----------------- core reads for dashboards (Postgres mode) -----------------
    def get_company_categories(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        archived: bool | None = False,
    ):
        if not self._use_postgres():
            return (
                self._get(
                    "/categories",
                    {"company_id": company_id, "region_id": region_id or ""},
                )
                or []
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()
        if manager_id:
            return self.get_accessible_categories(
                company_id, manager_id, (region_id or None), archived=archived
            )
        archived_clause = (
            "" if archived is None else ("AND is_archived=TRUE" if archived else "AND is_archived=FALSE")
        )
        with self._pg().cursor() as cur:
            if region_id:
                cur.execute(
                    f"""
                    SELECT id, company_id, region_id, name, data, created_at, updated_at
                    FROM categories
                    WHERE company_id=%s AND region_id=%s {archived_clause}
                    ORDER BY name ASC
                    """,
                    (company_id, region_id),
                )
            else:
                cur.execute(
                    f"""
                    SELECT id, company_id, region_id, name, data, created_at, updated_at
                    FROM categories
                    WHERE company_id=%s {archived_clause}
                    ORDER BY name ASC
                    """,
                    (company_id,),
                )
            return cur.fetchall() or []

    # ----------------- categories / hierarchy (Postgres mode) -----------------
    def _default_category_levels_config(self) -> dict:
        # Keep shape stable for UI: exactly 6 levels.
        return {
            "levels": [
                {"position": i, "title": f"Рівень {i}", "enabled": (i <= 2)}
                for i in range(1, 7)
            ],
            "use_products": True,
        }

    def get_category_levels_config(self, category_row: dict | None):
        """
        Returns dict: {"levels":[{position,title,enabled}...], "use_products": bool, ...}
        category_row may be a category dict/row, or None for default.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/categories/levels_config",
                    {"category_id": (category_row or {}).get("id", "")},
                )
                or {}
            )
        if not isinstance(category_row, dict) or not category_row.get("id"):
            return self._default_category_levels_config()
        data = (
            category_row.get("data")
            if isinstance(category_row.get("data"), dict)
            else {}
        )
        cfg = (
            data.get("hierarchy_config")
            if isinstance(data.get("hierarchy_config"), dict)
            else {}
        )
        levels = cfg.get("levels") if isinstance(cfg.get("levels"), list) else []
        out_levels: list[dict] = []
        for row in levels:
            if not isinstance(row, dict):
                continue
            try:
                pos = int(row.get("position") or 0)
            except Exception:
                continue
            if pos < 1 or pos > 6:
                continue
            out_levels.append(
                {
                    "position": pos,
                    "title": str(row.get("title") or f"Рівень {pos}").strip()
                    or f"Рівень {pos}",
                    "enabled": bool(row.get("enabled")),
                }
            )
        out_levels.sort(key=lambda x: int(x.get("position") or 0))
        if not out_levels:
            out_levels = self._default_category_levels_config().get("levels") or []
        return {
            "levels": out_levels,
            "use_products": bool(cfg.get("use_products", True)),
            "target_margin_percent": cfg.get("target_margin_percent"),
        }

    def get_category_target_margin(self, category_row: dict | str | None):
        """
        UI expects a numeric target margin (float) or None.
        Accepts category row/dict with optional `data` jsonb.
        """
        if not self._use_postgres():
            return self._get(
                "/categories/target_margin",
                {"category_id": (category_row or {}).get("id", "")},
            )
        # Allow passing category_id string (some views call it this way).
        if isinstance(category_row, str):
            cat_id = str(category_row or "").strip()
            if not cat_id:
                return None
            with contextlib.suppress(Exception):
                with self._pg().cursor() as cur:
                    cur.execute(
                        "SELECT id, name, data FROM categories WHERE id=%s LIMIT 1",
                        (cat_id,),
                    )
                    category_row = cur.fetchone() or {}
            if not isinstance(category_row, dict):
                return None
        if not isinstance(category_row, dict):
            return None
        # Prefer explicit top-level field if present in row dict
        for key in ("target_margin_percent", "target_margin", "target_margin_pct"):
            if key in category_row and category_row.get(key) not in (None, ""):
                with contextlib.suppress(Exception):
                    return float(str(category_row.get(key)).replace(",", "."))

        data = (
            category_row.get("data")
            if isinstance(category_row.get("data"), dict)
            else {}
        )
        # common locations
        candidates = []
        if isinstance(data, dict):
            candidates.append(data.get("target_margin_percent"))
            hc = (
                data.get("hierarchy_config")
                if isinstance(data.get("hierarchy_config"), dict)
                else {}
            )
            candidates.append(
                hc.get("target_margin_percent") if isinstance(hc, dict) else None
            )
        for v in candidates:
            if v in (None, ""):
                continue
            with contextlib.suppress(Exception):
                return float(str(v).replace(",", "."))
        return None

    def category_name_exists(
        self,
        company_id: str,
        region_id: str,
        name: str,
        exclude_category_id: str | None = None,
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._get(
                    "/categories/name_exists",
                    {
                        "company_id": company_id,
                        "region_id": region_id,
                        "name": name,
                        "exclude_category_id": exclude_category_id or "",
                    },
                )
                or False
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        name = str(name or "").strip()
        exclude_category_id = str(exclude_category_id or "").strip()
        if not company_id or not region_id or not name:
            return False
        with self._pg().cursor() as cur:
            if exclude_category_id:
                cur.execute(
                    """
                    SELECT 1
                    FROM categories
                    WHERE company_id=%s AND region_id=%s AND lower(name)=lower(%s) AND id<>%s
                    LIMIT 1
                    """,
                    (company_id, region_id, name, exclude_category_id),
                )
            else:
                cur.execute(
                    """
                    SELECT 1
                    FROM categories
                    WHERE company_id=%s AND region_id=%s AND lower(name)=lower(%s)
                    LIMIT 1
                    """,
                    (company_id, region_id, name),
                )
            return bool(cur.fetchone())

    def create_category_with_access(
        self,
        company_id: str,
        region_id: str,
        name: str,
        manager_id: str | None = None,  # noqa: ARG002 - kept for API compatibility
        hierarchy_config: dict | None = None,
    ) -> str:
        """
        Creates category row in `categories`.
        Access rows (category_access) are handled separately by `replace_category_access()`.
        Returns created category id (string) or "" on failure.
        """
        if not self._use_postgres():
            payload = {
                "company_id": company_id,
                "region_id": region_id,
                "name": name,
                "manager_id": manager_id or "",
                "hierarchy_config": hierarchy_config or {},
            }
            return str(self._post("/categories/create_with_access", payload) or "")

        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        name = str(name or "").strip()
        if not company_id or not region_id or not name:
            return ""

        cat_id = uuid.uuid4().hex
        now = self._now_ts()
        cfg = hierarchy_config if isinstance(hierarchy_config, dict) else {}
        data = {
            "hierarchy_config": {
                **self._default_category_levels_config(),
                **cfg,
            }
        }
        # Preserve top-level convenience fields if provided.
        if isinstance(cfg.get("target_margin_percent"), (int, float, str)) and cfg.get(
            "target_margin_percent"
        ) not in (None, ""):
            with contextlib.suppress(Exception):
                data["target_margin_percent"] = float(
                    str(cfg.get("target_margin_percent")).replace(",", ".")
                )

        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO categories
                      (id, company_id, region_id, name, data, created_at, updated_at)
                    VALUES
                      (%s,%s,%s,%s,%s::jsonb,%s,%s)
                    """,
                    (
                        cat_id,
                        company_id,
                        region_id,
                        name,
                        psycopg.types.json.Jsonb(data),
                        now,
                        now,
                    ),
                )
        except Exception:
            logger.exception("create_category_with_access failed")
            return ""

        self._pulse(company_id, "catalog")
        return cat_id

    def update_category(
        self,
        category_id: str,
        name: str | None = None,
        hierarchy_config: dict | None = None,
        manager_id: str | None = None,  # noqa: ARG002
        lock_token: str | None = None,  # noqa: ARG002
    ) -> bool:
        if not self._use_postgres():
            payload = {
                "category_id": category_id,
                "name": name or "",
                "hierarchy_config": hierarchy_config or {},
                "manager_id": manager_id or "",
                "lock_token": lock_token or "",
            }
            return bool(self._post("/categories/update", payload) or False)
        category_id = str(category_id or "").strip()
        if not category_id:
            return False

        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id, data FROM categories WHERE id=%s",
                (category_id,),
            )
            row = cur.fetchone() or {}
        company_id = str((row or {}).get("company_id") or "").strip()
        current_data = (
            (row or {}).get("data") if isinstance((row or {}).get("data"), dict) else {}
        )

        sets = []
        params: list[Any] = []
        if isinstance(name, str) and name.strip():
            sets.append("name=%s")
            params.append(name.strip())
        if isinstance(hierarchy_config, dict):
            new_cfg = {
                **self._default_category_levels_config(),
                **hierarchy_config,
            }
            merged = dict(current_data or {})
            merged["hierarchy_config"] = new_cfg
            sets.append("data=%s::jsonb")
            params.append(psycopg.types.json.Jsonb(merged))
        sets.append("updated_at=%s")
        params.append(self._now_ts())
        params.append(category_id)
        q = "UPDATE categories SET " + ", ".join(sets) + " WHERE id=%s"
        with self._pg().cursor() as cur:
            cur.execute(q, params)
        new_name = name.strip() if isinstance(name, str) and name.strip() else None
        if company_id and new_name is not None:
            self._sync_category_references(
                company_id, category_id, category_name=new_name, deleted=False
            )
        if company_id:
            self._pulse(company_id, "catalog")
            self._pulse(company_id, "products")
        return True

    def archive_category(
        self,
        category_id: str,
        manager_id: str | None = None,  # noqa: ARG002 - kept for call-site compatibility
        lock_token: str | None = None,  # noqa: ARG002
    ) -> bool:
        """
        Soft-архівує категорію (замість фізичного видалення): ховає її та каскадно
        всі її level_nodes/subcategories/series/brands, не чіпаючи записи товарів/
        замовлень, що на неї посилаються (вони й далі резолвлять назву по id).
        """
        if not self._use_postgres():
            return bool(
                self._post("/categories/archive", {"category_id": category_id}) or False
            )
        category_id = str(category_id or "").strip()
        if not category_id:
            return False
        ts = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute("SELECT company_id FROM categories WHERE id=%s", (category_id,))
            row = cur.fetchone() or {}
            company_id = str((row or {}).get("company_id") or "").strip()
            for table in ("level_nodes", "subcategories", "series", "brands"):
                with contextlib.suppress(Exception):
                    cur.execute(
                        f"UPDATE {table} SET is_archived=TRUE, archived_at=%s WHERE category_id=%s",
                        (ts, category_id),
                    )
            cur.execute(
                "UPDATE categories SET is_archived=TRUE, archived_at=%s, updated_at=%s WHERE id=%s",
                (ts, ts, category_id),
            )
        if company_id:
            self._pulse(company_id, "catalog")
            self._pulse(company_id, "products")
        return True

    def restore_category(self, category_id: str) -> bool:
        """Відновлює архівовану категорію разом з рівнями/підкатегоріями/серіями/брендами,
        заархівованими одночасно з нею (той самий archived_at)."""
        category_id = str(category_id or "").strip()
        if not category_id or not self._use_postgres():
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id, archived_at FROM categories WHERE id=%s", (category_id,)
            )
            row = cur.fetchone() or {}
            company_id = str((row or {}).get("company_id") or "").strip()
            archived_at = (row or {}).get("archived_at")
            cur.execute(
                "UPDATE categories SET is_archived=FALSE, archived_at=NULL WHERE id=%s",
                (category_id,),
            )
            if archived_at is not None:
                for table in ("level_nodes", "subcategories", "series", "brands"):
                    with contextlib.suppress(Exception):
                        cur.execute(
                            f"UPDATE {table} SET is_archived=FALSE, archived_at=NULL "
                            f"WHERE category_id=%s AND archived_at=%s",
                            (category_id, archived_at),
                        )
        if company_id:
            self._pulse(company_id, "catalog")
            self._pulse(company_id, "products")
        return True

