    def _count_products_by_data_field(
        self, company_id: str, field: str, ids: list[str]
    ) -> int:
        """How many products reference any of `ids` via data->>field - e.g.
        field='category_id'/'catalog_node_id'/'subcategory_id'/'brand_id'/
        'series_id'/'supplier_id'. `field` is bound as a parameter (a JSON
        key, not a column name) so this is safe to call with a fixed set of
        known keys."""
        cid = str(company_id or "").strip()
        clean_ids = [str(x).strip() for x in (ids or []) if str(x).strip()]
        if not self._use_postgres() or not cid or not clean_ids:
            return 0
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT count(*) AS n FROM products WHERE company_id=%s AND data->>%s = ANY(%s)",
                (cid, field, clean_ids),
            )
            row = cur.fetchone() or {}
        return int(row.get("n") or 0)

    def _force_delete_products_and_dependents(
        self, company_id: str, product_ids: list
    ) -> dict:
        """
        Admin-only force delete: given a set of product ids that are about to
        be removed (because their catalog category/level is being force-
        deleted), cascade-remove everything that hangs off them — schedule
        tasks/groups, media plan entries, cost-price stock inputs, orders
        that contain them (and those orders' own cost-price inputs) — plus
        their entity_owners rows. Without this, force-deleting the category
        would leave dangling product_id references scattered across half a
        dozen tables. Not used by the default (non-force) delete path, which
        refuses outright instead.
        """
        cid = str(company_id or "").strip()
        pids = sorted({str(x).strip() for x in (product_ids or []) if str(x).strip()})
        counts = {
            "products": 0, "orders": 0, "schedule_groups": 0,
            "schedule_tasks": 0, "media_plan": 0,
        }
        if not self._use_postgres() or not cid or not pids:
            return counts
        pid_set = set(pids)
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT id, product_ids FROM order_schedule_groups WHERE company_id=%s",
                (cid,),
            )
            group_ids = [
                str(r.get("id"))
                for r in (cur.fetchall() or [])
                if isinstance(r, dict)
                and (set(self._normalize_json_list(r.get("product_ids"))) & pid_set)
            ]
            task_ids: list[str] = []
            if group_ids:
                cur.execute(
                    "SELECT id FROM order_schedule_tasks WHERE group_id = ANY(%s)",
                    (group_ids,),
                )
                task_ids = [
                    str(r.get("id")) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]

            cur.execute(
                "SELECT id, product_ids FROM media_plan_entries WHERE company_id=%s",
                (cid,),
            )
            media_ids = [
                str(r.get("id"))
                for r in (cur.fetchall() or [])
                if isinstance(r, dict)
                and (set(self._normalize_json_list(r.get("product_ids"))) & pid_set)
            ]

            cur.execute(
                """
                SELECT id FROM orders o
                WHERE o.company_id=%s
                  AND EXISTS (
                      SELECT 1
                      FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) it
                      WHERE (it->>'product_id') = ANY(%s)
                  )
                """,
                (cid, pids),
            )
            order_ids = [
                str(r.get("id")) for r in (cur.fetchall() or []) if isinstance(r, dict)
            ]

            if task_ids:
                cur.execute("DELETE FROM order_schedule_tasks WHERE id = ANY(%s)", (task_ids,))
                cur.execute(
                    "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='schedule_task' AND entity_id = ANY(%s)",
                    (cid, task_ids),
                )
            if group_ids:
                cur.execute("DELETE FROM order_schedule_groups WHERE id = ANY(%s)", (group_ids,))
                cur.execute(
                    "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='schedule_group' AND entity_id = ANY(%s)",
                    (cid, group_ids),
                )
            if media_ids:
                cur.execute("DELETE FROM media_plan_entries WHERE id = ANY(%s)", (media_ids,))
                cur.execute(
                    "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='media_plan' AND entity_id = ANY(%s)",
                    (cid, media_ids),
                )

            cur.execute(
                "DELETE FROM cost_price_stock_inputs WHERE company_id=%s AND product_id = ANY(%s)",
                (cid, pids),
            )

            if order_ids:
                cur.execute(
                    "DELETE FROM cost_price_order_inputs WHERE company_id=%s AND order_id = ANY(%s)",
                    (cid, order_ids),
                )
                cur.execute("DELETE FROM orders WHERE id = ANY(%s)", (order_ids,))
                cur.execute(
                    "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='order' AND entity_id = ANY(%s)",
                    (cid, order_ids),
                )

            cur.execute("DELETE FROM products WHERE company_id=%s AND id = ANY(%s)", (cid, pids))
            cur.execute(
                "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='product' AND entity_id = ANY(%s)",
                (cid, pids),
            )

        counts = {
            "products": len(pids),
            "orders": len(order_ids),
            "schedule_groups": len(group_ids),
            "schedule_tasks": len(task_ids),
            "media_plan": len(media_ids),
        }
        logger.info(
            "_force_delete_products_and_dependents company=%s -> %s", cid, counts
        )
        return counts

    def delete_category(
        self, company_id: str, category_id: str, force: bool = False
    ) -> tuple[bool, str]:
        """Hard-delete a category (and its level_nodes/subcategories/series/
        brands) - only when NOTHING references it. Unlike archive_category,
        this permanently removes the rows; use archive instead if the
        category (or anything under it) is actually in use. Pass force=True
        (admin-only, from the UI) to cascade-delete every product under it
        instead of refusing — see _force_delete_products_and_dependents."""
        cid = str(company_id or "").strip()
        catid = str(category_id or "").strip()
        if not self._use_postgres() or not cid or not catid:
            return False, "Некоректні дані"
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT id FROM level_nodes WHERE category_id=%s", (catid,)
            )
            level_ids = [
                str(r.get("id") or "").strip()
                for r in (cur.fetchall() or [])
                if isinstance(r, dict) and str(r.get("id") or "").strip()
            ]
            cur.execute(
                "SELECT id FROM subcategories WHERE category_id=%s", (catid,)
            )
            subcat_ids = [
                str(r.get("id") or "").strip()
                for r in (cur.fetchall() or [])
                if isinstance(r, dict) and str(r.get("id") or "").strip()
            ]
            cur.execute("SELECT id FROM series WHERE category_id=%s", (catid,))
            series_ids = [
                str(r.get("id") or "").strip()
                for r in (cur.fetchall() or [])
                if isinstance(r, dict) and str(r.get("id") or "").strip()
            ]
            cur.execute("SELECT id FROM brands WHERE category_id=%s", (catid,))
            brand_ids = [
                str(r.get("id") or "").strip()
                for r in (cur.fetchall() or [])
                if isinstance(r, dict) and str(r.get("id") or "").strip()
            ]

        used = self._count_products_by_data_field(
            cid, "category_id", [catid]
        ) or self._count_products_by_data_field(
            cid, "catalog_node_id", [catid] + level_ids
        )
        if not used and subcat_ids:
            used = self._count_products_by_data_field(
                cid, "subcategory_id", subcat_ids
            )
        if not used and brand_ids:
            used = self._count_products_by_data_field(cid, "brand_id", brand_ids)
        if not used and series_ids:
            used = self._count_products_by_data_field(cid, "series_id", series_ids)
        if used and not force:
            return False, (
                f"Категорію використовують {used} товар(ів) - "
                "спочатку заархівуйте, видалити не можна"
            )

        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT count(*) AS n FROM order_schedule_groups WHERE company_id=%s AND category_id=%s",
                (cid, catid),
            )
            schedule_n = int((cur.fetchone() or {}).get("n") or 0)
        if schedule_n and not force:
            return False, (
                f"Категорію використовують {schedule_n} групи розкладу замовлень - "
                "спочатку заархівуйте, видалити не можна"
            )

        deleted_products = 0
        if force and (used or schedule_n):
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM products WHERE company_id=%s AND (data->>'category_id' = %s OR data->>'catalog_node_id' = ANY(%s))",
                    (cid, catid, [catid] + level_ids),
                )
                product_ids = [
                    str(r.get("id")) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]
                cur.execute(
                    "DELETE FROM order_schedule_tasks WHERE group_id IN (SELECT id FROM order_schedule_groups WHERE company_id=%s AND category_id=%s)",
                    (cid, catid),
                )
                cur.execute(
                    "DELETE FROM order_schedule_groups WHERE company_id=%s AND category_id=%s",
                    (cid, catid),
                )
            if product_ids:
                self._force_delete_products_and_dependents(cid, product_ids)
            deleted_products = len(product_ids)

        all_node_ids = level_ids + subcat_ids + series_ids + brand_ids + [catid]
        with self._pg().cursor() as cur:
            cur.execute("DELETE FROM level_nodes WHERE category_id=%s", (catid,))
            cur.execute("DELETE FROM subcategories WHERE category_id=%s", (catid,))
            cur.execute("DELETE FROM series WHERE category_id=%s", (catid,))
            cur.execute("DELETE FROM brands WHERE category_id=%s", (catid,))
            cur.execute("DELETE FROM categories WHERE id=%s", (catid,))
            cur.execute(
                "DELETE FROM node_owners WHERE company_id=%s AND node_id = ANY(%s)",
                (cid, all_node_ids),
            )
            with contextlib.suppress(Exception):
                cur.execute(
                    "DELETE FROM category_access WHERE category_id=%s", (catid,)
                )
        with contextlib.suppress(Exception):
            self.sync_company_catalog_nodes(cid)
        self._pulse(cid, "catalog")
        self._pulse(cid, "products")
        if deleted_products:
            return True, f"Категорію видалено разом з {deleted_products} товар(ів)"
        return True, "Категорію видалено"

    def _delete_leaf_catalog_row(
        self, table: str, id_field: str, company_id: str, row_id: str
    ) -> tuple[bool, str]:
        """Shared body for delete_subcategory/delete_series/delete_brand -
        leaf nodes, no children to cascade, just a usage-check then delete."""
        cid = str(company_id or "").strip()
        rid = str(row_id or "").strip()
        if not self._use_postgres() or not cid or not rid:
            return False, "Некоректні дані"
        used = self._count_products_by_data_field(cid, id_field, [rid])
        if used:
            return False, (
                f"Використовується {used} товар(ами) - "
                "спочатку заархівуйте, видалити не можна"
            )
        with self._pg().cursor() as cur:
            cur.execute(f"DELETE FROM {table} WHERE company_id=%s AND id=%s", (cid, rid))
        self._pulse(cid, "catalog")
        return True, "Видалено"

    def delete_subcategory(self, company_id: str, subcategory_id: str) -> tuple[bool, str]:
        return self._delete_leaf_catalog_row(
            "subcategories", "subcategory_id", company_id, subcategory_id
        )

    def delete_series(self, company_id: str, series_id: str) -> tuple[bool, str]:
        return self._delete_leaf_catalog_row(
            "series", "series_id", company_id, series_id
        )

    def delete_brand(self, company_id: str, brand_id: str) -> tuple[bool, str]:
        return self._delete_leaf_catalog_row(
            "brands", "brand_id", company_id, brand_id
        )

    def delete_product(self, company_id: str, product_id: str) -> tuple[bool, str]:
        """Hard-delete a product - only when it's not referenced by any
        order/schedule/cost-price/media-plan/packaging-context row. Unlike
        archive_product, this permanently removes the row."""
        cid = str(company_id or "").strip()
        pid = str(product_id or "").strip()
        if not self._use_postgres() or not cid or not pid:
            return False, "Некоректні дані"
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT count(*) AS n FROM orders
                WHERE company_id=%s AND EXISTS (
                    SELECT 1 FROM jsonb_array_elements(COALESCE(data->'items','[]'::jsonb)) it
                    WHERE (it->>'product_id')=%s
                )
                """,
                (cid, pid),
            )
            orders_n = int((cur.fetchone() or {}).get("n") or 0)

            cur.execute(
                "SELECT count(*) AS n FROM cost_price_stock_inputs WHERE company_id=%s AND product_id=%s",
                (cid, pid),
            )
            stock_n = int((cur.fetchone() or {}).get("n") or 0)

            cur.execute(
                "SELECT count(*) AS n FROM media_plan_entries WHERE company_id=%s AND product_ids ? %s",
                (cid, pid),
            )
            media_n = int((cur.fetchone() or {}).get("n") or 0)

            cur.execute(
                "SELECT count(*) AS n FROM order_schedule_groups WHERE company_id=%s AND product_ids ? %s",
                (cid, pid),
            )
            schedule_n = int((cur.fetchone() or {}).get("n") or 0)

            cur.execute(
                "SELECT count(*) AS n FROM packaging_supply_contexts WHERE company_id=%s AND linked_product_ids ? %s",
                (cid, pid),
            )
            packaging_ctx_n = int((cur.fetchone() or {}).get("n") or 0)

        used = orders_n + stock_n + media_n + schedule_n + packaging_ctx_n
        if used:
            return False, (
                f"Товар використовується (замовлення: {orders_n}, собівартість: {stock_n}, "
                f"медіаплан: {media_n}, розклад: {schedule_n}, паковання: {packaging_ctx_n}) - "
                "спочатку заархівуйте, видалити не можна"
            )

        with self._pg().cursor() as cur:
            cur.execute("DELETE FROM products WHERE company_id=%s AND id=%s", (cid, pid))
            cur.execute(
                "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='product' AND entity_id=%s",
                (cid, pid),
            )
        self._pulse(cid, "products")
        return True, "Товар видалено"

    def delete_supplier(self, company_id: str, supplier_id: str) -> tuple[bool, str]:
        """Hard-delete a supplier - only when nothing references it (unlike
        apply_supplier_merge_groups, there's nowhere to repoint TO in a
        plain delete). Use archive instead if it's actually in use."""
        cid = str(company_id or "").strip()
        sid = str(supplier_id or "").strip()
        if not self._use_postgres() or not cid or not sid:
            return False, "Некоректні дані"

        products_n = self._count_products_by_data_field(cid, "supplier_id", [sid])
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT count(*) AS n FROM packaging WHERE company_id=%s AND data->>'supplier_id'=%s",
                (cid, sid),
            )
            packaging_n = int((cur.fetchone() or {}).get("n") or 0)

            cur.execute(
                """
                SELECT count(*) AS n FROM orders
                WHERE company_id=%s AND (
                    supplier_id=%s
                    OR COALESCE(data->>'supplier_id','')=%s
                    OR EXISTS (
                        SELECT 1 FROM jsonb_array_elements(COALESCE(data->'items','[]'::jsonb)) it
                        WHERE COALESCE(it->>'supplier_id','')=%s
                    )
                )
                """,
                (cid, sid, sid, sid),
            )
            orders_n = int((cur.fetchone() or {}).get("n") or 0)

            settlements_n = 0
            with contextlib.suppress(Exception):
                cur.execute(
                    "SELECT count(*) AS n FROM supplier_settlements WHERE company_id=%s AND supplier_id=%s",
                    (cid, sid),
                )
                settlements_n = int((cur.fetchone() or {}).get("n") or 0)

        used = products_n + packaging_n + orders_n + settlements_n
        if used:
            return False, (
                f"Постачальника використовують (товари: {products_n}, паковання: {packaging_n}, "
                f"замовлення: {orders_n}, взаєморозрахунки: {settlements_n}) - "
                "спочатку заархівуйте, видалити не можна"
            )

        with self._pg().cursor() as cur:
            cur.execute("DELETE FROM suppliers WHERE company_id=%s AND id=%s", (cid, sid))
            cur.execute(
                "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='supplier' AND entity_id=%s",
                (cid, sid),
            )
        self._pulse(cid, "suppliers")
        return True, "Постачальника видалено"

    def find_or_create_level_node(
        self,
        category_id: str,
        position: int,
        name: str,
        parent_node_id: str | None = None,
    ) -> str:
        """
        Used by copy/setup flows to build `level_nodes`.
        Returns node id.
        """
        if not self._use_postgres():
            payload = {
                "category_id": category_id,
                "position": position,
                "name": name,
                "parent_node_id": parent_node_id or "",
            }
            return str(self._post("/level_nodes/find_or_create", payload) or "")
        category_id = str(category_id or "").strip()
        name = str(name or "").strip()
        if not category_id or not name:
            return ""
        try:
            pos = int(position or 0)
        except Exception:
            pos = 0
        if pos < 1 or pos > 6:
            return ""
        parent = str(parent_node_id or "").strip() or "root"
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT id FROM level_nodes
                WHERE category_id=%s AND position=%s AND parent_node_id=%s AND lower(name)=lower(%s)
                LIMIT 1
                """,
                (category_id, pos, parent, name),
            )
            row = cur.fetchone()
            if row and isinstance(row, dict) and row.get("id"):
                return str(row.get("id"))
            node_id = uuid.uuid4().hex
            now = self._now_ts()
            cur.execute(
                """
                INSERT INTO level_nodes
                  (id, category_id, position, parent_node_id, name, data, created_at, updated_at)
                VALUES
                  (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                """,
                (
                    node_id,
                    category_id,
                    pos,
                    parent,
                    name,
                    psycopg.types.json.Jsonb({}),
                    now,
                    now,
                ),
            )
            return node_id

    def get_category_level_nodes(
        self,
        category_id: str,
        position: int,
        parent_node_id: str | None = None,
        archived: bool | None = False,
    ):
        """
        Returns level_nodes rows for a category at given position and parent.
        UI (CopySetupView) passes parent_node_id=None for root.
        In schema, `level_nodes.parent_node_id` is NOT NULL; we use "root" marker.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/level_nodes/by_category_position",
                    {
                        "category_id": category_id,
                        "position": position,
                        "parent_node_id": parent_node_id or "",
                    },
                )
                or []
            )
        cat_id = str(category_id or "").strip()
        try:
            pos = int(position or 0)
        except Exception:
            pos = 0
        parent = str(parent_node_id or "").strip() or "root"
        if not cat_id or pos < 1 or pos > 6:
            return []
        archived_clause = (
            "" if archived is None else ("AND is_archived=TRUE" if archived else "AND is_archived=FALSE")
        )
        with self._pg().cursor() as cur:
            cur.execute(
                f"""
                SELECT id, category_id, position, parent_node_id, name, data, created_at, updated_at
                FROM level_nodes
                WHERE category_id=%s AND position=%s AND parent_node_id=%s {archived_clause}
                ORDER BY name ASC
                """,
                (cat_id, pos, parent),
            )
            return cur.fetchall() or []

    def update_level_node(self, node_id: str, name: str) -> bool:
        """
        Updates a level node name in `level_nodes`.
        Used by CategoriesBrandsView when editing hierarchy nodes.
        """
        if not self._use_postgres():
            return bool(
                self._post("/level_nodes/update", {"node_id": node_id, "name": name})
                or False
            )
        nid = str(node_id or "").strip()
        new_name = str(name or "").strip()
        if not nid or not new_name:
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT category_id, position, parent_node_id FROM level_nodes WHERE id=%s",
                (nid,),
            )
            row = cur.fetchone() or {}
            category_id = str((row or {}).get("category_id") or "").strip()
            position = int((row or {}).get("position") or 0)
            parent_node_id = (
                str((row or {}).get("parent_node_id") or "root").strip() or "root"
            )
            company_id = ""
            if category_id and position:
                cur.execute(
                    """
                    SELECT id FROM level_nodes
                    WHERE category_id=%s AND position=%s AND parent_node_id=%s
                      AND lower(trim(name))=lower(trim(%s)) AND id<>%s
                    LIMIT 1
                    """,
                    (category_id, position, parent_node_id, new_name, nid),
                )
                if cur.fetchone():
                    return False
            if category_id:
                with contextlib.suppress(Exception):
                    cur.execute(
                        "SELECT company_id FROM categories WHERE id=%s",
                        (category_id,),
                    )
                    crow = cur.fetchone() or {}
                    company_id = str((crow or {}).get("company_id") or "").strip()
            cur.execute(
                "UPDATE level_nodes SET name=%s, updated_at=%s WHERE id=%s",
                (new_name, self._now_ts(), nid),
            )
            # Keep synced tree fresh immediately (without waiting for full resync).
            with contextlib.suppress(Exception):
                cur.execute(
                    "UPDATE catalog_nodes SET name=%s, updated_at=%s WHERE id=%s",
                    (new_name, self._now_ts(), nid),
                )
            # If products are bound to this node (series/detail as product), mirror node rename in product title.
            with contextlib.suppress(Exception):
                cur.execute(
                    """
                    UPDATE products
                    SET name=%s, updated_at=%s
                    WHERE company_id=%s AND (data->>'catalog_node_id')=%s
                    """,
                    (new_name, self._now_ts(), company_id, nid),
                )
        if company_id:
            self._pulse(company_id, "catalog")
            self._pulse(company_id, "products")
        return True

    def archive_level_node(self, node_id: str) -> bool:
        """
        Soft-архівує вузол ієрархії разом з усім піддеревом (щоб приховані нащадки
        не "висіли" видимими під архівованим батьком). Запис не видаляється.
        """
        if not self._use_postgres():
            return bool(
                self._post("/level_nodes/archive", {"node_id": node_id}) or False
            )
        nid = str(node_id or "").strip()
        if not nid:
            return False
        company_id = ""
        subtree_ids = self._level_node_subtree_ids_deepest_first(nid) or [nid]
        with self._pg().cursor() as cur:
            cur.execute("SELECT category_id FROM level_nodes WHERE id=%s", (nid,))
            row = cur.fetchone() or {}
            category_id = str((row or {}).get("category_id") or "").strip()
            if category_id:
                with contextlib.suppress(Exception):
                    cur.execute(
                        "SELECT company_id FROM categories WHERE id=%s",
                        (category_id,),
                    )
                    crow = cur.fetchone() or {}
                    company_id = str((crow or {}).get("company_id") or "").strip()
            cur.execute(
                "UPDATE level_nodes SET is_archived=TRUE, archived_at=%s WHERE id=ANY(%s)",
                (self._now_ts(), subtree_ids),
            )
        if company_id:
            self._pulse(company_id, "catalog")
        return True

    def restore_level_node(self, node_id: str) -> bool:
        """Відновлює вузол разом з нащадками, заархівованими одночасно з ним."""
        nid = str(node_id or "").strip()
        if not nid or not self._use_postgres():
            return False
        company_id = ""
        subtree_ids = self._level_node_subtree_ids_deepest_first(nid) or [nid]
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT category_id, archived_at FROM level_nodes WHERE id=%s", (nid,)
            )
            row = cur.fetchone() or {}
            category_id = str((row or {}).get("category_id") or "").strip()
            archived_at = (row or {}).get("archived_at")
            if category_id:
                with contextlib.suppress(Exception):
                    cur.execute(
                        "SELECT company_id FROM categories WHERE id=%s",
                        (category_id,),
                    )
                    crow = cur.fetchone() or {}
                    company_id = str((crow or {}).get("company_id") or "").strip()
            cur.execute(
                "UPDATE level_nodes SET is_archived=FALSE, archived_at=NULL WHERE id=%s",
                (nid,),
            )
            if archived_at is not None:
                cur.execute(
                    "UPDATE level_nodes SET is_archived=FALSE, archived_at=NULL "
                    "WHERE id=ANY(%s) AND archived_at=%s",
                    (subtree_ids, archived_at),
                )
        if company_id:
            self._pulse(company_id, "catalog")
        return True

    def delete_level_node(self, node_id: str, force: bool = False) -> tuple[bool, str]:
        """Hard-delete a level node and its whole subtree - only when
        nothing references any node in that subtree. Unlike
        archive_level_node, this permanently removes the rows. Pass
        force=True (admin-only, from the UI) to cascade-delete every
        product in the subtree instead of refusing — see
        _force_delete_products_and_dependents."""
        nid = str(node_id or "").strip()
        if not self._use_postgres() or not nid:
            return False, "Некоректні дані"
        subtree_ids = self._level_node_subtree_ids_deepest_first(nid) or [nid]
        with self._pg().cursor() as cur:
            cur.execute("SELECT category_id FROM level_nodes WHERE id=%s", (nid,))
            row = cur.fetchone() or {}
            category_id = str((row or {}).get("category_id") or "").strip()
            company_id = ""
            if category_id:
                cur.execute(
                    "SELECT company_id FROM categories WHERE id=%s", (category_id,)
                )
                crow = cur.fetchone() or {}
                company_id = str((crow or {}).get("company_id") or "").strip()
        if not company_id:
            return False, "Не вдалося визначити компанію"

        used = self._count_products_by_data_field(
            company_id, "catalog_node_id", subtree_ids
        )
        if used and not force:
            return False, (
                f"Рівень використовують {used} товар(ів) - "
                "спочатку заархівуйте, видалити не можна"
            )

        deleted_products = 0
        if force and used:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM products WHERE company_id=%s AND data->>'catalog_node_id' = ANY(%s)",
                    (company_id, subtree_ids),
                )
                product_ids = [
                    str(r.get("id")) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]
            if product_ids:
                self._force_delete_products_and_dependents(company_id, product_ids)
            deleted_products = len(product_ids)

        with self._pg().cursor() as cur:
            cur.execute("DELETE FROM level_nodes WHERE id = ANY(%s)", (subtree_ids,))
            cur.execute(
                "DELETE FROM node_owners WHERE company_id=%s AND node_id = ANY(%s)",
                (company_id, subtree_ids),
            )
        with contextlib.suppress(Exception):
            self.sync_company_catalog_nodes(company_id)
        self._pulse(company_id, "catalog")
        self._pulse(company_id, "products")
        if deleted_products:
            return True, f"Рівень видалено разом з {deleted_products} товар(ів)"
        return True, "Рівень видалено"

    # ----------------- edit locks (Postgres mode) -----------------
    def _ts_after_seconds(self, seconds: int) -> str:
        try:
            sec = int(seconds or 0)
        except Exception:
            sec = 0
        # timestamp without tz, keep same formatting as `_now_ts()`
        return time.strftime(
            "%Y-%m-%d %H:%M:%S", time.localtime(time.time() + max(0, sec))
        )

    def acquire_edit_lock(
        self,
        company_id: str,
        scope: str,
        entity_id: str,
        manager_id: str,
        manager_name: (
            str | None
        ) = None,  # noqa: ARG002 - for API compatibility / message
        ttl_seconds: int = 180,
    ) -> dict:
        """
        Acquire an edit lock for entity. Returns dict:
        - ok: bool
        - lock_token: str (when ok)
        - message: str (when not ok)
        """
        if not self._use_postgres():
            payload = {
                "company_id": company_id,
                "scope": scope,
                "entity_id": entity_id,
                "manager_id": manager_id,
                "manager_name": manager_name or "",
                "ttl_seconds": ttl_seconds,
            }
            return self._post("/edit_locks/acquire", payload) or {
                "ok": False,
                "message": "lock service unavailable",
            }

        company_id = str(company_id or "").strip()
        scope = str(scope or "").strip()
        entity_id = str(entity_id or "").strip()
        manager_id = str(manager_id or "").strip()
        if not company_id or not scope or not entity_id or not manager_id:
            return {"ok": False, "message": "missing lock params"}

        now = self._now_ts()
        expires_at = self._ts_after_seconds(ttl_seconds)
        token = uuid.uuid4().hex

        try:
            with self._pg().cursor() as cur:
                # drop expired lock for this entity
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM edit_locks WHERE company_id=%s AND scope=%s AND entity_id=%s AND expires_at <= %s",
                        (company_id, scope, entity_id, now),
                    )

                cur.execute(
                    """
                    SELECT manager_id, token, expires_at
                    FROM edit_locks
                    WHERE company_id=%s AND scope=%s AND entity_id=%s
                    LIMIT 1
                    """,
                    (company_id, scope, entity_id),
                )
                row = cur.fetchone()
                if (
                    row
                    and isinstance(row, dict)
                    and row.get("manager_id")
                    and row.get("token")
                ):
                    locked_by = str(row.get("manager_id") or "")
                    if locked_by and locked_by != manager_id:
                        return {
                            "ok": False,
                            "message": "Об'єкт редагується іншим користувачем",
                            "locked_by": locked_by,
                            "expires_at": row.get("expires_at"),
                        }

                    # same manager: refresh token + ttl
                    cur.execute(
                        """
                        UPDATE edit_locks
                        SET token=%s, expires_at=%s, updated_at=%s, manager_id=%s
                        WHERE company_id=%s AND scope=%s AND entity_id=%s
                        """,
                        (
                            token,
                            expires_at,
                            now,
                            manager_id,
                            company_id,
                            scope,
                            entity_id,
                        ),
                    )
                    return {"ok": True, "lock_token": token}

                lock_id = uuid.uuid4().hex
                cur.execute(
                    """
                    INSERT INTO edit_locks
                      (id, company_id, scope, entity_id, manager_id, token, expires_at, updated_at)
                    VALUES
                      (%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        lock_id,
                        company_id,
                        scope,
                        entity_id,
                        manager_id,
                        token,
                        expires_at,
                        now,
                    ),
                )
            return {"ok": True, "lock_token": token}
        except Exception:
            logger.exception("acquire_edit_lock failed")
            return {"ok": False, "message": "Не вдалося отримати lock"}

    def heartbeat_edit_lock(
        self,
        company_id: str,
        scope: str,
        entity_id: str,
        manager_id: str,
        lock_token: str,
        ttl_seconds: int = 180,
    ) -> bool:
        if not self._use_postgres():
            payload = {
                "company_id": company_id,
                "scope": scope,
                "entity_id": entity_id,
                "manager_id": manager_id,
                "lock_token": lock_token,
                "ttl_seconds": ttl_seconds,
            }
            return bool(self._post("/edit_locks/heartbeat", payload) or False)
        company_id = str(company_id or "").strip()
        scope = str(scope or "").strip()
        entity_id = str(entity_id or "").strip()
        manager_id = str(manager_id or "").strip()
        lock_token = str(lock_token or "").strip()
        if (
            not company_id
            or not scope
            or not entity_id
            or not manager_id
            or not lock_token
        ):
            return False
        now = self._now_ts()
        expires_at = self._ts_after_seconds(ttl_seconds)
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    UPDATE edit_locks
                    SET expires_at=%s, updated_at=%s
                    WHERE company_id=%s AND scope=%s AND entity_id=%s AND manager_id=%s AND token=%s
                    """,
                    (
                        expires_at,
                        now,
                        company_id,
                        scope,
                        entity_id,
                        manager_id,
                        lock_token,
                    ),
                )
            return True
        except Exception:
            logger.exception("heartbeat_edit_lock failed")
            return False

    def release_edit_lock(
        self,
        company_id: str,
        scope: str,
        entity_id: str,
        manager_id: str,
        lock_token: str,
    ) -> bool:
        if not self._use_postgres():
            payload = {
                "company_id": company_id,
                "scope": scope,
                "entity_id": entity_id,
                "manager_id": manager_id,
                "lock_token": lock_token,
            }
            return bool(self._delete("/edit_locks/release", payload) or False)
        company_id = str(company_id or "").strip()
        scope = str(scope or "").strip()
        entity_id = str(entity_id or "").strip()
        manager_id = str(manager_id or "").strip()
        lock_token = str(lock_token or "").strip()
        if (
            not company_id
            or not scope
            or not entity_id
            or not manager_id
            or not lock_token
        ):
            return False
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    DELETE FROM edit_locks
                    WHERE company_id=%s AND scope=%s AND entity_id=%s AND manager_id=%s AND token=%s
                    """,
                    (company_id, scope, entity_id, manager_id, lock_token),
                )
            return True
        except Exception:
            logger.exception("release_edit_lock failed")
            return False

    def get_products(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        supplier_id: str | None = None,
        force_refresh: bool | None = None,
        archived: bool | None = False,
    ):
        """Cache-aside wrapper — see _cached_list. Cleared by
        invalidate_products_cache() on any product add/update/delete."""
        if not self._use_postgres():
            return self._get_products_uncached(
                company_id, region_id, manager_id, supplier_id, force_refresh, archived
            )
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        sid = str(supplier_id or "").strip()
        cache_key = f"products_{cid}_{rid}_{mid}_{sid}_{bool(archived)}"
        return self._cached_list(
            cache_key,
            bool(force_refresh),
            lambda: self._get_products_uncached(
                company_id, region_id, manager_id, supplier_id, force_refresh, archived
            ),
        )

    def _get_products_uncached(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        supplier_id: str | None = None,
        force_refresh: bool | None = None,  # noqa: ARG002
        archived: bool | None = False,
    ):
        if not self._use_postgres():
            return (
                self._get(
                    "/products",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                        "supplier_id": supplier_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()
        supplier_id = str(supplier_id or "").strip()
        archived_clause = (
            "" if archived is None else ("AND is_archived=TRUE" if archived else "AND is_archived=FALSE")
        )

        # Helper to normalize/flatten a product row
        def _normalize_product(r: dict) -> dict | None:
            if not isinstance(r, dict):
                return None
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = dict(r)
            for k, v in (data or {}).items():
                if k not in merged or merged.get(k) in (None, ""):
                    merged[k] = v
            # Drop the now-fully-unpacked raw "data" key -- a caller that
            # edits a couple of fields on this flattened dict and passes it
            # straight back to a save function must not be able to round-trip
            # this residual key as the new blob and nest a stale snapshot
            # inside itself (see the same fix on get_orders/get_order_by_id).
            merged.pop("data", None)
            # Normalize sales prices storage:
            # - legacy/UI often uses "sales_prices_json" as a JSON string
            # - some rows may store it as jsonb array or under "sales_prices"
            sp = merged.get("sales_prices_json")
            if isinstance(sp, list):
                with contextlib.suppress(Exception):
                    merged["sales_prices_json"] = json.dumps(sp, ensure_ascii=False)
            elif sp is None and isinstance(merged.get("sales_prices"), list):
                with contextlib.suppress(Exception):
                    merged["sales_prices_json"] = json.dumps(
                        merged.get("sales_prices") or [], ensure_ascii=False
                    )
            return merged

        # When manager_id is given, fetch only accessible products to avoid duplicates
        if manager_id:
            visible_ctx = self._get_manager_visible_scope_context(
                company_id, manager_id, region_id or None
            )
            allowed_product_ids = visible_ctx.get("product_ids") or set()
            if not allowed_product_ids and visible_ctx.get("restricted"):
                return []
            # If allowed_product_ids is non-empty, use it; otherwise fetch all for non-restricted admins
            if allowed_product_ids:
                with self._pg().cursor() as cur:
                    q = f"""
                    SELECT id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at
                    FROM products
                    WHERE company_id=%s AND id=ANY(%s) {archived_clause}
                    """
                    params: list[Any] = [company_id, list(allowed_product_ids)]
                    if supplier_id:
                        q += " AND (data->>'supplier_id')=%s"
                        params.append(supplier_id)
                    q += " ORDER BY name ASC"
                    cur.execute(q, params)
                    rows = cur.fetchall() or []
            else:
                # Unrestricted admin: fetch all products
                with self._pg().cursor() as cur:
                    q = f"""
                    SELECT id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at
                    FROM products
                    WHERE company_id=%s {archived_clause}
                    """
                    params: list[Any] = [company_id]
                    if region_id:
                        q += " AND region_id=%s"
                        params.append(region_id)
                    if supplier_id:
                        q += " AND (data->>'supplier_id')=%s"
                        params.append(supplier_id)
                    q += " ORDER BY name ASC"
                    cur.execute(q, params)
                    rows = cur.fetchall() or []
        else:
            # No manager filter: standard query
            with self._pg().cursor() as cur:
                q = f"""
                SELECT id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at
                FROM products
                WHERE company_id=%s {archived_clause}
                """
                params: list[Any] = [company_id]
                if region_id:
                    q += " AND region_id=%s"
                    params.append(region_id)
                if supplier_id:
                    q += " AND (data->>'supplier_id')=%s"
                    params.append(supplier_id)
                q += " ORDER BY name ASC"
                cur.execute(q, params)
                rows = cur.fetchall() or []

        # Flatten jsonb `data` into top-level fields for UI compatibility.
        out = [r for r in (_normalize_product(x) for x in rows) if r is not None]

        # Legacy repeated scope-copy operations could leave semantic duplicates
        # (same manager/region/category/supplier/name but different product ids).
        # Deduplicate manager-scoped reads so counters and product pages stay correct.
        if manager_id:
            dedup: dict[tuple[str, str, str, str, str], dict] = {}
            for row in out:
                if not isinstance(row, dict):
                    continue
                key = (
                    str(row.get("region_id") or "").strip(),
                    str(row.get("category_id") or "").strip(),
                    str(row.get("supplier_id") or "").strip(),
                    str(row.get("catalog_node_id") or "").strip(),
                    str(row.get("name") or "").strip().lower(),
                )
                existing = dedup.get(key)
                if existing is None:
                    dedup[key] = row
                    continue
                existing_updated = str(existing.get("updated_at") or "")
                row_updated = str(row.get("updated_at") or "")
                existing_created = str(existing.get("created_at") or "")
                row_created = str(row.get("created_at") or "")
                if (row_updated, row_created) > (existing_updated, existing_created):
                    dedup[key] = row
            out = list(dedup.values())
            out.sort(key=lambda r: str((r or {}).get("name") or "").lower())

        return out

    def get_product_by_id(self, company_id: str, product_id: str) -> dict | None:
        """
        Fetch a single product row (flattening jsonb `data` like `get_products`).
        Used by edit modals to ensure we show exactly what is saved in DB.
        """
        pid = str(product_id or "").strip()
        cid = str(company_id or "").strip()
        if not pid or not cid:
            return None
        if not self._use_postgres():
            # Fallback: pull list and filter locally (API may not expose single-item endpoint).
            rows = self.get_products(cid, region_id=None, manager_id=None) or []
            row = next(
                (
                    r
                    for r in rows
                    if isinstance(r, dict) and str(r.get("id") or "").strip() == pid
                ),
                None,
            )
            return row if isinstance(row, dict) else None
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at
                FROM products
                WHERE company_id=%s AND id=%s
                LIMIT 1
                """,
                (cid, pid),
            )
            r = cur.fetchone()
        if not isinstance(r, dict):
            return None
        data = r.get("data") if isinstance(r.get("data"), dict) else {}
        merged = dict(r)
        for k, v in (data or {}).items():
            if k not in merged or merged.get(k) in (None, ""):
                merged[k] = v
        merged.pop("data", None)
        # Normalize sales prices storage (keep same behavior as get_products).
        sp = merged.get("sales_prices_json")
        if isinstance(sp, list):
            with contextlib.suppress(Exception):
                merged["sales_prices_json"] = json.dumps(sp, ensure_ascii=False)
        elif sp is None and isinstance(merged.get("sales_prices"), list):
            with contextlib.suppress(Exception):
                merged["sales_prices_json"] = json.dumps(
                    merged.get("sales_prices") or [], ensure_ascii=False
                )
        return merged

    def product_name_exists(
        self,
        company_id: str,
        name: str,
        region_id: str,
        category_id: str,
        exclude_product_id: str | None = None,
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._get(
                    "/products/name_exists",
                    {
                        "company_id": company_id,
                        "name": name,
                        "region_id": region_id,
                        "category_id": category_id,
                        "exclude_product_id": exclude_product_id or "",
                    },
                )
                or False
            )
        cid = str(company_id or "").strip()
        nm = str(name or "").strip()
        rid = str(region_id or "").strip()
        cat_id = str(category_id or "").strip()
        ex = str(exclude_product_id or "").strip()
        if not cid or not nm or not rid or not cat_id:
            return False
        with self._pg().cursor() as cur:
            q = """
            SELECT 1
            FROM products
            WHERE company_id=%s AND region_id=%s AND lower(name)=lower(%s)
              AND (data->>'category_id')=%s
            """
            params: list[Any] = [cid, rid, nm, cat_id]
            if ex:
                q += " AND id<>%s"
                params.append(ex)
            q += " LIMIT 1"
            cur.execute(q, params)
            return bool(cur.fetchone())

    def product_duplicate_exists_for_import(
        self,
        *,
        company_id: str,
        manager_id: str,
        region_id: str,
        category_id: str,
        catalog_node_id: str | None,
        name: str,
        supplier_id: str | None,
        purchase_currency: str,
    ) -> bool:
        """
        Повний збіг з існуючим товаром для масового імпорту: компанія, менеджер, регіон,
        категорія, вузол каталогу (рівні + деталізація), назва, постачальник, валюта закупівлі.
        """
        if not self._use_postgres():
            return False
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        cat_id = str(category_id or "").strip()
        nm = str(name or "").strip()
        node = str(catalog_node_id or "").strip()
        sup = str(supplier_id or "").strip()
        cur_s = str(purchase_currency or "USD").strip().upper()
        cur_s = cur_s[:3] if len(cur_s) >= 3 else (cur_s or "USD")
        if not cid or not mid or not rid or not cat_id or not nm:
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT 1
                FROM products
                WHERE company_id=%s
                  AND region_id=%s
                  AND manager_id=%s
                  AND lower(trim(name)) = lower(trim(%s))
                  AND coalesce(nullif(trim(data->>'category_id'), ''), '') = %s
                  AND coalesce(nullif(trim(data->>'catalog_node_id'), ''), '') = %s
                  AND upper(left(coalesce(nullif(trim(data->>'purchase_currency'), ''), 'USD'), 3)) = %s
                  AND coalesce(nullif(trim(data->>'supplier_id'), ''), '') = %s
                LIMIT 1
                """,
                (cid, rid, mid, nm, cat_id, node, cur_s, sup),
            )
            return bool(cur.fetchone())

    def search_products_company(self, company_id: str, query: str, limit: int = 8):
        """
        Used by Products dialog quick-copy suggestions.
        Returns list of flattened product dicts.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/products/search_company",
                    {
                        "company_id": company_id,
                        "query": query,
                        "limit": int(limit or 8),
                    },
                )
                or []
            )
        cid = str(company_id or "").strip()
        qtxt = str(query or "").strip()
        try:
            lim = int(limit or 8)
        except Exception:
            lim = 8
        lim = max(1, min(25, lim))
        if not cid or len(qtxt) < 2:
            return []
        pat = f"%{qtxt}%"
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at
                FROM products
                WHERE company_id=%s
                  AND (
                    name ILIKE %s
                    OR (data->>'notes') ILIKE %s
                  )
                ORDER BY updated_at DESC
                LIMIT %s
                """,
                (cid, pat, pat, lim),
            )
            rows = cur.fetchall() or []
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = dict(r)
            for k, v in (data or {}).items():
                if k not in merged or merged.get(k) in (None, ""):
                    merged[k] = v
            merged.pop("data", None)
            out.append(merged)
        return out

    def resolve_or_create_product_levels(self, category_id: str, levels_payload: dict):
        """
        Ensures hierarchy level_nodes exist for a product under the given category.
        levels_payload is a dict: position -> {"node_id": "..."} or {"name": "..."}.

        Returns dict with:
          - category_id
          - leaf_node_id (deepest resolved node id; falls back to category_id)
          - nodes_by_pos: {pos: node_id}
        """
        if not self._use_postgres():
            return (
                self._post(
                    "/products/resolve_levels",
                    {"category_id": category_id, "levels": levels_payload},
                )
                or {}
            )
        cat_id = str(category_id or "").strip()
        if not cat_id:
            return {}
        levels_payload = levels_payload if isinstance(levels_payload, dict) else {}

        # Build chain from lowest to highest position; parent is previous node id.
        nodes_by_pos: dict[int, str] = {}
        parent_node_id: str | None = None
        leaf_node_id = cat_id

        for pos in sorted(
            [int(p) for p in levels_payload.keys() if str(p).strip().isdigit()]
        ):
            if pos < 1 or pos > 7:
                continue
            spec = (
                levels_payload.get(pos)
                if isinstance(levels_payload.get(pos), dict)
                else {}
            )
            node_id = str((spec or {}).get("node_id") or "").strip()
            if node_id:
                nodes_by_pos[pos] = node_id
                parent_node_id = node_id
                leaf_node_id = node_id
                continue
            name = str((spec or {}).get("name") or "").strip()
            if not name:
                continue
            created_id = self.find_or_create_level_node(
                cat_id, pos, name, parent_node_id=parent_node_id
            )
            if created_id:
                nodes_by_pos[pos] = created_id
                parent_node_id = created_id
                leaf_node_id = created_id

        # Best-effort: keep catalog_nodes in sync so future access scopes work.
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT company_id FROM categories WHERE id=%s LIMIT 1",
                    (cat_id,),
                )
                row = cur.fetchone() or {}
            cid = str((row or {}).get("company_id") or "").strip()
            if cid:
                self.sync_company_catalog_nodes(cid)
                self._pulse(cid, "catalog")

        return {
            "category_id": cat_id,
            "leaf_node_id": leaf_node_id,
            "nodes_by_pos": nodes_by_pos,
        }

    def add_product(self, payload: dict) -> bool:
        """
        Create product row.
        UI passes a dict with core fields and additional fields (stored in jsonb data).
        """
        if not self._use_postgres():
            return bool(self._post("/products/add", payload) or False)
        payload = payload if isinstance(payload, dict) else {}

        def _to_int_or_none_local(value):
            try:
                if value is None:
                    return None
                raw = str(value).strip().replace(",", ".")
                if raw == "":
                    return None
                parsed = int(float(raw))
                return parsed if parsed >= 0 else None
            except Exception:
                return None

        cid = str(payload.get("company_id") or "").strip()
        rid = str(payload.get("region_id") or "").strip()
        mid = str(payload.get("manager_id") or "").strip()
        name = str(payload.get("name") or "").strip()
        production_term_days = _to_int_or_none_local(
            payload.get("production_term_days")
        )
        if not cid or not rid or not name:
            return False
        prod_id = uuid.uuid4().hex
        now = self._now_ts()
        data = dict(payload)
        # Normalize sales prices so they are consistently stored.
        with contextlib.suppress(Exception):
            spj = data.get("sales_prices_json")
            if isinstance(spj, str) and spj.strip():
                parsed = json.loads(spj)
                if isinstance(parsed, list):
                    data["sales_prices"] = parsed
                    data["sales_prices_json"] = json.dumps(parsed, ensure_ascii=False)
            elif isinstance(spj, list):
                data["sales_prices"] = spj
                data["sales_prices_json"] = json.dumps(spj, ensure_ascii=False)
        # Remove top-level columns
        for k in (
            "id",
            "company_id",
            "region_id",
            "manager_id",
            "name",
            "created_at",
            "updated_at",
        ):
            data.pop(k, None)
        with self._pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO products
                                    (id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at)
                VALUES
                                    (%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                """,
                (
                    prod_id,
                    cid,
                    rid,
                    mid,
                    name,
                    production_term_days,
                    psycopg.types.json.Jsonb(data),
                    now,
                    now,
                ),
            )
        self._pulse(cid, "products")
        self._invalidate_product_scope_cache(cid)
        catalog_node_id = str(
            payload.get("catalog_node_id") or data.get("catalog_node_id") or ""
        ).strip()
        if catalog_node_id and mid and cid:
            with contextlib.suppress(Exception):
                self._assign_owner_to_nodes(mid, cid, [catalog_node_id])
        return True

    def update_product(
        self,
        product_id: str,
        payload: dict,
        manager_id: str | None = None,  # noqa: ARG002
        lock_token: str | None = None,  # noqa: ARG002
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/products/update", {"product_id": product_id, "payload": payload}
                )
                or False
            )
        pid = str(product_id or "").strip()
        payload = payload if isinstance(payload, dict) else {}

        def _to_int_or_none_local(value):
            try:
                if value is None:
                    return None
                raw = str(value).strip().replace(",", ".")
                if raw == "":
                    return None
                parsed = int(float(raw))
                return parsed if parsed >= 0 else None
            except Exception:
                return None

        if not pid:
            return False
        # Normalize sales prices before merge (UI passes sales_prices_json).
        with contextlib.suppress(Exception):
            spj = payload.get("sales_prices_json")
            if isinstance(spj, str) and spj.strip():
                parsed = json.loads(spj)
                if isinstance(parsed, list):
                    payload["sales_prices"] = parsed
                    payload["sales_prices_json"] = json.dumps(
                        parsed, ensure_ascii=False
                    )
            elif isinstance(spj, list):
                payload["sales_prices"] = spj
                payload["sales_prices_json"] = json.dumps(spj, ensure_ascii=False)

        new_name = str(payload.get("name") or "").strip()
        new_rid = str(payload.get("region_id") or "").strip()
        new_mid = str(payload.get("manager_id") or "").strip()
        _old_packaging_id = ""
        _old_supplier_id = ""
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id, manager_id, data FROM products WHERE id=%s LIMIT 1",
                (pid,),
            )
            row = cur.fetchone() or {}
            cid = str((row or {}).get("company_id") or "").strip()
            _existing_mid = str((row or {}).get("manager_id") or "").strip()
            current_data = row.get("data") if isinstance(row.get("data"), dict) else {}
            _old_packaging_id = str(
                (current_data or {}).get("packaging_id") or ""
            ).strip()
            _old_supplier_id = str(
                (current_data or {}).get("supplier_id") or ""
            ).strip()
            merged = dict(current_data or {})
            for k, v in payload.items():
                if k in {"id", "company_id", "created_at", "data"}:
                    # "data" is a residual key on a payload that started life
                    # as a flattened get_product_by_id()/get_products() dict
                    # (edited in place and passed straight back here) --
                    # never let it overwrite `merged` and nest a stale
                    # snapshot inside the product's own new data blob.
                    continue
                if k in {"region_id", "manager_id", "name"}:
                    continue
                merged[k] = v
            sets = []
            params: list[Any] = []
            if new_name:
                sets.append("name=%s")
                params.append(new_name)
            if new_rid:
                sets.append("region_id=%s")
                params.append(new_rid)
            if new_mid:
                sets.append("manager_id=%s")
                params.append(new_mid)
            if "production_term_days" in payload:
                sets.append("production_term_days=%s")
                params.append(
                    _to_int_or_none_local(payload.get("production_term_days"))
                )
            sets.append("data=%s::jsonb")
            params.append(psycopg.types.json.Jsonb(merged))
            sets.append("updated_at=%s")
            params.append(self._now_ts())
            params.append(pid)
            cur.execute(
                "UPDATE products SET " + ", ".join(sets) + " WHERE id=%s", params
            )
        if cid and new_name:
            self._sync_product_references(
                cid, pid, product_name=new_name, deleted=False
            )
        # Якщо змінилось пакування товару — оновлюємо packaging contexts
        _new_packaging_id = str(payload.get("packaging_id") or "").strip()
        _new_supplier_id = str(
            payload.get("supplier_id") or _old_supplier_id or ""
        ).strip()
        _packaging_changed = (
            _new_packaging_id and _new_packaging_id != _old_packaging_id
        )
        if cid and (
            _packaging_changed or (not _new_packaging_id and _old_packaging_id)
        ):
            with contextlib.suppress(Exception):
                self._resync_product_packaging_contexts(
                    cid,
                    pid,
                    removed_from_packaging_id=_old_packaging_id or None,
                    added_to_packaging_id=_new_packaging_id or None,
                    goods_supplier_id=_new_supplier_id,
                )
        if cid:
            self._pulse(cid, "products")
            self._pulse(cid, "orders")
            self._invalidate_product_scope_cache(cid)
        catalog_node_id = str(
            payload.get("catalog_node_id") or merged.get("catalog_node_id") or ""
        ).strip()
        _effective_mid = new_mid or _existing_mid
        if catalog_node_id and _effective_mid and cid:
            with contextlib.suppress(Exception):
                self._assign_owner_to_nodes(_effective_mid, cid, [catalog_node_id])
        return True

    def archive_product(
        self,
        product_id: str,
        manager_id: str | None = None,  # noqa: ARG002 - kept for call-site compatibility
        lock_token: str | None = None,  # noqa: ARG002
    ) -> bool:
        """Soft-архівує товар замість фізичного видалення — старі замовлення й далі
        резолвлять назву товару по id, оскільки запис нікуди не дівається."""
        if not self._use_postgres():
            return bool(
                self._post("/products/archive", {"product_id": product_id}) or False
            )
        pid = str(product_id or "").strip()
        if not pid:
            return False
        with self._pg().cursor() as cur:
            cur.execute("SELECT company_id FROM products WHERE id=%s LIMIT 1", (pid,))
            row = cur.fetchone() or {}
            cid = str((row or {}).get("company_id") or "").strip()
            cur.execute(
                "UPDATE products SET is_archived=TRUE, archived_at=%s WHERE id=%s",
                (self._now_ts(), pid),
            )
        if cid:
            self._pulse(cid, "products")
            self._invalidate_product_scope_cache(cid)
        return True

    def restore_product(self, product_id: str) -> bool:
        pid = str(product_id or "").strip()
        if not pid or not self._use_postgres():
            return False
        with self._pg().cursor() as cur:
            cur.execute("SELECT company_id FROM products WHERE id=%s LIMIT 1", (pid,))
            row = cur.fetchone() or {}
            cid = str((row or {}).get("company_id") or "").strip()
            cur.execute(
                "UPDATE products SET is_archived=FALSE, archived_at=NULL WHERE id=%s",
                (pid,),
            )
        if cid:
            self._pulse(cid, "products")
            self._invalidate_product_scope_cache(cid)
        return True

    def _level_node_subtree_ids_deepest_first(self, start_id: str) -> list[str]:
        nid = str(start_id or "").strip()
        if not nid:
            return []
        with self._pg().cursor() as cur:
            cur.execute("SELECT 1 FROM level_nodes WHERE id=%s LIMIT 1", (nid,))
            if not cur.fetchone():
                return []
            cur.execute(
                """
                WITH RECURSIVE sub AS (
                  SELECT id, parent_node_id, 0 AS depth
                  FROM level_nodes WHERE id=%s
                  UNION ALL
                  SELECT ln.id, ln.parent_node_id, sub.depth + 1
                  FROM level_nodes ln
                  JOIN sub ON ln.parent_node_id = sub.id
                )
                SELECT id FROM sub ORDER BY depth DESC, id ASC
                """,
                (nid,),
            )
            rows = cur.fetchall() or []
        return [
            str(r.get("id") or "").strip()
            for r in rows
            if isinstance(r, dict) and r.get("id")
        ]

    def get_packaging(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        supplier_rows: list | None = None,
        force_refresh: bool | None = None,
        archived: bool | None = False,
    ):
        """Cache-aside wrapper — see _cached_list. Cleared by
        invalidate_packaging_cache() on any packaging add/update/delete.
        `supplier_rows` (a pre-fetched optimization hint) doesn't affect the
        cache key — the returned rows are the same either way."""
        if not self._use_postgres():
            return self._get_packaging_uncached(
                company_id, region_id, manager_id, supplier_rows, force_refresh, archived
            )
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        cache_key = f"packaging_{cid}_{rid}_{mid}_{bool(archived)}"
        return self._cached_list(
            cache_key,
            bool(force_refresh),
            lambda: self._get_packaging_uncached(
                company_id, region_id, manager_id, supplier_rows, force_refresh, archived
            ),
        )

    def _get_packaging_uncached(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        supplier_rows: list | None = None,
        force_refresh: bool | None = None,  # noqa: ARG002
        archived: bool | None = False,
    ):
        if not self._use_postgres():
            return (
                self._get(
                    "/packaging",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()
        archived_clause = (
            "" if archived is None else ("AND p.is_archived=TRUE" if archived else "AND p.is_archived=FALSE")
        )
        with self._pg().cursor() as cur:
            q = f"""
            SELECT
              p.id, p.company_id, p.region_id, p.manager_id, p.name, p.data, p.created_at, p.updated_at,
              s.id AS supplier_join_id,
              s.name AS supplier_join_name,
              s.data AS supplier_join_data
            FROM packaging
            p
            LEFT JOIN suppliers s ON s.id = (p.data->>'supplier_id')
            WHERE p.company_id=%s {archived_clause}
            """
            params: list[Any] = [company_id]
            if region_id:
                q += " AND p.region_id=%s"
                params.append(region_id)
            q += " ORDER BY p.name ASC"
            cur.execute(q, params)
            rows = cur.fetchall() or []
        # Flatten jsonb `data` into top-level fields for UI compatibility.
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = dict(r)
            for k, v in (data or {}).items():
                if k not in merged or merged.get(k) in (None, ""):
                    merged[k] = v
            merged.pop("data", None)
            # UI expects nested suppliers dict: {"name": ..., "currency": ...}
            if not isinstance(merged.get("suppliers"), dict):
                sdata = (
                    merged.get("supplier_join_data")
                    if isinstance(merged.get("supplier_join_data"), dict)
                    else {}
                )
                scurrency = (
                    (sdata or {}).get("currency")
                    or (sdata or {}).get("price_currency")
                    or "USD"
                )
                merged["suppliers"] = {
                    "id": merged.get("supplier_join_id")
                    or (data or {}).get("supplier_id"),
                    "name": merged.get("supplier_join_name") or "",
                    "currency": str(scurrency or "USD").upper(),
                }
            # Remove join helper fields
            merged.pop("supplier_join_id", None)
            merged.pop("supplier_join_name", None)
            merged.pop("supplier_join_data", None)
            out.append(merged)
        if manager_id:
            visible_ctx = self._get_manager_visible_scope_context(
                company_id, manager_id, region_id or None
            )
            if visible_ctx.get("restricted"):
                allowed_packaging_ids = visible_ctx.get("packaging_ids") or set()
                out = [
                    row
                    for row in out
                    if isinstance(row, dict)
                    and str(row.get("id") or "").strip() in allowed_packaging_ids
                ]
        return out

    def search_packaging_company(
        self, company_id: str, query: str, limit: int = 5, region_id: str | None = None
    ):
        """
        Used by Packaging dialog quick-fill to find similar packaging by name/size/notes.
        Returns list of packaging dict rows with flattened data.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/packaging/search_company",
                    {
                        "company_id": company_id,
                        "query": query,
                        "limit": int(limit or 5),
                        "region_id": region_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        qtxt = str(query or "").strip()
        region_id = str(region_id or "").strip()
        try:
            lim = int(limit or 5)
        except Exception:
            lim = 5
        lim = max(1, min(20, lim))
        if not company_id or len(qtxt) < 2:
            return []
        pat = f"%{qtxt}%"
        with self._pg().cursor() as cur:
            sql = """
            SELECT
              p.id, p.company_id, p.region_id, p.manager_id, p.name, p.data, p.created_at, p.updated_at,
              s.id AS supplier_join_id,
              s.name AS supplier_join_name,
              s.data AS supplier_join_data
            FROM packaging p
            LEFT JOIN suppliers s ON s.id = (p.data->>'supplier_id')
            WHERE p.company_id=%s
              AND (
                p.name ILIKE %s
                OR (p.data->>'size') ILIKE %s
                OR (p.data->>'notes') ILIKE %s
              )
            """
            params: list[Any] = [company_id, pat, pat, pat]
            if region_id:
                sql += " AND p.region_id=%s"
                params.append(region_id)
            sql += " ORDER BY p.updated_at DESC LIMIT %s"
            params.append(lim)
            cur.execute(sql, params)
            rows = cur.fetchall() or []
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = dict(r)
            for k, v in (data or {}).items():
                if k not in merged or merged.get(k) in (None, ""):
                    merged[k] = v
            merged.pop("data", None)
            if not isinstance(merged.get("suppliers"), dict):
                sdata = (
                    merged.get("supplier_join_data")
                    if isinstance(merged.get("supplier_join_data"), dict)
                    else {}
                )
                scurrency = (
                    (sdata or {}).get("currency")
                    or (sdata or {}).get("price_currency")
                    or "USD"
                )
                merged["suppliers"] = {
                    "id": merged.get("supplier_join_id")
                    or (data or {}).get("supplier_id"),
                    "name": merged.get("supplier_join_name") or "",
                    "currency": str(scurrency or "USD").upper(),
                }
            merged.pop("supplier_join_id", None)
            merged.pop("supplier_join_name", None)
            merged.pop("supplier_join_data", None)
            out.append(merged)
        return out

    def packaging_name_exists(
        self,
        company_id: str,
        name: str,
        region_id: str,
        supplier_id: str | None = None,
        manager_id: str | None = None,
        exclude_packaging_id: str | None = None,
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._get(
                    "/packaging/name_exists",
                    {
                        "company_id": company_id,
                        "name": name,
                        "region_id": region_id,
                        "supplier_id": supplier_id or "",
                        "manager_id": manager_id or "",
                        "exclude_packaging_id": exclude_packaging_id or "",
                    },
                )
                or False
            )
        company_id = str(company_id or "").strip()
        name = str(name or "").strip()
        region_id = str(region_id or "").strip()
        supplier_id = str(supplier_id or "").strip()
        manager_id = str(manager_id or "").strip()
        exclude_packaging_id = str(exclude_packaging_id or "").strip()
        if not company_id or not name or not region_id:
            return False
        with self._pg().cursor() as cur:
            q = """
            SELECT 1 FROM packaging
            WHERE company_id=%s AND region_id=%s AND lower(name)=lower(%s)
            """
            params: list[Any] = [company_id, region_id, name]
            if supplier_id:
                q += " AND (data->>'supplier_id')=%s"
                params.append(supplier_id)
            if manager_id:
                q += " AND manager_id=%s"
                params.append(manager_id)
            if exclude_packaging_id:
                q += " AND id<>%s"
                params.append(exclude_packaging_id)
            q += " LIMIT 1"
            cur.execute(q, params)
            return bool(cur.fetchone())

    def add_packaging(self, payload: dict):
        """
        Insert packaging into `packaging`.
        If packaging with same name already exists in region, reuse it and add manager as co-owner.
        Returns packaging id (truthy) or "" on failure.
        """
        if not self._use_postgres():
            return str(self._post("/packaging/add", payload) or "")
        if not isinstance(payload, dict):
            return ""
        company_id = str(payload.get("company_id") or "").strip()
        region_id = str(payload.get("region_id") or "").strip()
        manager_id = str(payload.get("manager_id") or "").strip()
        name = str(payload.get("name") or "").strip() or "Пакування"
        if not company_id or not region_id:
            return ""

        now = self._now_ts()
        data = dict(payload)
        try:
            with self._pg().cursor() as cur:
                # Check if packaging with same name already exists in this region
                normalized_name = str(name or "").strip().lower()
                cur.execute(
                    """
                    SELECT id FROM packaging
                    WHERE company_id=%s AND region_id=%s AND lower(name)=%s
                    LIMIT 1
                    """,
                    (company_id, region_id, normalized_name),
                )
                existing = cur.fetchone()

                if existing:
                    # Reuse existing packaging
                    pid = str(
                        existing.get("id")
                        if isinstance(existing, dict)
                        else existing[0]
                    )
                    # Add manager as co-owner if not already
                    if manager_id:
                        cur.execute(
                            """
                            INSERT INTO entity_owners
                              (company_id, entity_type, entity_id, manager_id, created_at)
                            VALUES
                              (%s,%s,%s,%s,%s)
                            ON CONFLICT DO NOTHING
                            """,
                            (
                                company_id,
                                "packaging",
                                pid,
                                manager_id,
                                now,
                            ),
                        )
                else:
                    # Create new packaging
                    pid = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO packaging
                          (id, company_id, region_id, manager_id, name, data, created_at, updated_at)
                        VALUES
                          (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                        """,
                        (
                            pid,
                            company_id,
                            region_id,
                            manager_id,
                            name,
                            psycopg.types.json.Jsonb(data),
                            now,
                            now,
                        ),
                    )
                    # Create entity_owner record so creator can see this packaging
                    if manager_id:
                        cur.execute(
                            """
                            INSERT INTO entity_owners
                              (company_id, entity_type, entity_id, manager_id, created_at)
                            VALUES
                              (%s,%s,%s,%s,%s)
                            ON CONFLICT DO NOTHING
                            """,
                            (
                                company_id,
                                "packaging",
                                pid,
                                manager_id,
                                now,
                            ),
                        )
            self._pulse(company_id, "packaging")
            self.invalidate_packaging_cache(company_id)
            return pid
        except Exception:
            logger.exception("add_packaging failed")
        return ""

    def update_packaging(self, packaging_id: str, payload: dict) -> bool:
        if not self._use_postgres():
            return bool(
                self._post("/packaging/update", {"id": packaging_id, **(payload or {})})
                or False
            )
        pid = str(packaging_id or "").strip()
        if not pid or not isinstance(payload, dict):
            return False
        name = str(payload.get("name") or "").strip()
        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id, data FROM packaging WHERE id=%s LIMIT 1",
                (pid,),
            )
            row = cur.fetchone() or {}
            company_id = str(row.get("company_id") or "").strip()
            current_data = row.get("data") if isinstance(row.get("data"), dict) else {}
            merged = dict(current_data or {})
            # A payload that started life as a flattened get_suppliers()/
            # get_supplier_by_id()-style dict (edited in place and passed
            # straight back here) can carry a residual "data" key -- never
            # let it overwrite `merged` and nest a stale snapshot inside the
            # supplier's own new data blob.
            _payload_clean = {k: v for k, v in payload.items() if k != "data"}
            merged.update(_payload_clean)
            sets = ["data=%s::jsonb", "updated_at=%s"]
            params: list[Any] = [psycopg.types.json.Jsonb(merged), now]
            if name:
                sets.insert(0, "name=%s")
                params.insert(0, name)
            params.append(pid)
            cur.execute(
                "UPDATE packaging SET " + ", ".join(sets) + " WHERE id=%s",
                params,
            )
        if company_id:
            self._sync_packaging_references(
                company_id, pid, packaging_name=(name or None), deleted=False
            )
        if company_id:
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "products")
            self.invalidate_packaging_cache(company_id)
        return True

    def archive_packaging(self, packaging_id: str) -> bool:
        """Soft-архівує пакування замість фізичного видалення."""
        if not self._use_postgres():
            return bool(
                self._post("/packaging/archive", {"id": packaging_id}) or False
            )
        pid = str(packaging_id or "").strip()
        if not pid:
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id FROM packaging WHERE id=%s LIMIT 1", (pid,)
            )
            row = cur.fetchone() or {}
            company_id = str(row.get("company_id") or "").strip()
            cur.execute(
                "UPDATE packaging SET is_archived=TRUE, archived_at=%s WHERE id=%s",
                (self._now_ts(), pid),
            )
        if company_id:
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "products")
            self.invalidate_packaging_cache(company_id)
        return True

    def restore_packaging(self, packaging_id: str) -> bool:
        pid = str(packaging_id or "").strip()
        if not pid or not self._use_postgres():
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id FROM packaging WHERE id=%s LIMIT 1", (pid,)
            )
            row = cur.fetchone() or {}
            company_id = str(row.get("company_id") or "").strip()
            cur.execute(
                "UPDATE packaging SET is_archived=FALSE, archived_at=NULL WHERE id=%s",
                (pid,),
            )
        if company_id:
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "products")
            self.invalidate_packaging_cache(company_id)
        return True

    # ── Packaging supply (warehouse) contexts & journal ─────────────────────
    def _resync_product_packaging_contexts(
        self,
        company_id: str,
        product_id: str,
        *,
        removed_from_packaging_id: str | None = None,
        added_to_packaging_id: str | None = None,
        goods_supplier_id: str = "",
    ) -> None:
        """Цільовий (fast) re-sync packaging contexts для одного товару.
        Викликається при видаленні або зміні пакування товару — НЕ повний sync.

        Логіка:
        - Якщо removed_from_packaging_id: прибрати product_id з linked_product_ids
          в усіх контекстах де він є. Видалити контексти з порожнім linked_product_ids
          (крім «заглушок» з goods_supplier_id='').
        - Якщо added_to_packaging_id: знайти або створити контекст для
          (packaging_id, goods_supplier_id) і додати product_id до linked_product_ids.
        """
        if not self._use_postgres():
            return
        cid = str(company_id or "").strip()
        pid = str(product_id or "").strip()
        if not cid or not pid:
            return
        now = datetime.utcnow()
        try:
            with self._pg().cursor() as cur:
                # ── 1. Видалити product_id з усіх контекстів де він є ──────────
                if removed_from_packaging_id:
                    rpid = str(removed_from_packaging_id).strip()
                    # Отримуємо контексти що містять цей product_id
                    cur.execute(
                        """
                        SELECT id, linked_product_ids
                        FROM packaging_supply_contexts
                        WHERE company_id=%s AND packaging_id=%s
                          AND linked_product_ids @> %s::jsonb
                        """,
                        (cid, rpid, psycopg.types.json.Jsonb([pid])),
                    )
                    for ctx_row in list(cur.fetchall() or []):
                        if not isinstance(ctx_row, dict):
                            continue
                        ctx_id = str(ctx_row.get("id") or "").strip()
                        linked = ctx_row.get("linked_product_ids") or []
                        if isinstance(linked, (bytes, bytearray)):
                            import json as _json

                            try:
                                linked = _json.loads(linked)
                            except Exception:
                                linked = []
                        new_linked = [
                            x
                            for x in (linked if isinstance(linked, list) else [])
                            if str(x or "").strip() != pid
                        ]
                        if not new_linked:
                            # Контекст порожній — видаляємо разом з підданими
                            cur.execute(
                                "DELETE FROM packaging_supply_openings WHERE context_id=%s",
                                (ctx_id,),
                            )
                            cur.execute(
                                "DELETE FROM packaging_supply_orders WHERE context_id=%s AND row_kind='goods'",
                                (ctx_id,),
                            )
                            cur.execute(
                                "DELETE FROM packaging_supply_contexts WHERE id=%s",
                                (ctx_id,),
                            )
                        else:
                            cur.execute(
                                "UPDATE packaging_supply_contexts SET linked_product_ids=%s::jsonb, updated_at=%s WHERE id=%s",
                                (
                                    psycopg.types.json.Jsonb(
                                        sorted(set(str(x) for x in new_linked))
                                    ),
                                    now,
                                    ctx_id,
                                ),
                            )

                # ── 2. Додати product_id до нового контексту ─────────────────
                if added_to_packaging_id:
                    apid = str(added_to_packaging_id).strip()
                    gsid = str(goods_supplier_id or "").strip()
                    # Шукаємо всі регіони де є цей контекст (або де є продукт)
                    cur.execute(
                        """
                        SELECT DISTINCT region_id FROM packaging_supply_contexts
                        WHERE company_id=%s AND packaging_id=%s AND goods_supplier_id=%s
                        """,
                        (cid, apid, gsid),
                    )
                    existing_regions = {
                        str(r.get("region_id") or "").strip()
                        for r in (cur.fetchall() or [])
                        if isinstance(r, dict)
                    }
                    # Також перевіримо регіони продукту
                    cur.execute(
                        "SELECT region_id FROM products WHERE id=%s LIMIT 1",
                        (pid,),
                    )
                    pr = cur.fetchone()
                    if isinstance(pr, dict):
                        prod_rid = str(pr.get("region_id") or "").strip()
                        if prod_rid:
                            existing_regions.add(prod_rid)
                    if not existing_regions:
                        existing_regions = {""}  # company-wide fallback

                    # Знаходимо packaging_supplier_id для цього packaging
                    pkg_sup = ""
                    cur.execute(
                        "SELECT data FROM packaging WHERE id=%s LIMIT 1",
                        (apid,),
                    )
                    pkg_row = cur.fetchone()
                    if isinstance(pkg_row, dict):
                        pkg_data = pkg_row.get("data") or {}
                        pkg_sup = str(
                            (pkg_data if isinstance(pkg_data, dict) else {}).get(
                                "supplier_id"
                            )
                            or ""
                        ).strip()

                    for rid in existing_regions:
                        # Знайти або створити контекст
                        cur.execute(
                            """
                            SELECT id, linked_product_ids
                            FROM packaging_supply_contexts
                            WHERE company_id=%s AND region_id=%s AND packaging_id=%s AND goods_supplier_id=%s
                            LIMIT 1
                            """,
                            (cid, rid, apid, gsid),
                        )
                        ctx_exists = cur.fetchone()
                        if isinstance(ctx_exists, dict) and ctx_exists.get("id"):
                            ctx_id = str(ctx_exists["id"]).strip()
                            linked = ctx_exists.get("linked_product_ids") or []
                            if isinstance(linked, (bytes, bytearray)):
                                import json as _json

                                try:
                                    linked = _json.loads(linked)
                                except Exception:
                                    linked = []
                            new_linked = sorted(
                                set(
                                    list(linked if isinstance(linked, list) else [])
                                    + [pid]
                                )
                            )
                            cur.execute(
                                "UPDATE packaging_supply_contexts SET linked_product_ids=%s::jsonb, updated_at=%s WHERE id=%s",
                                (psycopg.types.json.Jsonb(new_linked), now, ctx_id),
                            )
                        else:
                            nid = uuid.uuid4().hex
                            cur.execute(
                                """
                                INSERT INTO packaging_supply_contexts
                                  (id, company_id, region_id, packaging_id, packaging_supplier_id, goods_supplier_id, linked_product_ids, updated_at)
                                VALUES (%s,%s,%s,%s,%s,%s,%s::jsonb,%s)
                                ON CONFLICT DO NOTHING
                                """,
                                (
                                    nid,
                                    cid,
                                    rid,
                                    apid,
                                    pkg_sup,
                                    gsid,
                                    psycopg.types.json.Jsonb([pid]),
                                    now,
                                ),
                            )
            self._pulse(cid, "packaging")
        except Exception:
            logger.exception("_resync_product_packaging_contexts failed pid=%s", pid)

    def sync_packaging_supply_contexts(
        self, company_id: str, region_id: str, manager_id: str | None = None
    ) -> list[dict]:
        """
        Ensure `packaging_supply_contexts` mirrors (packaging SKU × постачальник товару) for the region.
        Returns enriched rows (flat dicts).
        """
        if not self._use_postgres():
            return []

        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()

        pk_rows = [
            x
            for x in (
                self.get_packaging(company_id, region_id, manager_id=manager_id) or []
            )
            if isinstance(x, dict) and str(x.get("id") or "").strip()
        ]
        prod_rows = [
            x
            for x in (
                self.get_products(company_id, region_id, manager_id=manager_id) or []
            )
            if isinstance(x, dict) and str(x.get("id") or "").strip()
        ]

        grouped: dict[tuple[str, str], dict] = {}

        def _ensure_group(pack_id: str, goods_supplier_id: str) -> dict:
            key = (pack_id, goods_supplier_id)
            if key not in grouped:
                grouped[key] = {"product_ids": []}
            return grouped[key]

        for pr in prod_rows:
            pid = str(pr.get("id") or "").strip()
            p_pack = str(pr.get("packaging_id") or "").strip()
            if not pid or not p_pack:
                continue
            gs = str(pr.get("supplier_id") or "").strip()
            g = _ensure_group(p_pack, gs)
            if pid not in g["product_ids"]:
                g["product_ids"].append(pid)

        pack_ids_with_linked_goods = {k[0] for k in grouped}
        for pkg in pk_rows:
            pkid = str(pkg.get("id") or "").strip()
            if pkid and pkid not in pack_ids_with_linked_goods:
                _ensure_group(pkid, "")

        now = datetime.utcnow()
        expected_pairs = {
            (str(packaging_id_key).strip(), str(goods_supplier_id_key).strip())
            for (packaging_id_key, goods_supplier_id_key) in grouped.keys()
        }

        try:
            self._pg_with_packaging_supply_schema()
            with self._pg().cursor() as cur:
                # Build every (packaging, goods_supplier) row up front, then
                # write them all in one batched INSERT ... ON CONFLICT instead
                # of a SELECT + INSERT/UPDATE per group — this used to be
                # 2+ round trips per group (dozens/hundreds of packaging×
                # supplier combos), invisible on localhost but a multi-second
                # stall on every Packaging Stock tab load over the VPS link.
                upsert_rows: list[tuple] = []
                for (
                    packaging_id_key,
                    goods_supplier_id_key,
                ), payload in grouped.items():
                    pk_row = next(
                        (
                            x
                            for x in pk_rows
                            if str(x.get("id") or "").strip() == packaging_id_key
                        ),
                        None,
                    )
                    pkg_supplier = ""
                    if isinstance(pk_row, dict):
                        pkg_supplier = str(
                            pk_row.get("supplier_id")
                            or (
                                (pk_row.get("suppliers") or {})
                                if isinstance(pk_row.get("suppliers"), dict)
                                else {}
                            ).get("id")
                            or ""
                        ).strip()

                    prod_ids_sorted = sorted(
                        {
                            str(x)
                            for x in (payload.get("product_ids") or [])
                            if str(x).strip()
                        }
                    )
                    goods_sid = str(goods_supplier_id_key or "").strip()
                    upsert_rows.append(
                        (
                            uuid.uuid4().hex,
                            company_id,
                            region_id,
                            packaging_id_key,
                            pkg_supplier,
                            goods_sid,
                            psycopg.types.json.Jsonb(prod_ids_sorted),
                            now,
                        )
                    )

                CHUNK = 500
                for i in range(0, len(upsert_rows), CHUNK):
                    chunk = upsert_rows[i : i + CHUNK]
                    placeholders = ", ".join(
                        ["(%s,%s,%s,%s,%s,%s,%s::jsonb,%s)"] * len(chunk)
                    )
                    flat_params = [v for row in chunk for v in row]
                    cur.execute(
                        f"""
                        INSERT INTO packaging_supply_contexts
                          (id, company_id, region_id, packaging_id, packaging_supplier_id, goods_supplier_id, linked_product_ids, updated_at)
                        VALUES {placeholders}
                        ON CONFLICT (company_id, region_id, packaging_id, goods_supplier_id) DO UPDATE SET
                          packaging_supplier_id=EXCLUDED.packaging_supplier_id,
                          linked_product_ids=EXCLUDED.linked_product_ids,
                          updated_at=EXCLUDED.updated_at
                        """,
                        flat_params,
                    )

                # Full-region sync must also prune stale contexts; otherwise removed
                # packaging/SKU pairs remain visible in Packaging Stock.
                if not manager_id:
                    cur.execute(
                        """
                        SELECT id, packaging_id, goods_supplier_id
                        FROM packaging_supply_contexts
                        WHERE company_id=%s AND region_id=%s
                        """,
                        (company_id, region_id),
                    )
                    stale_ctx_ids: list[str] = []
                    for row in cur.fetchall() or []:
                        if not isinstance(row, dict):
                            continue
                        pair = (
                            str(row.get("packaging_id") or "").strip(),
                            str(row.get("goods_supplier_id") or "").strip(),
                        )
                        if pair not in expected_pairs:
                            ctx_id = str(row.get("id") or "").strip()
                            if ctx_id:
                                stale_ctx_ids.append(ctx_id)
                    if stale_ctx_ids:
                        cur.execute(
                            "DELETE FROM packaging_supply_openings WHERE context_id = ANY(%s)",
                            (stale_ctx_ids,),
                        )
                        cur.execute(
                            "DELETE FROM packaging_supply_orders WHERE context_id = ANY(%s)",
                            (stale_ctx_ids,),
                        )
                        cur.execute(
                            "DELETE FROM packaging_supply_contexts WHERE id = ANY(%s)",
                            (stale_ctx_ids,),
                        )

            cid = company_id
            if cid:
                self._pulse(cid, "packaging")
            rows = self.list_packaging_supply_contexts(company_id, region_id)
            if manager_id:
                rows = [
                    r
                    for r in (rows or [])
                    if isinstance(r, dict)
                    and (
                        str(r.get("packaging_id") or "").strip(),
                        str(r.get("goods_supplier_id") or "").strip(),
                    )
                    in expected_pairs
                ]
            return rows
        except Exception:
            logger.exception("sync_packaging_supply_contexts failed")
            rows = self.list_packaging_supply_contexts(company_id, region_id)
            if manager_id:
                rows = [
                    r
                    for r in (rows or [])
                    if isinstance(r, dict)
                    and (
                        str(r.get("packaging_id") or "").strip(),
                        str(r.get("goods_supplier_id") or "").strip(),
                    )
                    in expected_pairs
                ]
            return rows

    def list_packaging_supply_contexts(
        self, company_id: str, region_id: str
    ) -> list[dict]:
        if not self._use_postgres():
            return []

        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        self._pg_with_packaging_supply_schema()
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, company_id, region_id, packaging_id, packaging_supplier_id, goods_supplier_id, linked_product_ids, updated_at
                FROM packaging_supply_contexts
                WHERE company_id=%s AND region_id=%s
                ORDER BY packaging_id ASC, goods_supplier_id ASC
                """,
                (company_id, region_id),
            )
            rows = cur.fetchall() or []
        out = []
        for r in rows or []:
            try:
                out.append(dict(r))
            except Exception:
                if isinstance(r, dict):
                    out.append(r)
        return out

    def get_packaging_supply_opening(self, context_id: str) -> dict | None:
        cid = str(context_id or "").strip()
        if not cid or not self._use_postgres():
            return None
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT context_id, stock_packaging_supplier_qty, stock_goods_supplier_qty, balance_amount, balance_currency,
                       opening_shipped_goods_qty, balance_paid_amount, comment, updated_at
                FROM packaging_supply_openings WHERE context_id=%s LIMIT 1
                """,
                (cid,),
            )
            row = cur.fetchone()
        return dict(row) if isinstance(row, dict) else None

    def save_packaging_supply_opening(
        self,
        *,
        context_id: str,
        stock_packaging_supplier_qty: float,
        stock_goods_supplier_qty: float,
        balance_amount: float,
        balance_currency: str,
        company_id: str,
        opening_shipped_goods_qty: float = 0,
        balance_paid_amount: float = 0,
        comment: str = "",
    ) -> bool:
        if not self._use_postgres():
            return False
        ctx_id = str(context_id or "").strip()
        company_id = str(company_id or "").strip()
        if not ctx_id or not company_id:
            return False
        now = datetime.utcnow()
        ccy = str(balance_currency or "USD").upper().strip() or "USD"
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO packaging_supply_openings
                      (context_id, stock_packaging_supplier_qty, stock_goods_supplier_qty, balance_amount, balance_currency,
                       opening_shipped_goods_qty, balance_paid_amount, comment, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    ON CONFLICT (context_id) DO UPDATE SET
                      stock_packaging_supplier_qty=EXCLUDED.stock_packaging_supplier_qty,
                      stock_goods_supplier_qty=EXCLUDED.stock_goods_supplier_qty,
                      balance_amount=EXCLUDED.balance_amount,
                      balance_currency=EXCLUDED.balance_currency,
                      opening_shipped_goods_qty=EXCLUDED.opening_shipped_goods_qty,
                      balance_paid_amount=EXCLUDED.balance_paid_amount,
                      comment=EXCLUDED.comment,
                      updated_at=EXCLUDED.updated_at
                    """,
                    (
                        ctx_id,
                        float(stock_packaging_supplier_qty or 0),
                        float(stock_goods_supplier_qty or 0),
                        float(balance_amount or 0),
                        ccy,
                        max(
                            0.0,
                            min(
                                float(opening_shipped_goods_qty or 0),
                                float(stock_packaging_supplier_qty or 0),
                            ),
                        ),
                        max(0.0, float(balance_paid_amount or 0)),
                        str(comment or ""),
                        now,
                    ),
                )
            self._pulse(company_id, "packaging")
            return True
        except Exception:
            logger.exception("save_packaging_supply_opening failed")
            return False

    def save_packaging_writeoff(
        self,
        *,
        context_id: str,
        product_id: str = "",
        qty: float = 0,
        pack_qty: float = 0,
        goods_qty: float = 0,
        seq_no: int,
        manager_id: str,
        region_id: str,
        company_id: str,
        comment: str = "Списання",
        invoice_no: str = "",
        order_date: str = "",
    ) -> bool:
        """Зберігає списання пакування.  pack_qty — зі складу постачальника пакування,
        goods_qty — зі складу постачальника товару.  qty залишено для сумісності."""
        if not self._use_postgres():
            return False
        ctx_id = str(context_id or "").strip()
        cid = str(company_id or "").strip()
        if not ctx_id or not cid:
            return False
        pid = str(product_id or "").strip() or ctx_id
        _pack_qty = float(pack_qty or qty or 0)
        _goods_qty = float(goods_qty or 0)
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        now = datetime.utcnow()
        # Parse order_date: accept ISO string or None
        from datetime import date as _date

        try:
            _order_date = (
                _date.fromisoformat(str(order_date or "")[:10]) if order_date else None
            )
        except Exception:
            _order_date = None
        try:
            with self._pg().cursor() as cur:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS packaging_writeoffs (
                        id          uuid DEFAULT gen_random_uuid() PRIMARY KEY,
                        context_id  text NOT NULL,
                        product_id  text NOT NULL,
                        seq_no      int  NOT NULL DEFAULT 1,
                        qty         float8 NOT NULL DEFAULT 0,
                        pack_qty    float8 NOT NULL DEFAULT 0,
                        goods_qty   float8 NOT NULL DEFAULT 0,
                        order_date  date,
                        invoice_no  text NOT NULL DEFAULT '',
                        comment     text NOT NULL DEFAULT 'Списання',
                        manager_id  text NOT NULL DEFAULT '',
                        region_id   text NOT NULL DEFAULT '',
                        company_id  text NOT NULL DEFAULT '',
                        created_at  timestamptz NOT NULL DEFAULT now(),
                        updated_at  timestamptz NOT NULL DEFAULT now(),
                        UNIQUE (context_id, product_id, seq_no, manager_id, region_id)
                    )
                    """)
                for _col, _def in (
                    ("pack_qty", "float8 NOT NULL DEFAULT 0"),
                    ("goods_qty", "float8 NOT NULL DEFAULT 0"),
                    ("order_date", "date"),
                ):
                    with contextlib.suppress(Exception):
                        cur.execute(
                            f"ALTER TABLE packaging_writeoffs ADD COLUMN IF NOT EXISTS {_col} {_def}"
                        )
                cur.execute(
                    """
                    INSERT INTO packaging_writeoffs
                      (context_id, product_id, seq_no, qty, pack_qty, goods_qty,
                       order_date, invoice_no, comment, manager_id, region_id, company_id,
                       created_at, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    ON CONFLICT (context_id, product_id, seq_no, manager_id, region_id)
                    DO UPDATE SET
                      qty=EXCLUDED.qty, pack_qty=EXCLUDED.pack_qty,
                      goods_qty=EXCLUDED.goods_qty, order_date=EXCLUDED.order_date,
                      invoice_no=EXCLUDED.invoice_no,
                      comment=EXCLUDED.comment, updated_at=EXCLUDED.updated_at
                    """,
                    (
                        ctx_id,
                        pid,
                        int(seq_no or 1),
                        _pack_qty,
                        _pack_qty,
                        _goods_qty,
                        _order_date,
                        str(invoice_no or ""),
                        str(comment or "Списання"),
                        mid,
                        rid,
                        cid,
                        now,
                        now,
                    ),
                )
            self._pulse(cid, "packaging")
            return True
        except Exception:
            logger.exception("save_packaging_writeoff failed")
            return False

    def delete_packaging_writeoff(
        self,
        *,
        context_id: str,
        seq_no: int,
        manager_id: str,
        region_id: str,
        company_id: str,
        id: str = "",
    ) -> bool:
        """Видаляє списання за id (якщо передано) або context_id + seq_no."""
        if not self._use_postgres():
            return False
        row_id = str(id or "").strip()
        ctx_id = str(context_id or "").strip()
        cid = str(company_id or "").strip()
        if not cid:
            return False
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        try:
            with self._pg().cursor() as cur:
                if row_id:
                    cur.execute(
                        "DELETE FROM packaging_writeoffs WHERE id=%s::uuid AND company_id=%s",
                        (row_id, cid),
                    )
                else:
                    if not ctx_id:
                        return False
                    cur.execute(
                        """
                        DELETE FROM packaging_writeoffs
                        WHERE context_id=%s AND seq_no=%s
                          AND manager_id=%s AND region_id=%s
                        """,
                        (ctx_id, int(seq_no or 0), mid, rid),
                    )
            self._pulse(cid, "packaging")
            return True
        except Exception:
            logger.exception("delete_packaging_writeoff failed")
            return False

    def get_packaging_writeoffs(
        self,
        context_id: str,
        product_id: str = "",
        manager_id: str = "",
        region_id: str = "",
    ) -> list[dict]:
        """Повертає список списань для даного контексту.
        product_id ігнорується (залишено для сумісності)."""
        if not self._use_postgres():
            return []
        ctx_id = str(context_id or "").strip()
        if not ctx_id:
            return []
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        try:
            with self._pg().cursor() as cur:
                # The table is otherwise only ever created lazily by
                # add_packaging_writeoff() on the first write -- a company
                # that only ever READS this (e.g. just opening the view)
                # before anyone has recorded a single write-off would hit
                # UndefinedTable here. Ensure it exists on the read path too.
                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        CREATE TABLE IF NOT EXISTS packaging_writeoffs (
                            id          uuid DEFAULT gen_random_uuid() PRIMARY KEY,
                            context_id  text NOT NULL,
                            product_id  text NOT NULL,
                            seq_no      int  NOT NULL DEFAULT 1,
                            qty         float8 NOT NULL DEFAULT 0,
                            pack_qty    float8 NOT NULL DEFAULT 0,
                            goods_qty   float8 NOT NULL DEFAULT 0,
                            order_date  date,
                            invoice_no  text NOT NULL DEFAULT '',
                            comment     text NOT NULL DEFAULT 'Списання',
                            manager_id  text NOT NULL DEFAULT '',
                            region_id   text NOT NULL DEFAULT '',
                            company_id  text NOT NULL DEFAULT '',
                            created_at  timestamptz NOT NULL DEFAULT now(),
                            updated_at  timestamptz NOT NULL DEFAULT now(),
                            UNIQUE (context_id, product_id, seq_no, manager_id, region_id)
                        )
                        """
                    )
                # Ensure new columns exist before reading them (idempotent, cheap DDL)
                for _col, _def in (
                    ("pack_qty", "float8 NOT NULL DEFAULT 0"),
                    ("goods_qty", "float8 NOT NULL DEFAULT 0"),
                    ("order_date", "date"),
                ):
                    with contextlib.suppress(Exception):
                        cur.execute(
                            f"ALTER TABLE packaging_writeoffs ADD COLUMN IF NOT EXISTS {_col} {_def}"
                        )
                cur.execute(
                    """
                    SELECT id, context_id, product_id, seq_no,
                           qty, pack_qty, goods_qty, order_date,
                           invoice_no, comment, manager_id, region_id,
                           created_at, updated_at
                    FROM packaging_writeoffs
                    WHERE context_id=%s AND manager_id=%s AND region_id=%s
                    ORDER BY seq_no
                    """,
                    (ctx_id, mid, rid),
                )
                rows = cur.fetchall()
                result = []
                for r in rows or []:
                    d = dict(r)
                    # For pre-migration rows pack_qty defaults to 0 — fall back to qty
                    d["pack_qty"] = float(d.get("pack_qty") or d.get("qty") or 0)
                    d["goods_qty"] = float(d.get("goods_qty") or 0)
                    # Normalise order_date to ISO string or None
                    _od = d.get("order_date")
                    d["order_date"] = (
                        str(_od.isoformat())
                        if hasattr(_od, "isoformat")
                        else (str(_od)[:10] if _od else None)
                    )
                    result.append(d)
                return result
        except Exception:
            logger.exception("get_packaging_writeoffs failed")
            return []

    def packaging_writeoff_next_seq(
        self,
        context_id: str,
        product_id: str = "",
        manager_id: str = "",
        region_id: str = "",
    ) -> int:
        """Наступний порядковий номер списання для контексту."""
        rows = self.get_packaging_writeoffs(
            context_id, manager_id=manager_id, region_id=region_id
        )
        if not rows:
            return 1
        return max(int(r.get("seq_no") or 0) for r in rows) + 1

    def packaging_supply_next_seq(self, context_id: str) -> int:
        ctx_id = str(context_id or "").strip()
        if not ctx_id or not self._use_postgres():
            return 1
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT COALESCE(MAX(seq_no), 0) + 1 AS n
                FROM packaging_supply_orders
                WHERE context_id=%s AND row_kind=%s
                """,
                (ctx_id, "supply"),
            )
            row = cur.fetchone() or {}
            try:
                return int(row.get("n") or 1)
            except Exception:
                return 1

    def renumber_packaging_supply_seq(self, context_id: str) -> bool:
        """
        Перепризначити seq_no 1..N для рядків row_kind='supply' у контексті за хронологією як у журналі
        (дата → інвойс → попередній seq → created_at).
        """
        ctx = str(context_id or "").strip()
        if not ctx or not self._use_postgres():
            return False
        now = datetime.utcnow()
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id
                    FROM packaging_supply_orders
                    WHERE context_id=%s AND row_kind=%s
                    ORDER BY order_date ASC NULLS LAST,
                             COALESCE(invoice_no,'') ASC,
                             seq_no ASC,
                             created_at ASC
                    """,
                    (ctx, "supply"),
                )
                ids = []
                for r in cur.fetchall() or []:
                    if isinstance(r, dict) and str(r.get("id") or "").strip():
                        ids.append(str(r["id"]))
                # Batched UPDATE-from-VALUES instead of one execute() per row
                # — this renumbers on every supply-order add/edit/delete, and
                # a context can hold hundreds of rows.
                CHUNK = 500
                for start in range(0, len(ids), CHUNK):
                    batch = ids[start : start + CHUNK]
                    values_sql = ", ".join(["(%s::varchar, %s::integer)"] * len(batch))
                    id_seq_params: list = []
                    for offset, rid in enumerate(batch):
                        id_seq_params.extend([rid, start + offset + 1])
                    params = [now, *id_seq_params, ctx, "supply"]
                    cur.execute(
                        f"""
                        UPDATE packaging_supply_orders AS t
                        SET seq_no = v.seq_no, updated_at = %s
                        FROM (VALUES {values_sql}) AS v(id, seq_no)
                        WHERE t.id = v.id AND t.context_id=%s AND t.row_kind=%s
                        """,
                        params,
                    )
            return True
        except Exception:
            logger.exception("renumber_packaging_supply_seq failed ctx=%s", ctx[:24])
            return False

    def list_packaging_supply_orders(self, context_id: str) -> list[dict]:
        cid = str(context_id or "").strip()
        if not cid or not self._use_postgres():
            return []
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, context_id, seq_no, order_date, qty_ordered, status, cost_amount, paid_amount,
                       shipped_goods_supplier_qty, zp_1c, invoice_no, comment, row_kind, linked_order_id, linked_order_line_key,
                       created_at, updated_at
                FROM packaging_supply_orders
                WHERE context_id=%s AND row_kind IN ('supply','goods')
                ORDER BY order_date ASC NULLS LAST,
                         COALESCE(invoice_no,'') ASC,
                         CASE WHEN row_kind = 'goods' THEN 0 ELSE 1 END,
                         seq_no ASC,
                         COALESCE(linked_order_line_key,'') ASC,
                         created_at ASC
                """,
                (cid,),
            )
            rows = cur.fetchall() or []
        out = []
        for r in rows or []:
            try:
                out.append(dict(r))
            except Exception:
                if isinstance(r, dict):
                    out.append(r)
        return out

    def add_packaging_supply_order(self, payload: dict) -> str:
        if not self._use_postgres() or not isinstance(payload, dict):
            return ""
        company_id = str(payload.get("company_id") or "").strip()
        ctx_id = str(payload.get("context_id") or "").strip()
        if not company_id or not ctx_id:
            return ""
        oid = uuid.uuid4().hex
        now = datetime.utcnow()
        seq_no = int(payload.get("seq_no") or self.packaging_supply_next_seq(ctx_id))
        qty = float(payload.get("qty_ordered") or 0)
        status = str(payload.get("status") or "production").strip() or "production"
        cost = payload.get("cost_amount")
        paid = float(payload.get("paid_amount") or 0)
        shipped = float(payload.get("shipped_goods_supplier_qty") or 0)
        zp = str(payload.get("zp_1c") or "")
        inv = str(payload.get("invoice_no") or "")
        cmt = str(payload.get("comment") or "")
        od = payload.get("order_date")
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO packaging_supply_orders
                      (id, context_id, seq_no, order_date, qty_ordered, status, cost_amount, paid_amount,
                       shipped_goods_supplier_qty, zp_1c, invoice_no, comment, row_kind, linked_order_id, linked_order_line_key,
                       created_at, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        oid,
                        ctx_id,
                        seq_no,
                        od if od else None,
                        qty,
                        status,
                        (float(cost) if cost not in (None, "") else None),
                        paid,
                        shipped,
                        zp or None,
                        inv or None,
                        cmt or None,
                        "supply",
                        None,
                        None,
                        now,
                        now,
                    ),
                )
            self.renumber_packaging_supply_seq(ctx_id)
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "payments")
            return oid
        except Exception:
            logger.exception("add_packaging_supply_order failed")
        return ""

    def update_packaging_supply_order(self, order_id: str, payload: dict) -> bool:
        if not self._use_postgres() or not isinstance(payload, dict):
            return False
        oid = str(order_id or "").strip()
        if not oid:
            return False
        defer_reconcile: tuple[str, str, str] | None = None
        pulse_orders_extra = False
        company_pulse = ""
        ren_ctx = ""
        supply_update_done = False

        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT pso.row_kind, pso.linked_order_id, pso.linked_order_line_key,
                           pso.context_id, psc.company_id, pso.comment
                    FROM packaging_supply_orders pso
                    JOIN packaging_supply_contexts psc ON psc.id = pso.context_id
                    WHERE pso.id=%s LIMIT 1
                    """,
                    (oid,),
                )
                meta = cur.fetchone()
                if (
                    not isinstance(meta, dict)
                    or not str(meta.get("context_id") or "").strip()
                ):
                    # Row is gone (deleted locally/elsewhere, or its context was
                    # regenerated) — nothing to patch. Treat as success like
                    # delete_packaging_writeoff does for a missing row, otherwise
                    # this op retries forever and pins the sync indicator on
                    # "Не збережено" until the 5-retry auto-drop kicks in.
                    logger.warning(
                        "update_packaging_supply_order: row/context not found id=%s payload_keys=%s",
                        oid[:32],
                        list(payload.keys()),
                    )
                    return True

                row_kind = str(meta.get("row_kind") or "").strip()

                sets: list[str] = []
                vals: list[Any] = []

                if "order_date" in payload:
                    odv = payload.get("order_date")
                    sets.append("order_date=%s")
                    vals.append(odv if odv else None)
                if "qty_ordered" in payload:
                    sets.append("qty_ordered=%s")
                    vals.append(float(payload.get("qty_ordered") or 0))
                if "status" in payload:
                    sets.append("status=%s")
                    vals.append(
                        str(payload.get("status") or "production").strip()
                        or "production"
                    )
                if "cost_amount" in payload:
                    ca = payload.get("cost_amount")
                    sets.append("cost_amount=%s")
                    vals.append(float(ca) if ca not in (None, "") else None)
                if "paid_amount" in payload:
                    sets.append("paid_amount=%s")
                    vals.append(float(payload.get("paid_amount") or 0))
                if "shipped_goods_supplier_qty" in payload:
                    sets.append("shipped_goods_supplier_qty=%s")
                    vals.append(float(payload.get("shipped_goods_supplier_qty") or 0))
                if "zp_1c" in payload:
                    sets.append("zp_1c=%s")
                    vals.append(str(payload.get("zp_1c") or "") or None)
                if "invoice_no" in payload:
                    sets.append("invoice_no=%s")
                    vals.append(str(payload.get("invoice_no") or "") or None)
                if "comment" in payload:
                    sets.append("comment=%s")
                    vals.append(str(payload.get("comment") or "") or None)

                if sets:
                    sets.append("updated_at=%s")
                    vals.append(datetime.utcnow())
                    vals.append(oid)
                    cur.execute(
                        "UPDATE packaging_supply_orders SET "
                        + ", ".join(sets)
                        + " WHERE id=%s",
                        tuple(vals),
                    )
                    rc = getattr(cur, "rowcount", -1)
                    if rc == 0:
                        logger.warning(
                            "update_packaging_supply_order: UPDATE зачепив 0 рядків id=%s payload_keys=%s",
                            str(oid)[:32],
                            list(payload.keys()),
                        )
                        return False
                    ren_ctx = str(meta.get("context_id") or "").strip()
                    if row_kind == "supply":
                        supply_update_done = True

                company_pulse = str(meta.get("company_id") or "").strip()

                if row_kind == "goods" and company_pulse:
                    linked_oid = str(meta.get("linked_order_id") or "").strip()
                    line_key_raw = meta.get("linked_order_line_key")
                    zp_fix = payload.get("zp_1c") if "zp_1c" in payload else None
                    inv_fix = (
                        payload.get("invoice_no") if "invoice_no" in payload else None
                    )
                    qty_fix = (
                        payload.get("qty_ordered") if "qty_ordered" in payload else None
                    )
                    od_fix = (
                        payload.get("order_date") if "order_date" in payload else None
                    )
                    cmt_fix = payload.get("comment") if "comment" in payload else None
                    if linked_oid and any(
                        v is not None
                        for v in (zp_fix, inv_fix, qty_fix, od_fix, cmt_fix)
                    ):
                        cur.execute(
                            "SELECT manager_id, region_id, data FROM orders WHERE id=%s LIMIT 1",
                            (linked_oid,),
                        )
                        ox = cur.fetchone()
                        if isinstance(ox, dict):
                            d2 = dict(ox.get("data") or {})
                            its = (
                                list(d2.get("items") or [])
                                if isinstance(d2.get("items"), list)
                                else []
                            )
                            pack_comment_meta = str(meta.get("comment") or "")
                            line_resolved = _resolve_packaging_goods_item_index(
                                its,
                                pack_comment_meta,
                                line_key_raw,
                            )
                            chg = False
                            if zp_fix is not None:
                                zs = str(zp_fix or "").strip()[:40]
                                d2["order_no_1c"] = zs
                                if 0 <= line_resolved < len(its) and isinstance(
                                    its[line_resolved], dict
                                ):
                                    its[line_resolved]["order_no_1c"] = zs
                                chg = True
                            if inv_fix is not None:
                                iv = str(inv_fix or "").strip()[:40]
                                d2["invoice_no"] = iv
                                if 0 <= line_resolved < len(its) and isinstance(
                                    its[line_resolved], dict
                                ):
                                    its[line_resolved]["invoice_no"] = iv
                                chg = True
                            if (
                                qty_fix is not None
                                and 0 <= line_resolved < len(its)
                                and isinstance(its[line_resolved], dict)
                            ):
                                try:
                                    qv = float(str(qty_fix).replace(",", ".").strip())
                                except Exception:
                                    qv = 0.0
                                its[line_resolved]["qty"] = qv
                                its[line_resolved]["quantity"] = qv
                                chg = True
                            if od_fix is not None:
                                od_txt = str(od_fix or "").strip()[:10]
                                if od_txt:
                                    d2["order_date"] = od_txt
                                    chg = True
                            if (
                                cmt_fix is not None
                                and 0 <= line_resolved < len(its)
                                and isinstance(its[line_resolved], dict)
                            ):
                                its[line_resolved]["item_comment"] = str(
                                    cmt_fix or ""
                                ).strip()[:400]
                                chg = True
                            if chg:
                                d2["items"] = its
                                d2["updated_at"] = datetime.utcnow().isoformat(
                                    timespec="seconds"
                                )
                                cur.execute(
                                    "UPDATE orders SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                                    (
                                        psycopg.types.json.Jsonb(d2),
                                        self._now_ts(),
                                        linked_oid,
                                    ),
                                )
                                pulse_orders_extra = True
                                mgr = str(ox.get("manager_id") or "").strip()
                                rid_ord = str(ox.get("region_id") or "").strip()
                                if mgr and rid_ord:
                                    defer_reconcile = (company_pulse, rid_ord, mgr)

            if supply_update_done and ren_ctx:
                self.renumber_packaging_supply_seq(ren_ctx)

            if defer_reconcile:
                c0, r0, m0 = defer_reconcile
                with contextlib.suppress(Exception):
                    self.reconcile_packaging_supply_goods_links(c0, r0, manager_id=m0)

            if company_pulse:
                self._pulse(company_pulse, "packaging")
                self._pulse(company_pulse, "payments")
                if pulse_orders_extra:
                    self._pulse(company_pulse, "orders")
            return True
        except Exception:
            logger.exception("update_packaging_supply_order failed")
        return False

    def delete_packaging_supply_order(self, order_id: str) -> bool:
        if not self._use_postgres():
            return False
        oid = str(order_id or "").strip()
        if not oid:
            return False
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT psc.company_id, pso.row_kind, psc.region_id, pso.context_id
                    FROM packaging_supply_orders pso
                    JOIN packaging_supply_contexts psc ON psc.id = pso.context_id
                    WHERE pso.id=%s LIMIT 1
                    """,
                    (oid,),
                )
                meta = cur.fetchone()
                del_ctx = (
                    str((meta or {}).get("context_id") or "").strip()
                    if isinstance(meta, dict)
                    else ""
                )
                is_supply_del = (
                    isinstance(meta, dict)
                    and str(meta.get("row_kind") or "").strip() != "goods"
                )
                if (
                    isinstance(meta, dict)
                    and str(meta.get("row_kind") or "").strip() == "goods"
                ):
                    return False
                cur.execute("DELETE FROM packaging_supply_orders WHERE id=%s", (oid,))
            if is_supply_del and del_ctx:
                self.renumber_packaging_supply_seq(del_ctx)
            company_id = str((meta or {}).get("company_id") or "").strip()
            if company_id:
                self._pulse(company_id, "packaging")
                self._pulse(company_id, "payments")
            return True
        except Exception:
            logger.exception("delete_packaging_supply_order failed")
            return False

    def get_suppliers(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        force_refresh: bool | None = None,
        archived: bool | None = False,
    ):
        """Cache-aside wrapper — see _cached_list. Cleared by
        invalidate_suppliers_cache() on any supplier add/update/delete."""
        if not self._use_postgres():
            return self._get_suppliers_uncached(
                company_id, region_id, manager_id, force_refresh, archived
            )
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        cache_key = f"suppliers_{cid}_{rid}_{mid}_{bool(archived)}"
        return self._cached_list(
            cache_key,
            bool(force_refresh),
            lambda: self._get_suppliers_uncached(
                company_id, region_id, manager_id, force_refresh, archived
            ),
        )

    def _get_suppliers_uncached(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        force_refresh: bool | None = None,  # noqa: ARG002
        archived: bool | None = False,
    ):
        if not self._use_postgres():
            return (
                self._get(
                    "/suppliers",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()
        archived_clause = (
            "" if archived is None else ("AND is_archived=TRUE" if archived else "AND is_archived=FALSE")
        )
        with self._pg().cursor() as cur:
            q = f"""
            SELECT id, company_id, region_id, manager_id, name, data, created_at, updated_at
            FROM suppliers
            WHERE company_id=%s {archived_clause}
            """
            params: list[Any] = [company_id]
            if region_id:
                q += " AND region_id=%s"
                params.append(region_id)
            q += " ORDER BY name ASC"
            cur.execute(q, params)
            rows = cur.fetchall() or []
        # Flatten jsonb `data` into top-level fields for UI compatibility.
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = dict(r)
            for k, v in (data or {}).items():
                if k not in merged or merged.get(k) in (None, ""):
                    merged[k] = v
            merged.pop("data", None)
            out.append(merged)
        if manager_id:
            visible_ctx = self._get_manager_visible_scope_context(
                company_id, manager_id, region_id or None
            )
            if visible_ctx.get("restricted"):
                allowed_supplier_ids = set(visible_ctx.get("supplier_ids") or set())
                # Keep directly assigned/created suppliers visible even before they are
                # linked to any in-scope products.
                allowed_supplier_ids.update(
                    self.get_entity_owner_entity_ids(company_id, manager_id, "supplier")
                    or []
                )
                allowed_supplier_ids.update(
                    str(row.get("id") or "").strip()
                    for row in out
                    if isinstance(row, dict)
                    and str(row.get("manager_id") or "").strip() == manager_id
                )
                allowed_supplier_ids.discard("")
                out = [
                    row
                    for row in out
                    if isinstance(row, dict)
                    and str(row.get("id") or "").strip() in allowed_supplier_ids
                ]
        return out

    def search_suppliers_company(
        self, company_id: str, query: str, limit: int = 5, region_id: str | None = None
    ):
        """
        Used by Suppliers dialog quick-fill to find similar suppliers by name (and some common fields).
        Returns list of supplier dict rows.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/suppliers/search_company",
                    {
                        "company_id": company_id,
                        "query": query,
                        "limit": int(limit or 5),
                        "region_id": region_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        qtxt = str(query or "").strip()
        region_id = str(region_id or "").strip()
        try:
            lim = int(limit or 5)
        except Exception:
            lim = 5
        lim = max(1, min(20, lim))
        if not company_id or len(qtxt) < 2:
            return []
        pat = f"%{qtxt}%"
        with self._pg().cursor() as cur:
            sql = """
            SELECT id, company_id, region_id, manager_id, name, data, created_at, updated_at
            FROM suppliers
            WHERE company_id=%s
              AND (
                name ILIKE %s
                OR (data->>'phone') ILIKE %s
                OR (data->>'swift') ILIKE %s
                OR (data->>'alipay_id') ILIKE %s
                OR (data->>'wechat_id') ILIKE %s
              )
            """
            params: list[Any] = [company_id, pat, pat, pat, pat, pat]
            if region_id:
                sql += " AND region_id=%s"
                params.append(region_id)
            sql += " ORDER BY updated_at DESC LIMIT %s"
            params.append(lim)
            cur.execute(sql, params)
            rows = cur.fetchall() or []
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = dict(r)
            for k, v in (data or {}).items():
                if k not in merged or merged.get(k) in (None, ""):
                    merged[k] = v
            merged.pop("data", None)
            out.append(merged)
        return out

    @staticmethod
    def _normalize_supplier_name(raw_name: Any) -> str:
        return " ".join(str(raw_name or "").strip().split()).lower()

    def supplier_name_exists(
        self,
        company_id: str,
        name: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        exclude_supplier_id: str | None = None,
    ) -> bool:
        normalized_name = self._normalize_supplier_name(name)
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        exclude_id = str(exclude_supplier_id or "").strip()
        if not cid or not rid or not normalized_name:
            return False

        if not self._use_postgres():
            rows = self.get_suppliers(cid, rid, manager_id=(mid or None)) or []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                if exclude_id and str(row.get("id") or "").strip() == exclude_id:
                    continue
                if self._normalize_supplier_name(row.get("name")) == normalized_name:
                    return True
            return False

        with self._pg().cursor() as cur:
            sql = ["""
                SELECT 1
                FROM suppliers
                WHERE company_id=%s
                  AND region_id=%s
                  AND lower(trim(name))=%s
                """]
            params: list[Any] = [cid, rid, normalized_name]
            if mid:
                sql.append("AND manager_id=%s")
                params.append(mid)
            if exclude_id:
                sql.append("AND id<>%s")
                params.append(exclude_id)
            sql.append("LIMIT 1")
            cur.execute("\n".join(sql), params)
            return bool(cur.fetchone())

    def add_supplier(self, payload: dict):
        """
        Insert supplier into `suppliers`.
        Payload is a flattened dict used by UI (name/phone/currency/swift/...).
        Returns supplier id (truthy) or ""/False on failure.
        """
        if not self._use_postgres():
            return str(self._post("/suppliers/add", payload) or "")
        if not isinstance(payload, dict):
            return ""
        company_id = str(payload.get("company_id") or "").strip()
        region_id = str(payload.get("region_id") or "").strip()
        manager_id = str(payload.get("manager_id") or "").strip()
        name = str(payload.get("name") or "").strip() or "Постачальник"
        if not company_id or not region_id:
            return ""
        if self.supplier_name_exists(
            company_id,
            name,
            region_id=region_id,
            manager_id=(manager_id or None),
        ):
            return ""
        sid = uuid.uuid4().hex
        now = self._now_ts()
        # Store full supplier fields inside jsonb `data` as well, so searches work.
        data = dict(payload)
        # Keep normalized duplicates out of jsonb if needed later; for now store all.
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO suppliers
                      (id, company_id, region_id, manager_id, name, data, created_at, updated_at)
                    VALUES
                      (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                    """,
                    (
                        sid,
                        company_id,
                        region_id,
                        manager_id,
                        name,
                        psycopg.types.json.Jsonb(data),
                        now,
                        now,
                    ),
                )
                if manager_id:
                    cur.execute(
                        """
                        INSERT INTO entity_owners
                          (company_id, entity_type, entity_id, manager_id, created_at)
                        VALUES (%s,%s,%s,%s,%s)
                        ON CONFLICT DO NOTHING
                        """,
                        (company_id, "supplier", sid, manager_id, now),
                    )
            self._pulse(company_id, "suppliers")
            self.invalidate_suppliers_cache(company_id)
            return sid
        except Exception:
            logger.exception("add_supplier failed")
            return ""

    def update_supplier(self, supplier_id: str, payload: dict) -> bool:
        if not self._use_postgres():
            return bool(
                self._post("/suppliers/update", {"id": supplier_id, **(payload or {})})
                or False
            )
        sid = str(supplier_id or "").strip()
        if not sid or not isinstance(payload, dict):
            return False
        name = str(payload.get("name") or "").strip()
        currency = str(payload.get("currency") or "").upper().strip()
        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT company_id, region_id, manager_id, data FROM suppliers WHERE id=%s LIMIT 1",
                (sid,),
            )
            row = cur.fetchone() or {}
            company_id = str(row.get("company_id") or "").strip()
            region_id = str(
                payload.get("region_id") or row.get("region_id") or ""
            ).strip()
            manager_id = str(
                payload.get("manager_id") or row.get("manager_id") or ""
            ).strip()
            if name and self.supplier_name_exists(
                company_id,
                name,
                region_id=region_id,
                manager_id=(manager_id or None),
                exclude_supplier_id=sid,
            ):
                return False
            current_data = row.get("data") if isinstance(row.get("data"), dict) else {}
            merged = dict(current_data or {})
            # A payload that started life as a flattened get_suppliers()/
            # get_supplier_by_id()-style dict (edited in place and passed
            # straight back here) can carry a residual "data" key -- never
            # let it overwrite `merged` and nest a stale snapshot inside the
            # supplier's own new data blob.
            _payload_clean = {k: v for k, v in payload.items() if k != "data"}
            merged.update(_payload_clean)
            sets = ["data=%s::jsonb", "updated_at=%s"]
            params: list[Any] = [psycopg.types.json.Jsonb(merged), now]
            if name:
                sets.insert(0, "name=%s")
                params.insert(0, name)
            params.append(sid)
            cur.execute(
                "UPDATE suppliers SET " + ", ".join(sets) + " WHERE id=%s",
                params,
            )
        if company_id:
            self._sync_supplier_references(
                company_id,
                sid,
                supplier_name=(name or None),
                supplier_currency=(currency or None),
                deleted=False,
            )
        if company_id:
            self._pulse(company_id, "suppliers")
            self._pulse(company_id, "products")
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "orders")
            self._pulse(company_id, "payments")
            self.invalidate_suppliers_cache(company_id)
            self.invalidate_products_cache(company_id)
            self.invalidate_packaging_cache(company_id)
        return True

    def archive_supplier(self, supplier_id: str) -> bool:
        """Soft-архівує постачальника замість фізичного видалення — старі замовлення
        й взаєморозрахунки й далі резолвлять назву постачальника по id."""
        if not self._use_postgres():
            return bool(self._post("/suppliers/archive", {"id": supplier_id}) or False)
        sid = str(supplier_id or "").strip()
        if not sid:
            return False
        with self._pg().cursor() as cur:
            cur.execute("SELECT company_id FROM suppliers WHERE id=%s LIMIT 1", (sid,))
            row = cur.fetchone() or {}
            company_id = str(row.get("company_id") or "").strip()
            cur.execute(
                "UPDATE suppliers SET is_archived=TRUE, archived_at=%s WHERE id=%s",
                (self._now_ts(), sid),
            )
        if company_id:
            self._pulse(company_id, "suppliers")
            self._pulse(company_id, "products")
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "orders")
            self._pulse(company_id, "payments")
            self.invalidate_suppliers_cache(company_id)
            self.invalidate_products_cache(company_id)
            self.invalidate_packaging_cache(company_id)
        return True

    def restore_supplier(self, supplier_id: str) -> bool:
        sid = str(supplier_id or "").strip()
        if not sid or not self._use_postgres():
            return False
        with self._pg().cursor() as cur:
            cur.execute("SELECT company_id FROM suppliers WHERE id=%s LIMIT 1", (sid,))
            row = cur.fetchone() or {}
            company_id = str(row.get("company_id") or "").strip()
            cur.execute(
                "UPDATE suppliers SET is_archived=FALSE, archived_at=NULL WHERE id=%s",
                (sid,),
            )
        if company_id:
            self._pulse(company_id, "suppliers")
            self._pulse(company_id, "products")
            self._pulse(company_id, "packaging")
            self._pulse(company_id, "orders")
            self._pulse(company_id, "payments")
            self.invalidate_suppliers_cache(company_id)
            self.invalidate_products_cache(company_id)
            self.invalidate_packaging_cache(company_id)
        return True

    def get_orders(
        self,
        company_id: str,
        region_id: str | None = None,
        limit: int | None = None,
        offset: int | None = None,
        manager_id: str | None = None,
        force_refresh: bool | None = None,
        visible_product_ids: list[str] | None = None,
    ):  # noqa: ARG002
        if not self._use_postgres():
            return (
                self._get(
                    "/orders",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "limit": int(limit or 0) or "",
                        "offset": int(offset or 0) or "",
                        "manager_id": manager_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()
        visible_product_ids = (
            [
                str(x or "").strip()
                for x in visible_product_ids or []
                if str(x or "").strip()
            ]
            if visible_product_ids is not None
            else None
        )
        if visible_product_ids is not None and len(visible_product_ids) == 0:
            return []
        limit_n = int(limit) if isinstance(limit, int) and limit > 0 else None
        offset_n = int(offset) if isinstance(offset, int) and offset > 0 else 0

        # Pre-compute scope context so SQL can include entity_owner order IDs.
        # Orders assigned to this manager via entity_owners may have a different
        # SQL manager_id column value — they would be silently excluded by the
        # visible_product_ids SQL filter unless we explicitly include them here.
        visible_ctx = None
        if manager_id:
            visible_ctx = self._get_manager_visible_scope_context(
                company_id, manager_id, region_id or None
            )

        with self._pg().cursor() as cur:
            q = """
            SELECT id, company_id, region_id, manager_id, supplier_id, data, created_at, updated_at
            FROM orders
            WHERE company_id=%s
            """
            params: list[Any] = [company_id]
            if region_id:
                q += " AND region_id=%s"
                params.append(region_id)
            if visible_product_ids is not None:
                _owner_mid = str(manager_id or "").strip()
                if _owner_mid:
                    # Include orders visible via entity_owners even when their SQL
                    # manager_id column differs from the current manager's ID.
                    _scope_order_ids = list((visible_ctx or {}).get("order_ids") or [])
                    q += " AND (manager_id=%s"
                    params.append(_owner_mid)
                    if _scope_order_ids:
                        q += " OR id = ANY(%s)"
                        params.append(_scope_order_ids)
                    q += " OR EXISTS ("
                    q += " SELECT 1 FROM jsonb_array_elements(COALESCE(data->'items', '[]'::jsonb)) AS it"
                    q += " WHERE (it->>'product_id') = ANY(%s)"
                    q += " ))"
                    params.append(visible_product_ids)
                else:
                    q += " AND EXISTS ("
                    q += " SELECT 1 FROM jsonb_array_elements(COALESCE(data->'items', '[]'::jsonb)) AS it"
                    q += " WHERE (it->>'product_id') = ANY(%s)"
                    q += " )"
                    params.append(visible_product_ids)
            q += " ORDER BY updated_at DESC"
            if limit_n is not None:
                q += " LIMIT %s OFFSET %s"
                params.extend([limit_n, offset_n])
            cur.execute(q, params)
            rows = cur.fetchall() or []

        # Flatten jsonb `data` into top-level keys for UI compatibility.
        # SQL-level identity columns must not be clobbered by stale values in the
        # JSON blob (e.g. data["manager_id"] = "" would break _is_order_visible).
        _SQL_COLS = (
            "id",
            "company_id",
            "region_id",
            "manager_id",
            "supplier_id",
            "created_at",
            "updated_at",
        )
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            merged = {**r, **data}
            for _col in _SQL_COLS:
                if _col in r and r[_col] is not None:
                    merged[_col] = r[_col]
            # `r` carries a literal "data" key (the raw jsonb column) that's
            # now fully unpacked into the flat fields above -- drop it so a
            # caller that fetches an order, edits a couple of fields, and
            # passes the same dict straight back to upsert_order() can't
            # round-trip this residual key as the new data blob and nest a
            # stale snapshot inside itself (upsert_order's `data.data ||
            # EXCLUDED.data` merge doesn't know this key is stale baggage).
            merged.pop("data", None)
            out.append(merged)
        if manager_id and visible_ctx is not None:
            if visible_ctx.get("restricted"):
                allowed_order_ids = visible_ctx.get("order_ids") or set()
                out = [
                    row
                    for row in out
                    if isinstance(row, dict)
                    and str(row.get("id") or "").strip() in allowed_order_ids
                ]
        return out

    def get_order_by_id(
        self,
        order_id: str,
        company_id: str | None = None,
        manager_id: str | None = None,
        force_refresh: (
            bool | None
        ) = None,  # noqa: ARG002 — API parity with get_orders callers
    ):
        """One Postgres order row (jsonb merged). HTTP mode → None."""
        if not self._use_postgres():
            return None
        oid = str(order_id or "").strip()
        if not oid:
            return None
        cid_f = str(company_id or "").strip()
        mid_f = str(manager_id or "").strip()
        with self._pg().cursor() as cur:
            q = """
            SELECT id, company_id, region_id, manager_id, supplier_id, data, created_at, updated_at
            FROM orders
            WHERE id=%s
            """
            params: list[Any] = [oid]
            if cid_f:
                q += " AND company_id=%s"
                params.append(cid_f)
            if mid_f:
                q += " AND manager_id=%s"
                params.append(mid_f)
            q += " LIMIT 1"
            cur.execute(q, params)
            r = cur.fetchone()
        if not isinstance(r, dict):
            return None
        data = r.get("data") if isinstance(r.get("data"), dict) else {}
        merged = {**r, **data}
        # See get_orders() for why this residual key must not survive the
        # flatten -- callers regularly mutate a couple of fields on the
        # returned dict and hand it straight back to upsert_order().
        merged.pop("data", None)
        return merged

    def reconcile_packaging_supply_goods_links(
        self, company_id: str, region_id: str, manager_id: str | None = None
    ) -> None:
        """
        Повторно будує рядки `packaging_supply_orders` з `row_kind='goods'` з замовлень:
        один рядок на позицію замовлення, де у товара заданий `packaging_id` і збігається `supplier_id` замовлення
        із `goods_supplier_id` контексту складу пакування. Дзеркалить ЗП 1С та інвойс з замовлення.
        """
        if not self._use_postgres():
            return
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        manager_id = str(manager_id or "").strip()
        if not company_id or not region_id or not manager_id:
            return

        def _iso10(raw: Any) -> str:
            if raw is None:
                return ""
            if isinstance(raw, datetime):
                try:
                    return raw.date().isoformat()
                except Exception:
                    return ""
            if isinstance(raw, date):
                try:
                    return raw.isoformat()
                except Exception:
                    return ""
            s = str(raw).strip()
            if not s:
                return ""
            if "T" in s:
                s = s.split("T", 1)[0]
            return s[:10]

        def _flt(raw: Any) -> float:
            try:
                if raw is None or str(raw).strip() == "":
                    return 0.0
                return float(str(raw).replace(",", "."))
            except Exception:
                return 0.0

        try:
            self.sync_packaging_supply_contexts(
                company_id, region_id, manager_id=manager_id
            )
            contexts = [
                c
                for c in (
                    self.list_packaging_supply_contexts(company_id, region_id) or []
                )
                if isinstance(c, dict)
            ]

            ctx_map: dict[tuple[str, str], str] = {}
            timelines: dict[str, list[tuple[str, int]]] = {}
            ctx_ids_ok: list[str] = []

            prod_rows = [
                p
                for p in (
                    self.get_products(company_id, region_id, manager_id=manager_id)
                    or []
                )
                if isinstance(p, dict)
            ]
            prod_pack: dict[str, str] = {}
            for p in prod_rows:
                pid = str(p.get("id") or "").strip()
                pk = str(p.get("packaging_id") or "").strip()
                if pid and pk:
                    prod_pack[pid] = pk

            for c in contexts:
                cid = str(c.get("id") or "").strip()
                if not cid:
                    continue
                ctx_ids_ok.append(cid)
                k = (
                    str(c.get("packaging_id") or "").strip(),
                    str(c.get("goods_supplier_id") or "").strip(),
                )
                ctx_map[k] = cid

            ord_rows = [
                o
                for o in (
                    self.get_orders(
                        company_id, region_id, limit=None, manager_id=manager_id
                    )
                    or []
                )
                if isinstance(o, dict)
            ]

            now = datetime.utcnow()
            batches: list[tuple] = []

            with self._pg().cursor() as cur:
                # Both loops used to be one round trip PER context (dozens to
                # hundreds of packaging×supplier contexts) — batched into a
                # single query each, since this reconcile runs on every
                # Packaging Stock tab load per region.
                for cid in ctx_ids_ok:
                    timelines[cid] = []
                if ctx_ids_ok:
                    cur.execute(
                        """
                        SELECT context_id, order_date::text AS od, seq_no
                        FROM packaging_supply_orders
                        WHERE context_id = ANY(%s) AND row_kind=%s
                        ORDER BY order_date ASC NULLS LAST, seq_no ASC, created_at ASC
                        """,
                        (ctx_ids_ok, "supply"),
                    )
                    for rr in cur.fetchall() or []:
                        if not isinstance(rr, dict):
                            continue
                        cid = str(rr.get("context_id") or "").strip()
                        if cid not in timelines:
                            continue
                        dtxt = rr.get("od")
                        ds = ""
                        if dtxt:
                            ds = _iso10(dtxt)
                        try:
                            sq = int(rr.get("seq_no") or 0)
                        except Exception:
                            sq = 0
                        if ds:
                            timelines[cid].append((ds, sq))

                if ctx_ids_ok:
                    cur.execute(
                        "DELETE FROM packaging_supply_orders WHERE context_id = ANY(%s) AND row_kind=%s",
                        (ctx_ids_ok, "goods"),
                    )

                def _wave(seq_list: list[tuple[str, int]], gd: str) -> int:
                    if not gd:
                        return 0
                    best = 0
                    for d, sq in seq_list:
                        if d and d <= gd:
                            try:
                                best = max(best, int(sq))
                            except Exception:
                                continue
                    return int(best)

                for o in ord_rows:
                    oid = str(o.get("id") or "").strip()
                    sup = str(o.get("supplier_id") or "").strip()
                    gd = _iso10(o.get("order_date"))
                    zp_h = str(o.get("order_no_1c") or "").strip()
                    inv_h = str(o.get("invoice_no") or "").strip()
                    items = o.get("items") if isinstance(o.get("items"), list) else []
                    multi = len(items) > 1

                    # Pre-compute per-context packaging item positions for this order.
                    # ctx_pack_positions[ctx_id] = [item_index, ...] in order of appearance.
                    ctx_pack_positions: dict[str, list[int]] = {}
                    for idx2, it2 in enumerate(items):
                        if not isinstance(it2, dict):
                            continue
                        pid2 = str(it2.get("product_id") or "").strip()
                        pkg_id2 = prod_pack.get(pid2) or ""
                        ctx_id2 = ctx_map.get((pkg_id2, sup)) or ""
                        if ctx_id2:
                            ctx_pack_positions.setdefault(ctx_id2, []).append(idx2)

                    for idx, it in enumerate(items):
                        if not isinstance(it, dict):
                            continue
                        pid = str(it.get("product_id") or "").strip()
                        if not pid:
                            continue
                        pkg_id = prod_pack.get(pid) or ""
                        if not pkg_id:
                            continue
                        ctx_id_res = ctx_map.get((pkg_id, sup)) or ""
                        if not ctx_id_res:
                            continue

                        qty = _flt(it.get("qty") or it.get("quantity"))

                        # Determine sub-invoice position: 1-based index among packaging items for this context.
                        pkg_positions = ctx_pack_positions.get(ctx_id_res, [])
                        try:
                            pkg_pos = pkg_positions.index(idx) + 1
                        except ValueError:
                            pkg_pos = 1
                        n_pkg = len(pkg_positions)

                        if multi or n_pkg > 1:
                            # For multi-item orders or multiple packaging items: use per-item invoice.
                            zp_item = (
                                str(it.get("order_no_1c") or "").strip()
                                or str(it.get("manual_order_no_1c") or "").strip()
                            )
                            inv_item = (
                                str(it.get("invoice_no") or "").strip()
                                or str(it.get("manual_invoice") or "").strip()
                            )
                            # Auto-generate sub-invoice if item has no explicit invoice.
                            if not inv_item:
                                inv_item = (
                                    f"{inv_h}/{pkg_pos:02d}"
                                    if inv_h
                                    else f"{pkg_pos:02d}"
                                )
                            if not zp_item:
                                zp_item = f"{zp_h}/{pkg_pos:02d}" if zp_h else ""
                            zp_line = zp_item
                            inv_line = inv_item
                        else:
                            zp_line = zp_h
                            inv_line = inv_h

                        # Build comment: for multi-item orders include product_name (once)
                        # so each sub-row is identifiable. For single-item orders the product
                        # is already shown in a dedicated column — adding it to comment duplicates.
                        # Also strip any previously-written product_name prefix to prevent accumulation.
                        pn = str(it.get("product_name") or "").strip()
                        ic = str(it.get("item_comment") or "").strip()
                        if pn and ic:
                            prefix = pn + "; "
                            if ic.lower().startswith(prefix.lower()):
                                ic = ic[len(prefix) :]
                            elif ic.lower() == pn.lower():
                                ic = ""
                        cmt_bits = []
                        # Include product_name only for multi-item orders (where sub-rows exist)
                        if pn and (multi or n_pkg > 1):
                            cmt_bits.append(pn)
                        if ic:
                            cmt_bits.append(ic)
                        c_line = "; ".join(cmt_bits)[:400]

                        wave = _wave(timelines.get(ctx_id_res, []), gd)
                        nid = uuid.uuid4().hex
                        batches.append(
                            (
                                nid,
                                ctx_id_res,
                                int(wave or 0),
                                gd if gd else None,
                                float(qty),
                                " ",
                                None,
                                0.0,
                                0.0,
                                zp_line or None,
                                inv_line or None,
                                c_line or None,
                                "goods",
                                oid,
                                str(int(idx)),
                                now,
                                now,
                            )
                        )

                CHUNK = 500
                for i in range(0, len(batches), CHUNK):
                    chunk = batches[i : i + CHUNK]
                    placeholders = ", ".join(
                        ["(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)"] * len(chunk)
                    )
                    flat_params = [v for row in chunk for v in row]
                    cur.execute(
                        f"""
                        INSERT INTO packaging_supply_orders
                          (id, context_id, seq_no, order_date, qty_ordered, status, cost_amount,
                           paid_amount, shipped_goods_supplier_qty, zp_1c, invoice_no, comment, row_kind,
                           linked_order_id, linked_order_line_key, created_at, updated_at)
                        VALUES {placeholders}
                        """,
                        flat_params,
                    )

            try:
                self._pulse(company_id, "packaging")
                self._pulse(company_id, "payments")
            except Exception:
                pass
        except Exception:
            logger.exception("reconcile_packaging_supply_goods_links failed")

    # ----------------- orders write paths (Postgres mode) -----------------
    def bulk_sync(self, changed_by: str | None = None):  # noqa: ARG002
        """
        Compatibility context manager used by some views (OrdersView migration).
        In Postgres mode we use autocommit; this is a no-op wrapper.
        """
        return contextlib.nullcontext()

    def upsert_order(
        self, payload: dict, manager_id: str | None = None
    ) -> bool:  # noqa: ARG002
        """
        Insert or update an order row.
        Stores most fields inside jsonb `data` but keeps common selectors in columns.
        Uses INSERT ... ON CONFLICT to eliminate SELECT + UPDATE/INSERT round trips.
        """
        if not self._use_postgres():
            return bool(
                self._post(
                    "/orders/upsert",
                    {"payload": payload, "manager_id": manager_id or ""},
                )
                or False
            )
        if not isinstance(payload, dict):
            return False
        oid = str(payload.get("id") or "").strip() or uuid.uuid4().hex
        cid = str(payload.get("company_id") or "").strip()
        rid = str(payload.get("region_id") or "").strip()
        mid = str(payload.get("manager_id") or manager_id or "").strip()
        supplier_id = str(payload.get("supplier_id") or "").strip()
        if not cid or not rid:
            return False
        now = self._now_ts()
        data = dict(payload)
        for k in (
            "id",
            "company_id",
            "region_id",
            "manager_id",
            "supplier_id",
            "created_at",
            "updated_at",
        ):
            data.pop(k, None)
        # Defense in depth: get_orders()/get_order_by_id() return a flattened
        # dict with the raw jsonb column's fields unpacked to the top level --
        # a caller that fetches one, tweaks a couple of fields, and passes it
        # straight back here should never have a stray "data" key left over.
        # If one slips through anyway, dropping it here stops it from being
        # nested as a sub-object inside the new blob via `orders.data ||
        # EXCLUDED.data` and silently burying the real (fresh) top-level
        # fields under a stale inner snapshot.
        if isinstance(data.get("data"), dict):
            logger.warning(
                "upsert_order: payload had a residual 'data' key (order id=%s) -- dropped to avoid nesting",
                oid,
            )
        data.pop("data", None)
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO orders (id, company_id, region_id, manager_id, supplier_id, data, created_at, updated_at)
                    VALUES (%s, %s, %s, %s, %s, %s::jsonb, %s, %s)
                    ON CONFLICT (id) DO UPDATE SET
                        company_id = EXCLUDED.company_id,
                        region_id = EXCLUDED.region_id,
                        manager_id = EXCLUDED.manager_id,
                        supplier_id = EXCLUDED.supplier_id,
                        data = orders.data || EXCLUDED.data,
                        updated_at = EXCLUDED.updated_at
                    """,
                    (
                        oid,
                        cid,
                        rid,
                        mid,
                        supplier_id,
                        psycopg.types.json.Jsonb(data),
                        now,
                        now,
                    ),
                )
            self._pulse(cid, "orders")
            self._invalidate_mgr_scope_cache(cid)
            with contextlib.suppress(Exception):
                self.reconcile_packaging_supply_goods_links(
                    cid, rid, manager_id=str(mid)
                )
            return True
        except Exception:
            logger.exception("upsert_order failed")
            return False

    # ──────────────────── order attachments (Інвойс/Пакінг) ───────────────────

    def upsert_order_attachment(
        self,
        order_id: str,
        company_id: str,
        kind: str,
        filename: str,
        file_data: bytes,
        mime_type: str,
        manager_id: str,
    ) -> str | None:
        """Insert or replace the single attachment for (order_id, kind)."""
        if not self._use_postgres():
            return None
        import uuid as _uuid

        with contextlib.suppress(Exception):
            now = self._now_ts()
            aid = f"oa_{_uuid.uuid4().hex}"
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO order_attachments
                        (id, order_id, company_id, kind, original_filename,
                         file_size, mime_type, file_data, uploaded_by_manager_id,
                         created_at, updated_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON CONFLICT (order_id, kind) DO UPDATE SET
                        original_filename = EXCLUDED.original_filename,
                        file_size = EXCLUDED.file_size,
                        mime_type = EXCLUDED.mime_type,
                        file_data = EXCLUDED.file_data,
                        uploaded_by_manager_id = EXCLUDED.uploaded_by_manager_id,
                        updated_at = EXCLUDED.updated_at
                    RETURNING id
                    """,
                    (
                        aid,
                        str(order_id),
                        str(company_id),
                        str(kind),
                        str(filename),
                        len(file_data),
                        str(mime_type or ""),
                        file_data,
                        str(manager_id or ""),
                        now,
                        now,
                    ),
                )
                row = cur.fetchone()
                return str(row["id"]) if row else aid
        return None

    def get_order_attachments_meta(self, order_id: str) -> list[dict]:
        """Return attachment metadata (no file_data) for one order."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id, kind, original_filename, file_size, mime_type,
                           uploaded_by_manager_id, created_at
                    FROM order_attachments
                    WHERE order_id=%s
                    """,
                    (str(order_id),),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_order_attachments_meta_bulk(self, order_ids: list[str]) -> dict[str, list[dict]]:
        """Return {order_id: [attachment_meta, ...]} for many orders in one query
        (used to color the Інвойс/Пакінг indicator across a whole visible list)."""
        if not self._use_postgres() or not order_ids:
            return {}
        out: dict[str, list[dict]] = {}
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT order_id, id, kind, original_filename, file_size, mime_type,
                           uploaded_by_manager_id, created_at
                    FROM order_attachments
                    WHERE order_id = ANY(%s)
                    """,
                    (list({str(x) for x in order_ids if str(x or "").strip()}),),
                )
                for r in cur.fetchall() or []:
                    if not isinstance(r, dict):
                        continue
                    oid = str(r.get("order_id") or "")
                    out.setdefault(oid, []).append(r)
        return out

    def get_order_attachment_data(self, attachment_id: str) -> bytes | None:
        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT file_data FROM order_attachments WHERE id=%s LIMIT 1",
                    (str(attachment_id),),
                )
                row = cur.fetchone()
                if row:
                    data = row.get("file_data") if isinstance(row, dict) else None
                    return bytes(data) if data is not None else None
        return None

    def delete_order_attachment(self, attachment_id: str) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM order_attachments WHERE id=%s", (str(attachment_id),)
                )
            return True
        return False

    def patch_order_fields(self, order_id: str, company_id: str, fields: dict) -> bool:
        """Patch specific JSONB fields of an order without replacing the entire data blob.
        Sends only the changed keys; existing keys not in `fields` are preserved."""
        if not order_id or not company_id or not isinstance(fields, dict) or not fields:
            return False
        if not self._use_postgres():
            payload = dict(fields)
            payload["id"] = order_id
            payload["company_id"] = company_id
            return bool(
                self._post(
                    "/orders/patch_fields",
                    {"order_id": order_id, "company_id": company_id, "fields": fields},
                )
                or False
            )
        now = self._now_ts()
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    UPDATE orders
                    SET data = data || %s::jsonb, updated_at = %s
                    WHERE id = %s AND company_id = %s
                    """,
                    (psycopg.types.json.Jsonb(fields), now, order_id, company_id),
                )
            self._pulse(company_id, "orders")
            return True
        except Exception:
            logger.exception("patch_order_fields failed")
            return False

    def delete_order(
        self, order_id: str, manager_id: str | None = None
    ) -> bool:  # noqa: ARG002
        if not self._use_postgres():
            return bool(
                self._delete(
                    "/orders/delete",
                    {"order_id": order_id, "manager_id": manager_id or ""},
                )
                or False
            )
        oid = str(order_id or "").strip()
        if not oid:
            return False
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT company_id, region_id, manager_id FROM orders WHERE id=%s LIMIT 1",
                    (oid,),
                )
                row = cur.fetchone() or {}
                cid = str((row or {}).get("company_id") or "").strip()
                rid = str((row or {}).get("region_id") or "").strip()
                mid = str((row or {}).get("manager_id") or manager_id or "").strip()
                cur.execute(
                    "DELETE FROM packaging_supply_orders WHERE linked_order_id=%s AND row_kind=%s",
                    (oid, "goods"),
                )
                cur.execute(
                    "DELETE FROM cost_price_order_inputs WHERE order_id=%s",
                    (oid,),
                )
                cur.execute("DELETE FROM orders WHERE id=%s", (oid,))
            if cid:
                self._pulse(cid, "orders")
            with contextlib.suppress(Exception):
                if cid and rid and mid:
                    self.reconcile_packaging_supply_goods_links(
                        cid, rid, manager_id=mid
                    )
            return True
        except Exception:
            logger.exception("delete_order failed")
            return False

    # ----------------- supplier settlements (PaymentsView) -----------------
    def get_supplier_settlements(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
        force_refresh: bool | None = None,
    ):  # noqa: ARG002
        if not self._use_postgres():
            return (
                self._get(
                    "/payments/supplier_settlements",
                    {"company_id": company_id, "region_id": region_id or ""},
                )
                or []
            )
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        if not cid:
            return []
        # Schema can differ in deployments (missing/renamed columns).
        cols_info = self._get_supplier_settlements_cols()
        has_note = cols_info["has_note"]
        has_ts = cols_info["has_ts"]
        has_type = cols_info["has_type"]
        has_comment = cols_info["has_comment"]
        has_data = cols_info["has_data"]
        has_manager_id = cols_info["has_manager_id"]

        # Resolve the manager's current scope BEFORE the SQL fetch (not after)
        # so we can pre-filter to "suppliers I currently see" OR "settlements
        # I personally created" in one query, instead of fetching every
        # manager's rows for the company. See the post-fetch partitioning
        # below for why a plain "manager_id=mid OR manager_id IS NULL" filter
        # was wrong: it let a since-transferred supplier's history follow
        # whoever currently owns it, and it hid the original creator's own
        # rows from their own view once they lost that ownership.
        visible_ctx = None
        allowed_supplier_ids: set[str] = set()
        if mid:
            visible_ctx = self._get_manager_visible_scope_context(cid, mid, rid or None)
            if visible_ctx.get("restricted"):
                allowed_supplier_ids = set(visible_ctx.get("supplier_ids") or set())

        with self._pg().cursor() as cur:
            select_cols = [
                "id",
                "company_id",
                "region_id",
                "supplier_id",
                "amount",
                "currency",
            ]
            if has_type:
                select_cols.append("type")
            if has_note:
                select_cols.append("note")
            if has_comment:
                select_cols.append("comment")
            if has_data:
                select_cols.append("data")
            if has_ts:
                select_cols.append("ts")
            if has_manager_id:
                select_cols.append("manager_id")
            select_cols.extend(["created_at", "updated_at"])

            q = f"""
            SELECT {", ".join(select_cols)}
            FROM supplier_settlements
            WHERE company_id=%s
            """
            params: list[Any] = [cid]
            if rid:
                q += " AND region_id=%s"
                params.append(rid)
            if mid and has_manager_id and visible_ctx is not None and visible_ctx.get("restricted"):
                # Own rows are always fetched (own history survives losing the
                # supplier's scope); everything else only if the supplier is
                # currently in view (candidates for the joint-pool check below).
                q += " AND (supplier_id = ANY(%s) OR manager_id = %s)"
                params.append(sorted(allowed_supplier_ids))
                params.append(mid)
            if has_ts:
                q += " ORDER BY ts DESC, updated_at DESC"
            else:
                q += " ORDER BY updated_at DESC"
            cur.execute(q, params)
            rows = cur.fetchall() or []
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            merged = dict(r)
            merged["amount"] = (
                float(merged["amount"]) if merged.get("amount") is not None else None
            )
            merged["currency"] = (
                str(merged.get("currency") or "").upper().strip() or None
            )
            # Flatten jsonb `data` into top-level keys for UI compatibility (PaymentsView expects it).
            if isinstance(merged.get("data"), dict):
                data = merged.get("data") or {}
                for k in (
                    "invoice_no",
                    "order_no_1c",
                    "product_id",
                    "product_name",
                    "manual_invoice",
                    "manual_order_no_1c",
                ):
                    if (k not in merged) or (merged.get(k) in (None, "")):
                        if k in data and data.get(k) not in (None, ""):
                            merged[k] = data.get(k)
            # Normalize text field for UI: prefer explicit comment, else note.
            if "comment" not in merged or merged.get("comment") in (None, ""):
                if merged.get("note") not in (None, ""):
                    merged["comment"] = merged.get("note")
            if (not merged.get("comment")) and isinstance(merged.get("data"), dict):
                dc = str((merged.get("data") or {}).get("comment") or "").strip()
                if dc:
                    merged["comment"] = dc
            out.append(merged)
        if mid and visible_ctx is not None and visible_ctx.get("restricted"):
            # Each settlement row belongs to exactly one manager_id (see
            # PaymentsView._build_settlement_who_picker: sharing a category
            # means each person gets their OWN independent row, never a row
            # shared by several people) -- so visibility is simply "your own
            # rows, always" plus "anyone's un-attributed legacy rows, as long
            # as the supplier is still in your current scope". A row someone
            # else created for a supplier you can now also see (e.g. after a
            # category transfer) stays theirs, not yours.
            filtered = []
            for row in out:
                if not isinstance(row, dict):
                    continue
                sid = str(row.get("supplier_id") or "").strip()
                row_mid = str(row.get("manager_id") or "").strip() if has_manager_id else ""
                if row_mid == mid:
                    # Always see your own settlement history, even for a
                    # supplier/category you no longer currently own (a
                    # category transfer must not erase who actually paid).
                    filtered.append(row)
                    continue
                if sid not in allowed_supplier_ids:
                    # Not your own row, and this supplier isn't in your
                    # current scope at all -- never visible.
                    continue
                if not row_mid:
                    # Legacy row with no creator pin (or manager_id column not
                    # present yet on this DB) -- fall back to the old
                    # "follows current scope" behavior so existing data isn't
                    # hidden outright.
                    filtered.append(row)
                # Otherwise: sid is in scope but the row belongs to a
                # different manager (their own personal opening balance /
                # compensation, or the previous owner's history after a
                # transfer) -- stays theirs, not shown to you.
            out = filtered
        return out

    def get_managers_with_supplier_access(
        self, company_id: str, supplier_id: str, region_id: str | None = None
    ) -> list[dict]:
        """
        Regular managers (admins/superadmins excluded — they see everything by
        default, not a meaningful "who has access" choice) who currently have
        view access to this supplier via their category/product scope.

        Used by PaymentsView so that when a manual settlement (opening balance /
        compensation) is created for a supplier multiple people can see, the
        user can choose exactly who it should be attributed to — instead of it
        silently always being tied to whoever happens to be logged in.
        """
        cid = str(company_id or "").strip()
        sid = str(supplier_id or "").strip()
        if not cid or not sid:
            return []
        admin_roles = {
            "адмін", "админ", "admin", "суперадмін", "суперадмин", "superadmin",
        }
        out = []
        for m in self.get_company_managers(cid) or []:
            if not isinstance(m, dict) or not m.get("id"):
                continue
            if m.get("is_blocked") or m.get("is_approved") is False:
                continue
            role_slug = str(m.get("role") or "").strip().lower().replace(" ", "")
            if role_slug in admin_roles:
                continue
            mid = str(m.get("id"))
            ctx = self._get_manager_visible_scope_context(cid, mid, region_id)
            if ctx.get("restricted") and sid not in (ctx.get("supplier_ids") or set()):
                continue
            if not ctx.get("restricted") and not ctx.get("supplier_ids"):
                # Unrestricted-but-empty context only happens for admin-like
                # roles (already filtered above) or a manager with literally
                # no scope assigned yet — either way, not a real access grant.
                continue
            out.append({"id": mid, "full_name": m.get("full_name") or mid})
        return out

    def upsert_supplier_settlement(self, payload: dict) -> bool:
        if not self._use_postgres():
            return bool(
                self._post("/payments/supplier_settlements/upsert", payload) or False
            )
        if not isinstance(payload, dict):
            return False
        sid = str(payload.get("supplier_id") or "").strip()
        cid = str(payload.get("company_id") or "").strip()
        rid = str(payload.get("region_id") or "").strip()
        if not cid or not rid or not sid:
            return False
        settlement_id = str(payload.get("id") or "").strip() or uuid.uuid4().hex
        amount = payload.get("amount")
        try:
            amount_f = (
                float(str(amount).replace(",", "."))
                if amount not in (None, "")
                else None
            )
        except Exception:
            amount_f = None
        currency = str(payload.get("currency") or "").upper().strip()
        stype = str(payload.get("type") or "").strip() or "opening_balance"
        comment = str(payload.get("comment") or payload.get("note") or "").strip()
        ts = (
            payload.get("ts")
            or payload.get("date")
            or payload.get("created_at")
            or None
        )
        # Accept iso timestamps; fall back to now
        now = self._now_ts()
        try:
            ts_val = (
                datetime.fromisoformat(str(ts).replace("Z", "+00:00")) if ts else now
            )
            if getattr(ts_val, "tzinfo", None) is not None:
                ts_val = ts_val.astimezone().replace(tzinfo=None)
        except Exception:
            ts_val = now
        try:
            with self._pg().cursor() as cur:
                cols_info = self._get_supplier_settlements_cols()
                has_note = cols_info["has_note"]
                has_ts = cols_info["has_ts"]
                has_type = cols_info["has_type"]
                has_comment = cols_info["has_comment"]
                has_data = cols_info["has_data"]
                has_manager_id = cols_info["has_manager_id"]

                data_payload: dict = {}
                if comment:
                    data_payload["comment"] = comment
                data_payload["type"] = stype
                data_payload["currency"] = currency
                # Extra UI fields (PaymentsView expects these on settlement rows).
                for k in (
                    "invoice_no",
                    "order_no_1c",
                    "product_id",
                    "product_name",
                    "manual_invoice",
                    "manual_order_no_1c",
                    "supplier_name",
                ):
                    if payload.get(k) not in (None, ""):
                        data_payload[k] = payload.get(k)
                if ts:
                    data_payload["ts_raw"] = str(ts)
                # Build queries depending on schema.
                cur.execute(
                    "SELECT 1 FROM supplier_settlements WHERE id=%s LIMIT 1",
                    (settlement_id,),
                )
                exists = bool(cur.fetchone())
                if exists:
                    set_parts = [
                        "company_id=%s",
                        "region_id=%s",
                        "supplier_id=%s",
                        "amount=%s",
                        "currency=%s",
                    ]
                    vals: list[Any] = [cid, rid, sid, amount_f, currency]
                    if has_type:
                        set_parts.append("type=%s")
                        vals.append(stype)
                    if has_note:
                        set_parts.append("note=%s")
                        vals.append(comment)
                    if has_comment:
                        set_parts.append("comment=%s")
                        vals.append(comment)
                    if has_data:
                        set_parts.append("data=%s::jsonb")
                        vals.append(psycopg.types.json.Jsonb(data_payload))
                    if has_ts:
                        set_parts.append("ts=%s")
                        vals.append(ts_val)
                    if has_manager_id:
                        mgr = str(payload.get("manager_id") or "").strip()
                        if mgr:
                            set_parts.append("manager_id=%s")
                            vals.append(mgr)
                    set_parts.append("updated_at=%s")
                    vals.append(now)
                    vals.append(settlement_id)
                    cur.execute(
                        f"UPDATE supplier_settlements SET {', '.join(set_parts)} WHERE id=%s",
                        tuple(vals),
                    )
                else:
                    cols_ins = [
                        "id",
                        "company_id",
                        "region_id",
                        "supplier_id",
                        "amount",
                        "currency",
                    ]
                    vals_ins: list[Any] = [
                        settlement_id,
                        cid,
                        rid,
                        sid,
                        amount_f,
                        currency,
                    ]
                    if has_type:
                        cols_ins.append("type")
                        vals_ins.append(stype)
                    if has_note:
                        cols_ins.append("note")
                        vals_ins.append(comment)
                    if has_comment:
                        cols_ins.append("comment")
                        vals_ins.append(comment)
                    if has_data:
                        cols_ins.append("data")
                        vals_ins.append(psycopg.types.json.Jsonb(data_payload))
                    if has_ts:
                        cols_ins.append("ts")
                        vals_ins.append(ts_val)
                    if has_manager_id:
                        mgr = str(payload.get("manager_id") or "").strip()
                        if mgr:
                            cols_ins.append("manager_id")
                            vals_ins.append(mgr)
                    cols_ins.extend(["created_at", "updated_at"])
                    vals_ins.extend([now, now])
                    placeholders = ",".join(["%s"] * len(cols_ins))
                    cur.execute(
                        f"INSERT INTO supplier_settlements ({', '.join(cols_ins)}) VALUES ({placeholders})",
                        tuple(vals_ins),
                    )
            self._pulse(cid, "payments")
            return True
        except Exception:
            logger.exception("upsert_supplier_settlement failed")
            return False

    def delete_supplier_settlement(self, settlement_id: str) -> bool:
        if not self._use_postgres():
            return bool(
                self._delete(
                    "/payments/supplier_settlements/delete", {"id": settlement_id}
                )
                or False
            )
        sid = str(settlement_id or "").strip()
        if not sid:
            return False
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT company_id FROM supplier_settlements WHERE id=%s LIMIT 1",
                    (sid,),
                )
                row = cur.fetchone() or {}
                cid = str((row or {}).get("company_id") or "").strip()
                cur.execute("DELETE FROM supplier_settlements WHERE id=%s", (sid,))
            if cid:
                self._pulse(cid, "payments")
            return True
        except Exception:
            logger.exception("delete_supplier_settlement failed")
            return False

    # ----- Media Plan Entries -----

    def get_media_plan_entries(
        self,
        company_id: str,
        manager_id: str | None = None,
        region_id: str | None = None,
    ) -> list[dict]:
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not cid or not self._use_postgres():
            return []
        try:
            # When manager_id is given, always get accessible products first to filter correctly
            allowed_product_ids: set | None = None
            if mid:
                visible_ctx = self._get_manager_visible_scope_context(
                    cid, mid, rid or None
                )
                allowed_product_ids = visible_ctx.get("product_ids") or set()
                # If restricted and no accessible products, return empty
                if visible_ctx.get("restricted") and not allowed_product_ids:
                    return []

            def _fetch(with_label: bool) -> list:
                with self._pg().cursor() as cur:
                    cols = (
                        "id, company_id, manager_id, region_id, "
                        "product_ids, product_names, display_label, comment, not_relevant, post_dates, "
                        "created_at, updated_at"
                        if with_label
                        else "id, company_id, manager_id, region_id, "
                        "product_ids, product_names, comment, not_relevant, post_dates, "
                        "created_at, updated_at"
                    )
                    q = f"SELECT {cols} FROM media_plan_entries WHERE company_id=%s"
                    p: list[Any] = [cid]
                    if rid:
                        q += " AND region_id=%s"
                        p.append(rid)
                    q += " ORDER BY created_at ASC"
                    cur.execute(q, p)
                    return cur.fetchall() or []

            try:
                rows = _fetch(with_label=True)
            except Exception:
                # display_label column doesn't exist yet — migration pending
                rows = _fetch(with_label=False)

            out = []
            for r in rows:
                if not isinstance(r, dict):
                    continue
                d = dict(r)
                if "display_label" not in d:
                    d["display_label"] = ""
                # Normalise jsonb columns — psycopg3 may return them already parsed
                for col in ("product_ids", "product_names", "post_dates"):
                    v = d.get(col)
                    if isinstance(v, str):
                        try:
                            d[col] = json.loads(v)
                        except Exception:
                            d[col] = []
                    elif not isinstance(v, list):
                        d[col] = []
                out.append(d)

            # Filter by accessible products if manager has restricted access
            if mid and allowed_product_ids is not None:
                out = [
                    row
                    for row in out
                    if isinstance(row, dict)
                    and any(
                        str(pid or "").strip() in allowed_product_ids
                        for pid in (row.get("product_ids") or [])
                    )
                ]
            return out
        except Exception:
            logger.exception("get_media_plan_entries failed")
            return []

    def upsert_media_plan_entry(self, payload: dict) -> bool:
        if not isinstance(payload, dict) or not self._use_postgres():
            return False
        cid = str(payload.get("company_id") or "").strip()
        mid = str(payload.get("manager_id") or "").strip()
        rid = str(payload.get("region_id") or "").strip()
        if not cid:
            return False
        eid = str(payload.get("id") or "").strip() or uuid.uuid4().hex

        def _to_json_list(v) -> Any:
            if isinstance(v, list):
                return psycopg.types.json.Jsonb(v)
            if isinstance(v, str):
                try:
                    parsed = json.loads(v)
                    return psycopg.types.json.Jsonb(
                        parsed if isinstance(parsed, list) else []
                    )
                except Exception:
                    return psycopg.types.json.Jsonb([])
            return psycopg.types.json.Jsonb([])

        pids = _to_json_list(payload.get("product_ids"))
        pnames = _to_json_list(payload.get("product_names"))
        dates = _to_json_list(payload.get("post_dates"))
        display_label = str(payload.get("display_label") or "").strip()
        comment = str(payload.get("comment") or "").strip()
        not_relevant = bool(payload.get("not_relevant", False))
        now = self._now_ts()
        try:

            def _do_upsert(with_label: bool) -> None:
                with self._pg().cursor() as cur:
                    if with_label:
                        cur.execute(
                            """
                            INSERT INTO media_plan_entries
                              (id, company_id, manager_id, region_id,
                               product_ids, product_names, display_label, comment, not_relevant, post_dates,
                               created_at, updated_at)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                            ON CONFLICT (id) DO UPDATE SET
                                company_id = EXCLUDED.company_id,
                                manager_id = EXCLUDED.manager_id,
                                region_id = EXCLUDED.region_id,
                                product_ids = EXCLUDED.product_ids,
                                product_names = EXCLUDED.product_names,
                                display_label = EXCLUDED.display_label,
                                comment = EXCLUDED.comment,
                                not_relevant = EXCLUDED.not_relevant,
                                post_dates = EXCLUDED.post_dates,
                                updated_at = EXCLUDED.updated_at
                            """,
                            (
                                eid,
                                cid,
                                mid,
                                rid,
                                pids,
                                pnames,
                                display_label,
                                comment,
                                not_relevant,
                                dates,
                                now,
                                now,
                            ),
                        )
                    else:
                        cur.execute(
                            """
                            INSERT INTO media_plan_entries
                              (id, company_id, manager_id, region_id,
                               product_ids, product_names, comment, not_relevant, post_dates,
                               created_at, updated_at)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                            ON CONFLICT (id) DO UPDATE SET
                                company_id = EXCLUDED.company_id,
                                manager_id = EXCLUDED.manager_id,
                                region_id = EXCLUDED.region_id,
                                product_ids = EXCLUDED.product_ids,
                                product_names = EXCLUDED.product_names,
                                comment = EXCLUDED.comment,
                                not_relevant = EXCLUDED.not_relevant,
                                post_dates = EXCLUDED.post_dates,
                                updated_at = EXCLUDED.updated_at
                            """,
                            (
                                eid,
                                cid,
                                mid,
                                rid,
                                pids,
                                pnames,
                                comment,
                                not_relevant,
                                dates,
                                now,
                                now,
                            ),
                        )
                    if mid:
                        cur.execute(
                            """
                            INSERT INTO entity_owners
                              (company_id, entity_type, entity_id, manager_id, created_at)
                            VALUES (%s,%s,%s,%s,%s)
                            ON CONFLICT DO NOTHING
                            """,
                            (cid, "media_plan", eid, mid, now),
                        )

            try:
                _do_upsert(with_label=True)
            except Exception:
                # display_label column doesn't exist yet — retry without it
                _do_upsert(with_label=False)
            self._pulse(cid, "media_plan")
            return True
        except Exception:
            logger.exception("upsert_media_plan_entry failed")
            return False

    def delete_media_plan_entry(self, entry_id: str) -> bool:
        pid = str(entry_id or "").strip()
