    # ----- Order Schedule -----

    @staticmethod
    def _normalize_json_list(value) -> list:
        if isinstance(value, list):
            return value
        if isinstance(value, str):
            try:
                parsed = json.loads(value)
                return parsed if isinstance(parsed, list) else []
            except Exception:
                return []
        return []

    @staticmethod
    def _normalize_json_dict(value) -> dict:
        if isinstance(value, dict):
            return value
        if isinstance(value, str):
            try:
                parsed = json.loads(value)
                return parsed if isinstance(parsed, dict) else {}
            except Exception:
                return {}
        return {}

    def get_manager_ui_preference(
        self,
        manager_id: str,
        key: str,
        default_value: str = "",
    ) -> str:
        mid = str(manager_id or "").strip()
        pref_key = str(key or "").strip()
        if not mid or not pref_key:
            return str(default_value or "")
        if not self._use_postgres():
            return str(default_value or "")
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT meta FROM public.managers WHERE id=%s LIMIT 1",
                    (mid,),
                )
                row = cur.fetchone() or {}
            meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
            prefs = (
                meta.get("ui_preferences")
                if isinstance((meta or {}).get("ui_preferences"), dict)
                else {}
            )
            val = prefs.get(pref_key)
            if val is None:
                return str(default_value or "")
            return str(val)
        except Exception:
            logger.exception("get_manager_ui_preference failed")
            return str(default_value or "")

    def set_manager_ui_preference(self, manager_id: str, key: str, value: str) -> bool:
        mid = str(manager_id or "").strip()
        pref_key = str(key or "").strip()
        if not mid or not pref_key:
            return False
        if not self._use_postgres():
            return False
        now = self._now_ts()
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT meta, company_id FROM public.managers WHERE id=%s LIMIT 1",
                    (mid,),
                )
                row = cur.fetchone() or {}
                meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
                company_id = str((row or {}).get("company_id") or "").strip()
                meta = dict(meta or {})
                prefs = (
                    dict(meta.get("ui_preferences"))
                    if isinstance(meta.get("ui_preferences"), dict)
                    else {}
                )
                prefs[pref_key] = str(value or "")
                meta["ui_preferences"] = prefs
                cur.execute(
                    "UPDATE public.managers SET meta=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(meta), now, mid),
                )
            if company_id:
                with contextlib.suppress(Exception):
                    self._pulse(company_id, "ui")
            return True
        except Exception:
            logger.exception("set_manager_ui_preference failed")
            return False

    def get_order_schedule_groups(
        self,
        company_id: str,
        manager_id: str | None = None,
        region_id: str | None = None,
    ) -> list[dict]:
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not cid or not self._use_postgres():
            return []
        _q_full = """
                    SELECT id, company_id, manager_id, region_id, category_id,
                           item_type, display_mode, display_label,
                           COALESCE(is_inactive, FALSE) AS is_inactive,
                           product_ids, product_names, level_node_ids,
                           COALESCE(note, '') AS note,
                           production_term_days, price,
                           COALESCE(currency, '') AS currency,
                           created_at, updated_at
                    FROM order_schedule_groups
                    WHERE company_id=%s
                """
        _q_fallback = """
                    SELECT id, company_id, manager_id, region_id, category_id,
                           item_type, display_mode, display_label,
                           COALESCE(is_inactive, FALSE) AS is_inactive,
                           product_ids, product_names, level_node_ids,
                           created_at, updated_at
                    FROM order_schedule_groups
                    WHERE company_id=%s
                """

        def _fetch(q: str) -> list[dict]:
            params: list[Any] = [cid]
            if rid:
                q += " AND region_id=%s"
                params.append(rid)
            q += " ORDER BY lower(display_label) ASC, created_at ASC"
            with self._pg().cursor() as cur:
                cur.execute(q, params)
                return cur.fetchall() or []

        try:
            try:
                rows = _fetch(_q_full)
            except Exception:
                # New columns not yet migrated — fall back to base query and apply DDL
                try:
                    with self._pg().cursor() as _cur:
                        _cur.execute(
                            "ALTER TABLE order_schedule_groups ADD COLUMN IF NOT EXISTS note text NOT NULL DEFAULT ''"
                        )
                        _cur.execute(
                            "ALTER TABLE order_schedule_groups ADD COLUMN IF NOT EXISTS production_term_days integer"
                        )
                        _cur.execute(
                            "ALTER TABLE order_schedule_groups ADD COLUMN IF NOT EXISTS price numeric"
                        )
                        _cur.execute(
                            "ALTER TABLE order_schedule_groups ADD COLUMN IF NOT EXISTS currency character varying(8) NOT NULL DEFAULT ''"
                        )
                except Exception:
                    logger.exception("order_schedule_groups column migration failed")
                try:
                    rows = _fetch(_q_full)
                except Exception:
                    rows = _fetch(_q_fallback)
            out = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                item = dict(row)
                item["product_ids"] = self._normalize_json_list(item.get("product_ids"))
                item["product_names"] = self._normalize_json_list(
                    item.get("product_names")
                )
                item["level_node_ids"] = self._normalize_json_dict(
                    item.get("level_node_ids")
                )
                out.append(item)
            if mid:
                visible_ctx = self._get_manager_visible_scope_context(
                    cid, mid, rid or None
                )
                if visible_ctx.get("restricted"):
                    allowed_product_ids = visible_ctx.get("product_ids") or set()
                    out = [
                        row
                        for row in out
                        if isinstance(row, dict)
                        and (
                            str(row.get("item_type") or "") == "note"
                            or any(
                                str(pid or "").strip() in allowed_product_ids
                                for pid in (row.get("product_ids") or [])
                            )
                        )
                    ]
            return out
        except Exception:
            logger.exception("get_order_schedule_groups failed")
            return []

    def upsert_order_schedule_group(self, payload: dict) -> bool:
        if not isinstance(payload, dict) or not self._use_postgres():
            return False
        cid = str(payload.get("company_id") or "").strip()
        mid = str(payload.get("manager_id") or "").strip()
        rid = str(payload.get("region_id") or "").strip()
        if not cid:
            return False
        gid = str(payload.get("id") or "").strip() or uuid.uuid4().hex
        category_id = str(payload.get("category_id") or "").strip()
        item_type = str(payload.get("item_type") or "product").strip() or "product"
        display_mode = str(payload.get("display_mode") or "name").strip() or "name"
        display_label = str(payload.get("display_label") or "").strip()
        is_inactive = bool(payload.get("is_inactive", False))
        product_ids = psycopg.types.json.Jsonb(
            self._normalize_json_list(payload.get("product_ids"))
        )
        product_names = psycopg.types.json.Jsonb(
            self._normalize_json_list(payload.get("product_names"))
        )
        level_node_ids = psycopg.types.json.Jsonb(
            self._normalize_json_dict(payload.get("level_node_ids"))
        )
        note = str(payload.get("note") or "").strip()
        production_term_days = payload.get("production_term_days")
        try:
            production_term_days = (
                int(production_term_days) if production_term_days is not None else None
            )
        except (TypeError, ValueError):
            production_term_days = None
        price = payload.get("price")
        try:
            price = float(price) if price is not None else None
        except (TypeError, ValueError):
            price = None
        currency = str(payload.get("currency") or "").strip()
        now = self._now_ts()
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO order_schedule_groups
                      (id, company_id, manager_id, region_id, category_id,
                       item_type, display_mode, display_label, is_inactive,
                       product_ids, product_names, level_node_ids,
                       note, production_term_days, price, currency,
                       created_at, updated_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON CONFLICT (id) DO UPDATE SET
                        company_id = EXCLUDED.company_id,
                        manager_id = EXCLUDED.manager_id,
                        region_id = EXCLUDED.region_id,
                        category_id = EXCLUDED.category_id,
                        item_type = EXCLUDED.item_type,
                        display_mode = EXCLUDED.display_mode,
                        display_label = EXCLUDED.display_label,
                        is_inactive = EXCLUDED.is_inactive,
                        product_ids = EXCLUDED.product_ids,
                        product_names = EXCLUDED.product_names,
                        level_node_ids = EXCLUDED.level_node_ids,
                        note = EXCLUDED.note,
                        production_term_days = EXCLUDED.production_term_days,
                        price = EXCLUDED.price,
                        currency = EXCLUDED.currency,
                        updated_at = EXCLUDED.updated_at
                    """,
                    (
                        gid,
                        cid,
                        mid,
                        rid,
                        category_id,
                        item_type,
                        display_mode,
                        display_label,
                        is_inactive,
                        product_ids,
                        product_names,
                        level_node_ids,
                        note,
                        production_term_days,
                        price,
                        currency,
                        now,
                        now,
                    ),
                )
            self._pulse(cid, "schedule")
            self._invalidate_mgr_scope_cache(cid)
            return True
        except Exception:
            logger.exception("upsert_order_schedule_group failed")
            return False

    def delete_order_schedule_group(self, group_id: str) -> bool:
        gid = str(group_id or "").strip()
