    def get_order_schedule_tasks(
        self,
        company_id: str,
        manager_id: str | None = None,
        region_id: str | None = None,
        include_archived: bool = True,
    ) -> list[dict]:
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not cid or not self._use_postgres():
            return []
        try:
            with self._pg().cursor() as cur:
                q = """
                    SELECT id, group_id, company_id, manager_id, region_id,
                           month_anchor, date_from, date_to,
                           planned_qty, planned_amount, planned_currency, planned_amount_usd,
                           actual_qty, actual_amount, actual_currency, actual_amount_usd,
                           delivery_type_id, delivery_type_name,
                           status, archived, sort_index, created_at, updated_at
                    FROM order_schedule_tasks
                    WHERE company_id=%s
                """
                params: list[Any] = [cid]
                if rid:
                    q += " AND region_id=%s"
                    params.append(rid)
                if not include_archived:
                    q += " AND archived=FALSE"
                q += " ORDER BY month_anchor ASC, sort_index ASC, created_at ASC"
                cur.execute(q, params)
                out = [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
            if mid:
                visible_ctx = self._get_manager_visible_scope_context(
                    cid, mid, rid or None
                )
                if visible_ctx.get("restricted"):
                    allowed_group_ids = set(visible_ctx.get("group_ids") or set())
                    # Note groups have product_ids=[] so they're never in allowed_group_ids.
                    # Fetch them separately so their tasks aren't filtered out.
                    with contextlib.suppress(Exception):
                        with self._pg().cursor() as _nc:
                            _nq = "SELECT id FROM order_schedule_groups WHERE company_id=%s AND item_type='note'"
                            _np: list[Any] = [cid]
                            if rid:
                                _nq += " AND region_id=%s"
                                _np.append(rid)
                            _nc.execute(_nq, _np)
                            for _nr in _nc.fetchall() or []:
                                _nid = str(
                                    (_nr.get("id") if isinstance(_nr, dict) else _nr[0])
                                    or ""
                                ).strip()
                                if _nid:
                                    allowed_group_ids.add(_nid)
                    out = [
                        row
                        for row in out
                        if isinstance(row, dict)
                        and str(row.get("group_id") or "").strip() in allowed_group_ids
                    ]
            return out
        except Exception:
            logger.exception("get_order_schedule_tasks failed")
            return []

