    def get_company_delivery_methods(
        self, company_id: str, region_id: str | None = None
    ):
        if not self._use_postgres():
            return (
                self._get(
                    "/delivery_methods",
                    {"company_id": company_id, "region_id": region_id or ""},
                )
                or []
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        with self._pg().cursor() as cur:
            if region_id:
                cur.execute(
                    "SELECT methods FROM delivery_methods WHERE company_id=%s AND region_id=%s LIMIT 1",
                    (company_id, region_id),
                )
                row = cur.fetchone()
                return (
                    row["methods"]
                    if row and isinstance(row.get("methods"), list)
                    else []
                )

            # All regions: merge methods across all region rows so UI can resolve names
            # for orders coming from different regions.
            cur.execute(
                "SELECT methods FROM delivery_methods WHERE company_id=%s ORDER BY updated_at DESC",
                (company_id,),
            )
            rows = cur.fetchall() or []

        merged: list[dict] = []
        seen_ids: set[str] = set()
        for r in rows:
            if not isinstance(r, dict):
                continue
            methods = r.get("methods")
            if not isinstance(methods, list):
                continue
            for m in methods:
                if not isinstance(m, dict):
                    continue
                mid = str(m.get("id") or "").strip()
                if not mid or mid in seen_ids:
                    continue
                seen_ids.add(mid)
                merged.append(m)
        return merged

    # ----------------- company payment field templates -----------------
    def get_company_payment_field_templates(
        self, company_id: str, region_id: str | None = None
    ) -> list[dict]:
        """
        Return company-level payment field templates for suppliers.
        Each row: {id, company_id, name, code, has_text, has_image, order_index}.
        """
        if not self._use_postgres():
            return (
                self._get("/payments/templates", {"company_id": company_id or ""}) or []
            )

        cid = str(company_id or "").strip()
        if not cid:
            return []
        rid = str(region_id or "").strip()
        with self._pg().cursor() as cur:
            # Region-specific overrides: if there are templates for (cid,rid) use them; else fallback to regionless ('').
            if rid:
                cur.execute(
                    "SELECT COUNT(1) AS cnt FROM company_payment_field_templates WHERE company_id=%s AND region_id=%s",
                    (cid, rid),
                )
                has_region = (cur.fetchone() or {}).get("cnt", 0) or 0
                target_rid = rid if int(has_region) > 0 else ""
            else:
                target_rid = ""
            cur.execute(
                """
                SELECT id, company_id, region_id, name, code, has_text, has_image, order_index, updated_at
                FROM company_payment_field_templates
                WHERE company_id=%s AND region_id=%s
                ORDER BY order_index ASC, updated_at ASC
                """,
                (cid, target_rid),
            )
            rows = cur.fetchall() or []
        return [r for r in rows if isinstance(r, dict)]

    def save_company_payment_field_templates(
        self, company_id: str, templates: list[dict], region_id: str | None = None
    ) -> bool:
        """
        Replace company payment field templates with provided list.
        `templates` is a list of dicts: {id?, name, code?, has_text, has_image, order_index}.
        """
        if not self._use_postgres():
            payload = {"company_id": company_id or "", "templates": templates or []}
            return bool(self._post("/payments/templates/save", payload) or False)

        cid = str(company_id or "").strip()
        if not cid:
            return False
        rid = str(region_id or "").strip()

        # Normalize and assign ids/codes.
        norm: list[dict] = []
        used_codes: set[str] = set()
        for idx, t in enumerate(templates or []):
            if not isinstance(t, dict):
                continue
            name = str(t.get("name") or "").strip()
            if not name:
                continue
            raw_code = str(t.get("code") or name).strip().lower()
            # Simple slug: letters/digits/underscore only.
            code = "".join(ch if ch.isalnum() else "_" for ch in raw_code) or "field"
            base = code
            suffix = 2
            while code in used_codes:
                code = f"{base}_{suffix}"
                suffix += 1
            used_codes.add(code)

            tid = str(t.get("id") or "").strip() or uuid.uuid4().hex
            has_text = bool(t.get("has_text", True))
            has_image = bool(t.get("has_image", False))
            order_index = int(t.get("order_index", idx))
            norm.append(
                {
                    "id": tid,
                    "company_id": cid,
                    "region_id": rid,
                    "name": name,
                    "code": code,
                    "has_text": has_text,
                    "has_image": has_image,
                    "order_index": order_index,
                }
            )

        now = self._now_ts()
        try:
            with self._pg().cursor() as cur:
                # Batched upsert instead of one execute() per template.
                if norm:
                    CHUNK = 500
                    for i in range(0, len(norm), CHUNK):
                        chunk = norm[i : i + CHUNK]
                        placeholders = ", ".join(["(%s,%s,%s,%s,%s,%s,%s,%s,%s)"] * len(chunk))
                        flat_params = [
                            v
                            for row in chunk
                            for v in (
                                row["id"],
                                row["company_id"],
                                row["region_id"],
                                row["name"],
                                row["code"],
                                row["has_text"],
                                row["has_image"],
                                row["order_index"],
                                now,
                            )
                        ]
                        cur.execute(
                            f"""
                            INSERT INTO company_payment_field_templates
                              (id, company_id, region_id, name, code, has_text, has_image, order_index, updated_at)
                            VALUES {placeholders}
                            ON CONFLICT (id)
                            DO UPDATE
                              SET company_id=EXCLUDED.company_id,
                                  region_id=EXCLUDED.region_id,
                                  name=EXCLUDED.name,
                                  code=EXCLUDED.code,
                                  has_text=EXCLUDED.has_text,
                                  has_image=EXCLUDED.has_image,
                                  order_index=EXCLUDED.order_index,
                                  updated_at=EXCLUDED.updated_at
                            """,
                            flat_params,
                        )

                # Optionally, delete templates that are no longer present.
                keep_ids = [r["id"] for r in norm]
                cur.execute(
                    """
                    DELETE FROM company_payment_field_templates
                    WHERE company_id=%s AND region_id=%s AND id <> ALL(%s)
                    """,
                    (cid, rid, keep_ids or [""]),
                )

            self._pulse(cid, "company")
            return True
        except Exception:
            logger.exception("save_company_payment_field_templates failed")
            return False

    # ----------------- per-manager payment field overrides -----------------
    def get_manager_payment_field_overrides(
        self, manager_id: str, company_id: str, region_id: str | None = None
    ) -> dict:
        """
        Return per-manager overrides for payment field templates.
        Result: {template_id: {visible, custom_name, has_text, has_image}}.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/payments/templates/overrides",
                    {"manager_id": manager_id or "", "company_id": company_id or ""},
                )
                or {}
            )

        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        if not mid or not cid:
            return {}

        with self._pg().cursor() as cur:
            if rid:
                cur.execute(
                    "SELECT COUNT(1) AS cnt FROM manager_payment_field_overrides WHERE manager_id=%s AND company_id=%s AND region_id=%s",
                    (mid, cid, rid),
                )
                has_region = (cur.fetchone() or {}).get("cnt", 0) or 0
                target_rid = rid if int(has_region) > 0 else ""
            else:
                target_rid = ""
            cur.execute(
                """
                SELECT template_id, visible, custom_name, has_text, has_image
                FROM manager_payment_field_overrides
                WHERE manager_id=%s AND company_id=%s AND region_id=%s
                """,
                (mid, cid, target_rid),
            )
            rows = cur.fetchall() or []
        out: dict = {}
        for r in rows:
            if not isinstance(r, dict) or not r.get("template_id"):
                continue
            out[str(r["template_id"])] = {
                "visible": bool(r.get("visible", True)),
                "custom_name": r.get("custom_name"),
                "has_text": r.get("has_text"),
                "has_image": r.get("has_image"),
            }
        return out

    def save_manager_payment_field_overrides(
        self,
        manager_id: str,
        company_id: str,
        overrides: dict,
        region_id: str | None = None,
    ) -> bool:
        """
        Save per-manager overrides:
        overrides: {template_id: {visible, custom_name, has_text, has_image}}.
        """
        if not self._use_postgres():
            payload = {
                "manager_id": manager_id or "",
                "company_id": company_id or "",
                "overrides": overrides or {},
            }
            return bool(
                self._post("/payments/templates/overrides/save", payload) or False
            )

        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        if not mid or not cid:
            return False

        now = self._now_ts()
        try:
            with self._pg().cursor() as cur:
                # Upsert each override row.
                for template_id, row in (overrides or {}).items():
                    tid = str(template_id or "").strip()
                    if not tid or not isinstance(row, dict):
                        continue
                    visible = bool(row.get("visible", True))
                    custom_name = (row.get("custom_name") or "").strip() or None
                    has_text = row.get("has_text")
                    has_image = row.get("has_image")

                    # Compatibility upsert for mixed schemas:
                    # some deployed DBs may have a different unique key than
                    # (manager_id, region_id, template_id), so ON CONFLICT can fail.
                    cur.execute(
                        """
                        UPDATE manager_payment_field_overrides
                        SET visible=%s,
                            custom_name=%s,
                            has_text=%s,
                            has_image=%s,
                            updated_at=%s
                        WHERE manager_id=%s
                          AND company_id=%s
                          AND region_id=%s
                          AND template_id=%s
                        """,
                        (
                            visible,
                            custom_name,
                            has_text,
                            has_image,
                            now,
                            mid,
                            cid,
                            rid,
                            tid,
                        ),
                    )

                    if int(getattr(cur, "rowcount", 0) or 0) > 0:
                        continue

                    try:
                        cur.execute(
                            """
                            INSERT INTO manager_payment_field_overrides
                              (manager_id, company_id, region_id, template_id, visible, custom_name, has_text, has_image, updated_at)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
                            """,
                            (
                                mid,
                                cid,
                                rid,
                                tid,
                                visible,
                                custom_name,
                                has_text,
                                has_image,
                                now,
                            ),
                        )
                    except psycopg.errors.UniqueViolation:
                        # Legacy key variant (without company_id) — update existing row.
                        cur.execute(
                            """
                            UPDATE manager_payment_field_overrides
                            SET company_id=%s,
                                visible=%s,
                                custom_name=%s,
                                has_text=%s,
                                has_image=%s,
                                updated_at=%s
                            WHERE manager_id=%s
                              AND region_id=%s
                              AND template_id=%s
                            """,
                            (
                                cid,
                                visible,
                                custom_name,
                                has_text,
                                has_image,
                                now,
                                mid,
                                rid,
                                tid,
                            ),
                        )
            # pricing/company scope is not strictly needed, але нехай буде company.
            self._pulse(cid, "company")
            return True
        except Exception:
            logger.exception("save_manager_payment_field_overrides failed")
            return False

    def get_effective_payment_fields_for_manager(
        self, company_id: str, manager_id: str, region_id: str | None = None
    ) -> list[dict]:
        """
        Combine company templates and manager overrides into effective payment fields config.
        Each result row: {id, code, name, has_text, has_image, order_index}.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/payments/templates/effective",
                    {"company_id": company_id or "", "manager_id": manager_id or ""},
                )
                or []
            )

        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not cid or not mid:
            return []

        templates = self.get_company_payment_field_templates(cid, region_id=rid) or []
        overrides = (
            self.get_manager_payment_field_overrides(mid, cid, region_id=rid) or {}
        )

        effective: list[dict] = []
        for t in templates:
            if not isinstance(t, dict) or not t.get("id"):
                continue
            tid = str(t.get("id"))
            base_name = (t.get("name") or "").strip()
            ov = overrides.get(tid) or {}
            visible = ov.get("visible", True)
            if not visible:
                continue
            name = (ov.get("custom_name") or "").strip() or base_name
            has_text = ov.get("has_text")
            has_image = ov.get("has_image")
            eff_has_text = (
                bool(t.get("has_text")) if has_text is None else bool(has_text)
            )
            eff_has_image = (
                bool(t.get("has_image")) if has_image is None else bool(has_image)
            )
            effective.append(
                {
                    "id": tid,
                    "code": t.get("code"),
                    "name": name,
                    "has_text": eff_has_text,
                    "has_image": eff_has_image,
                    "order_index": int(t.get("order_index") or 0),
                }
            )

        effective.sort(key=lambda r: int(r.get("order_index") or 0))
        return effective

    def save_company_delivery_methods(
        self, company_id: str, methods: list, region_id: str | None = None, **_ignored
    ) -> bool:
        """
        Save delivery methods for a company/region.
        methods: list[dict] expected by UI (stored as jsonb).
        """
        if not self._use_postgres():
            payload = {
                "company_id": company_id,
                "region_id": region_id or "",
                "methods": methods,
            }
            return bool(self._post("/delivery_methods/save", payload) or False)
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        if not company_id or not region_id:
            return False
        now = self._now_ts()
        mid = uuid.uuid4().hex
        methods_payload = methods if isinstance(methods, list) else []
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM delivery_methods WHERE company_id=%s AND region_id=%s LIMIT 1",
                    (company_id, region_id),
                )
                row = cur.fetchone()
                if row and row.get("id"):
                    cur.execute(
                        "UPDATE delivery_methods SET methods=%s::jsonb, updated_at=%s WHERE id=%s",
                        (
                            psycopg.types.json.Jsonb(methods_payload),
                            now,
                            str(row.get("id")),
                        ),
                    )
                else:
                    cur.execute(
                        """
                        INSERT INTO delivery_methods (id, company_id, region_id, methods, updated_at)
                        VALUES (%s,%s,%s,%s::jsonb,%s)
                        """,
                        (
                            mid,
                            company_id,
                            region_id,
                            psycopg.types.json.Jsonb(methods_payload),
                            now,
                        ),
                    )
            self._pulse(company_id, "company")
            return True
        except Exception:
            logger.exception("save_company_delivery_methods failed")
            return False

    def get_manager_delivery_overrides(
        self, manager_id: str, region_id: str | None = None
    ):
        """
        Personal delivery price overrides for a manager (per region).

        UI expects a dict: {delivery_method_id: {"price": float, "currency": "USD"}}
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/delivery_methods/manager_overrides",
                    {"manager_id": manager_id or ""},
                )
                or {}
            )

        mid = str(manager_id or "").strip()
        if not mid:
            return {}
        rid = str(region_id or "").strip()

        def _fetch_for(rid_value: str):
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT overrides
                    FROM manager_delivery_overrides
                    WHERE manager_id=%s AND region_id=%s
                    LIMIT 1
                    """,
                    (mid, rid_value),
                )
                row = cur.fetchone() or {}
            ov = row.get("overrides")
            return ov if isinstance(ov, dict) else {}

        # Prefer region-specific overrides; fallback to legacy regionless ('') overrides.
        if rid:
            region_specific = _fetch_for(rid)
            if region_specific:
                return region_specific
        return _fetch_for("")

    def save_manager_delivery_overrides(
        self, manager_id: str, overrides: dict, region_id: str | None = None
    ) -> bool:
        """
        Save per-manager delivery method overrides.
        `overrides` is a dict keyed by method id.
        """
        if not self._use_postgres():
            payload = {"manager_id": manager_id or "", "overrides": overrides or {}}
            return bool(
                self._post("/delivery_methods/manager_overrides/save", payload) or False
            )

        mid = str(manager_id or "").strip()
        if not mid:
            return False
        rid = str(region_id or "").strip()
        overrides_payload = overrides if isinstance(overrides, dict) else {}
        now = self._now_ts()
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO manager_delivery_overrides (manager_id, region_id, overrides, updated_at)
                    VALUES (%s, %s, %s::jsonb, %s)
                    ON CONFLICT (manager_id, region_id)
                    DO UPDATE SET overrides=EXCLUDED.overrides, updated_at=EXCLUDED.updated_at
                    """,
                    (mid, rid, psycopg.types.json.Jsonb(overrides_payload), now),
                )
            # No direct company_id column here; pulse by resolved manager company if possible.
            with contextlib.suppress(Exception):
                prof = (
                    self.get_manager_profile(mid)
                    if hasattr(self, "get_manager_profile")
                    else {}
                )
                cid = str((prof or {}).get("company_id") or "").strip()
                if cid:
                    self._pulse(cid, "company")
            return True
        except Exception:
            logger.exception("save_manager_delivery_overrides failed")
            return False

    def get_effective_delivery_methods_for_manager(
        self,
        company_id: str,
        manager_id: str,
        region_id: str | None = None,
        include_user_disabled: bool = False,
    ):
        """
        Combine company delivery methods with manager overrides.

        Returns list[dict] compatible with Products profitability view:
        - base_price_per_kg, base_price_currency
        - effective_price_per_kg, effective_price_currency
        - user_enabled: bool — user's personal on/off preference

        By default (include_user_disabled=False) methods the user has personally
        disabled are excluded. Pass include_user_disabled=True to get all methods
        (e.g. in the calculator so the user can re-enable them).
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/delivery_methods/effective",
                    {
                        "company_id": company_id or "",
                        "manager_id": manager_id or "",
                        "region_id": region_id or "",
                    },
                )
                or []
            )

        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not cid or not mid:
            return []

        # Company methods are region-scoped; if rid isn't provided, keep legacy behavior.
        methods = (
            self.get_company_delivery_methods(cid, rid)
            if rid
            else self.get_company_delivery_methods(cid, None) or []
        )
        overrides = self.get_manager_delivery_overrides(mid, region_id=rid) or {}

        def _to_float_or_none_local(value):
            try:
                if value is None:
                    return None
                raw = str(value).strip().replace(",", ".")
                if raw == "":
                    return None
                return float(raw)
            except Exception:
                return None

        out: list[dict] = []
        for row in methods:
            if not isinstance(row, dict) or not row.get("id"):
                continue
            method_id = str(row.get("id"))
            base_price = row.get("base_price_per_kg")
            base_term = _to_float_or_none_local(row.get("delivery_term_days"))
            base_ccy = str(
                row.get("price_currency") or row.get("base_price_currency") or "USD"
            ).upper()
            override_entry = overrides.get(method_id)

            eff_price = base_price
            eff_term = base_term
            eff_ccy = base_ccy
            if isinstance(override_entry, dict):
                if override_entry.get("price") is not None:
                    eff_price = override_entry.get("price")
                if override_entry.get("delivery_term_days") is not None:
                    eff_term = _to_float_or_none_local(
                        override_entry.get("delivery_term_days")
                    )
                eff_ccy = str(override_entry.get("currency") or base_ccy).upper()
            elif override_entry is not None:
                # Legacy: override stored as raw number
                eff_price = override_entry

            # Respect user's personal enabled/disabled preference
            user_enabled = True
            if isinstance(override_entry, dict) and "enabled" in override_entry:
                user_enabled = bool(override_entry["enabled"])
            if not include_user_disabled and not user_enabled:
                continue  # skip methods the user has personally disabled

            merged = dict(row)
            merged["base_price_currency"] = base_ccy
            merged["base_delivery_term_days"] = base_term
            merged["effective_price_per_kg"] = eff_price
            merged["effective_price_currency"] = eff_ccy
            merged["effective_delivery_term_days"] = eff_term
            merged["user_enabled"] = user_enabled
            out.append(merged)
        return out

    # ----------------- visibility helpers (Postgres mode) -----------------
    def get_visible_managers(
        self,
        company_id: str,
        requester_manager_id: str | None = None,
        requester_role: str | None = None,
        region_id: str | None = None,
        force_refresh: bool | None = None,  # noqa: ARG002
    ):
        """
        Used by MainDashboard to populate "switch manager context" buttons.

        Compatibility note: older UI calls this as
          get_visible_managers(company_id, manager_id, role)
        so we keep positional args stable.

        Rules (requested):
        - Admin: can switch to ALL managers in own company, but NO ONE can switch into an Admin account.
        - Non-admin: can switch ONLY to direct subordinates (manager_supervisors supervisor_id -> manager_id).
        - Subordinates cannot switch to supervisors.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/managers/visible",
                    {
                        "company_id": company_id,
                        "requester_manager_id": requester_manager_id or "",
                        "requester_role": requester_role or "",
                        "region_id": region_id or "",
                    },
                )
                or []
            )

        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        req_id = str(requester_manager_id or "").strip()
        role_slug = str(requester_role or "").strip().lower().replace(" ", "")
        if not cid:
            return []

        def _is_admin_role(slug: str) -> bool:
            return slug in {
                "адмін",
                "админ",
                "admin",
                "суперадмін",
                "суперадмин",
                "superadmin",
            }

        # Always exclude admin/superadmin targets from impersonation list
        exclude_role_slugs = {
            "адмін",
            "админ",
            "admin",
            "суперадмін",
            "суперадмин",
            "superadmin",
        }

        if _is_admin_role(role_slug):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id, company_id, full_name, email, phone, role, is_approved, is_blocked, meta, created_at, updated_at
                    FROM public.managers
                    WHERE company_id=%s
                    ORDER BY full_name ASC
                    """,
                    (cid,),
                )
                rows = cur.fetchall() or []
        else:
            if not req_id:
                return []
            # manager_supervisors is company-scoped (own database); public.managers
            # is general (shared database) — resolve in two steps, no cross-DB join.
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT manager_id FROM manager_supervisors WHERE company_id=%s AND supervisor_id=%s",
                    (cid, req_id),
                )
                sub_ids = [
                    str(r["manager_id"])
                    for r in (cur.fetchall() or [])
                    if r.get("manager_id")
                ]
            if not sub_ids:
                return []
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id, company_id, full_name, email, phone, role, is_approved, is_blocked, meta, created_at, updated_at
                    FROM public.managers
                    WHERE id = ANY(%s)
                    ORDER BY full_name ASC
                    """,
                    (sub_ids,),
                )
                rows = cur.fetchall() or []

        out = []
        for r in rows:
            if not isinstance(r, dict) or not r.get("id"):
                continue
            if req_id and str(r.get("id")) == req_id:
                continue
            slug = str(r.get("role") or "").strip().lower().replace(" ", "")
            if slug in exclude_role_slugs:
                continue
            if rid and str(r.get("company_id") or "").strip() != cid:
                continue
            out.append(r)
        return out

    def get_visible_regions_for_manager(
        self, company_id: str, manager_id: str, force_refresh: bool | None = None
    ):  # noqa: ARG002
        """
        Returns regions available to manager.
        If no explicit allowed regions -> all company regions (compat mode).
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/regions/visible_for_manager",
                    {"company_id": company_id, "manager_id": manager_id},
                )
                or []
            )
        company_id = str(company_id or "").strip()
        manager_id = str(manager_id or "").strip()
        if not company_id:
            return []
        allowed = (
            set(self.get_manager_allowed_region_ids(manager_id))
            if manager_id
            else set()
        )
        regions = self.get_company_regions(company_id)
        if allowed:
            return [
                r for r in regions if isinstance(r, dict) and r.get("id") in allowed
            ]
        return regions

    # ----------------- manager workspace state (Postgres mode) -----------------
    def get_manager_workspace_state(self, manager_id: str):
        if not self._use_postgres():
            return (
                self._get("/managers/workspace_state", {"manager_id": manager_id}) or {}
            )
        mid = str(manager_id or "").strip()
        if not mid:
            return {}
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT state FROM manager_workspace_state WHERE manager_id=%s LIMIT 1",
                (mid,),
            )
            row = cur.fetchone()
        if row and isinstance(row.get("state"), dict):
            return row["state"]
        return {}

    # ------------------------------------------------------------------ #
    #  i18n — translation languages / keys / values                       #
    #  Keys live in code (every t(key, uk_text) call carries its own      #
    #  Ukrainian fallback) and self-register here the first time they're  #
    #  seen; translated VALUES are entered by superadmin via the "Мови"   #
    #  screen and stored here so they migrate with the rest of the DB.    #
    # ------------------------------------------------------------------ #
    def _ensure_i18n_tables(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.translation_languages (
                    code        character varying(8) NOT NULL,
                    name        character varying(64) NOT NULL,
                    flag_emoji  character varying(16) NOT NULL DEFAULT '',
                    sort_order  integer NOT NULL DEFAULT 0,
                    enabled     boolean NOT NULL DEFAULT true,
                    created_at  timestamp without time zone NOT NULL,
                    updated_at  timestamp without time zone NOT NULL,
                    PRIMARY KEY (code)
                )
                """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.translation_keys (
                    key         character varying(255) NOT NULL,
                    uk_text     text NOT NULL DEFAULT '',
                    created_at  timestamp without time zone NOT NULL,
                    updated_at  timestamp without time zone NOT NULL,
                    PRIMARY KEY (key)
                )
                """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.translation_values (
                    id          character varying NOT NULL,
                    key         character varying(255) NOT NULL,
                    lang_code   character varying(8) NOT NULL,
                    value       text NOT NULL DEFAULT '',
                    updated_at  timestamp without time zone NOT NULL,
                    PRIMARY KEY (id),
                    UNIQUE (key, lang_code)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_translation_values_key "
                "ON public.translation_values (key)"
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_translation_values_lang "
                "ON public.translation_values (lang_code)"
            )
        self._general_pg().commit()

    def get_translation_languages(self) -> list[dict]:
        """All languages (incl. disabled), ordered for display."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT code, name, flag_emoji, sort_order, enabled "
                    "FROM public.translation_languages ORDER BY sort_order ASC, code ASC"
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def save_translation_languages_bulk(self, rows: list[dict]) -> bool:
        """Replace the language list in bulk (used by the 'Мови' screen and
        the initial 5-language seed). Mirrors save_gsm_parser_brands_bulk."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                incoming_codes = [
                    str(r.get("code") or "").strip().upper()
                    for r in rows
                    if str(r.get("code") or "").strip()
                ]
                if incoming_codes:
                    cur.execute(
                        "DELETE FROM public.translation_languages WHERE code != ALL(%s)",
                        (incoming_codes,),
                    )
                for idx, row in enumerate(rows):
                    code = str(row.get("code") or "").strip().upper()
                    if not code:
                        continue
                    cur.execute(
                        """
                        INSERT INTO public.translation_languages
                            (code, name, flag_emoji, sort_order, enabled, created_at, updated_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s)
                        ON CONFLICT (code) DO UPDATE SET
                            name        = EXCLUDED.name,
                            flag_emoji  = EXCLUDED.flag_emoji,
                            sort_order  = EXCLUDED.sort_order,
                            enabled     = EXCLUDED.enabled,
                            updated_at  = EXCLUDED.updated_at
                        """,
                        (
                            code,
                            str(row.get("name") or "").strip(),
                            str(row.get("flag_emoji") or "").strip(),
                            idx,
                            bool(row.get("enabled", True)),
                            now,
                            now,
                        ),
                    )
            self._general_pg().commit()
            return True
        return False

    def register_translation_key(self, key: str, uk_text: str) -> bool:
        """Upsert one key into the registry — called the first time t(key, ...)
        is ever seen this process. Keeps uk_text in sync if it changes in code."""
        if not self._use_postgres() or not key:
            return False
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.translation_keys (key, uk_text, created_at, updated_at)
                    VALUES (%s, %s, %s, %s)
                    ON CONFLICT (key) DO UPDATE SET
                        uk_text    = EXCLUDED.uk_text,
                        updated_at = EXCLUDED.updated_at
                    """,
                    (str(key), str(uk_text or ""), now, now),
                )
            self._general_pg().commit()
            return True
        return False

    def get_all_translation_keys(self) -> set:
        """Just the key column — used to preload the in-memory 'already
        registered' set so t() doesn't hit the DB for known keys."""
        if not self._use_postgres():
            return set()
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            with self._general_pg().cursor() as cur:
                cur.execute("SELECT key FROM public.translation_keys")
                rows = cur.fetchall() or []
            return {
                str(r.get("key")) for r in rows if isinstance(r, dict) and r.get("key")
            }
        return set()

    def get_translations_for_lang(self, lang_code: str) -> dict:
        """key -> value for ONE language — used by t()'s per-language cache."""
        if not self._use_postgres() or not lang_code:
            return {}
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT key, value FROM public.translation_values WHERE lang_code=%s",
                    (str(lang_code).upper(),),
                )
                rows = cur.fetchall() or []
            return {
                str(r.get("key")): str(r.get("value") or "")
                for r in rows
                if isinstance(r, dict) and r.get("key")
            }
        return {}

    def get_all_translations(self) -> dict:
        """Full picture for the 'Мови' admin table:
        {"keys": [{"key":..., "uk_text":...}, ...], "values": {key: {lang: value}}}."""
        if not self._use_postgres():
            return {"keys": [], "values": {}}
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT key, uk_text FROM public.translation_keys ORDER BY key ASC"
                )
                key_rows = [
                    dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]
                cur.execute(
                    "SELECT key, lang_code, value FROM public.translation_values"
                )
                val_rows = cur.fetchall() or []
            values: dict = {}
            for r in val_rows:
                if not isinstance(r, dict):
                    continue
                k = str(r.get("key") or "")
                lc = str(r.get("lang_code") or "")
                if not k or not lc:
                    continue
                values.setdefault(k, {})[lc] = str(r.get("value") or "")
            return {"keys": key_rows, "values": values}
        return {"keys": [], "values": {}}

    def count_empty_translations(self) -> int:
        """Count empty/missing translation cells across all non-UA languages
        (key x language pairs with no value or a whitespace-only value) —
        powers the 'Порожні переклади' counter on the superadmin overview."""
        if not self._use_postgres():
            return 0
        try:
            self._ensure_i18n_tables()
            codes = [
                str(lang.get("code") or "").strip().upper()
                for lang in (self.get_translation_languages() or [])
                if str(lang.get("code") or "").strip().upper() != "UA"
            ]
            if not codes:
                return 0
            with self._general_pg().cursor() as cur:
                cur.execute("SELECT key FROM public.translation_keys")
                keys = [
                    str(r.get("key"))
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and r.get("key")
                ]
                if not keys:
                    return 0
                cur.execute(
                    "SELECT key, lang_code, value FROM public.translation_values "
                    "WHERE lang_code = ANY(%s) AND key = ANY(%s)",
                    (codes, keys),
                )
                filled = {
                    (str(r.get("key") or ""), str(r.get("lang_code") or "").upper())
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and str(r.get("value") or "").strip()
                }
            return len(keys) * len(codes) - len(filled)
        except Exception:
            return 0

    def save_translation_values_bulk(self, lang_code: str, values: dict) -> bool:
        """Upsert many key->value pairs for one language at once — used by
        the 'Мови' screen Save button and the Excel-import flow."""
        if not self._use_postgres() or not lang_code or not values:
            return False
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            import uuid as _uuid

            now = self._now_ts()
            lc = str(lang_code).strip().upper()
            rows = [
                (f"tv_{_uuid.uuid4().hex}", str(key), lc, str(value or ""), now)
                for key, value in values.items()
                if key
            ]
            if not rows:
                return True
            with self._general_pg().cursor() as cur:
                # Batched multi-row INSERT instead of one execute() per key —
                # over a remote (non-localhost) Postgres connection, one round
                # trip per row turns a few-thousand-key import into minutes.
                CHUNK = 500
                for i in range(0, len(rows), CHUNK):
                    chunk = rows[i : i + CHUNK]
                    placeholders = ", ".join(["(%s, %s, %s, %s, %s)"] * len(chunk))
                    flat_params = [v for row in chunk for v in row]
                    cur.execute(
                        f"""
                        INSERT INTO public.translation_values (id, key, lang_code, value, updated_at)
                        VALUES {placeholders}
                        ON CONFLICT (key, lang_code) DO UPDATE SET
                            value      = EXCLUDED.value,
                            updated_at = EXCLUDED.updated_at
                        """,
                        flat_params,
                    )
            self._general_pg().commit()
            return True
        return False

    def seed_translation_values_bulk_if_new(self, lang_code: str, values: dict) -> bool:
        """Insert key→value for one language only when the pair doesn't exist yet.
        Unlike save_translation_values_bulk this never overwrites user edits."""
        if not self._use_postgres() or not lang_code or not values:
            return False
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            import uuid as _uuid

            now = self._now_ts()
            lc = str(lang_code).strip().upper()
            rows = [
                (f"tv_{_uuid.uuid4().hex}", str(key), lc, str(value or ""), now)
                for key, value in values.items()
                if key
            ]
            if not rows:
                return True
            with self._general_pg().cursor() as cur:
                # Batched multi-row INSERT instead of one execute() per key.
                # This runs on EVERY app boot (AuthScreen.__init__ ->
                # seed_ui_translations_if_new, once per language) — over
                # localhost the old per-row loop was invisible (~2000 tiny
                # round trips at sub-ms each), but over a remote VPS Postgres
                # connection each round trip costs real network latency,
                # turning app startup into a multi-minute stall that looked
                # like a frozen black window.
                CHUNK = 500
                for i in range(0, len(rows), CHUNK):
                    chunk = rows[i : i + CHUNK]
                    placeholders = ", ".join(["(%s, %s, %s, %s, %s)"] * len(chunk))
                    flat_params = [v for row in chunk for v in row]
                    cur.execute(
                        f"""
                        INSERT INTO public.translation_values (id, key, lang_code, value, updated_at)
                        VALUES {placeholders}
                        ON CONFLICT (key, lang_code) DO NOTHING
                        """,
                        flat_params,
                    )
            self._general_pg().commit()
            return True
        return False

    def save_translation_keys_uk_bulk(self, values: dict) -> bool:
        """Update uk_text for many keys at once — used by the 'Мови' screen
        when the superadmin edits the base Ukrainian column."""
        if not self._use_postgres() or not values:
            return False
        with contextlib.suppress(Exception):
            self._ensure_i18n_tables()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                for key, uk_text in values.items():
                    if not key:
                        continue
                    cur.execute(
                        "UPDATE public.translation_keys SET uk_text=%s, updated_at=%s WHERE key=%s",
                        (str(uk_text or ""), now, str(key)),
                    )
            self._general_pg().commit()
            return True
        return False

    def save_manager_workspace_state(self, manager_id: str, state: dict) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/managers/workspace_state/save",
                    {"manager_id": manager_id, "state": state},
                )
                or False
            )
        mid = str(manager_id or "").strip()
        if not mid or not isinstance(state, dict):
            return False
        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO manager_workspace_state (manager_id, state, updated_at)
                VALUES (%s, %s::jsonb, %s)
                ON CONFLICT (manager_id) DO UPDATE SET state=EXCLUDED.state, updated_at=EXCLUDED.updated_at
                """,
                (mid, psycopg.types.json.Jsonb(state), now),
            )
        return True

    # ----------------- cost-price stock inputs (Postgres mode) -----------------
    def get_cost_price_stock_inputs(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
    ) -> dict:
        if not self._use_postgres():
            return (
                self._get(
                    "/cost_price_stock_inputs",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                    },
                )
                or {}
            )

        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        if not cid:
            return {}

        visible_ctx = (
            self._get_manager_visible_scope_context(cid, mid, rid or None)
            if mid
            else {"restricted": False, "product_ids": set()}
        )
        if (
            mid
            and visible_ctx.get("restricted")
            and not (visible_ctx.get("product_ids") or set())
        ):
            return {}

        with self._pg().cursor() as cur:
            q = """
                SELECT product_id, qty, amount, amount_ccy, new_price, new_price_ccy, updated_at
                FROM cost_price_stock_inputs
                WHERE company_id=%s
            """
            params: list[Any] = [cid]
            if rid:
                q += " AND region_id=%s"
                params.append(rid)
            cur.execute(q, params)
            rows = cur.fetchall() or []

        out = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            pid = str(row.get("product_id") or "").strip()
            if not pid:
                continue
            prev = out.get(pid)
            cur_ts = str(row.get("updated_at") or "")
            prev_ts = str((prev or {}).get("updated_at") or "")
            if prev is not None and prev_ts >= cur_ts:
                continue
            out[pid] = {
                "qty": row.get("qty"),
                "amount": row.get("amount"),
                "ccy": str(row.get("amount_ccy") or "USD").upper().strip() or "USD",
                "new_price": row.get("new_price"),
                "new_ccy": str(row.get("new_price_ccy") or "USD").upper().strip()
                or "USD",
                "updated_at": row.get("updated_at"),
            }
        if mid and visible_ctx.get("restricted"):
            allowed_product_ids = visible_ctx.get("product_ids") or set()
            out = {
                pid: val
                for pid, val in out.items()
                if str(pid or "").strip() in allowed_product_ids
            }
        return out

    def upsert_cost_price_stock_input(
        self,
        company_id: str,
        product_id: str,
        patch: dict,
        *,
        region_id: str | None = None,
        manager_id: str | None = None,
    ) -> bool:
        if not isinstance(patch, dict):
            return False

        if not self._use_postgres():
            return bool(
                self._post(
                    "/cost_price_stock_inputs/upsert",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                        "product_id": product_id,
                        "patch": patch,
                    },
                )
                or False
            )

        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        pid = str(product_id or "").strip()
        if not cid or not mid or not pid:
            return False

        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO cost_price_stock_inputs
                    (company_id, manager_id, region_id, product_id, qty, amount, amount_ccy, new_price, new_price_ccy, updated_at)
                VALUES
                    (%s, %s, %s, %s, %s, %s, COALESCE(NULLIF(%s, ''), 'USD'), %s, COALESCE(NULLIF(%s, ''), 'USD'), %s)
                ON CONFLICT (company_id, manager_id, region_id, product_id)
                DO UPDATE SET
                    qty = EXCLUDED.qty,
                    amount = EXCLUDED.amount,
                    amount_ccy = COALESCE(NULLIF(EXCLUDED.amount_ccy, ''), cost_price_stock_inputs.amount_ccy),
                    new_price = EXCLUDED.new_price,
                    new_price_ccy = COALESCE(NULLIF(EXCLUDED.new_price_ccy, ''), cost_price_stock_inputs.new_price_ccy),
                    updated_at = EXCLUDED.updated_at
                """,
                (
                    cid,
                    mid,
                    rid,
                    pid,
                    patch.get("qty"),
                    patch.get("amount"),
                    str(patch.get("ccy") or "").upper().strip() or None,
                    patch.get("new_price"),
                    str(patch.get("new_ccy") or "").upper().strip() or None,
                    now,
                ),
            )
        return True

    def get_cost_price_order_inputs(
        self,
        company_id: str,
        region_id: str | None = None,
        manager_id: str | None = None,
    ) -> dict:
        if not self._use_postgres():
            return (
                self._get(
                    "/cost_price_order_inputs",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                    },
                )
                or {}
            )

        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        if not cid:
            return {}

        visible_ctx = (
            self._get_manager_visible_scope_context(cid, mid, rid or None)
            if mid
            else {"restricted": False, "order_ids": set()}
        )
        if (
            mid
            and visible_ctx.get("restricted")
            and not (visible_ctx.get("order_ids") or set())
        ):
            return {}

        with self._pg().cursor() as cur:
            q = """
                SELECT order_id, line_idx, unit_cost_usd, unit_cost_currency, new_price, new_price_ccy, updated_at
                FROM cost_price_order_inputs
                WHERE company_id=%s
            """
            params: list[Any] = [cid]
            if rid:
                q += " AND region_id=%s"
                params.append(rid)
            cur.execute(q, params)
            rows = cur.fetchall() or []

        out = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            order_id = str(row.get("order_id") or "").strip()
            if not order_id:
                continue
            try:
                line_idx = int(row.get("line_idx") or 0)
            except Exception:
                line_idx = 0
            key = f"{order_id}:{line_idx}"
            prev = out.get(key)
            cur_ts = str(row.get("updated_at") or "")
            prev_ts = str((prev or {}).get("updated_at") or "")
            if prev is not None and prev_ts >= cur_ts:
                continue
            out[key] = {
                "unit_cost_usd": row.get("unit_cost_usd"),
                "unit_cost_currency": str(row.get("unit_cost_currency") or "USD")
                .upper()
                .strip()
                or "USD",
                "new_price": row.get("new_price"),
                "new_price_ccy": str(row.get("new_price_ccy") or "USD").upper().strip()
                or "USD",
                "updated_at": row.get("updated_at"),
            }
        if mid and visible_ctx.get("restricted"):
            allowed_order_ids = visible_ctx.get("order_ids") or set()
            out = {
                key: val
                for key, val in out.items()
                if str(key).split(":", 1)[0] in allowed_order_ids
            }
        return out

    def upsert_cost_price_order_input(
        self,
        company_id: str,
        order_id: str,
        line_idx: int,
        patch: dict,
        *,
        region_id: str | None = None,
        manager_id: str | None = None,
    ) -> bool:
        if not isinstance(patch, dict):
            return False

        if not self._use_postgres():
            return bool(
                self._post(
                    "/cost_price_order_inputs/upsert",
                    {
                        "company_id": company_id,
                        "region_id": region_id or "",
                        "manager_id": manager_id or "",
                        "order_id": order_id,
                        "line_idx": int(line_idx or 0),
                        "patch": patch,
                    },
                )
                or False
            )

        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        mid = str(manager_id or "").strip()
        oid = str(order_id or "").strip()
        try:
            idx = int(line_idx or 0)
        except Exception:
            idx = 0
        if not cid or not mid or not oid:
            return False

        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO cost_price_order_inputs
                    (company_id, manager_id, region_id, order_id, line_idx, unit_cost_usd, unit_cost_currency, new_price, new_price_ccy, updated_at)
                VALUES
                    (%s, %s, %s, %s, %s, %s, COALESCE(NULLIF(%s, ''), 'USD'), %s, COALESCE(NULLIF(%s, ''), 'USD'), %s)
                ON CONFLICT (company_id, manager_id, region_id, order_id, line_idx)
                DO UPDATE SET
                    unit_cost_usd = EXCLUDED.unit_cost_usd,
                    unit_cost_currency = COALESCE(NULLIF(EXCLUDED.unit_cost_currency, ''), cost_price_order_inputs.unit_cost_currency),
                    new_price = EXCLUDED.new_price,
                    new_price_ccy = COALESCE(NULLIF(EXCLUDED.new_price_ccy, ''), cost_price_order_inputs.new_price_ccy),
                    updated_at = EXCLUDED.updated_at
                """,
                (
                    cid,
                    mid,
                    rid,
                    oid,
                    idx,
                    patch.get("unit_cost_usd"),
                    str(patch.get("unit_cost_currency") or "").upper().strip() or None,
                    patch.get("new_price"),
                    str(patch.get("new_price_ccy") or "").upper().strip() or None,
                    now,
                ),
            )
        return True

    # ----------------- extensions / background (Postgres mode) -----------------
    def is_company_gsm_parser_enabled(self, company_id: str) -> bool:
        """Cache-aside — this gate is checked repeatedly (sidebar, every
        tab's visibility check) during a single dashboard build/render pass;
        cached per company, cleared by _pulse(company_id, "extensions")."""
        cid = str(company_id or "").strip()
        if not self._use_postgres() or not cid:
            return self._is_company_gsm_parser_enabled_uncached(company_id)
        return self._cached_list(
            f"gsm_enabled_{cid}",
            False,
            lambda: self._is_company_gsm_parser_enabled_uncached(company_id),
        )

    def _is_company_gsm_parser_enabled_uncached(self, company_id: str) -> bool:
        if not self._use_postgres():
            return bool(
                self._get("/extensions/gsm_parser/enabled", {"company_id": company_id})
                or False
            )
        cid = str(company_id or "").strip()
        if not cid:
            return False
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                    (cid, "gsm_parser"),
                )
                row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            # Superadmin is the sole company-wide gate: enabling it turns it
            # on for every user in the company, with no separate admin-level
            # override. `admin_enabled` is legacy and no longer consulted —
            # individual users instead control their own visibility via
            # get_gsm_parser_user_prefs.
            # - legacy: {"enabled": bool}
            # - current: {"sa_enabled": bool}
            if "sa_enabled" in (state or {}):
                return bool((state or {}).get("sa_enabled", True))
            if "enabled" in (state or {}):
                return bool((state or {}).get("enabled"))
            # If never configured, allow by default (prevents "dead" button).
            return True
        return False

    def get_company_gsm_parser_state(self, company_id: str) -> dict:
        """
        Returns dict with keys: sa_enabled, admin_enabled, effective_enabled.
        """
        if not self._use_postgres():
            return (
                self._get("/extensions/gsm_parser/state", {"company_id": company_id})
                or {}
            )
        cid = str(company_id or "").strip()
        if not cid:
            return {
                "sa_enabled": False,
                "admin_enabled": False,
                "effective_enabled": False,
            }
        sa_enabled = False
        admin_enabled = False
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                    (cid, "gsm_parser"),
                )
                row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            sa_enabled = bool(
                (state or {}).get("sa_enabled")
                if "sa_enabled" in (state or {})
                else (state or {}).get("enabled")
            )
            admin_enabled = bool((state or {}).get("admin_enabled", True))
        return {
            "sa_enabled": sa_enabled,
            "admin_enabled": admin_enabled,
            # sa_enabled alone gates access now — see is_company_gsm_parser_enabled.
            "effective_enabled": sa_enabled,
        }

    def get_companies_gsm_parser_state(self, company_ids: list[str]) -> dict:
        """
        Bulk version for superadmin extensions page.
        Returns mapping: company_id -> state dict.
        """
        if not self._use_postgres():
            return (
                self._post(
                    "/extensions/gsm_parser/states", {"company_ids": company_ids}
                )
                or {}
            )
        company_ids = [str(x) for x in (company_ids or []) if str(x).strip()]
        out: dict[str, dict] = {}
        if not company_ids:
            return out
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT company_id, state
                FROM company_extensions
                WHERE ext_key=%s AND company_id = ANY(%s)
                """,
                ("gsm_parser", company_ids),
            )
            rows = cur.fetchall() or []
        by_id = {
            r.get("company_id"): (
                r.get("state") if isinstance(r.get("state"), dict) else {}
            )
            for r in rows
            if isinstance(r, dict) and r.get("company_id")
        }
        for cid in company_ids:
            st = by_id.get(cid, {}) or {}
            sa_enabled = bool(
                st.get("sa_enabled") if "sa_enabled" in st else st.get("enabled")
            )
            admin_enabled = bool(st.get("admin_enabled", True))
            out[cid] = {
                "sa_enabled": sa_enabled,
                "admin_enabled": admin_enabled,
                "effective_enabled": sa_enabled,
            }
        return out

    def set_company_gsm_parser_superadmin(self, company_id: str, enabled: bool) -> bool:
        """
        Superadmin toggle for gsm_parser per company.
        """
        if not self._use_postgres():
            return bool(
                self._post(
                    "/extensions/gsm_parser/set_superadmin",
                    {"company_id": company_id, "enabled": bool(enabled)},
                )
                or False
            )
        cid = str(company_id or "").strip()
        if not cid:
            return False
        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                (cid, "gsm_parser"),
            )
            row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            state = dict(state or {})
            state["sa_enabled"] = bool(enabled)
            # keep admin flag unless not set
            state.setdefault("admin_enabled", True)
            cur.execute(
                """
                INSERT INTO company_extensions (company_id, ext_key, state, updated_at)
                VALUES (%s,%s,%s::jsonb,%s)
                ON CONFLICT (company_id, ext_key) DO UPDATE SET state=EXCLUDED.state, updated_at=EXCLUDED.updated_at
                """,
                (cid, "gsm_parser", psycopg.types.json.Jsonb(state), now),
            )
        self._pulse(cid, "extensions")
        return True

    def set_company_gsm_parser_admin(self, company_id: str, enabled: bool) -> bool:
        """
        Admin toggle for gsm_parser within company.
        """
        if not self._use_postgres():
            return bool(
                self._post(
                    "/extensions/gsm_parser/set_admin",
                    {"company_id": company_id, "enabled": bool(enabled)},
                )
                or False
            )
        cid = str(company_id or "").strip()
        if not cid:
            return False
        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                (cid, "gsm_parser"),
            )
            row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            state = dict(state or {})
            # default SA flag if not set: True (so admin can manage unless SA disabled explicitly)
            state.setdefault("sa_enabled", True)
            state["admin_enabled"] = bool(enabled)
            cur.execute(
                """
                INSERT INTO company_extensions (company_id, ext_key, state, updated_at)
                VALUES (%s,%s,%s::jsonb,%s)
                ON CONFLICT (company_id, ext_key) DO UPDATE SET state=EXCLUDED.state, updated_at=EXCLUDED.updated_at
                """,
                (cid, "gsm_parser", psycopg.types.json.Jsonb(state), now),
            )
        self._pulse(cid, "extensions")
        return True

    def get_company_fx_rates(self, company_id: str) -> dict | None:
        """Today's fixed exchange rates, if some user of this company (VPS
        or local) already fetched them today — None if nobody has yet.
        Backs the "fetch once per day, shared for the whole company"
        behaviour: on VPS this is genuinely shared across every user's
        machine; for a Локал company it's harmless (same effect as the
        per-machine local file cache in fx_rates.py, just also mirrored
        here)."""
        if not self._use_postgres():
            return None
        cid = str(company_id or "").strip()
        if not cid:
            return None
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                    (cid, "fx_rates"),
                )
                row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            rates = state.get("rates")
            day = str(state.get("date") or "")
            if isinstance(rates, dict) and rates and day == self._now_ts()[:10]:
                return rates
        return None

    def set_company_fx_rates(self, company_id: str, rates: dict, day: str) -> bool:
        """Persist today's fetched rates so the next user of this company
        (same day) can skip the network fetch entirely — see
        get_company_fx_rates()."""
        if not self._use_postgres():
            return False
        cid = str(company_id or "").strip()
        if not cid or not isinstance(rates, dict) or not rates or not day:
            return False
        with contextlib.suppress(Exception):
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO company_extensions (company_id, ext_key, state, updated_at)
                    VALUES (%s,%s,%s::jsonb,%s)
                    ON CONFLICT (company_id, ext_key) DO UPDATE SET state=EXCLUDED.state, updated_at=EXCLUDED.updated_at
                    """,
                    (
                        cid,
                        "fx_rates",
                        psycopg.types.json.Jsonb({"date": day, "rates": rates}),
                        self._now_ts(),
                    ),
                )
            return True
        return False

