    def _normalize_gsm_parser_config(self, config: dict | None) -> dict:
        defaults = self._default_gsm_parser_config()
        incoming = config if isinstance(config, dict) else {}

        automation = (
            incoming.get("automation")
            if isinstance(incoming.get("automation"), dict)
            else {}
        )
        comparison = (
            incoming.get("comparison")
            if isinstance(incoming.get("comparison"), dict)
            else {}
        )
        telegram = (
            incoming.get("telegram")
            if isinstance(incoming.get("telegram"), dict)
            else {}
        )
        settings = (
            incoming.get("settings")
            if isinstance(incoming.get("settings"), dict)
            else {}
        )
        devices = (
            settings.get("devices") if isinstance(settings.get("devices"), dict) else {}
        )
        delays = (
            settings.get("delays") if isinstance(settings.get("delays"), dict) else {}
        )

        runs_per_day = automation.get(
            "runs_per_day", defaults["automation"]["runs_per_day"]
        )
        try:
            runs_per_day = max(1, min(12, int(runs_per_day)))
        except Exception:
            runs_per_day = defaults["automation"]["runs_per_day"]

        raw_times = automation.get("start_times")
        if not isinstance(raw_times, list):
            raw_times = list(defaults["automation"]["start_times"])
        start_times = [str(item or "").strip() for item in raw_times[:runs_per_day]]
        while len(start_times) < runs_per_day:
            start_times.append("")

        def _clean_rows(rows, allowed_keys):
            out = []
            for row in rows or []:
                if not isinstance(row, dict):
                    continue
                out.append(
                    {key: str(row.get(key) or "").strip() for key in allowed_keys}
                )
            return out

        gsm_rows = _clean_rows(
            (
                devices.get("gsm_arena")
                if isinstance(devices.get("gsm_arena"), list)
                else defaults["settings"]["devices"]["gsm_arena"]
            ),
            ["brand", "url", "last_device"],
        )
        ekatalog_rows = _clean_rows(
            (
                devices.get("ekatalog")
                if isinstance(devices.get("ekatalog"), list)
                else defaults["settings"]["devices"]["ekatalog"]
            ),
            ["device_type", "brand", "url", "last_device"],
        )
        message_rows = []
        raw_messages = (
            telegram.get("messages")
            if isinstance(telegram.get("messages"), list)
            else defaults["telegram"]["messages"]
        )
        for idx, row in enumerate(raw_messages):
            if not isinstance(row, dict):
                continue
            message_rows.append(
                {
                    "id": str(row.get("id") or f"message_{idx + 1}").strip(),
                    "title": str(row.get("title") or f"Повідомлення {idx + 1}").strip(),
                    "message_type": str(row.get("message_type") or "text").strip()
                    or "text",
                    "enabled": bool(row.get("enabled", True)),
                    "text": str(row.get("text") or "").strip(),
                }
            )
        if not message_rows:
            message_rows = list(defaults["telegram"]["messages"])

        assets = (
            telegram.get("assets") if isinstance(telegram.get("assets"), dict) else {}
        )

        # Flexible per-category Telegram report blocks (header / device_card),
        # user-editable in the GSM Parser extension UI without touching code —
        # any number of blocks per category, in any order.
        raw_categories = (
            telegram.get("categories")
            if isinstance(telegram.get("categories"), dict)
            else {}
        )
        categories_out: dict = {}
        for cat_key, blocks in raw_categories.items():
            if not isinstance(blocks, list):
                continue
            clean_blocks = []
            for b in blocks:
                if not isinstance(b, dict):
                    continue
                kind = str(b.get("kind") or "").strip()
                if kind == "header":
                    clean_blocks.append(
                        {
                            "kind": "header",
                            "enabled": bool(b.get("enabled", True)),
                            "text": str(b.get("text") or ""),
                            "photo_path": str(b.get("photo_path") or "").strip(),
                        }
                    )
                elif kind == "device_card":
                    flds = b.get("fields") if isinstance(b.get("fields"), list) else []
                    clean_blocks.append(
                        {
                            "kind": "device_card",
                            "enabled": bool(b.get("enabled", True)),
                            "fields": [str(f) for f in flds],
                        }
                    )
            categories_out[str(cat_key)] = clean_blocks

        # Normalize comparison settings
        exclude_words = comparison.get("exclude_words")
        if not isinstance(exclude_words, list):
            exclude_words = defaults["comparison"]["exclude_words"]
        exclude_words = [str(w).strip() for w in exclude_words]

        custom_rules = comparison.get("custom_rules")
        if not isinstance(custom_rules, list):
            custom_rules = []

        normalized_delays = {}
        for key, value in defaults["settings"]["delays"].items():
            raw_value = delays.get(key, value)
            try:
                normalized_delays[key] = max(0.0, float(raw_value))
            except Exception:
                normalized_delays[key] = value

        raw_retention_days = settings.get(
            "change_retention_days", defaults["settings"]["change_retention_days"]
        )
        try:
            change_retention_days = max(1, min(3650, int(raw_retention_days)))
        except Exception:
            change_retention_days = defaults["settings"]["change_retention_days"]

        raw_recent_count = settings.get(
            "gsm_recent_count", defaults["settings"]["gsm_recent_count"]
        )
        try:
            gsm_recent_count = max(1, min(200, int(raw_recent_count)))
        except Exception:
            gsm_recent_count = defaults["settings"]["gsm_recent_count"]

        raw_max_age_months = settings.get(
            "shops_appeared_max_age_months",
            defaults["settings"]["shops_appeared_max_age_months"],
        )
        try:
            shops_appeared_max_age_months = max(1, min(120, int(raw_max_age_months)))
        except Exception:
            shops_appeared_max_age_months = defaults["settings"][
                "shops_appeared_max_age_months"
            ]

        ek_on_sale_statuses = str(
            settings.get("ek_on_sale_statuses")
            or defaults["settings"]["ek_on_sale_statuses"]
        ).strip() or defaults["settings"]["ek_on_sale_statuses"]

        return {
            "automation": {
                "runs_per_day": runs_per_day,
                "start_times": start_times,
            },
            "comparison": {
                "remove_4g5g": bool(
                    comparison.get("remove_4g5g", defaults["comparison"]["remove_4g5g"])
                ),
                "remove_punctuation": bool(
                    comparison.get(
                        "remove_punctuation",
                        defaults["comparison"]["remove_punctuation"],
                    )
                ),
                "case_insensitive": bool(
                    comparison.get(
                        "case_insensitive", defaults["comparison"]["case_insensitive"]
                    )
                ),
                "exclude_words": exclude_words,
                "custom_rules": custom_rules,
            },
            "telegram": {
                "tg_enabled": bool(telegram.get("tg_enabled", True)),
                "bot_token": str(telegram.get("bot_token") or "").strip(),
                "chat_id": str(telegram.get("chat_id") or "").strip(),
                "chat_link": str(telegram.get("chat_link") or "").strip(),
                "spreadsheet_url": str(telegram.get("spreadsheet_url") or "").strip(),
                "report_window_start": str(
                    telegram.get("report_window_start")
                    or defaults["telegram"]["report_window_start"]
                ).strip(),
                "report_window_end": str(
                    telegram.get("report_window_end")
                    or defaults["telegram"]["report_window_end"]
                ).strip(),
                "report_send_time": str(
                    telegram.get("report_send_time")
                    or defaults["telegram"]["report_send_time"]
                ).strip(),
                "assets": {
                    "gsm_logo_path": str(assets.get("gsm_logo_path") or "").strip(),
                    "ekatalog_logo_path": str(
                        assets.get("ekatalog_logo_path") or ""
                    ).strip(),
                    "gsm_logo_url": str(
                        assets.get("gsm_logo_url")
                        or defaults["telegram"]["assets"]["gsm_logo_url"]
                    ).strip(),
                    "ekatalog_logo_url": str(
                        assets.get("ekatalog_logo_url")
                        or defaults["telegram"]["assets"]["ekatalog_logo_url"]
                    ).strip(),
                },
                "messages": message_rows,
                # Only persist "categories" once the config has actually gone
                # through the flexible block editor at least once (key present
                # in the incoming draft) — otherwise a save triggered from an
                # unrelated tab (e.g. "Бренди") before the automation tab was
                # ever opened would round-trip an empty {} and permanently
                # silence every category's Telegram messages (an empty dict
                # is NOT the same as "not configured yet" to the runner).
                **({"categories": categories_out} if "categories" in (telegram or {}) else {}),
            },
            "settings": {
                "change_retention_days": change_retention_days,
                "gsm_recent_count": gsm_recent_count,
                "shops_appeared_max_age_months": shops_appeared_max_age_months,
                "ek_on_sale_statuses": ek_on_sale_statuses,
                "devices": {
                    "gsm_arena": gsm_rows,
                    "ekatalog": ekatalog_rows,
                },
                "delays": normalized_delays,
            },
        }

    def get_gsm_parser_global_config(self) -> dict:
        """
        Global GSM Parser config (shared for all companies).
        Company access remains per-company via sa/admin enabled flags.
        """
        global_company_id = "__global__"
        global_ext_key = "gsm_parser_config"

        if not self._use_postgres():
            with contextlib.suppress(Exception):
                payload = self._get(
                    "/extensions/gsm_parser/config", {"company_id": global_company_id}
                )
                if isinstance(payload, dict) and "config" in payload:
                    payload = payload.get("config")
                return self._normalize_gsm_parser_config(payload)
            return self._default_gsm_parser_config()

        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                    (global_company_id, global_ext_key),
                )
                row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            payload = (state or {}).get("config") if isinstance(state, dict) else state
            if not payload and isinstance(state, dict):
                payload = state
            return self._normalize_gsm_parser_config(payload)
        return self._default_gsm_parser_config()

    def save_gsm_parser_global_config(self, config: dict) -> bool:
        normalized = self._normalize_gsm_parser_config(config)
        global_company_id = "__global__"
        global_ext_key = "gsm_parser_config"

        if not self._use_postgres():
            with contextlib.suppress(Exception):
                return bool(
                    self._post(
                        "/extensions/gsm_parser/config",
                        {"company_id": global_company_id, "config": normalized},
                    )
                    or False
                )
            return False

        now = self._now_ts()
        payload = {"config": normalized}
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO company_extensions (company_id, ext_key, state, updated_at)
                VALUES (%s,%s,%s::jsonb,%s)
                ON CONFLICT (company_id, ext_key) DO UPDATE SET state=EXCLUDED.state, updated_at=EXCLUDED.updated_at
                """,
                (
                    global_company_id,
                    global_ext_key,
                    psycopg.types.json.Jsonb(payload),
                    now,
                ),
            )
        return True

    def get_gsm_pending_telegram_notifications(self) -> list[dict]:
        """Telegram reports deferred by the "Не турбувати" quiet-hours window
        (see gsm_parser_runner._maybe_queue_or_send_telegram), waiting to be
        flushed once the configured send time is reached."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT state FROM company_extensions WHERE company_id=%s AND ext_key=%s LIMIT 1",
                    ("__global__", "gsm_parser_pending_tg"),
                )
                row = cur.fetchone() or {}
            state = row.get("state") if isinstance(row.get("state"), dict) else {}
            items = state.get("items") if isinstance(state, dict) else None
            return list(items) if isinstance(items, list) else []
        return []

    def save_gsm_pending_telegram_notifications(self, items: list[dict]) -> bool:
        if not self._use_postgres():
            return False
        now = self._now_ts()
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO company_extensions (company_id, ext_key, state, updated_at)
                    VALUES (%s,%s,%s::jsonb,%s)
                    ON CONFLICT (company_id, ext_key) DO UPDATE SET state=EXCLUDED.state, updated_at=EXCLUDED.updated_at
                    """,
                    (
                        "__global__",
                        "gsm_parser_pending_tg",
                        psycopg.types.json.Jsonb({"items": items}),
                        now,
                    ),
                )
            return True
        return False

    def get_company_gsm_parser_config(self, company_id: str) -> dict:
        """Backward-compatible alias: config is global, company_id ignored."""
