    def save_company_gsm_parser_config(self, company_id: str, config: dict) -> bool:
        """Backward-compatible alias: config is global, company_id ignored."""
        return self.save_gsm_parser_global_config(config)

    def reset_gsm_parser_run_log(self, header: str) -> None:
        """Start a fresh run log (overwrites whatever the previous run left).
        Mirrors LAST_PARSE_LOG_PATH.write_text() but centrally, so the
        desktop UI can see progress regardless of which machine is
        actually running the parser."""
        if not self._use_postgres():
            return
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_run_log (id, content, updated_at)
                    VALUES ('current', %s, %s)
                    ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content, updated_at=EXCLUDED.updated_at
                    """,
                    (str(header or "") + "\n", self._now_ts()),
                )

    def append_gsm_parser_run_log(self, line: str) -> None:
        """Append one line to the current run log (see reset_gsm_parser_run_log)."""
        if not self._use_postgres():
            return
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    UPDATE public.gsm_parser_run_log
                    SET content = content || %s, updated_at = %s
                    WHERE id='current'
                    """,
                    (str(line or "") + "\n", self._now_ts()),
                )

    def get_gsm_parser_run_log(self) -> str:
        """Full text of the current/most recent run's progress log."""
        if not self._use_postgres():
            return ""
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT content FROM public.gsm_parser_run_log WHERE id='current'"
                )
                row = cur.fetchone()
            return str((row or {}).get("content") or "")
        return ""

    def get_gsm_parser_schedule(self) -> dict:
        """
        Get GSM Parser schedule config from app_update_policy.
        Returns dict with keys: enabled (bool), run_times (list[str]), last_run (ts), next_run (ts).
        """
        defaults = {
            "enabled": False,
            "run_times": ["02:00", "14:00"],  # UTC times as HH:MM
            "last_run": None,
            "next_run": None,
        }
        if not self._use_postgres():
            return defaults

        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT policy FROM public.app_update_policy WHERE id=%s LIMIT 1",
                    ("gsm_parser_schedule",),
                )
                row = cur.fetchone() or {}
            policy = row.get("policy") if isinstance(row.get("policy"), dict) else {}
            out = dict(defaults)
            if policy:
                out.update(policy)
            # Ensure run_times is list of strings
            if not isinstance(out.get("run_times"), list):
                out["run_times"] = defaults["run_times"]
            out["run_times"] = [str(t).strip() for t in out.get("run_times", [])]
            out["enabled"] = bool(out.get("enabled", False))
            return out
        return defaults

    def set_gsm_parser_schedule(self, enabled: bool, run_times: list[str]) -> bool:
        """
        Set GSM Parser schedule in app_update_policy.
        run_times: list of times as strings ["02:00", "14:00", ...]
        """
        if not self._use_postgres():
            return True

        from datetime import datetime, timedelta

        run_times = [str(t).strip() for t in (run_times or [])]
        current = self.get_gsm_parser_schedule()

        # Recalculate next_run based on new times
        now_dt = datetime.utcnow()
        next_run = None
        for rt in sorted(run_times):
            try:
                h, m = map(int, rt.split(":"))
                target = now_dt.replace(hour=h, minute=m, second=0, microsecond=0)
                if target > now_dt:
                    next_run = target
                    break
            except Exception:
                pass
        if not next_run and run_times:
            try:
                h, m = map(int, run_times[0].split(":"))
                next_run = (now_dt + timedelta(days=1)).replace(
                    hour=h, minute=m, second=0, microsecond=0
                )
            except Exception:
                pass

        payload = {
            "enabled": bool(enabled),
            "run_times": run_times,
            "last_run": current.get("last_run"),
            "next_run": next_run.isoformat() if next_run else None,
        }

        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.app_update_policy (id, policy, updated_at)
                VALUES (%s, %s::jsonb, %s)
                ON CONFLICT (id) DO UPDATE SET policy=EXCLUDED.policy, updated_at=EXCLUDED.updated_at
                """,
                (
                    "gsm_parser_schedule",
                    psycopg.types.json.Jsonb(payload),
                    self._now_ts(),
                ),
            )
        return True

    def update_gsm_parser_run_timestamp(self, last_run: str | None = None) -> bool:
        """Update last_run and calculate next_run timestamp."""
        if not self._use_postgres():
            return True

        now = self._now_ts()
        current = self.get_gsm_parser_schedule()
        run_times = current.get("run_times", [])

        # Calculate next run time
        from datetime import datetime, timedelta

        try:
            now_dt = datetime.fromisoformat(
                now.isoformat() if hasattr(now, "isoformat") else str(now)
            )
        except Exception:
            now_dt = datetime.utcnow()

        next_run = None
        if run_times:
            for run_time in sorted(run_times):
                try:
                    h, m = map(int, run_time.split(":"))
                    target = now_dt.replace(hour=h, minute=m, second=0, microsecond=0)
                    if target > now_dt:
                        next_run = target
                        break
                except Exception:
                    pass
            if not next_run and run_times:
                try:
                    h, m = map(int, run_times[0].split(":"))
                    next_run = (now_dt + timedelta(days=1)).replace(
                        hour=h, minute=m, second=0, microsecond=0
                    )
                except Exception:
                    pass

        payload = dict(current)
        payload["last_run"] = last_run or now
        payload["next_run"] = next_run.isoformat() if next_run else None

        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                UPDATE public.app_update_policy
                SET policy=%s::jsonb, updated_at=%s
                WHERE id=%s
                """,
                (psycopg.types.json.Jsonb(payload), now, "gsm_parser_schedule"),
            )
        return True

    # ------------------------------------------------------------------ #
    #  GSM Parser Brands Table (global config — not per-company)          #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_parser_brands_table(self):
        """Create gsm_parser_brands if it does not exist yet."""
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_brands (
                    id              character varying NOT NULL,
                    brand           character varying(128) NOT NULL DEFAULT '',
                    gsm_url         text NOT NULL DEFAULT '',
                    last_item       character varying(512) NOT NULL DEFAULT '',
                    ek_url_phones   text NOT NULL DEFAULT '',
                    ek_url_tablets  text NOT NULL DEFAULT '',
                    ek_url_watches  text NOT NULL DEFAULT '',
                    sort_order      integer NOT NULL DEFAULT 0,
                    enabled         boolean NOT NULL DEFAULT true,
                    created_at      timestamp without time zone NOT NULL,
                    updated_at      timestamp without time zone NOT NULL,
                    PRIMARY KEY (id)
                )
                """)
            cur.execute(
                "ALTER TABLE public.gsm_parser_brands "
                "ADD COLUMN IF NOT EXISTS enabled boolean NOT NULL DEFAULT true"
            )
        self._general_pg().commit()

    def get_gsm_parser_brands(self) -> list[dict]:
        """Return all brand rows ordered by sort_order, brand."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_parser_brands_table()
            with self._general_pg().cursor() as cur:
                cur.execute("""
                    SELECT id, brand, gsm_url, last_item,
                           ek_url_phones, ek_url_tablets, ek_url_watches,
                           sort_order, enabled
                    FROM public.gsm_parser_brands
                    ORDER BY sort_order ASC, brand ASC
                    """)
                rows = cur.fetchall() or []
            return [dict(r) for r in rows if isinstance(r, dict)]
        return []

    def set_gsm_brand_enabled(self, brand_id: str, enabled: bool) -> bool:
        """Toggle a single brand's enabled flag without touching other fields."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.gsm_parser_brands SET enabled=%s, updated_at=%s WHERE id=%s",
                    (enabled, self._now_ts(), str(brand_id).strip()),
                )
            self._general_pg().commit()
            return True
        return False

    def save_gsm_parser_brand(self, brand_row: dict) -> str | None:
        """
        Upsert a brand row.  Returns the row id on success, None on failure.
        If brand_row has no 'id' (or empty string), a new row is created.
        """
        if not self._use_postgres():
            return None
        import uuid as _uuid

        with contextlib.suppress(Exception):
            self._ensure_gsm_parser_brands_table()
            row_id = str(brand_row.get("id") or "").strip() or f"gb_{_uuid.uuid4().hex}"
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_brands
                        (id, brand, gsm_url, last_item,
                         ek_url_phones, ek_url_tablets, ek_url_watches,
                         sort_order, enabled, created_at, updated_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON CONFLICT (id) DO UPDATE SET
                        brand           = EXCLUDED.brand,
                        gsm_url         = EXCLUDED.gsm_url,
                        last_item       = EXCLUDED.last_item,
                        ek_url_phones   = EXCLUDED.ek_url_phones,
                        ek_url_tablets  = EXCLUDED.ek_url_tablets,
                        ek_url_watches  = EXCLUDED.ek_url_watches,
                        sort_order      = EXCLUDED.sort_order,
                        enabled         = EXCLUDED.enabled,
                        updated_at      = EXCLUDED.updated_at
                    """,
                    (
                        row_id,
                        str(brand_row.get("brand") or "").strip(),
                        str(brand_row.get("gsm_url") or "").strip(),
                        str(brand_row.get("last_item") or "").strip(),
                        str(brand_row.get("ek_url_phones") or "").strip(),
                        str(brand_row.get("ek_url_tablets") or "").strip(),
                        str(brand_row.get("ek_url_watches") or "").strip(),
                        int(brand_row.get("sort_order") or 0),
                        bool(brand_row.get("enabled", True)),
                        now,
                        now,
                    ),
                )
            self._general_pg().commit()
            return row_id
        return None

    def delete_gsm_parser_brand(self, row_id: str) -> bool:
        """Delete a brand row by id."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM public.gsm_parser_brands WHERE id=%s",
                    (str(row_id).strip(),),
                )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------ #
    #  GSM Parser — Manual E-Katalog links (EK-only brands, e.g. Amazfit/  #
    #  MiBand — superadmin adds items missing from the auto-crawled       #
    #  listing page; gsm_parser_runner merges these into candidate_links  #
    #  on every EK-primary run so they get parsed/refreshed like normal)  #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_manual_ek_links_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_manual_ek_links (
                    id            character varying NOT NULL,
                    brand         character varying(128) NOT NULL DEFAULT '',
                    device_type   character varying(32) NOT NULL DEFAULT '',
                    url           text NOT NULL DEFAULT '',
                    added_by      character varying(128) NOT NULL DEFAULT '',
                    created_at    timestamp without time zone NOT NULL,
                    PRIMARY KEY (id)
                )
                """)
            cur.execute("""
                CREATE UNIQUE INDEX IF NOT EXISTS ux_gsm_manual_ek_links_brand_url
                ON public.gsm_parser_manual_ek_links (LOWER(brand), LOWER(url))
                """)
        self._general_pg().commit()

    def get_gsm_manual_ek_links(
        self, brand: str | None = None, device_type: str | None = None
    ) -> list[dict]:
        """Return manual EK links, optionally scoped to one brand/type
        (as used by the runner) or all of them (as used by the settings UI)."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_manual_ek_links_table()
            conditions = []
            params: list = []
            if brand:
                conditions.append("LOWER(brand)=LOWER(%s)")
                params.append(str(brand).strip())
            if device_type:
                conditions.append("LOWER(device_type)=LOWER(%s)")
                params.append(str(device_type).strip())
            where = (" WHERE " + " AND ".join(conditions)) if conditions else ""
            with self._general_pg().cursor() as cur:
                cur.execute(
                    f"SELECT id, brand, device_type, url, added_by, created_at "
                    f"FROM public.gsm_parser_manual_ek_links{where} "
                    f"ORDER BY created_at DESC",
                    params,
                )
                rows = cur.fetchall() or []
            return [dict(r) for r in rows if isinstance(r, dict)]
        return []

    def add_gsm_manual_ek_link(
        self, brand: str, device_type: str, url: str, added_by: str
    ) -> bool:
        if not self._use_postgres():
            return False
        clean_url = str(url or "").strip()
        clean_brand = str(brand or "").strip()
        if not clean_url or not clean_brand:
            return False
        import uuid as _uuid

        with contextlib.suppress(Exception):
            self._ensure_gsm_manual_ek_links_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_manual_ek_links
                        (id, brand, device_type, url, added_by, created_at)
                    VALUES (%s, %s, %s, %s, %s, %s)
                    ON CONFLICT (LOWER(brand), LOWER(url)) DO NOTHING
                    """,
                    (
                        f"mekl_{_uuid.uuid4().hex}",
                        clean_brand,
                        str(device_type or "").strip(),
                        clean_url,
                        str(added_by or "").strip(),
                        self._now_ts(),
                    ),
                )
            self._general_pg().commit()
            return True
        return False

    def delete_gsm_manual_ek_link(self, link_id: str) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM public.gsm_parser_manual_ek_links WHERE id=%s",
                    (str(link_id).strip(),),
                )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------ #
    #  GSM Parser — Daily History                                         #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_daily_history_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_daily_history (
                    id            character varying NOT NULL,
                    device_id     character varying NOT NULL,
                    record_date   date NOT NULL,
                    price_gsm     numeric,
                    price_ek_min  numeric,
                    price_ek_max  numeric,
                    shops_count   integer,
                    status        character varying(64) NOT NULL DEFAULT '',
                    created_at    timestamp without time zone NOT NULL,
                    PRIMARY KEY (id),
                    UNIQUE (device_id, record_date)
                )
                """)
            cur.execute("""
                CREATE INDEX IF NOT EXISTS idx_gsm_daily_hist_dev_date
                ON public.gsm_parser_daily_history (device_id, record_date DESC)
                """)
        self._general_pg().commit()

    def record_gsm_daily_history(self, device_id: str, fields: dict) -> bool:
        """
        Upsert daily snapshot for a device.
        fields: price_gsm, price_ek_min, price_ek_max, shops_count, status
        """
        if not self._use_postgres():
            return False
        import uuid as _uuid
        from datetime import date

        with contextlib.suppress(Exception):
            self._ensure_gsm_daily_history_table()
            today = date.today()

            def _to_num(v):
                try:
                    return (
                        float(
                            str(v or "")
                            .replace(" ", "")
                            .replace(",", ".")
                            .replace("грн", "")
                            .strip()
                        )
                        if v
                        else None
                    )
                except Exception:
                    return None

            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_daily_history
                        (id, device_id, record_date, price_gsm, price_ek_min,
                         price_ek_max, shops_count, status, created_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                    ON CONFLICT (device_id, record_date) DO UPDATE SET
                        price_gsm    = COALESCE(EXCLUDED.price_gsm,    gsm_parser_daily_history.price_gsm),
                        price_ek_min = COALESCE(EXCLUDED.price_ek_min, gsm_parser_daily_history.price_ek_min),
                        price_ek_max = COALESCE(EXCLUDED.price_ek_max, gsm_parser_daily_history.price_ek_max),
                        shops_count  = COALESCE(EXCLUDED.shops_count,  gsm_parser_daily_history.shops_count),
                        status       = COALESCE(NULLIF(EXCLUDED.status, ''), gsm_parser_daily_history.status)
                    """,
                    (
                        f"dh_{_uuid.uuid4().hex}",
                        str(device_id),
                        today,
                        _to_num(fields.get("price_gsm")),
                        _to_num(fields.get("price_ek_min")),
                        _to_num(fields.get("price_ek_max")),
                        (
                            int(fields["shops_count"])
                            if fields.get("shops_count")
                            else None
                        ),
                        str(fields.get("status") or ""),
                        self._now_ts(),
                    ),
                )
            self._general_pg().commit()
            return True
        return False

    def get_gsm_daily_history(self, device_id: str, days: int = 120) -> list[dict]:
        """Return daily history for a device, newest first."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT record_date, price_gsm, price_ek_min, price_ek_max,
                           shops_count, status
                    FROM public.gsm_parser_daily_history
                    WHERE device_id=%s
                      AND record_date >= CURRENT_DATE - INTERVAL '%s days'
                    ORDER BY record_date ASC
                    """,
                    (str(device_id), int(days)),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_gsm_daily_history_since(self, since_ts) -> dict[str, list[dict]]:
        """Bulk: device_id -> list of daily-history rows created since `since_ts`.
        Used by the app-side local cache's incremental sync — avoids re-pulling
        the whole multi-year history table on every refresh.

        Always bounded to the last 730 days regardless of since_ts: with
        since_ts=None (first-ever sync) this table has no other cutoff at
        all, so every device's full multi-year history got pulled and cached
        client-side in one shot — across thousands of devices that's what
        blew the on-disk cache up to hundreds of MB and made json.load()
        MemoryError on load."""
        if not self._use_postgres():
            return {}
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                if since_ts:
                    cur.execute(
                        """
                        SELECT device_id, record_date, price_gsm, price_ek_min,
                               price_ek_max, shops_count, status, created_at
                        FROM public.gsm_parser_daily_history
                        WHERE created_at > %s
                          AND record_date >= CURRENT_DATE - INTERVAL '730 days'
                        ORDER BY device_id, record_date ASC
                        """,
                        (since_ts,),
                    )
                else:
                    cur.execute("""
                        SELECT device_id, record_date, price_gsm, price_ek_min,
                               price_ek_max, shops_count, status, created_at
                        FROM public.gsm_parser_daily_history
                        WHERE record_date >= CURRENT_DATE - INTERVAL '730 days'
                        ORDER BY device_id, record_date ASC
                        """)
                rows = cur.fetchall() or []
            out: dict[str, list[dict]] = {}
            for r in rows:
                if not isinstance(r, dict):
                    continue
                did = str(r.get("device_id") or "")
                if did:
                    out.setdefault(did, []).append(r)
            return out
        return {}

    # ------------------------------------------------------------------ #
    #  GSM Parser — Parse Trigger                                         #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_trigger_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_trigger (
                    id             character varying NOT NULL DEFAULT 'singleton',
                    last_parse_at  timestamp without time zone,
                    changes_count  integer NOT NULL DEFAULT 0,
                    PRIMARY KEY (id)
                )
                """)
        self._general_pg().commit()

    def get_parser_service_config(self) -> dict:
        """VPS FastAPI parser service config (service URL + API key, NOT the DB DSN)."""
        defaults: dict = {"vps_service_url": "", "vps_api_key": ""}
        if not self._use_postgres():
            return defaults
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT policy FROM public.app_update_policy WHERE id=%s LIMIT 1",
                    ("parser_service",),
                )
                row = cur.fetchone() or {}
            policy = row.get("policy") if isinstance(row.get("policy"), dict) else {}
            out = dict(defaults)
            out.update(policy or {})
            return out
        return defaults

    def set_parser_service_config(self, vps_service_url: str, vps_api_key: str) -> bool:
        """Save VPS FastAPI parser service config."""
        if not self._use_postgres():
            return True
        payload = {
            "vps_service_url": str(vps_service_url or "").strip(),
            "vps_api_key": str(vps_api_key or "").strip(),
        }
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.app_update_policy (id, policy, updated_at)
                VALUES (%s, %s::jsonb, %s)
                ON CONFLICT (id) DO UPDATE
                    SET policy=EXCLUDED.policy, updated_at=EXCLUDED.updated_at
                """,
                ("parser_service", psycopg.types.json.Jsonb(payload), self._now_ts()),
            )
        return True

    def set_gsm_parse_trigger(self, changes_count: int) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            self._ensure_gsm_trigger_table()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_trigger (id, last_parse_at, changes_count)
                    VALUES ('singleton', %s, %s)
                    ON CONFLICT (id) DO UPDATE SET
                        last_parse_at = EXCLUDED.last_parse_at,
                        changes_count = EXCLUDED.changes_count
                    """,
                    (now, int(changes_count)),
                )
            self._general_pg().commit()
            return True
        return False

    def get_gsm_parse_trigger(self) -> dict:
        """Returns {last_parse_at: datetime|None, changes_count: int}."""
        if not self._use_postgres():
            return {"last_parse_at": None, "changes_count": 0}
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT last_parse_at, changes_count FROM public.gsm_parser_trigger WHERE id='singleton' LIMIT 1"
                )
                row = cur.fetchone() or {}
            return {
                "last_parse_at": (row or {}).get("last_parse_at"),
                "changes_count": int((row or {}).get("changes_count") or 0),
            }
        return {"last_parse_at": None, "changes_count": 0}

    # ------------------------------------------------------------------ #
    #  GSM Parser — User Presets                                          #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_presets_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_user_presets (
                    id           character varying NOT NULL,
                    manager_id   character varying NOT NULL,
                    preset_name  character varying(255) NOT NULL,
                    filters      jsonb NOT NULL DEFAULT '{}'::jsonb,
                    created_at   timestamp without time zone NOT NULL,
                    updated_at   timestamp without time zone NOT NULL,
                    PRIMARY KEY (id)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_gsm_presets_manager ON public.gsm_parser_user_presets (manager_id)"
            )
        self._general_pg().commit()

    def get_gsm_user_presets(self, manager_id: str) -> list[dict]:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_presets_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id, preset_name, filters, created_at
                    FROM public.gsm_parser_user_presets
                    WHERE manager_id=%s
                    ORDER BY preset_name ASC
                    """,
                    (str(manager_id),),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def save_gsm_user_preset(
        self, manager_id: str, preset_name: str, filters: dict
    ) -> str | None:
        import uuid as _uuid

        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            self._ensure_gsm_presets_table()
            preset_id = f"prs_{_uuid.uuid4().hex}"
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_user_presets
                        (id, manager_id, preset_name, filters, created_at, updated_at)
                    VALUES (%s, %s, %s, %s::jsonb, %s, %s)
                    """,
                    (
                        preset_id,
                        str(manager_id),
                        str(preset_name or "").strip(),
                        psycopg.types.json.Jsonb(filters or {}),
                        now,
                        now,
                    ),
                )
            self._general_pg().commit()
            return preset_id
        return None

    def delete_gsm_user_preset(self, preset_id: str) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM public.gsm_parser_user_presets WHERE id=%s",
                    (str(preset_id),),
                )
            self._general_pg().commit()
            return True
        return False

    def get_gsm_last_preset_id(self, manager_id: str) -> str:
        """Return last used GSM preset ID for this user (stored in managers.meta)."""
        if not self._use_postgres() or not manager_id:
            return ""
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT meta FROM public.managers WHERE id=%s", (str(manager_id),)
                )
                row = cur.fetchone()
                if row:
                    meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
                    return str(meta.get("gsm_last_preset_id") or "")
        return ""

    def save_gsm_last_preset_id(self, manager_id: str, preset_id: str) -> None:
        """Persist the last used GSM preset ID in managers.meta."""
        if not self._use_postgres() or not manager_id:
            return
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT meta FROM public.managers WHERE id=%s", (str(manager_id),)
                )
                row = cur.fetchone()
                meta = (
                    row.get("meta")
                    if (row and isinstance(row.get("meta"), dict))
                    else {}
                )
            meta["gsm_last_preset_id"] = str(preset_id or "")
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.managers SET meta=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(meta), self._now_ts(), str(manager_id)),
                )
            self._general_pg().commit()

    # ------------------------------------------------------------------ #
    #  GSM Parser — Compatible Devices                                    #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_compatible_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_compatible (
                    id                   character varying NOT NULL,
                    device_id            character varying NOT NULL,
                    compatible_device_id character varying NOT NULL,
                    status               character varying(64) NOT NULL DEFAULT 'compatible',
                    notes                text NOT NULL DEFAULT '',
                    variant_label        character varying(100) NOT NULL DEFAULT '',
                    created_at           timestamp without time zone NOT NULL,
                    updated_at           timestamp without time zone NOT NULL,
                    PRIMARY KEY (id),
                    UNIQUE (device_id, compatible_device_id)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_gsm_compat_device ON public.gsm_parser_compatible (device_id)"
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_gsm_compat_compat ON public.gsm_parser_compatible (compatible_device_id)"
            )
            # Migration: add variant_label column if not present (existing tables)
            cur.execute("""
                ALTER TABLE public.gsm_parser_compatible
                ADD COLUMN IF NOT EXISTS variant_label character varying(100) NOT NULL DEFAULT ''
                """)
            # Migration: add accessory_type so case vs. glass compatibility can differ
            # for the same device pair ('case' | 'glass').
            cur.execute("""
                ALTER TABLE public.gsm_parser_compatible
                ADD COLUMN IF NOT EXISTS accessory_type character varying(16) NOT NULL DEFAULT 'case'
                """)
            cur.execute("""
                ALTER TABLE public.gsm_parser_compatible
                DROP CONSTRAINT IF EXISTS gsm_parser_compatible_device_id_compatible_device_id_key
                """)
            cur.execute(
                "SELECT 1 FROM pg_constraint WHERE conname = 'gsm_parser_compatible_pair_type_key'"
            )
            if not cur.fetchone():
                cur.execute("""
                    ALTER TABLE public.gsm_parser_compatible
                    ADD CONSTRAINT gsm_parser_compatible_pair_type_key
                    UNIQUE (device_id, compatible_device_id, accessory_type)
                    """)
        self._general_pg().commit()

    def get_gsm_compatible_devices(
        self, device_id: str, accessory_type: str = "case"
    ) -> list[dict]:
        """Return confirmed compatible devices from this device's perspective (device_id = queried device)."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_compatible_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT c.id, c.status, c.notes, c.variant_label, c.accessory_type,
                           c.compatible_device_id AS other_device_id,
                           d.model_name, d.brand, d.image_url, d.source_url
                    FROM public.gsm_parser_compatible c
                    JOIN public.gsm_parser_devices d ON d.id = c.compatible_device_id
                    WHERE c.device_id=%s AND c.accessory_type=%s
                    ORDER BY d.brand, d.model_name
                    """,
                    (str(device_id), str(accessory_type)),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_all_gsm_compatible_by_device(
        self, device_ids: list[str] | None = None
    ) -> dict[str, dict[str, list]]:
        """Bulk equivalent of calling get_gsm_compatible_devices(id, 'case') +
        get_gsm_compatible_devices(id, 'glass') for every device — one query
        instead of 2-per-device. Same row shape per entry (other_device_id/
        model_name/brand/status/variant_label), grouped by device_id then
        accessory_type. Used by the app-side cache sync so a 5000-device
        catalog doesn't mean 10000 sequential DB round-trips.

        device_ids: when given, scopes the query to just those devices (the
        cache-sync's changed set) instead of pulling every device's compat
        rows on every sync."""
        if not self._use_postgres():
            return {}
        with contextlib.suppress(Exception):
            self._ensure_gsm_compatible_table()
            with self._general_pg().cursor() as cur:
                if device_ids:
                    cur.execute(
                        """
                        SELECT c.device_id, c.id, c.status, c.notes, c.variant_label, c.accessory_type,
                               c.compatible_device_id AS other_device_id,
                               d.model_name, d.brand, d.image_url, d.source_url
                        FROM public.gsm_parser_compatible c
                        JOIN public.gsm_parser_devices d ON d.id = c.compatible_device_id
                        WHERE c.device_id = ANY(%s)
                        """,
                        (list(device_ids),),
                    )
                else:
                    cur.execute("""
                        SELECT c.device_id, c.id, c.status, c.notes, c.variant_label, c.accessory_type,
                               c.compatible_device_id AS other_device_id,
                               d.model_name, d.brand, d.image_url, d.source_url
                        FROM public.gsm_parser_compatible c
                        JOIN public.gsm_parser_devices d ON d.id = c.compatible_device_id
                        """)
                rows = cur.fetchall() or []
            out: dict[str, dict[str, list]] = {}
            for r in rows:
                if not isinstance(r, dict):
                    continue
                did = str(r.get("device_id") or "")
                if not did:
                    continue
                atype = str(r.get("accessory_type") or "case")
                out.setdefault(did, {"case": [], "glass": []})
                out[did].setdefault(atype, []).append(r)
            return out
        return {}

    def get_gsm_possible_compatible(
        self, brand: str, display_size: str, exclude_id: str
    ) -> list[dict]:
        """Devices of same brand and same display_size (possible compat based on size)."""
        if not self._use_postgres() or not display_size:
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id, model_name, brand, image_url, source_url,
                           specs->>'display_size' AS display_size
                    FROM public.gsm_parser_devices
                    WHERE source='GSM Arena'
                      AND brand=%s
                      AND specs->>'display_size'=%s
                      AND id != %s
                    ORDER BY model_name
                    LIMIT 20
                    """,
                    (str(brand), str(display_size), str(exclude_id)),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_gsm_possible_compatible_expanded(
        self, brand: str, display_size: str, exclude_id: str
    ) -> list[dict]:
        """Like get_gsm_possible_compatible but also includes regional_variants for each device,
        so the UI can expand Xiaomi (and other) devices into per-variant rows when sizes differ.
        """
        if not self._use_postgres() or not display_size:
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_regional_variants_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT d.id, d.model_name, d.brand, d.image_url, d.source_url,
                           d.specs->>'display_size' AS display_size,
                           v.variants AS regional_variants
                    FROM public.gsm_parser_devices d
                    LEFT JOIN public.gsm_parser_regional_variants v ON v.device_id = d.id
                    WHERE d.source='GSM Arena'
                      AND d.brand=%s
                      AND d.specs->>'display_size'=%s
                      AND d.id != %s
                    ORDER BY d.model_name
                    LIMIT 30
                    """,
                    (str(brand), str(display_size), str(exclude_id)),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_gsm_possible_compatible_by_size_expanded(
        self, brand: str, length: str, width: str, exclude_id: str
    ) -> list[dict]:
        """Same shape as get_gsm_possible_compatible_expanded, but matches by
        physical footprint (length + width) instead of screen diagonal —
        used for case-compatibility suggestions, where the diagonal is
        irrelevant but the phone's outline is what determines case fit.
        Diagonal-based matching (get_gsm_possible_compatible_expanded) stays
        the suggestion source for glass."""
        if not self._use_postgres() or not length or not width:
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_regional_variants_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT d.id, d.model_name, d.brand, d.image_url, d.source_url,
                           d.specs->>'display_size' AS display_size,
                           v.variants AS regional_variants
                    FROM public.gsm_parser_devices d
                    LEFT JOIN public.gsm_parser_regional_variants v ON v.device_id = d.id
                    WHERE d.source='GSM Arena'
                      AND d.brand=%s
                      AND d.specs->>'length'=%s
                      AND d.specs->>'width'=%s
                      AND d.id != %s
                    ORDER BY d.model_name
                    LIMIT 30
                    """,
                    (str(brand), str(length), str(width), str(exclude_id)),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_all_gsm_compatible_pairs(self) -> list[dict]:
        """Return all unique confirmed compatibility pairs for global view, per accessory_type.
        Each pair is returned once per accessory_type (device_id < compatible_device_id ordering).
        Prefers the row where variant_label is non-empty when both directions exist."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_compatible_table()
            with self._general_pg().cursor() as cur:
                cur.execute("""
                    SELECT c.device_id, c.compatible_device_id, c.status, c.variant_label, c.accessory_type,
                           d1.model_name AS device_name, d1.brand AS device_brand, d1.device_type AS device_type,
                           d2.model_name AS compat_name,  d2.brand AS compat_brand
                    FROM public.gsm_parser_compatible c
                    JOIN public.gsm_parser_devices d1 ON d1.id = c.device_id
                    JOIN public.gsm_parser_devices d2 ON d2.id = c.compatible_device_id
                    ORDER BY c.accessory_type, c.status, d1.brand, d1.model_name, d2.model_name
                    """)
                rows = [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]

            # Deduplicate: keep one row per canonical pair+accessory_type (prefer rows with variant_label)
            seen: dict = {}
            for row in rows:
                a, b = row.get("device_id", ""), row.get("compatible_device_id", "")
                key = (
                    min(a, b),
                    max(a, b),
                    str(row.get("status") or ""),
                    str(row.get("accessory_type") or "case"),
                )
                if key not in seen or (
                    row.get("variant_label") and not seen[key].get("variant_label")
                ):
                    seen[key] = row
            return list(seen.values())
        return []

    def save_gsm_compatible(
        self,
        device_id: str,
        compat_id: str,
        status: str,
        notes: str = "",
        variant_label: str = "",
        accessory_type: str = "case",
    ) -> bool:
        """Upsert compatibility (bidirectional: also inserts reverse row).

        accessory_type: 'case' | 'glass' — same device pair can have independent
        compatibility per accessory type.
        variant_label: identifies which regional variant of compat_id is compatible with device_id.
        The reverse row always gets variant_label='' (no variant restriction on device_id's side).
        """
        import uuid as _uuid

        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            self._ensure_gsm_compatible_table()
            now = self._now_ts()
            at = str(accessory_type or "case")
            with self._general_pg().cursor() as cur:
                # (device_id → compat_id): store the variant_label of compat_id
                # (compat_id → device_id): device_id has no variant restriction from compat's perspective
                for a, b, vl in [
                    (device_id, compat_id, str(variant_label or "")),
                    (compat_id, device_id, ""),
                ]:
                    cur.execute(
                        """
                        INSERT INTO public.gsm_parser_compatible
                            (id, device_id, compatible_device_id, status, notes, variant_label, accessory_type, created_at, updated_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                        ON CONFLICT (device_id, compatible_device_id, accessory_type) DO UPDATE SET
                            status        = EXCLUDED.status,
                            notes         = EXCLUDED.notes,
                            variant_label = EXCLUDED.variant_label,
                            updated_at    = EXCLUDED.updated_at
                        """,
                        (
                            f"cmp_{_uuid.uuid4().hex}",
                            a,
                            b,
                            str(status),
                            str(notes),
                            vl,
                            at,
                            now,
                            now,
                        ),
                    )
            self._general_pg().commit()
            return True
        return False

    def delete_gsm_compatible(
        self, device_id: str, compat_id: str, accessory_type: str = "case"
    ) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    DELETE FROM public.gsm_parser_compatible
                    WHERE accessory_type=%s
                      AND ((device_id=%s AND compatible_device_id=%s)
                       OR (device_id=%s AND compatible_device_id=%s))
                    """,
                    (str(accessory_type), device_id, compat_id, compat_id, device_id),
                )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------ #
    #  GSM Parser — per-user edit permissions (case/glass compat, Xiaomi) #
    # ------------------------------------------------------------------ #
    def _ensure_manager_gsm_permissions_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.manager_gsm_parser_permissions (
                    manager_id character varying NOT NULL,
                    company_id character varying NOT NULL,
                    permission character varying(32) NOT NULL,
                    created_at timestamp without time zone NOT NULL,
                    PRIMARY KEY (manager_id, permission)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_mgr_gsm_perms_company "
                "ON public.manager_gsm_parser_permissions (company_id)"
            )
        self._general_pg().commit()

    def get_manager_gsm_permissions(self, manager_id: str) -> set[str]:
        """Return the set of GSM-parser edit permissions granted to this manager
        ('compat_case' | 'compat_glass' | 'xiaomi_sizes')."""
        if not self._use_postgres() or not manager_id:
            return set()
        with contextlib.suppress(Exception):
            self._ensure_manager_gsm_permissions_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT permission FROM public.manager_gsm_parser_permissions WHERE manager_id=%s",
                    (str(manager_id),),
                )
                rows = cur.fetchall() or []
            return {
                str((r if isinstance(r, dict) else {}).get("permission") or "")
                for r in rows
            } - {""}
        return set()

    def get_company_managers_gsm_permissions(
        self, company_id: str
    ) -> dict[str, set[str]]:
        """Bulk fetch: manager_id -> set of granted permissions, for one company."""
        if not self._use_postgres() or not company_id:
            return {}
        with contextlib.suppress(Exception):
            self._ensure_manager_gsm_permissions_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT manager_id, permission FROM public.manager_gsm_parser_permissions WHERE company_id=%s",
                    (str(company_id),),
                )
                rows = cur.fetchall() or []
            out: dict[str, set[str]] = {}
            for r in rows:
                rd = r if isinstance(r, dict) else {}
                mid = str(rd.get("manager_id") or "")
                perm = str(rd.get("permission") or "")
                if mid and perm:
                    out.setdefault(mid, set()).add(perm)
            return out
        return {}

    def set_manager_gsm_permission(
        self, manager_id: str, company_id: str, permission: str, granted: bool
    ) -> bool:
        """Grant or revoke one GSM-parser edit permission for a manager."""
        if not self._use_postgres() or not manager_id or not permission:
            return False
        with contextlib.suppress(Exception):
            self._ensure_manager_gsm_permissions_table()
            with self._general_pg().cursor() as cur:
                if granted:
                    cur.execute(
                        """
                        INSERT INTO public.manager_gsm_parser_permissions
                            (manager_id, company_id, permission, created_at)
                        VALUES (%s, %s, %s, %s)
                        ON CONFLICT (manager_id, permission) DO NOTHING
                        """,
                        (
                            str(manager_id),
                            str(company_id or ""),
                            str(permission),
                            self._now_ts(),
                        ),
                    )
                else:
                    cur.execute(
                        "DELETE FROM public.manager_gsm_parser_permissions WHERE manager_id=%s AND permission=%s",
                        (str(manager_id), str(permission)),
                    )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------
    # Per-company / per-user tab (feature) toggles
    # ------------------------------------------------------------------

    def _ensure_feature_toggle_tables(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.company_feature_toggles (
                    company_id character varying NOT NULL,
                    feature_key character varying(64) NOT NULL,
                    enabled boolean NOT NULL,
                    updated_at timestamp without time zone NOT NULL,
                    PRIMARY KEY (company_id, feature_key)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_company_feature_toggles_feature "
                "ON public.company_feature_toggles (feature_key)"
            )
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.manager_feature_overrides (
                    manager_id character varying NOT NULL,
                    company_id character varying NOT NULL,
                    feature_key character varying(64) NOT NULL,
                    enabled boolean NOT NULL,
                    updated_at timestamp without time zone NOT NULL,
                    PRIMARY KEY (manager_id, feature_key)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_manager_feature_overrides_company "
                "ON public.manager_feature_overrides (company_id)"
            )
        self._general_pg().commit()

    def is_company_feature_enabled(self, company_id: str, feature_key: str) -> bool:
        """Fail-open: a feature never explicitly configured is enabled."""
        if not self._use_postgres() or not company_id:
            return True
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT enabled FROM public.company_feature_toggles "
                    "WHERE company_id=%s AND feature_key=%s LIMIT 1",
                    (str(company_id), str(feature_key)),
                )
                row = cur.fetchone()
            if row is None:
                return True
            return bool((row if isinstance(row, dict) else {}).get("enabled", True))
        return True

    def get_company_feature_toggles(self, company_id: str) -> dict[str, bool]:
        """Only explicitly-configured keys are present; absence = enabled."""
        if not self._use_postgres() or not company_id:
            return {}
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT feature_key, enabled FROM public.company_feature_toggles "
                    "WHERE company_id=%s",
                    (str(company_id),),
                )
                rows = cur.fetchall() or []
            return {
                str((r if isinstance(r, dict) else {}).get("feature_key")): bool(
                    (r if isinstance(r, dict) else {}).get("enabled")
                )
                for r in rows
                if (r if isinstance(r, dict) else {}).get("feature_key")
            }
        return {}

    def get_companies_feature_toggles(
        self, company_ids: list[str]
    ) -> dict[str, dict[str, bool]]:
        """Bulk fetch across many companies in one query (general DB, so this
        is a real bulk read — unlike get_companies_gsm_parser_state, which
        queries the single active company's own dedicated DB)."""
        company_ids = [str(x) for x in (company_ids or []) if str(x).strip()]
        out: dict[str, dict[str, bool]] = {cid: {} for cid in company_ids}
        if not self._use_postgres() or not company_ids:
            return out
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT company_id, feature_key, enabled "
                    "FROM public.company_feature_toggles WHERE company_id = ANY(%s)",
                    (company_ids,),
                )
                rows = cur.fetchall() or []
            for r in rows:
                rd = r if isinstance(r, dict) else {}
                cid = str(rd.get("company_id") or "")
                key = str(rd.get("feature_key") or "")
                if cid and key:
                    out.setdefault(cid, {})[key] = bool(rd.get("enabled"))
        return out

    def set_company_feature_enabled(
        self, company_id: str, feature_key: str, enabled: bool
    ) -> bool:
        """Superadmin toggle for one feature on one company. Enforces the
        pack_stock -> packaging dependency: disabling packaging cascades to
        force-disable pack_stock (company + any per-user overrides); enabling
        pack_stock while packaging is disabled is rejected."""
        from feature_flags import transitive_requires

        if not self._use_postgres() or not company_id or not feature_key:
            return False
        if enabled and feature_key != "packaging":
            for req in transitive_requires(feature_key):
                if not self.is_company_feature_enabled(company_id, req):
                    return False
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.company_feature_toggles
                        (company_id, feature_key, enabled, updated_at)
                    VALUES (%s, %s, %s, %s)
                    ON CONFLICT (company_id, feature_key)
                    DO UPDATE SET enabled=EXCLUDED.enabled, updated_at=EXCLUDED.updated_at
                    """,
                    (str(company_id), str(feature_key), bool(enabled), now),
                )
                if feature_key == "packaging" and not enabled:
                    cur.execute(
                        """
                        INSERT INTO public.company_feature_toggles
                            (company_id, feature_key, enabled, updated_at)
                        VALUES (%s, 'pack_stock', FALSE, %s)
                        ON CONFLICT (company_id, feature_key)
                        DO UPDATE SET enabled=FALSE, updated_at=EXCLUDED.updated_at
                        """,
                        (str(company_id), now),
                    )
                    cur.execute(
                        """
                        UPDATE public.manager_feature_overrides
                        SET enabled=FALSE, updated_at=%s
                        WHERE company_id=%s AND feature_key='pack_stock'
                        """,
                        (now, str(company_id)),
                    )
            self._general_pg().commit()
            self._pulse(str(company_id), "extensions")
            return True
        return False

    def get_manager_feature_overrides(self, manager_id: str) -> dict[str, bool]:
        if not self._use_postgres() or not manager_id:
            return {}
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT feature_key, enabled FROM public.manager_feature_overrides "
                    "WHERE manager_id=%s",
                    (str(manager_id),),
                )
                rows = cur.fetchall() or []
            return {
                str((r if isinstance(r, dict) else {}).get("feature_key")): bool(
                    (r if isinstance(r, dict) else {}).get("enabled")
                )
                for r in rows
                if (r if isinstance(r, dict) else {}).get("feature_key")
            }
        return {}

    def get_company_managers_feature_overrides(
        self, company_id: str
    ) -> dict[str, dict[str, bool]]:
        """Bulk fetch: manager_id -> {feature_key: enabled}, for one company."""
        if not self._use_postgres() or not company_id:
            return {}
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT manager_id, feature_key, enabled "
                    "FROM public.manager_feature_overrides WHERE company_id=%s",
                    (str(company_id),),
                )
                rows = cur.fetchall() or []
            out: dict[str, dict[str, bool]] = {}
            for r in rows:
                rd = r if isinstance(r, dict) else {}
                mid = str(rd.get("manager_id") or "")
                key = str(rd.get("feature_key") or "")
                if mid and key:
                    out.setdefault(mid, {})[key] = bool(rd.get("enabled"))
            return out
        return {}

    def set_manager_feature_override(
        self,
        manager_id: str,
        company_id: str,
        feature_key: str,
        enabled: bool | None,
    ) -> bool:
        """enabled=None clears the override (inherit company setting).
        enabled=True/False is a real per-manager override in either direction —
        it can WIDEN a feature the company has turned off for a specific
        manager, not just narrow it (e.g. a company disables "Пакування" for
        everyone, but one manager still needs it). The only remaining
        constraint is internal consistency of the requires-chain: a feature's
        prerequisites must be EFFECTIVELY on for this manager (via the
        company toggle or their own override on that prerequisite) before it
        can be force-enabled — enforced against get_effective_features, not
        the raw company toggle, so a manager can widen a whole dependency
        chain by widening each level."""
        from feature_flags import transitive_requires

        if not self._use_postgres() or not manager_id or not feature_key:
            return False
        if enabled:
            effective = self.get_effective_features(manager_id, company_id)
            for req in transitive_requires(feature_key):
                if not effective.get(req, True):
                    return False
        with contextlib.suppress(Exception):
            self._ensure_feature_toggle_tables()
            with self._general_pg().cursor() as cur:
                if enabled is None:
                    cur.execute(
                        "DELETE FROM public.manager_feature_overrides "
                        "WHERE manager_id=%s AND feature_key=%s",
                        (str(manager_id), str(feature_key)),
                    )
                else:
                    cur.execute(
                        """
                        INSERT INTO public.manager_feature_overrides
                            (manager_id, company_id, feature_key, enabled, updated_at)
                        VALUES (%s, %s, %s, %s, %s)
                        ON CONFLICT (manager_id, feature_key)
                        DO UPDATE SET enabled=EXCLUDED.enabled, updated_at=EXCLUDED.updated_at
                        """,
                        (
                            str(manager_id),
                            str(company_id or ""),
                            str(feature_key),
                            bool(enabled),
                            self._now_ts(),
                        ),
                    )
            self._general_pg().commit()
            self._pulse(str(company_id or ""), "extensions")
            return True
        return False

    def get_effective_features(
        self, manager_id: str, company_id: str
    ) -> dict[str, bool]:
        """Cache-aside — callers like Dashboard._is_feature_enabled() check
        ONE feature key at a time but this resolves the WHOLE dict every
        call; a single sidebar render can check a dozen+ keys, each
        previously paying 2 fresh round trips. Cleared by
        _pulse(company_id, "extensions") the instant a toggle actually
        changes, so "takes effect immediately" still holds."""
        mid_key = str(manager_id or "")
        cid_key = str(company_id or "")
        if not self._use_postgres():
            return self._get_effective_features_uncached(manager_id, company_id)
        return self._cached_list(
            f"eff_features_{cid_key}_{mid_key}",
            False,
            lambda: self._get_effective_features_uncached(manager_id, company_id),
        )

    def _get_effective_features_uncached(
        self, manager_id: str, company_id: str
    ) -> dict[str, bool]:
        """The one function everything else should call. Resolves company
        toggle + per-user override (either direction) + requires-chain.

        A per-manager override REPLACES the company toggle for that manager
        when present — it can turn a feature ON for one manager even though
        the company has it OFF (e.g. company disables an extension for
        everyone, one manager still needs it), not just narrow access. The
        requires-chain is still enforced on the final effective values, so a
        dependent feature (e.g. pack_stock) only ends up effectively on if
        its prerequisite (packaging) is ALSO effectively on for this manager —
        via the company toggle or that manager's own override."""
        from feature_flags import FEATURE_ORDER, TOGGLEABLE_FEATURES

        company_toggles = self.get_company_feature_toggles(company_id)
        user_overrides = (
            self.get_manager_feature_overrides(manager_id) if manager_id else {}
        )
        effective: dict[str, bool] = {}
        for key in FEATURE_ORDER:
            base = (
                user_overrides[key]
                if key in user_overrides
                else company_toggles.get(key, True)
            )
            requires_ok = all(
                effective.get(req, True)
                for req in TOGGLEABLE_FEATURES[key].requires
            )
            effective[key] = bool(base and requires_ok)
        return effective

    def delete_gsm_device(self, device_id: str) -> bool:
        """Delete a device and all related records (history, compat, comments).

        E-Katalog price/shop-count daily history for a MATCHED device is
        recorded under its GSM Arena PARENT's id, not this row's own id
        (see gsm_parser_runner.py's _record_daily_history — it's one row
        per parent device per day, combining price_gsm with price_ek_min/
        max/shops_count). Deleting only WHERE device_id=<this id> misses
        that parent row entirely, leaving the E-Katalog price/shop history
        intact even though the E-Katalog match itself was just removed —
        so the parent's EK-specific columns must be cleared separately
        (its own GSM Arena price history must stay)."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT specs->>'gsm_ref_device_id' AS parent_id "
                    "FROM public.gsm_parser_devices WHERE id=%s",
                    (device_id,),
                )
                _row = cur.fetchone()
                parent_id = str((_row or {}).get("parent_id") or "").strip() or None

                for tbl, col in [
                    ("gsm_parser_change_history", "device_id"),
                    ("gsm_parser_daily_history", "device_id"),
                    ("gsm_parser_compatible", "device_id"),
                    ("gsm_parser_compatible", "compatible_device_id"),
                    ("gsm_parser_comments", "device_id"),
                    ("gsm_parser_regional_variants", "device_id"),
                    ("gsm_parser_device_photos", "device_id"),
                ]:
                    cur.execute(
                        f"DELETE FROM public.{tbl} WHERE {col}=%s", (device_id,)
                    )
                cur.execute(
                    "DELETE FROM public.gsm_parser_devices WHERE id=%s", (device_id,)
                )

                if parent_id:
                    cur.execute(
                        """
                        UPDATE public.gsm_parser_daily_history
                        SET price_ek_min = NULL, price_ek_max = NULL, shops_count = NULL
                        WHERE device_id = %s
                        """,
                        (parent_id,),
                    )
                    cur.execute(
                        """
                        DELETE FROM public.gsm_parser_daily_history
                        WHERE device_id = %s
                          AND price_gsm IS NULL AND price_ek_min IS NULL
                          AND price_ek_max IS NULL AND shops_count IS NULL
                        """,
                        (parent_id,),
                    )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------ #
    #  GSM Parser — Device Photos (stored as bytes — never hot-linked to  #
    #  GSM Arena from the app, to avoid re-triggering anti-bot blocking)  #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_device_photos_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_device_photos (
                    id           character varying NOT NULL,
                    device_id    character varying NOT NULL,
                    role         character varying(16) NOT NULL,
                    sort_order   integer NOT NULL DEFAULT 0,
                    image_data   bytea NOT NULL,
                    content_type character varying(32) NOT NULL DEFAULT 'image/jpeg',
                    created_at   timestamp without time zone NOT NULL,
                    PRIMARY KEY (id)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_gsm_photos_device "
                "ON public.gsm_parser_device_photos (device_id, role, sort_order)"
            )
        self._general_pg().commit()

    def save_gsm_device_photos(
        self,
        device_id: str,
        main_photo: bytes | None,
        gallery_photos: list[bytes] | None = None,
        content_type: str = "image/jpeg",
    ) -> bool:
        """Replace all stored photos for a device (delete+insert in one transaction).
        main_photo: single bytes blob (role='main', sort_order=0) or None to skip.
        gallery_photos: up to 7 bytes blobs (role='gallery', sort_order=0..6)."""
        import uuid as _uuid

        if not self._use_postgres():
            return False
        if main_photo is None and not gallery_photos:
            return False
        with contextlib.suppress(Exception):
            self._ensure_gsm_device_photos_table()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM public.gsm_parser_device_photos WHERE device_id=%s",
                    (str(device_id),),
                )
                if main_photo:
                    cur.execute(
                        """
                        INSERT INTO public.gsm_parser_device_photos
                            (id, device_id, role, sort_order, image_data, content_type, created_at)
                        VALUES (%s, %s, 'main', 0, %s, %s, %s)
                        """,
                        (
                            f"gph_{_uuid.uuid4().hex}",
                            str(device_id),
                            main_photo,
                            str(content_type),
                            now,
                        ),
                    )
                for idx, photo in enumerate((gallery_photos or [])[:7]):
                    if not photo:
                        continue
                    cur.execute(
                        """
                        INSERT INTO public.gsm_parser_device_photos
                            (id, device_id, role, sort_order, image_data, content_type, created_at)
                        VALUES (%s, %s, 'gallery', %s, %s, %s, %s)
                        """,
                        (
                            f"gph_{_uuid.uuid4().hex}",
                            str(device_id),
                            idx,
                            photo,
                            str(content_type),
                            now,
                        ),
                    )
            self._general_pg().commit()
            return True
        return False

    def get_gsm_device_main_photo(self, device_id: str) -> bytes | None:
        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT image_data FROM public.gsm_parser_device_photos "
                    "WHERE device_id=%s AND role='main' LIMIT 1",
                    (str(device_id),),
                )
                row = cur.fetchone()
                if row:
                    data = row.get("image_data") if isinstance(row, dict) else None
                    return bytes(data) if data is not None else None
        return None

    def get_gsm_device_gallery_photos(self, device_id: str) -> list[bytes]:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT image_data FROM public.gsm_parser_device_photos "
                    "WHERE device_id=%s AND role='gallery' ORDER BY sort_order ASC",
                    (str(device_id),),
                )
                rows = cur.fetchall() or []
            return [
                bytes(r.get("image_data"))
                for r in rows
                if isinstance(r, dict) and r.get("image_data") is not None
            ]
        return []

    def get_gsm_device_main_photos_bulk(
        self, device_ids: list[str]
    ) -> dict[str, bytes]:
        """One query for many devices — used to build/refresh the local table-thumbnail cache."""
        ids = [str(i) for i in (device_ids or []) if i]
        if not self._use_postgres() or not ids:
            return {}
        with contextlib.suppress(Exception):
            self._ensure_gsm_device_photos_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT device_id, image_data FROM public.gsm_parser_device_photos "
                    "WHERE role='main' AND device_id = ANY(%s)",
                    (ids,),
                )
                rows = cur.fetchall() or []
            return {
                str(r.get("device_id")): bytes(r.get("image_data"))
                for r in rows
                if isinstance(r, dict)
                and r.get("device_id")
                and r.get("image_data") is not None
            }
        return {}

    def get_gsm_devices_photo_status(self) -> dict:
        """Returns {normalized_source_url: info} for all GSM Arena devices.
        Used by the parser runner to decide full vs lightweight parse per device."""
        if not self._use_postgres():
            return {}
        with contextlib.suppress(Exception):
            self._ensure_gsm_device_photos_table()
            with self._general_pg().cursor() as cur:
                cur.execute("""
                    SELECT
                        d.id AS device_id,
                        d.model_name,
                        LOWER(TRIM(TRAILING '/' FROM TRIM(d.source_url))) AS url_key,
                        COALESCE(d.specs->>'announced', '') AS announced,
                        COALESCE(d.specs->>'released', '')  AS released,
                        (COUNT(CASE WHEN p.role = 'main'    THEN 1 END) > 0)::bool AS has_main,
                        COUNT(CASE WHEN p.role = 'gallery'  THEN 1 END)::int        AS gallery_count
                    FROM public.gsm_parser_devices d
                    LEFT JOIN public.gsm_parser_device_photos p ON p.device_id = d.id
                    WHERE d.source = 'GSM Arena'
                    GROUP BY d.id, d.model_name, d.source_url,
                             d.specs->>'announced', d.specs->>'released'
                """)
                rows = cur.fetchall() or []
            return {
                str(r.get("url_key") or ""): {
                    "device_id": str(r.get("device_id") or ""),
                    "model_name": str(r.get("model_name") or ""),
                    "has_main": bool(r.get("has_main")),
                    "gallery_count": int(r.get("gallery_count") or 0),
                    "announced_empty": not str(r.get("announced") or "").strip(),
                    "released_empty": not str(r.get("released") or "").strip(),
                }
                for r in rows
                if isinstance(r, dict) and r.get("url_key")
            }
        return {}

    def add_gsm_device_gallery_photos(
        self,
        device_id: str,
        photos: list,
        start_sort_order: int,
        content_type: str = "image/jpeg",
    ) -> int:
        """Append gallery photos at positions start_sort_order..6 without touching existing ones.
        Returns the number of photos actually inserted."""
        if not self._use_postgres() or not photos:
            return 0
        added = 0
        with contextlib.suppress(Exception):
            self._ensure_gsm_device_photos_table()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                for idx, photo in enumerate(photos):
                    if not photo:
                        continue
                    sort_order = start_sort_order + idx
                    if sort_order >= 7:
                        break
                    cur.execute(
                        """
                        INSERT INTO public.gsm_parser_device_photos
                            (id, device_id, role, sort_order, image_data, content_type, created_at)
                        SELECT %s, %s, 'gallery', %s, %s, %s, %s
                        WHERE NOT EXISTS (
                            SELECT 1 FROM public.gsm_parser_device_photos
                            WHERE device_id=%s AND role='gallery' AND sort_order=%s
                        )
                        """,
                        (
                            f"gph_{uuid.uuid4().hex}",
                            str(device_id),
                            sort_order,
                            photo,
                            content_type,
                            now,
                            str(device_id),
                            sort_order,
                        ),
                    )
                    added += 1
            self._general_pg().commit()
        return added

    def update_gsm_device_price_and_dates(
        self,
        device_id: str,
        price_raw: str,
        price_uah: str,
        announced: str,
        released: str,
        device_order: int | None = None,
    ) -> dict:
        """Update price fields (always) and date fields (only when currently empty in DB).
        GSM Arena changes are applied directly — no gsm_parser_change_history entry
        is written for them (change tracking is E-Katalog-only: price/shops fields).

        device_order (the device's current position on GSM Arena's brand listing
        page) is refreshed here too when given, even if price/dates didn't change —
        this is the "lightweight" re-scrape path taken on every run after a device's
        first full parse, so without this its order would freeze at whatever
        position it had the one time it WAS fully parsed, drifting out of sync with
        devices scraped/repositioned later and producing an effectively random
        sort order within a brand over time.

        Returns {field_key: (old_value, new_value)} for changed fields."""
        if not self._use_postgres():
            return {}
        changed: dict = {}
        with contextlib.suppress(Exception):
            now = datetime.now()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT specs FROM public.gsm_parser_devices WHERE id=%s LIMIT 1",
                    (str(device_id),),
                )
                row = cur.fetchone()
                if not row:
                    return {}
                specs = row.get("specs") if isinstance(row, dict) else {}
                if not isinstance(specs, dict):
                    specs = {}

                new_specs = dict(specs)

                for key, new_val in (
                    ("price_gsm", price_raw),
                    ("price_uah", price_uah),
                ):
                    old_val = str(specs.get(key) or "").strip()
                    nv = str(new_val or "").strip()
                    if old_val != nv:
                        new_specs[key] = nv
                        changed[key] = (old_val, nv)

                for key, new_val in (("announced", announced), ("released", released)):
                    old_val = str(specs.get(key) or "").strip()
                    nv = str(new_val or "").strip()
                    if not old_val and nv:
                        new_specs[key] = nv
                        changed[key] = (old_val, nv)

                if changed:
                    cur.execute(
                        "UPDATE public.gsm_parser_devices "
                        "SET specs=%s::jsonb, updated_at=%s, device_order=COALESCE(%s, device_order) WHERE id=%s",
                        (
                            json.dumps(new_specs, ensure_ascii=False),
                            now,
                            device_order,
                            str(device_id),
                        ),
                    )
                elif device_order is not None:
                    cur.execute(
                        "UPDATE public.gsm_parser_devices SET device_order=%s "
                        "WHERE id=%s AND device_order IS DISTINCT FROM %s",
                        (device_order, str(device_id), device_order),
                    )
            self._general_pg().commit()
        return changed

    def save_gsm_device_manual_ek_url(self, device_id: str, url: str) -> bool:
        """Superadmin override: pin a specific E-Katalog product page to a
        GSM Arena device so the next parser run fetches it directly instead
        of brute-force searching the brand listing (useful when auto-matching
        picked the wrong page or found nothing at all). Stored on the GSM
        Arena row's specs; empty url clears the override."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT specs FROM public.gsm_parser_devices WHERE id=%s LIMIT 1",
                    (str(device_id),),
                )
                row = cur.fetchone()
                if not row:
                    return False
                specs = row.get("specs") if isinstance(row, dict) else {}
                if not isinstance(specs, dict):
                    specs = {}
                new_specs = dict(specs)
                clean_url = str(url or "").strip()
                if clean_url:
                    new_specs["manual_ek_url"] = clean_url
                else:
                    new_specs.pop("manual_ek_url", None)
                cur.execute(
                    "UPDATE public.gsm_parser_devices "
                    "SET specs=%s::jsonb, updated_at=%s WHERE id=%s",
                    (
                        json.dumps(new_specs, ensure_ascii=False),
                        self._now_ts(),
                        str(device_id),
                    ),
                )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------ #
    #  GSM Parser — SuperAdmin Comments                                   #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_comments_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_comments (
                    id           character varying NOT NULL,
                    device_id    character varying NOT NULL,
                    comment_text text NOT NULL DEFAULT '',
                    rich_data    jsonb NOT NULL DEFAULT '[]'::jsonb,
                    created_at   timestamp without time zone NOT NULL,
                    updated_at   timestamp without time zone NOT NULL,
                    PRIMARY KEY (id),
                    UNIQUE (device_id)
                )
                """)
        self._general_pg().commit()

    def get_all_gsm_device_comments(
        self, device_ids: list[str] | None = None
    ) -> dict[str, dict]:
        """Bulk: device_id -> comment row. Used to build the local cache's
        detail_by_id without one query per device.

        device_ids: when given, scopes to just those devices (the cache-sync's
        changed set) instead of pulling every device's comment on every sync."""
        if not self._use_postgres():
            return {}
        with contextlib.suppress(Exception):
            self._ensure_gsm_comments_table()
            with self._general_pg().cursor() as cur:
                if device_ids:
                    cur.execute(
                        "SELECT id, device_id, comment_text, rich_data, updated_at "
                        "FROM public.gsm_parser_comments WHERE device_id = ANY(%s)",
                        (list(device_ids),),
                    )
                else:
                    cur.execute(
                        "SELECT id, device_id, comment_text, rich_data, updated_at "
                        "FROM public.gsm_parser_comments"
                    )
                rows = cur.fetchall() or []
            return {
                str(r.get("device_id")): r
                for r in rows
                if isinstance(r, dict) and r.get("device_id")
            }
        return {}

    def get_gsm_device_comment(self, device_id: str) -> dict | None:
        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            self._ensure_gsm_comments_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id, comment_text, rich_data, updated_at FROM public.gsm_parser_comments WHERE device_id=%s LIMIT 1",
                    (str(device_id),),
                )
                row = cur.fetchone()
            return dict(row) if isinstance(row, dict) and row else None
        return None

    def save_gsm_device_comment(
        self, device_id: str, comment_text: str, rich_data: list
    ) -> bool:
        import uuid as _uuid

        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            self._ensure_gsm_comments_table()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_comments
                        (id, device_id, comment_text, rich_data, created_at, updated_at)
                    VALUES (%s, %s, %s, %s::jsonb, %s, %s)
                    ON CONFLICT (device_id) DO UPDATE SET
                        comment_text = EXCLUDED.comment_text,
                        rich_data    = EXCLUDED.rich_data,
                        updated_at   = EXCLUDED.updated_at
                    """,
                    (
                        f"cmt_{_uuid.uuid4().hex}",
                        str(device_id),
                        str(comment_text),
                        psycopg.types.json.Jsonb(rich_data or []),
                        now,
                        now,
                    ),
                )
            self._general_pg().commit()
            return True
        return False

    # ------------------------------------------------------------------ #
    #  GSM Parser — Regional Variants (Xiaomi)                            #
    # ------------------------------------------------------------------ #
    def _ensure_gsm_regional_variants_table(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.gsm_parser_regional_variants (
                    device_id   character varying NOT NULL,
                    variants    jsonb NOT NULL DEFAULT '[]'::jsonb,
                    updated_at  timestamp without time zone NOT NULL DEFAULT now(),
                    CONSTRAINT gsm_parser_regional_variants_pkey PRIMARY KEY (device_id)
                )
                """)
        self._general_pg().commit()

    def get_all_gsm_regional_variants(
        self, device_ids: list[str] | None = None
    ) -> dict[str, list]:
        """Bulk: device_id -> variants list. Used to build the local cache's
        detail_by_id without one query per device.

        device_ids: when given, scopes to just those devices (the cache-sync's
        changed set) instead of pulling every device's variants on every sync."""
        if not self._use_postgres():
            return {}
        with contextlib.suppress(Exception):
            self._ensure_gsm_regional_variants_table()
            with self._general_pg().cursor() as cur:
                if device_ids:
                    cur.execute(
                        "SELECT device_id, variants FROM public.gsm_parser_regional_variants "
                        "WHERE device_id = ANY(%s)",
                        (list(device_ids),),
                    )
                else:
                    cur.execute(
                        "SELECT device_id, variants FROM public.gsm_parser_regional_variants"
                    )
                rows = cur.fetchall() or []
            out: dict[str, list] = {}
            for r in rows:
                if not isinstance(r, dict):
                    continue
                did = str(r.get("device_id") or "")
                v = r.get("variants")
                if did:
                    out[did] = list(v) if isinstance(v, list) else []
            return out
        return {}

    def get_gsm_regional_variants(self, device_id: str) -> list:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_gsm_regional_variants_table()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT variants FROM public.gsm_parser_regional_variants WHERE device_id=%s LIMIT 1",
                    (str(device_id),),
                )
                row = cur.fetchone()
                if row:
                    v = row.get("variants") if isinstance(row, dict) else None
                    return list(v) if isinstance(v, list) else []
        return []

    def save_gsm_regional_variants(self, device_id: str, variants: list) -> bool:
        if not self._use_postgres():
            return False
        # Hard block on China regardless of caller (Xiaomi GitHub sync, a
        # manual SA edit, or a stale process still running old sync code) —
        # its sizes are unreliable to source and explicitly not wanted, so
        # this is enforced here at the DB write itself rather than trusted
        # to whichever code path happens to be calling in.
        variants = [
            v for v in (variants or [])
            if not (isinstance(v, dict) and str(v.get("region") or "").strip() == "China")
        ]
        with contextlib.suppress(Exception):
            self._ensure_gsm_regional_variants_table()
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.gsm_parser_regional_variants (device_id, variants, updated_at)
                    VALUES (%s, %s::jsonb, %s)
                    ON CONFLICT (device_id) DO UPDATE SET
                        variants   = EXCLUDED.variants,
                        updated_at = EXCLUDED.updated_at
                    """,
                    (str(device_id), psycopg.types.json.Jsonb(variants or []), now),
                )
                # get_gsm_merged_results_changed_since() only looks at
                # gsm_parser_devices.updated_at — without also touching it
                # here, a variants-only edit (manual SA edit or the Xiaomi
                # region GitHub sync) is invisible to every running app's
                # incremental cache sync forever, since that query never
                # joins this table.
                cur.execute(
                    "UPDATE public.gsm_parser_devices SET updated_at=%s WHERE id=%s",
                    (now, str(device_id)),
                )
            self._general_pg().commit()
            return True
        return False

    def get_all_gsm_xiaomi_devices(self) -> list[dict]:
        """Return all Xiaomi devices with id, model_name, network_label (from
        specs) plus enough extra columns (device_type, image_url, network
        fields) for a "regions appeared" Telegram card — see
        xiaomi_regions_sync.py."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute("""
                    SELECT id,
                           model_name,
                           source,
                           device_type,
                           source_url,
                           image_url,
                           COALESCE(specs->>'network_label', '') AS network_label,
                           COALESCE(specs->>'network_full', '') AS network_full,
                           COALESCE(specs->>'target_net', '') AS target_net
                    FROM public.gsm_parser_devices
                    WHERE brand = 'Xiaomi'
                    ORDER BY model_name
                    """)
                rows = cur.fetchall()
                return list(rows) if rows else []
        return []

    def get_xiaomi_devices_missing_dimensions(self) -> tuple[int, list[dict]]:
        """Return (count, rows) for Xiaomi devices that have at least one variant
        with region+models filled but missing size (L/W) or diagonal."""
        if not self._use_postgres():
            return 0, []
        try:
            self._ensure_gsm_regional_variants_table()
            with self._general_pg().cursor() as cur:
                cur.execute("""
                    SELECT d.id, d.model_name, d.source_url, v.variants
                    FROM public.gsm_parser_devices d
                    JOIN public.gsm_parser_regional_variants v ON d.id = v.device_id
                    WHERE d.brand = 'Xiaomi'
                    ORDER BY d.model_name
                    """)
                rows = cur.fetchall()

            result = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                variants = row.get("variants")
                if not isinstance(variants, list):
                    continue
                has_incomplete = any(
                    bool(str(v.get("region") or "").strip())
                    and bool(str(v.get("models") or "").strip())
                    and (
                        not (
                            str(v.get("L") or "").strip()
                            and str(v.get("W") or "").strip()
                        )
                        or not str(v.get("diagonal") or "").strip()
                    )
                    for v in variants
                    if isinstance(v, dict)
                )
                if has_incomplete:
                    result.append(
                        {
                            "id": row.get("id"),
                            "model_name": row.get("model_name"),
                            "source_url": row.get("source_url"),
                            "variants": variants,
                        }
                    )
            return len(result), result
        except Exception:
            return 0, []

    def get_gsm_devices_list(
        self,
        search: str = "",
        brands: list | None = None,
        device_types: list | None = None,
        years: list | None = None,
        statuses: list | None = None,
        source: str = "",
        sort_col: str = "brand",
        sort_asc: bool = True,
        limit: int = 2000,
    ) -> list[dict]:
        """Flexible query for results view (with all filters)."""
        if not self._use_postgres():
            return []
        allowed = {"brand", "device_type", "model_name", "source", "last_seen_at"}
        col = sort_col if sort_col in allowed else "brand"
        direction = "ASC" if sort_asc else "DESC"

        conditions: list[str] = []
        params: list = []

        if search:
            conditions.append("(LOWER(brand) LIKE %s OR LOWER(model_name) LIKE %s)")
            like = f"%{search.lower()}%"
            params += [like, like]
        if brands:
            conditions.append("brand = ANY(%s)")
            params.append(list(brands))
        if device_types:
            conditions.append("device_type = ANY(%s)")
            params.append(list(device_types))
        if source:
            conditions.append("source=%s")
            params.append(str(source))
        if years:
            year_conds = " OR ".join(["specs->>'year'=%s"] * len(years))
            conditions.append(f"({year_conds})")
            params += [str(y) for y in years]
        if statuses:
            stat_conds = " OR ".join(["specs->>'status'=%s"] * len(statuses))
            conditions.append(f"({stat_conds})")
            params += [str(s) for s in statuses]

        where = ("WHERE " + " AND ".join(conditions)) if conditions else ""
        query = (
            f"SELECT id, source, brand, device_type, model_name, image_url, source_url, "
            f"specs, last_seen_at "
            f"FROM public.gsm_parser_devices {where} "
            f"ORDER BY {col} {direction} "
            f"LIMIT %s"
        )
        params.append(int(limit))

        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(query, params)
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_gsm_device_by_id(self, device_id: str) -> dict | None:
        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT * FROM public.gsm_parser_devices WHERE id=%s LIMIT 1",
                    (str(device_id),),
                )
                row = cur.fetchone()
            return dict(row) if isinstance(row, dict) else None
        return None

    def find_standalone_gsm_devices(
        self, source: str, query: str, limit: int = 20
    ) -> list[dict]:
        """SuperAdmin manual-merge picker: devices from `source` ('GSM Arena'
        or 'E-Katalog') matching `query` by name, searched across every
        brand — including ones that already have a counterpart on the
        other side (flagged via "matched"), not just unmatched ones. A
        superadmin needs to find an ALREADY-wrongly-matched record too, to
        correct it (see merge_gsm_ek_devices, which allows re-pointing an
        existing link)."""
        if not self._use_postgres():
            return []
        q = f"%{(query or '').strip()}%"
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                if source == "GSM Arena":
                    cur.execute(
                        """
                        SELECT g.id, g.brand, g.device_type, g.model_name, g.image_url,
                               EXISTS (
                                 SELECT 1 FROM public.gsm_parser_devices e
                                 WHERE e.source='E-Katalog'
                                   AND (e.specs->>'gsm_ref_device_id') = g.id
                               ) AS matched
                        FROM public.gsm_parser_devices g
                        WHERE g.source='GSM Arena'
                          AND g.model_name ILIKE %s
                        ORDER BY matched, g.model_name
                        LIMIT %s
                        """,
                        (q, limit),
                    )
                else:
                    cur.execute(
                        """
                        SELECT id, brand, device_type, model_name, image_url,
                               (specs->>'gsm_ref_device_id' IS NOT NULL
                                AND specs->>'gsm_ref_device_id' != '') AS matched
                        FROM public.gsm_parser_devices
                        WHERE source='E-Katalog'
                          AND model_name ILIKE %s
                        ORDER BY matched, model_name
                        LIMIT %s
                        """,
                        (q, limit),
                    )
                return [dict(r) for r in (cur.fetchall() or [])]
        return []

    def merge_gsm_ek_devices(self, gsm_device_id: str, ek_device_id: str) -> tuple[bool, str]:
        """SuperAdmin manual override: link a GSM Arena row and an
        E-Katalog row that are actually the same real device but
        auto-matching (see _ek_name_matches in gsm_parser_runner.py) missed
        it or matched the wrong pair. Uses the exact same
        specs["gsm_ref_device_id"]/["gsm_ref_model_key"] link every other
        GSM<->EK pairing relies on (get_gsm_merged_results, the results
        table, comparisons - all of it), so a manual merge behaves
        identically to an automatic one from that point on.

        Either side may already be linked to something else - this always
        WINS and overwrites: the EK row's link is re-pointed to this GSM
        device, and if that GSM device was previously linked from a
        DIFFERENT EK row, that old EK row's link is cleared (reverted to
        standalone) so a GSM device is never claimed by two EK rows at
        once, which get_gsm_merged_results would otherwise show as two
        near-duplicate result rows for the same device."""
        if not self._use_postgres():
            return False, "PostgreSQL вимкнено"
        gsm_device_id = str(gsm_device_id or "").strip()
        ek_device_id = str(ek_device_id or "").strip()
        if not gsm_device_id or not ek_device_id:
            return False, "Не вибрано обидва записи"
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id, source, model_key FROM public.gsm_parser_devices WHERE id=%s",
                    (gsm_device_id,),
                )
                gsm_row = cur.fetchone()
                if not gsm_row or str(gsm_row.get("source") or "") != "GSM Arena":
                    return False, "Запис GSM Arena не знайдено"
                cur.execute(
                    "SELECT id, source, specs FROM public.gsm_parser_devices WHERE id=%s",
                    (ek_device_id,),
                )
                ek_row = cur.fetchone()
                if not ek_row or str(ek_row.get("source") or "") != "E-Katalog":
                    return False, "Запис Єкаталог не знайдено"

                # Any OTHER EK row currently claiming this GSM device loses
                # that claim — a GSM device can only be linked from one EK
                # row at a time (see docstring).
                cur.execute(
                    """
                    SELECT id, specs FROM public.gsm_parser_devices
                    WHERE source='E-Katalog' AND (specs->>'gsm_ref_device_id') = %s
                      AND id != %s
                    """,
                    (gsm_device_id, ek_device_id),
                )
                for other in cur.fetchall() or []:
                    other_specs = dict(other.get("specs") or {})
                    other_specs.pop("gsm_ref_device_id", None)
                    other_specs.pop("gsm_ref_model_key", None)
                    cur.execute(
                        "UPDATE public.gsm_parser_devices SET specs=%s::jsonb, updated_at=%s WHERE id=%s",
                        (json.dumps(other_specs, ensure_ascii=False), datetime.now(), other.get("id")),
                    )

                specs = ek_row.get("specs") if isinstance(ek_row.get("specs"), dict) else {}
                specs = dict(specs)
                specs["gsm_ref_device_id"] = gsm_device_id
                specs["gsm_ref_model_key"] = str(gsm_row.get("model_key") or "")
                cur.execute(
                    "UPDATE public.gsm_parser_devices SET specs=%s::jsonb, updated_at=%s WHERE id=%s",
                    (json.dumps(specs, ensure_ascii=False), datetime.now(), ek_device_id),
                )
            return True, "Об'єднано"
        except Exception as e:
            logger.exception("merge_gsm_ek_devices failed")
            return False, f"Помилка: {e}"

    def get_gsm_distinct_brands(self) -> list[str]:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT DISTINCT brand FROM public.gsm_parser_devices WHERE source='GSM Arena' ORDER BY brand"
                )
                return [
                    str(r.get("brand") or "")
                    for r in (cur.fetchall() or [])
                    if r.get("brand")
                ]
        return []

    def get_gsm_merged_results(
        self,
        search: str = "",
        brands: list | None = None,
        device_types: list | None = None,
        years: list | None = None,
        statuses: list | None = None,
        sort_col: str = "gsm_order",
        sort_asc: bool = True,
        limit: int = 2000,
    ) -> list[dict]:
        """LEFT JOIN of GSM Arena devices with their EK counterparts, UNIONed
        with standalone E-Katalog devices that have no GSM Arena match at
        all (brands scraped E-Katalog-only, e.g. Amazfit/MiBand — see
        gsm_parser_runner's "Бренд без GSM Arena" path). Without the UNION
        branch those devices exist in the DB but never appeared in this
        table at all, since the base query only ever started from GSM
        Arena rows.

        Column names in filtering/sorting below refer to the OUTER
        (post-UNION) result set — both branches produce the same column
        shape so they can be filtered/sorted uniformly after combining.
        """
        if not self._use_postgres():
            return []

        # "gsm_order" = native GSM Arena order: brand sort_order, then device position.
        # Other sort_col values let the user sort by that column via header clicks.
        col_map = {
            "brand": "brand",
            "device_type": "device_type",
            "gsm_name": "gsm_name",
            "last_seen_at": "last_seen_at",
            "year": "gsm_specs->>'year'",
        }
        direction = "ASC" if sort_asc else "DESC"

        if sort_col == "gsm_order" or sort_col not in col_map:
            # Within a brand, order by real date instead of GSM Arena's native
            # scrape position (device_order) — the latter only reflects
            # whatever position a device happened to occupy the one time it
            # was fully parsed and drifts out of sync with reality (see
            # update_gsm_device_price_and_dates's device_order refresh, which
            # helps but only self-heals gradually as devices get rescraped).
            # A date parsed straight out of already-stored specs is correct
            # immediately for every existing row, no rescrape needed.
            #
            # gsm_specs->>'released' / 'announced' are either "DD.MM.YYYY"
            # (parse_gsm_date in GSM_Parser/main.py) or free text such as
            # "Coming soon" when GSM Arena has no date yet.
            #
            # Tiers (0 = top of the brand group):
            #   0 — GSM Arena device not yet released ("Coming soon" et al.)
            #   1 — GSM Arena device with a real release date
            #   2 — GSM Arena device with only an announce date
            #   3 — standalone E-Katalog-only device (Amazfit/MiBand etc.),
            #       ordered by "Дата додавання" year/month
            #   4 — nothing parseable at all
            _rel_is_date = "gsm_specs->>'released' ~ '^\\d{2}\\.\\d{2}\\.\\d{4}$'"
            _ann_is_date = "gsm_specs->>'announced' ~ '^\\d{2}\\.\\d{2}\\.\\d{4}$'"
            order_clause = (
                "COALESCE(brand_sort_order, 9999) ASC, "
                "CASE "
                f"  WHEN gsm_name IS NOT NULL AND gsm_specs->>'released' ILIKE '%%coming%%' THEN 0 "
                f"  WHEN gsm_name IS NOT NULL AND {_rel_is_date} THEN 1 "
                f"  WHEN gsm_name IS NOT NULL AND {_ann_is_date} THEN 2 "
                "  WHEN gsm_name IS NULL THEN 3 "
                "  ELSE 4 "
                "END ASC, "
                f"CASE WHEN {_rel_is_date} THEN to_date(gsm_specs->>'released', 'DD.MM.YYYY') END DESC, "
                f"CASE WHEN {_ann_is_date} THEN to_date(gsm_specs->>'announced', 'DD.MM.YYYY') END DESC, "
                "COALESCE("
                "  NULLIF(ek_specs->>'date_added_year', '')::int, "
                "  NULLIF(substring(ek_specs->>'date_added' from '\\d{4}'), '')::int, "
                "  0"
                ") DESC, "
                "COALESCE(NULLIF(ek_specs->>'date_added_month', '')::int, 0) DESC, "
                "brand ASC"
            )
        else:
            order_clause = f"{col_map[sort_col]} {direction}"

        conditions: list[str] = []
        params: list = []

        if search:
            conditions.append(
                "(LOWER(brand) LIKE %s OR LOWER(COALESCE(gsm_name, ek_name, '')) LIKE %s)"
            )
            like = f"%{search.lower()}%"
            params += [like, like]
        if brands:
            conditions.append("brand = ANY(%s)")
            params.append(list(brands))
        if device_types:
            conditions.append("device_type = ANY(%s)")
            params.append(list(device_types))
        if years:
            ph = ", ".join(["%s"] * len(years))
            conditions.append(f"gsm_specs->>'year' IN ({ph})")
            params += [str(y) for y in years]
        if statuses:
            ph = ", ".join(["%s"] * len(statuses))
            conditions.append(f"ek_specs->>'status' IN ({ph})")
            params += [str(s) for s in statuses]

        where_clause = (" WHERE " + " AND ".join(conditions)) if conditions else ""
        params.append(int(limit))

        query = f"""
            SELECT * FROM (
                SELECT
                    g.id, g.brand, g.device_type,
                    g.model_name AS gsm_name,
                    g.image_url,
                    g.source_url AS gsm_url,
                    g.specs AS gsm_specs,
                    g.last_seen_at,
                    b.sort_order AS brand_sort_order,
                    g.device_order,
                    e.id AS ek_id,
                    e.model_name AS ek_name,
                    e.source_url AS ek_url,
                    e.specs AS ek_specs
                FROM public.gsm_parser_devices g
                LEFT JOIN public.gsm_parser_brands b
                    ON LOWER(b.brand) = LOWER(g.brand)
                LEFT JOIN public.gsm_parser_devices e
                    ON e.source = 'E-Katalog'
                    AND (e.specs->>'gsm_ref_device_id') = g.id
                WHERE g.source = 'GSM Arena'

                UNION ALL

                SELECT
                    e.id, e.brand, e.device_type,
                    NULL AS gsm_name,
                    e.image_url,
                    NULL AS gsm_url,
                    NULL AS gsm_specs,
                    e.last_seen_at,
                    b.sort_order AS brand_sort_order,
                    NULL AS device_order,
                    e.id AS ek_id,
                    e.model_name AS ek_name,
                    e.source_url AS ek_url,
                    e.specs AS ek_specs
                FROM public.gsm_parser_devices e
                LEFT JOIN public.gsm_parser_brands b
                    ON LOWER(b.brand) = LOWER(e.brand)
                WHERE e.source = 'E-Katalog'
                    AND (
                        e.specs->>'gsm_ref_device_id' IS NULL
                        OR NOT EXISTS (
                            SELECT 1 FROM public.gsm_parser_devices g2
                            WHERE g2.source = 'GSM Arena'
                                AND g2.id = (e.specs->>'gsm_ref_device_id')
                        )
                    )
            ) combined
            {where_clause}
            ORDER BY {order_clause}
            LIMIT %s
        """
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(query, params)
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def get_gsm_merged_device_by_id(self, device_id: str) -> dict | None:
        """Single-device version of get_gsm_merged_results's LEFT JOIN shape
        (gsm_specs/ek_id/ek_name/ek_url/ek_specs all present) — used wherever
        a device card is opened from outside the results table (e.g. the
        sidebar "З'явились в продажу"/"Нові..." panels), so it shows full
        GSM Arena + E-Katalog data instead of get_gsm_device_by_id's raw,
        un-joined single-table row."""
        if not self._use_postgres():
            return None
        did = str(device_id or "").strip()
        if not did:
            return None
        query = """
            SELECT * FROM (
                SELECT
                    g.id, g.brand, g.device_type,
                    g.model_name AS gsm_name,
                    g.image_url,
                    g.source_url AS gsm_url,
                    g.specs AS gsm_specs,
                    g.last_seen_at,
                    e.id AS ek_id,
                    e.model_name AS ek_name,
                    e.source_url AS ek_url,
                    e.specs AS ek_specs
                FROM public.gsm_parser_devices g
                LEFT JOIN public.gsm_parser_devices e
                    ON e.source = 'E-Katalog'
                    AND (e.specs->>'gsm_ref_device_id') = g.id
                WHERE g.source = 'GSM Arena' AND g.id = %s

                UNION ALL

                SELECT
                    e.id, e.brand, e.device_type,
                    NULL AS gsm_name,
                    e.image_url,
                    NULL AS gsm_url,
                    NULL AS gsm_specs,
                    e.last_seen_at,
                    e.id AS ek_id,
                    e.model_name AS ek_name,
                    e.source_url AS ek_url,
                    e.specs AS ek_specs
                FROM public.gsm_parser_devices e
                WHERE e.source = 'E-Katalog' AND e.id = %s
            ) combined
            LIMIT 1
        """
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(query, (did, did))
                row = cur.fetchone()
            return dict(row) if isinstance(row, dict) else None
        return None

    def get_gsm_device_ids(self) -> set:
        """Lightweight: ids of every device that appears as its own row in
        get_gsm_merged_results — used by the app-side cache to detect
        devices that were deleted (hard-delete, no soft-delete flag, so an
        id-diff is the only signal).

        That's all GSM Arena rows PLUS standalone E-Katalog rows with no
        GSM Arena match (brands scraped E-Katalog-only, e.g. Amazfit/MiBand
        — see gsm_parser_runner's "Бренд без GSM Arena" path). Without the
        second branch, those devices' ids never appear here, so the cache's
        deletion-diff filter treated them as deleted on every single sync
        and wiped them from the UI even though they're untouched in the DB."""
        if not self._use_postgres():
            return set()
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id FROM public.gsm_parser_devices WHERE source='GSM Arena'
                    UNION
                    SELECT e.id FROM public.gsm_parser_devices e
                    WHERE e.source = 'E-Katalog'
                      AND (
                          e.specs->>'gsm_ref_device_id' IS NULL
                          OR NOT EXISTS (
                              SELECT 1 FROM public.gsm_parser_devices g2
                              WHERE g2.source = 'GSM Arena'
                                  AND g2.id = (e.specs->>'gsm_ref_device_id')
                          )
                      )
                    """
                )
                rows = cur.fetchall() or []
            return {
                str(r.get("id")) for r in rows if isinstance(r, dict) and r.get("id")
            }
        return set()

    def get_gsm_merged_results_changed_since(
        self, since_ts, limit: int = 5000
    ) -> list[dict]:
        """Same row shape as get_gsm_merged_results, but only rows whose GSM
        Arena or E-Katalog side changed after `since_ts` — for the app-side
        cache's incremental sync (only pull what's different, not everything).

        Also UNIONs in changed/new standalone E-Katalog devices (brands
        scraped E-Katalog-only, e.g. Amazfit/MiBand — see
        get_gsm_merged_results for why this branch exists) — without it,
        those devices never made it into the incremental cache update even
        after get_gsm_merged_results itself was fixed to include them,
        since a regular "Синхронізація" always goes through this
        changed-since path, not the full-refresh one."""
        if not self._use_postgres():
            return []
        if not since_ts:
            return self.get_gsm_merged_results(limit=limit)
        query = """
            SELECT * FROM (
                SELECT
                    g.id, g.brand, g.device_type,
                    g.model_name AS gsm_name,
                    g.image_url,
                    g.source_url AS gsm_url,
                    g.specs AS gsm_specs,
                    g.last_seen_at,
                    e.id AS ek_id,
                    e.model_name AS ek_name,
                    e.source_url AS ek_url,
                    e.specs AS ek_specs
                FROM public.gsm_parser_devices g
                LEFT JOIN public.gsm_parser_devices e
                    ON e.source = 'E-Katalog'
                    AND (e.specs->>'gsm_ref_device_id') = g.id
                WHERE g.source = 'GSM Arena'
                  AND (g.updated_at > %s OR e.updated_at > %s)

                UNION ALL

                SELECT
                    e.id, e.brand, e.device_type,
                    NULL AS gsm_name,
                    e.image_url,
                    NULL AS gsm_url,
                    NULL AS gsm_specs,
                    e.last_seen_at,
                    e.id AS ek_id,
                    e.model_name AS ek_name,
                    e.source_url AS ek_url,
                    e.specs AS ek_specs
                FROM public.gsm_parser_devices e
                WHERE e.source = 'E-Katalog'
                  AND e.updated_at > %s
                  AND (
                      e.specs->>'gsm_ref_device_id' IS NULL
                      OR NOT EXISTS (
                          SELECT 1 FROM public.gsm_parser_devices g2
                          WHERE g2.source = 'GSM Arena'
                              AND g2.id = (e.specs->>'gsm_ref_device_id')
                      )
                  )
            ) combined
            ORDER BY brand, gsm_name
            LIMIT %s
        """
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(query, (since_ts, since_ts, since_ts, int(limit)))
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def clear_gsm_parser_all_data(self) -> dict:
        """
        Delete ALL GSM parser data: devices, change history, daily history, trigger.
        Returns {ok: bool, devices: int, changes: int, history: int}.
        """
        if not self._use_postgres():
            return {"ok": False}
        counts = {"devices": 0, "changes": 0, "history": 0}
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute("SELECT COUNT(*) AS c FROM public.gsm_parser_devices")
                counts["devices"] = int((cur.fetchone() or {}).get("c") or 0)
                cur.execute(
                    "SELECT COUNT(*) AS c FROM public.gsm_parser_change_history"
                )
                counts["changes"] = int((cur.fetchone() or {}).get("c") or 0)
                try:
                    cur.execute(
                        "SELECT COUNT(*) AS c FROM public.gsm_parser_daily_history"
                    )
                    counts["history"] = int((cur.fetchone() or {}).get("c") or 0)
                except Exception:
                    pass

                cur.execute("DELETE FROM public.gsm_parser_devices")
                cur.execute("DELETE FROM public.gsm_parser_change_history")
                with contextlib.suppress(Exception):
                    cur.execute("DELETE FROM public.gsm_parser_daily_history")
                with contextlib.suppress(Exception):
                    cur.execute("DELETE FROM public.gsm_parser_trigger")
            self._general_pg().commit()
            counts["ok"] = True
            return counts
        return {"ok": False}

    def clear_gsm_parser_ek_data(self) -> dict:
        """Delete only E-Katalog rows (source='E-Katalog') without touching GSM Arena data.

        E-Katalog daily price/shop history for a MATCHED device lives under
        its GSM Arena PARENT's id (see delete_gsm_device docstring) — so on
        top of deleting the E-Katalog rows themselves, the EK-specific
        columns of their parents' daily_history rows must be cleared too,
        or the price/shop chart keeps showing stale E-Katalog data forever."""
        if not self._use_postgres():
            return {"ok": False}
        counts = {"devices": 0, "changes": 0}
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id, specs->>'gsm_ref_device_id' AS parent_id "
                    "FROM public.gsm_parser_devices WHERE source='E-Katalog'"
                )
                ek_rows = cur.fetchall() or []
                counts["devices"] = len(ek_rows)
                history_ids = sorted({
                    str(r.get(key) or "").strip()
                    for r in ek_rows if isinstance(r, dict)
                    for key in ("id", "parent_id")
                    if str(r.get(key) or "").strip()
                })
                cur.execute(
                    "SELECT COUNT(*) AS c FROM public.gsm_parser_change_history"
                    " WHERE source='E-Katalog'"
                )
                counts["changes"] = int((cur.fetchone() or {}).get("c") or 0)
                cur.execute(
                    "DELETE FROM public.gsm_parser_devices WHERE source='E-Katalog'"
                )
                cur.execute(
                    "DELETE FROM public.gsm_parser_change_history WHERE source='E-Katalog'"
                )
                if history_ids:
                    id_ph = ",".join(["%s"] * len(history_ids))
                    cur.execute(
                        f"""
                        UPDATE public.gsm_parser_daily_history
                        SET price_ek_min = NULL, price_ek_max = NULL, shops_count = NULL
                        WHERE device_id IN ({id_ph})
                        """,
                        history_ids,
                    )
                    cur.execute(
                        f"""
                        DELETE FROM public.gsm_parser_daily_history
                        WHERE device_id IN ({id_ph})
                          AND price_gsm IS NULL AND price_ek_min IS NULL
                          AND price_ek_max IS NULL AND shops_count IS NULL
                        """,
                        history_ids,
                    )
            self._general_pg().commit()
            counts["ok"] = True
            return counts
        return {"ok": False}

    def clear_gsm_parser_brands_data(self, brands: list[str]) -> dict:
        """Delete all GSM+EK data for specific brands."""
        if not self._use_postgres() or not brands:
            return {"ok": False}
        counts = {"devices": 0, "changes": 0, "history": 0}
        with contextlib.suppress(Exception):
            ph = ",".join(["%s"] * len(brands))
            with self._general_pg().cursor() as cur:
                cur.execute(
                    f"SELECT COUNT(*) AS c FROM public.gsm_parser_devices WHERE brand IN ({ph})",
                    brands,
                )
                counts["devices"] = int((cur.fetchone() or {}).get("c") or 0)
                cur.execute(
                    f"SELECT id FROM public.gsm_parser_devices WHERE brand IN ({ph})",
                    brands,
                )
                ids = [
                    str(r.get("id") or "")
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and r.get("id")
                ]
                if ids:
                    id_ph = ",".join(["%s"] * len(ids))
                    try:
                        cur.execute(
                            f"SELECT COUNT(*) AS c FROM public.gsm_parser_change_history WHERE device_id IN ({id_ph})",
                            ids,
                        )
                        counts["changes"] = int((cur.fetchone() or {}).get("c") or 0)
                    except Exception:
                        pass
                    try:
                        cur.execute(
                            f"SELECT COUNT(*) AS c FROM public.gsm_parser_daily_history WHERE device_id IN ({id_ph})",
                            ids,
                        )
                        counts["history"] = int((cur.fetchone() or {}).get("c") or 0)
                    except Exception:
                        pass
                    with contextlib.suppress(Exception):
                        cur.execute(
                            f"DELETE FROM public.gsm_parser_change_history WHERE device_id IN ({id_ph})",
                            ids,
                        )
                    with contextlib.suppress(Exception):
                        cur.execute(
                            f"DELETE FROM public.gsm_parser_daily_history WHERE device_id IN ({id_ph})",
                            ids,
                        )
                    with contextlib.suppress(Exception):
                        cur.execute(
                            f"DELETE FROM public.gsm_parser_compatible WHERE device_id IN ({id_ph}) OR compatible_device_id IN ({id_ph})",
                            ids + ids,
                        )
                cur.execute(
                    f"DELETE FROM public.gsm_parser_devices WHERE brand IN ({ph})",
                    brands,
                )
            self._general_pg().commit()
            counts["ok"] = True
            return counts
        return {"ok": False}

