    def clear_gsm_price_shop_history(self, brands: list[str] | None = None) -> dict:
        """Delete history of min/max E-Katalog price and shop-count changes only:
        the matching columns in gsm_parser_daily_history and the corresponding
        gsm_parser_change_history rows. Devices and GSM Arena data stay intact —
        unlike clear_gsm_parser_all_data/clear_gsm_parser_brands_data.

        brands=None clears for all products; otherwise scoped to those brands.
        """
        if not self._use_postgres():
            return {"ok": False}
        counts = {"history": 0, "changes": 0}
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                if brands:
                    ph = ",".join(["%s"] * len(brands))
                    cur.execute(
                        f"SELECT id FROM public.gsm_parser_devices WHERE brand IN ({ph})",
                        brands,
                    )
                    ids = [
                        str(r.get("id") or "")
                        for r in (cur.fetchall() or [])
                        if isinstance(r, dict) and r.get("id")
                    ]
                    if not ids:
                        return {"ok": True, "history": 0, "changes": 0}
                    id_ph = ",".join(["%s"] * len(ids))
                    cur.execute(
                        f"""
                        SELECT COUNT(*) AS c FROM public.gsm_parser_daily_history
                        WHERE device_id IN ({id_ph})
                          AND (price_ek_min IS NOT NULL OR price_ek_max IS NOT NULL OR shops_count IS NOT NULL)
                        """,
                        ids,
                    )
                    counts["history"] = int((cur.fetchone() or {}).get("c") or 0)
                    cur.execute(
                        f"""
                        SELECT COUNT(*) AS c FROM public.gsm_parser_change_history
                        WHERE device_id IN ({id_ph}) AND field_key IN ('price_min','price_max','shops_count')
                        """,
                        ids,
                    )
                    counts["changes"] = int((cur.fetchone() or {}).get("c") or 0)
                    cur.execute(
                        f"""
                        UPDATE public.gsm_parser_daily_history
                        SET price_ek_min = NULL, price_ek_max = NULL, shops_count = NULL
                        WHERE device_id IN ({id_ph})
                        """,
                        ids,
                    )
                    cur.execute(
                        f"""
                        DELETE FROM public.gsm_parser_daily_history
                        WHERE device_id IN ({id_ph})
                          AND price_gsm IS NULL AND price_ek_min IS NULL
                          AND price_ek_max IS NULL AND shops_count IS NULL
                        """,
                        ids,
                    )
                    cur.execute(
                        f"""
                        DELETE FROM public.gsm_parser_change_history
                        WHERE device_id IN ({id_ph}) AND field_key IN ('price_min','price_max','shops_count')
                        """,
                        ids,
                    )
                else:
                    cur.execute(
                        """
                        SELECT COUNT(*) AS c FROM public.gsm_parser_daily_history
                        WHERE price_ek_min IS NOT NULL OR price_ek_max IS NOT NULL OR shops_count IS NOT NULL
                        """
                    )
                    counts["history"] = int((cur.fetchone() or {}).get("c") or 0)
                    cur.execute(
                        """
                        SELECT COUNT(*) AS c FROM public.gsm_parser_change_history
                        WHERE field_key IN ('price_min','price_max','shops_count')
                        """
                    )
                    counts["changes"] = int((cur.fetchone() or {}).get("c") or 0)
                    cur.execute(
                        """
                        UPDATE public.gsm_parser_daily_history
                        SET price_ek_min = NULL, price_ek_max = NULL, shops_count = NULL
                        """
                    )
                    cur.execute(
                        """
                        DELETE FROM public.gsm_parser_daily_history
                        WHERE price_gsm IS NULL AND price_ek_min IS NULL
                          AND price_ek_max IS NULL AND shops_count IS NULL
                        """
                    )
                    cur.execute(
                        """
                        DELETE FROM public.gsm_parser_change_history
                        WHERE field_key IN ('price_min','price_max','shops_count')
                        """
                    )
            self._general_pg().commit()
            counts["ok"] = True
            return counts
        return {"ok": False}

    def get_gsm_distinct_years(self) -> list[str]:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT DISTINCT specs->>'year' AS yr FROM public.gsm_parser_devices WHERE source='GSM Arena' AND specs->>'year' IS NOT NULL ORDER BY yr DESC"
                )
                return [
                    str(r.get("yr") or "")
                    for r in (cur.fetchall() or [])
                    if r.get("yr")
                ]
        return []

    def save_gsm_parser_brands_bulk(self, rows: list[dict]) -> bool:
        """Replace all brand rows in bulk (used when user saves the whole table)."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            self._ensure_gsm_parser_brands_table()
            import uuid as _uuid

            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                # Delete rows that are no longer in the list
                incoming_ids = [
                    str(r.get("id") or "").strip()
                    for r in rows
                    if str(r.get("id") or "").strip()
                ]
                if incoming_ids:
                    cur.execute(
                        "DELETE FROM public.gsm_parser_brands WHERE id != ALL(%s)",
                        (incoming_ids,),
                    )
                else:
                    cur.execute("DELETE FROM public.gsm_parser_brands")
                # Upsert each row
                for idx, row in enumerate(rows):
                    row_id = (
                        str(row.get("id") or "").strip() or f"gb_{_uuid.uuid4().hex}"
                    )
                    enabled = bool(row.get("enabled", True))
                    cur.execute(
                        """
                        INSERT INTO public.gsm_parser_brands
                            (id, brand, gsm_url, last_item,
                             ek_url_phones, ek_url_tablets, ek_url_watches,
                             sort_order, enabled, created_at, updated_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                        ON CONFLICT (id) DO UPDATE SET
                            brand           = EXCLUDED.brand,
                            gsm_url         = EXCLUDED.gsm_url,
                            last_item       = EXCLUDED.last_item,
                            ek_url_phones   = EXCLUDED.ek_url_phones,
                            ek_url_tablets  = EXCLUDED.ek_url_tablets,
                            ek_url_watches  = EXCLUDED.ek_url_watches,
                            sort_order      = EXCLUDED.sort_order,
                            enabled         = EXCLUDED.enabled,
                            updated_at      = EXCLUDED.updated_at
                        """,
                        (
                            row_id,
                            str(row.get("brand") or "").strip(),
                            str(row.get("gsm_url") or "").strip(),
                            str(row.get("last_item") or "").strip(),
                            str(row.get("ek_url_phones") or "").strip(),
                            str(row.get("ek_url_tablets") or "").strip(),
                            str(row.get("ek_url_watches") or "").strip(),
                            idx,
                            enabled,
                            now,
                            now,
                        ),
                    )
            self._general_pg().commit()
            return True
        return False

    # ── GSM Parser: per-user preferences ──────────────────────────────────
    _GSM_USER_PREFS_KEY = "gsm_parser_user_prefs"

    def get_gsm_parser_user_prefs(self, manager_id: str) -> dict:
        raw = self.get_manager_ui_preference(manager_id, self._GSM_USER_PREFS_KEY, "{}")
        try:
            prefs = json.loads(raw or "{}")
        except Exception:
            prefs = {}
        return {
            "enabled": bool(prefs.get("enabled", True)),
            "brands": prefs.get("brands", "all"),
            "device_types": prefs.get("device_types", "all"),
        }

    def set_gsm_parser_user_prefs(self, manager_id: str, prefs: dict) -> bool:
        return self.set_manager_ui_preference(
            manager_id, self._GSM_USER_PREFS_KEY, json.dumps(prefs, ensure_ascii=False)
        )

    def get_gsm_parser_available_brands(self) -> list:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT DISTINCT brand FROM public.gsm_parser_devices "
                    "WHERE brand IS NOT NULL AND brand != '' ORDER BY brand"
                )
                return [
                    r["brand"]
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and r.get("brand")
                ]
        return []

    def get_gsm_parser_available_device_types(self) -> list:
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT DISTINCT device_type FROM public.gsm_parser_devices "
                    "WHERE device_type IS NOT NULL AND device_type != '' ORDER BY device_type"
                )
                return [
                    r["device_type"]
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and r.get("device_type")
                ]
        return []

    def get_gsm_parser_device_by_id(self, device_id: str) -> dict | None:
        if not self._use_postgres():
            return None
        did = str(device_id or "").strip()
        if not did:
            return None
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id, source, brand, device_type, model_name, image_url, source_url, specs "
                    "FROM public.gsm_parser_devices WHERE id=%s LIMIT 1",
                    (did,),
                )
                row = cur.fetchone()
                return dict(row) if row else None
        return None

    def get_gsm_parser_sidebar_data(
        self,
        brand_filter=None,
        device_type_filter=None,
        limit: int = 50,
    ) -> dict:
        """Returns {gsm_new, ek_new, appeared_for_sale, regions_appeared} — each
        a list of {id, model_name, brand, device_type}."""
        empty = {
            "gsm_new": [],
            "ek_new": [],
            "appeared_for_sale": [],
            "regions_appeared": [],
        }
        if not self._use_postgres():
            return empty
        bf = None if (not brand_filter or brand_filter == "all") else list(brand_filter)
        dtf = (
            None
            if (not device_type_filter or device_type_filter == "all")
            else list(device_type_filter)
        )

        result = {
            "gsm_new": [],
            "ek_new": [],
            "appeared_for_sale": [],
            "regions_appeared": [],
        }
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT DATE_TRUNC('day', MAX(changed_at)) AS run_day "
                    "FROM public.gsm_parser_change_history"
                )
                run_row = cur.fetchone() or {}
                run_day = run_row.get("run_day") if isinstance(run_row, dict) else None
                if run_day is None:
                    return result

                b_clause = "AND brand = ANY(%s)" if bf is not None else ""
                d_clause = "AND device_type = ANY(%s)" if dtf is not None else ""

                def _p(*base):
                    p = list(base)
                    if bf is not None:
                        p.append(bf)
                    if dtf is not None:
                        p.append(dtf)
                    p.append(limit)
                    return p

                cur.execute(
                    f"SELECT id, model_name, brand, device_type "
                    f"FROM public.gsm_parser_devices "
                    f"WHERE source='GSM Arena' AND DATE_TRUNC('day', created_at) >= %s "
                    f"{b_clause} {d_clause} ORDER BY created_at DESC LIMIT %s",
                    _p(run_day),
                )
                result["gsm_new"] = [
                    dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]

                cur.execute(
                    f"SELECT id, model_name, brand, device_type "
                    f"FROM public.gsm_parser_devices "
                    f"WHERE source='E-Katalog' AND DATE_TRUNC('day', created_at) >= %s "
                    f"{b_clause} {d_clause} ORDER BY created_at DESC LIMIT %s",
                    _p(run_day),
                )
                result["ek_new"] = [
                    dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]

                # Reads the "__shops_appeared__" marker written by
                # gsm_parser_runner.py::_upsert_device — that's the only
                # place that knows whether an on-sale sighting is this
                # device's FIRST one ever (guarded by the persistent
                # specs["ek_ever_on_sale"] flag). Reconstructing this from
                # raw shops_count transitions (old behavior) couldn't tell a
                # genuine first appearance apart from a long-established
                # device's stock merely flickering 0->positive again, so it
                # kept resurfacing old devices as "just appeared for sale".
                # max_age_months is no longer applied here — the marker is
                # only ever written after the runner's own age check passed
                # at parse time (against the listing's real "Дата
                # додавання", not this row's created_at, which measures
                # discovery lag rather than listing age).
                _appeared_params: list = [run_day]
                if bf is not None:
                    _appeared_params.append(bf)
                if dtf is not None:
                    _appeared_params.append(dtf)
                _appeared_params.append(limit)
                cur.execute(
                    f"SELECT DISTINCT ON (d.id) d.id, d.model_name, d.brand, d.device_type "
                    f"FROM public.gsm_parser_devices d "
                    f"JOIN public.gsm_parser_change_history ch ON ch.device_id = d.id "
                    f"WHERE d.source='E-Katalog' "
                    f"AND ch.field_key='__shops_appeared__' "
                    f"AND DATE_TRUNC('day', ch.changed_at) >= %s "
                    f"{b_clause} {d_clause} "
                    f"ORDER BY d.id, d.model_name LIMIT %s",
                    _appeared_params,
                )
                result["appeared_for_sale"] = [
                    dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]

                _regions_params: list = [run_day]
                if bf is not None:
                    _regions_params.append(bf)
                if dtf is not None:
                    _regions_params.append(dtf)
                _regions_params.append(limit)
                cur.execute(
                    f"SELECT DISTINCT ON (d.id) d.id, d.model_name, d.brand, d.device_type "
                    f"FROM public.gsm_parser_devices d "
                    f"JOIN public.gsm_parser_change_history ch ON ch.device_id = d.id "
                    f"WHERE ch.field_key='__regions_appeared__' "
                    f"AND DATE_TRUNC('day', ch.changed_at) >= %s "
                    f"{b_clause} {d_clause} "
                    f"ORDER BY d.id, d.model_name LIMIT %s",
                    _regions_params,
                )
                result["regions_appeared"] = [
                    dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]
        return result

    def get_effective_background_source(
        self, company_id: str | None = None, manager_id: str | None = None
    ):
        """
        UI may call this to resolve background. Return empty string if unset.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/ui/background/effective",
                    {"manager_id": manager_id or "", "company_id": company_id or ""},
                )
                or ""
            )

        # Postgres mode: currently only per-manager local background is supported.
        # (Stored in managers.meta.local_background as pgfile://... URL.)
        mid = str(manager_id or "").strip()
        if mid:
            return self.get_manager_local_background(mid) or ""
        return ""

    def get_manager_local_background(self, manager_id: str):
        """
        Return manager's personal background source (local path or file handle).
        UI treats this as an optional string.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/ui/background/manager_local", {"manager_id": manager_id or ""}
                )
                or ""
            )
        mid = str(manager_id or "").strip()
        if not mid:
            return ""
        with self._general_pg().cursor() as cur:
            cur.execute("SELECT meta FROM public.managers WHERE id=%s LIMIT 1", (mid,))
            row = cur.fetchone() or {}
        meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
        # Prefer local cached file if present (media/user_backgrounds).
        local_path = str((meta or {}).get("local_background_local_path") or "").strip()
        if local_path and os.path.exists(local_path):
            return local_path
        val = (meta or {}).get("local_background")
        return str(val) if val else ""

    def set_manager_local_background(self, manager_id: str, local_path: str) -> bool:
        """
        Store personal background for manager.
        In Postgres mode we upload file into `files` and store pgfile handle in `managers.meta.local_background`.
        """
        if not self._use_postgres():
            return bool(
                self._post(
                    "/ui/background/manager_local/set",
                    {"manager_id": manager_id or "", "local_path": local_path or ""},
                )
                or False
            )
        mid = str(manager_id or "").strip()
        path = str(local_path or "").strip()
        if not mid or not path:
            return False
        url = self.upload_file("backgrounds", path)
        if not url:
            return False
        # Also store a local cached copy in media/user_backgrounds for instant load/offline usage.
        cached_path = ""
        try:
            os.makedirs(
                os.path.join(os.getcwd(), "media", "user_backgrounds"), exist_ok=True
            )
            ext = os.path.splitext(path)[1].lower() or ".jpg"
            file_id = (
                url.split("://", 1)[1].strip()
                if str(url).lower().startswith("pgfile://")
                else uuid.uuid4().hex
            )
            cached_path = os.path.join(
                os.getcwd(), "media", "user_backgrounds", f"{file_id}{ext}"
            )
            if not os.path.exists(cached_path):
                import shutil

                shutil.copy2(path, cached_path)
        except Exception:
            logger.exception("Failed to cache personal background locally")
        now = self._now_ts()
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT meta, company_id FROM public.managers WHERE id=%s LIMIT 1",
                    (mid,),
                )
                row = cur.fetchone() or {}
                meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
                cid = str(row.get("company_id") or "").strip()
                meta = dict(meta or {})
                meta["local_background"] = url
                if cached_path:
                    meta["local_background_local_path"] = cached_path
                meta["local_background_updated_at"] = (
                    now.isoformat() if hasattr(now, "isoformat") else str(now)
                )
                cur.execute(
                    "UPDATE public.managers SET meta=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(meta), now, mid),
                )
            if cid:
                self._pulse(cid, "ui")
            return True
        except Exception:
            logger.exception("set_manager_local_background failed")
            return False

    def clear_manager_local_background(self, manager_id: str) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/ui/background/manager_local/clear",
                    {"manager_id": manager_id or ""},
                )
                or False
            )
        mid = str(manager_id or "").strip()
        if not mid:
            return False
        now = self._now_ts()
        try:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT meta, company_id FROM public.managers WHERE id=%s LIMIT 1",
                    (mid,),
                )
                row = cur.fetchone() or {}
                meta = row.get("meta") if isinstance(row.get("meta"), dict) else {}
                cid = str(row.get("company_id") or "").strip()
                url = str((meta or {}).get("local_background") or "").strip()
                local_path = str(
                    (meta or {}).get("local_background_local_path") or ""
                ).strip()
                meta = dict(meta or {})
                meta.pop("local_background", None)
                meta.pop("local_background_local_path", None)
                meta["local_background_updated_at"] = (
                    now.isoformat() if hasattr(now, "isoformat") else str(now)
                )
                cur.execute(
                    "UPDATE public.managers SET meta=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(meta), now, mid),
                )
            if url:
                with contextlib.suppress(Exception):
                    self.delete_file_by_url(url)
            if local_path:
                with contextlib.suppress(Exception):
                    if os.path.exists(local_path):
                        os.remove(local_path)
            if cid:
                self._pulse(cid, "ui")
            return True
        except Exception:
            logger.exception("clear_manager_local_background failed")
            return False

    # ----------------- files / images (Postgres mode) -----------------
    def upload_file(
        self,
        bucket: str,
        local_path: str,
        filename: str | None = None,
        content_type: str | None = None,
    ) -> str:
        """
        Store file bytes in Postgres (`files.content`) and return a URL-like handle: pgfile://<id>
        UI will pass `local_path` to a temp/compressed image file.
        """
        if not self._use_postgres():
            # backend mode
            payload = {
                "bucket": bucket,
                "local_path": local_path,
                "filename": filename or "",
                "content_type": content_type or "",
            }
            return str(self._post("/files/upload", payload) or "")

        bucket = str(bucket or "").strip() or "files"
        path = str(local_path or "").strip()
        if not path or not os.path.exists(path):
            return ""
        fname = str(filename or os.path.basename(path) or "file").strip() or "file"
        ext = os.path.splitext(fname)[1].lower()
        if not content_type:
            content_type = {
                ".png": "image/png",
                ".jpg": "image/jpeg",
                ".jpeg": "image/jpeg",
                ".gif": "image/gif",
                ".webp": "image/webp",
            }.get(ext, "application/octet-stream")
        try:
            with open(path, "rb") as f:
                data = f.read()
        except Exception:
            logger.exception("upload_file read failed")
            return ""
        file_id = uuid.uuid4().hex
        created_at = self._now_ts()
        size = int(len(data))
        url = f"pgfile://{file_id}"
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO files (id, bucket, filename, content_type, size, path, created_at, content, url)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)
                    """,
                    (
                        file_id,
                        bucket,
                        fname,
                        content_type,
                        size,
                        "",
                        created_at,
                        data,
                        url,
                    ),
                )
            return url
        except Exception:
            logger.exception("upload_file insert failed")
            return ""

    def resolve_image_source(self, url: str) -> str:
        """
        Convert stored pgfile handle into a data URI usable by `ft.Image(src=...)`.
        For non-pgfile URLs, return as-is.
        """
        u = str(url or "").strip()
        if not u:
            return ""
        if not self._use_postgres():
            return u
        if not u.lower().startswith("pgfile://"):
            return u
        file_id = u.split("://", 1)[1].strip()
        if not file_id:
            return ""
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT content_type, content FROM files WHERE id=%s LIMIT 1",
                    (file_id,),
                )
                row = cur.fetchone() or {}
            content = row.get("content")
            ctype = (
                (row.get("content_type") or "application/octet-stream")
                if isinstance(row, dict)
                else "application/octet-stream"
            )
            if not content:
                return ""
            import base64

            b64 = base64.b64encode(content).decode("ascii")
            return f"data:{ctype};base64,{b64}"
        except Exception:
            logger.exception("resolve_image_source failed")
            return ""

    def resolve_image_base64(self, url: str) -> str:
        """
        Return raw base64 (NO data: prefix) for `ft.Image(src_base64=...)`.
        For non-pgfile URLs, return empty string (caller should use src instead).
        """
        u = str(url or "").strip()
        if not u:
            return ""
        if not self._use_postgres():
            return ""
        if not u.lower().startswith("pgfile://"):
            return ""
        file_id = u.split("://", 1)[1].strip()
        if not file_id:
            return ""
        try:
            with self._pg().cursor() as cur:
                cur.execute("SELECT content FROM files WHERE id=%s LIMIT 1", (file_id,))
                row = cur.fetchone() or {}
            content = row.get("content")
            if not content:
                return ""
            import base64

            return base64.b64encode(content).decode("ascii")
        except Exception:
            logger.exception("resolve_image_base64 failed")
            return ""

    def resolve_image_file_path(self, url: str) -> str:
        """
        Materialize `pgfile://<id>` into a local cached file path and return it.
        This is compatible with older Flet versions that don't support `src_base64`.
        For non-pgfile URLs, returns the input URL unchanged.
        """
        u = str(url or "").strip()
        if not u:
            return ""
        if not self._use_postgres():
            return u
        if not u.lower().startswith("pgfile://"):
            return u
        file_id = u.split("://", 1)[1].strip()
        if not file_id:
            return ""
        try:
            cache_dir = os.path.join(os.getcwd(), "media", "_cache")
            os.makedirs(cache_dir, exist_ok=True)
            # default extension
            out_path = os.path.join(cache_dir, f"{file_id}.bin")
            if os.path.exists(out_path) and os.path.getsize(out_path) > 0:
                return out_path
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT content_type, content FROM files WHERE id=%s LIMIT 1",
                    (file_id,),
                )
                row = cur.fetchone() or {}
            content = row.get("content") if isinstance(row, dict) else None
            ctype = (
                (row.get("content_type") or "").lower() if isinstance(row, dict) else ""
            )
            if not content:
                return ""
            ext = ".bin"
            if "jpeg" in ctype or "jpg" in ctype:
                ext = ".jpg"
            elif "png" in ctype:
                ext = ".png"
            elif "gif" in ctype:
                ext = ".gif"
            elif "webp" in ctype:
                ext = ".webp"
            out_path = os.path.join(cache_dir, f"{file_id}{ext}")
            if os.path.exists(out_path) and os.path.getsize(out_path) > 0:
                return out_path
            with open(out_path, "wb") as f:
                f.write(content)
            return out_path
        except Exception:
            logger.exception("resolve_image_file_path failed")
            return ""

    def delete_file_by_url(self, url: str) -> bool:
        """
        Delete file stored in Postgres by its pgfile:// id.
        """
        u = str(url or "").strip()
        if not u:
            return False
        if not self._use_postgres():
            return bool(self._delete("/files/delete_by_url", {"url": u}) or False)
        if not u.lower().startswith("pgfile://"):
            return False
        file_id = u.split("://", 1)[1].strip()
        if not file_id:
            return False
        try:
            with self._pg().cursor() as cur:
                cur.execute("DELETE FROM files WHERE id=%s", (file_id,))
            return True
        except Exception:
            logger.exception("delete_file_by_url failed")
            return False

    # ----------------- category visibility (Postgres mode) -----------------
    def get_accessible_categories(
        self,
        company_id: str,
        manager_id: str,
        region_id: str | None = None,
        archived: bool | None = False,
        force_refresh: bool | None = None,
    ):
        """Cache-aside wrapper — see _cached_list. Cleared automatically by
        _pulse(company_id, "catalog") (category/level/brand mutations)."""
        cid = str(company_id or "").strip()
        if not self._use_postgres() or not cid:
            return self._get_accessible_categories_uncached(
                company_id, manager_id, region_id, archived
            )
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        cache_key = f"acc_categories_{cid}_{mid}_{rid}_{bool(archived)}"
        return self._cached_list(
            cache_key,
            bool(force_refresh),
            lambda: self._get_accessible_categories_uncached(
                company_id, manager_id, region_id, archived
            ),
        )

    def _get_accessible_categories_uncached(
        self,
        company_id: str,
        manager_id: str,
        region_id: str | None = None,
        archived: bool | None = False,
    ):
        """
        Returns categories visible to manager based on access tables.
        Compatibility:
        - If no restrictions found -> return all company categories (optionally filtered by region).
        - If category_access rows exist -> return those categories.
        - Else if manager_access_scopes exist -> map category nodes to categories and return.
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/categories/accessible",
                    {
                        "company_id": company_id,
                        "manager_id": manager_id,
                        "region_id": region_id or "",
                    },
                )
                or []
            )
        company_id = str(company_id or "").strip()
        manager_id = str(manager_id or "").strip()
        region_id = str(region_id or "").strip()
        if not company_id or not manager_id:
            return []

        # 1) canonical scope nodes (node_owners / manager_access_scopes) — check first
        #    so that partial-level access doesn't get overridden by the ancestor category
        #    written to category_access for region-lookup purposes.
        node_ids = set(
            self.get_manager_scope_node_ids(
                manager_id, company_id=company_id, permission="view"
            )
        )
        if node_ids:
            # Ensure nodes exist
            with contextlib.suppress(Exception):
                self.sync_company_catalog_nodes(company_id)
            nodes = [
                n
                for n in (self.get_company_catalog_nodes(company_id) or [])
                if isinstance(n, dict) and n.get("id")
            ]
            by_id = {str(n.get("id")): n for n in nodes}
            allowed_category_node_ids = set()
            for node_id in node_ids:
                current_node = by_id.get(str(node_id) or "")
                visited = set()
                while current_node and current_node.get("id"):
                    current_node_id = str(current_node.get("id") or "").strip()
                    if not current_node_id or current_node_id in visited:
                        break
                    visited.add(current_node_id)
                    if str(current_node.get("node_type") or "").strip() == "category":
                        allowed_category_node_ids.add(current_node_id)
                        break
                    current_node = by_id.get(
                        str(current_node.get("parent_id") or "").strip()
                    )
            if allowed_category_node_ids:
                allowed_region_ids = None
                if region_id:
                    allowed_region_ids = {region_id}
                cats = self.get_company_categories(
                    company_id, region_id or None, archived=archived
                )
                out = []
                for c in cats:
                    if not isinstance(c, dict) or not c.get("id"):
                        continue
                    if c.get("id") in allowed_category_node_ids:
                        if (
                            allowed_region_ids
                            and c.get("region_id") not in allowed_region_ids
                        ):
                            continue
                        out.append(c)
                return out

        # 2) legacy category_access fallback (for managers assigned via old system)
        cat_ids = set(
            self.get_manager_category_ids(
                manager_id, company_id=company_id, region_id=(region_id or None)
            )
        )
        if cat_ids:
            cats = self.get_company_categories(
                company_id, region_id or None, archived=archived
            )
            return [c for c in cats if isinstance(c, dict) and c.get("id") in cat_ids]

        # 3) no restrictions:
        # - Admin/SuperAdmin: all categories
        # - Everyone else: treat as "no access selected" -> empty
        role_slug = self._get_manager_role_slug(manager_id)
        if role_slug in {
            "адмін",
            "админ",
            "admin",
            "суперадмін",
            "суперадмин",
            "superadmin",
        }:
            return self.get_company_categories(
                company_id, region_id or None, archived=archived
            )
        return []

    def get_region_price_tiers(self, region_id: str):
        if not self._use_postgres():
            return self._get("/regions/price_tiers", {"region_id": region_id}) or []
        region_id = str(region_id or "").strip()
        if not region_id:
            return []
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT tiers FROM region_price_tiers WHERE region_id=%s ORDER BY updated_at DESC LIMIT 1",
                (region_id,),
            )
            row = cur.fetchone()
        if row and isinstance(row.get("tiers"), list):
            tiers = row["tiers"]
            # Ensure every tier has a stable `id` for UI mappings (sales_prices_json tier_id).
            out = []
            for idx, t in enumerate(tiers or []):
                if not isinstance(t, dict):
                    continue
                name = str(t.get("name") or "").strip()
                currency = str(t.get("currency") or "USD").upper()
                tid = t.get("id")
                if not tid:
                    # deterministic id based on region+name (fallback to index if name empty)
                    seed = f"{region_id}:{name}" if name else f"{region_id}:#{idx}"
                    tid = uuid.uuid5(uuid.NAMESPACE_URL, seed).hex
                out.append({**t, "id": str(tid), "name": name, "currency": currency})
            return out
        return []

    def get_manager_region_price_tiers_overrides(self, manager_id: str, region_id: str):
        """
        Personal price tiers for a manager (override tier definitions/labels per region).

        Returns normalized list[dict] where each tier has stable `id`.
        """
        if not self._use_postgres():
            # HTTP backend (if any) does not support this yet; fallback to company defaults.
            return self.get_region_price_tiers(region_id)

        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not mid or not rid:
            return []

        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT tiers
                FROM manager_region_price_tiers_overrides
                WHERE manager_id=%s AND region_id=%s
                LIMIT 1
                """,
                (mid, rid),
            )
            row = cur.fetchone()
        tiers = (row or {}).get("tiers")
        if isinstance(tiers, list):
            # Ensure every tier has stable `id` for UI mappings.
            out = []
            for idx, t in enumerate(tiers or []):
                if not isinstance(t, dict):
                    continue
                name = str(t.get("name") or "").strip()
                currency = str(t.get("currency") or "USD").upper()
                tid = t.get("id")
                if not tid:
                    seed = f"{rid}:{name}" if name else f"{rid}:#{idx}"
                    tid = uuid.uuid5(uuid.NAMESPACE_URL, seed).hex
                out.append({**t, "id": str(tid), "name": name, "currency": currency})
            return out
        return []

    def save_manager_region_price_tiers_overrides(
        self, manager_id: str, region_id: str, tiers_payload: list
    ) -> bool:
        """
        Save personal tiers (manager override) for a specific region.
        """
        if not self._use_postgres():
            return False

        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not mid or not rid:
            return False

        tiers = tiers_payload if isinstance(tiers_payload, list) else []
        # Preserve existing tier ids when user only renames tiers (tier_id is the key used by products.sales_prices_json).
        existing_tiers = self.get_manager_region_price_tiers_overrides(mid, rid)
        existing_by_name = {
            str(t.get("name") or "").strip().lower(): t.get("id")
            for t in (existing_tiers or [])
            if isinstance(t, dict) and (t.get("name") is not None) and t.get("id")
        }
        existing_by_idx = [
            str(t.get("id")).strip()
            for t in (existing_tiers or [])
            if isinstance(t, dict) and t.get("id")
        ]

        # Normalize tiers to include stable `id`.
        now = self._now_ts()
        norm_tiers = []
        for idx, t in enumerate(tiers or []):
            if not isinstance(t, dict):
                continue
            name = str(t.get("name") or "").strip()
            currency = str(t.get("currency") or "USD").upper()
            tid = t.get("id")
            if not tid:
                # Prefer matching by old name (for deletions where remaining tiers keep same name).
                if name:
                    tid = existing_by_name.get(name.lower())
                # Fallback: preserve by index (for rename where name changed but order stays).
                if not tid and idx < len(existing_by_idx):
                    tid = existing_by_idx[idx]
                # Final: generate deterministic id (for new tier rows).
                if not tid:
                    seed = f"{rid}:tier_idx:{idx}"
                    tid = uuid.uuid5(uuid.NAMESPACE_URL, seed).hex
            norm_tiers.append({**t, "id": str(tid), "name": name, "currency": currency})

        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO manager_region_price_tiers_overrides (manager_id, region_id, tiers, updated_at)
                    VALUES (%s,%s,%s::jsonb,%s)
                    ON CONFLICT (manager_id, region_id)
                    DO UPDATE SET tiers=EXCLUDED.tiers, updated_at=EXCLUDED.updated_at
                    """,
                    (mid, rid, psycopg.types.json.Jsonb(norm_tiers), now),
                )
        except Exception:
            logger.exception("save_manager_region_price_tiers_overrides failed")
            return False

        # Trigger pricing scope refresh for the manager's company.
        with contextlib.suppress(Exception):
            prof = (
                self.get_manager_profile(mid)
                if hasattr(self, "get_manager_profile")
                else {}
            )
            cid = str((prof or {}).get("company_id") or "").strip()
            if cid:
                self._pulse(cid, "pricing")
        return True

    def get_effective_region_price_tiers_for_manager(
        self, company_id: str, manager_id: str, region_id: str | None = None
    ):
        """
        Effective tiers = personal override if exists, else company defaults.

        `company_id` is kept for API consistency; `region_id` is assumed to be already company-scoped.
        """
        if not self._use_postgres():
            return self.get_region_price_tiers(region_id)

        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip() if region_id else ""
        if not mid or not rid:
            return []

        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT tiers
                FROM manager_region_price_tiers_overrides
                WHERE manager_id=%s AND region_id=%s
                LIMIT 1
                """,
                (mid, rid),
            )
            row = cur.fetchone()

        # Important: if override row exists, we must use it even when it's an empty list.
        if row is not None:
            return self.get_manager_region_price_tiers_overrides(mid, rid)

        # Fallback to company defaults
        return self.get_region_price_tiers(rid)

    def get_company_managers(
        self, company_id: str, force_refresh: bool | None = None
    ):  # noqa: ARG002
        if not self._use_postgres():
            return self._get("/managers", {"company_id": company_id}) or []
        cid = str(company_id or "").strip()
        # Superadmin "Всі компанії" mode passes a special key; treat as no filter.
        if cid in {"", "__all_companies__", "__all_companies__"}:
            cid = ""
        with self._general_pg().cursor() as cur:
            if cid:
                cur.execute(
                    """
                    SELECT id, company_id, full_name, email, phone, role, is_approved, is_blocked, meta, created_at, updated_at
                    FROM public.managers
                    WHERE company_id=%s
                    ORDER BY full_name ASC
                    """,
                    (cid,),
                )
            else:
                cur.execute("""
                    SELECT id, company_id, full_name, email, phone, role, is_approved, is_blocked, meta, created_at, updated_at
                    FROM public.managers
                    ORDER BY full_name ASC
                    """)
            rows = cur.fetchall() or []
        return rows

    def get_manager_profile(self, manager_id: str):
        """
        Returns full manager profile dict for dashboards/impersonation.
        """
        if not self._use_postgres():
            return self._get("/managers/profile", {"manager_id": manager_id}) or {}
        mid = str(manager_id or "").strip()
        if not mid:
            return {}
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, company_id, full_name, email, phone, role, is_approved, is_blocked, meta, created_at, updated_at
                FROM public.managers
                WHERE id=%s
                LIMIT 1
                """,
                (mid,),
            )
            row = cur.fetchone()
        return row if isinstance(row, dict) else {}

    def update_manager_data(self, manager_id: str, payload: dict) -> bool:
        if not self._use_postgres():
            return bool(
                self._post("/managers/update", {"id": manager_id, **(payload or {})})
                or False
            )
        manager_id = str(manager_id or "").strip()
        full_name = str((payload or {}).get("full_name") or "").strip()
        email = str((payload or {}).get("email") or "").strip().lower()
        phone = str((payload or {}).get("phone") or "").strip()
        password = str((payload or {}).get("password") or "")
        now = self._now_ts()
        sets = []
        params: list[Any] = []
        if full_name:
            sets.append("full_name=%s")
            params.append(full_name)
        if email:
            sets.append("email=%s")
            params.append(email)
        if phone:
            sets.append("phone=%s")
            params.append(phone)
        if password:
            sets.append("password_hash=%s")
            params.append(self._hash_password(password))
        sets.append("updated_at=%s")
        params.append(now)
        params.append(manager_id)
        q = "UPDATE public.managers SET " + ", ".join(sets) + " WHERE id=%s"
        with self._general_pg().cursor() as cur:
            cur.execute(q, params)
        return True

    def set_manager_blocked(self, manager_id: str, blocked: bool) -> bool:
        """Block or unblock a manager. Blocked managers cannot log in."""
        if not self._use_postgres():
            return bool(
                self._post(
                    "/managers/set_blocked",
                    {"id": manager_id, "blocked": bool(blocked)},
                )
                or False
            )
        with self._general_pg().cursor() as cur:
            cur.execute(
                "UPDATE public.managers SET is_blocked=%s, updated_at=%s WHERE id=%s",
                (bool(blocked), self._now_ts(), str(manager_id or "").strip()),
            )
        return True

    def _collect_scope_product_rows(
        self,
        company_id: str,
        node_ids: list,
        source_manager_id: str | None = None,
    ) -> dict:
        if not self._use_postgres():
            return {
                "products": [],
                "expanded_ids": set(),
                "category_ids": set(),
            }
        cid = str(company_id or "").strip()
        seed_ids = {str(x) for x in (node_ids or []) if str(x).strip()}
        source_mid = str(source_manager_id or "").strip()
        if not cid or not seed_ids:
            return {"products": [], "expanded_ids": set(), "category_ids": set()}

        self.sync_company_catalog_nodes(cid)
        all_nodes = [
            n
            for n in (self.get_company_catalog_nodes(cid, force_refresh=False) or [])
            if isinstance(n, dict) and n.get("id")
        ]
        if not all_nodes:
            return {"products": [], "expanded_ids": set(), "category_ids": set()}

        by_id = {str(n.get("id")): n for n in all_nodes}
        children_of: dict[str, list[str]] = {}
        for node in all_nodes:
            parent_id = str(node.get("parent_id") or "").strip()
            node_id = str(node.get("id") or "").strip()
            if parent_id and node_id:
                children_of.setdefault(parent_id, []).append(node_id)

        expanded_ids: set[str] = set()
        stack = list(seed_ids)
        while stack:
            current_id = str(stack.pop() or "").strip()
            if not current_id or current_id in expanded_ids:
                continue
            expanded_ids.add(current_id)
            # Only expand children if this is not a category OR no explicit children are in seed_ids
            node = by_id.get(current_id) or {}
            if str(node.get("node_type") or "").strip() != "category":
                stack.extend(children_of.get(current_id, []))
            else:
                # For categories: only expand to children that are ALSO explicitly in seed_ids
                explicit_children = [
                    c for c in children_of.get(current_id, []) if c in seed_ids
                ]
                if explicit_children:
                    stack.extend(explicit_children)

        direct_category_ids: set[str] = set()
        category_ids: set[str] = set()
        for node_id in expanded_ids:
            node = by_id.get(node_id) or {}
            if str(node.get("node_type") or "").strip() == "category":
                category_ids.add(node_id)
                if node_id in seed_ids:
                    direct_category_ids.add(node_id)
                continue
            current_node = node
            visited: set[str] = set()
            while current_node and current_node.get("id"):
                current_node_id = str(current_node.get("id") or "").strip()
                if not current_node_id or current_node_id in visited:
                    break
                visited.add(current_node_id)
                if str(current_node.get("node_type") or "").strip() == "category":
                    category_ids.add(current_node_id)
                    break
                current_node = by_id.get(
                    str(current_node.get("parent_id") or "").strip()
                )

        cond_parts = []
        params: list[Any] = [cid]
        # Never search by direct_category_ids if we have explicit non-category nodes in seed_ids
        # This ensures partial access (e.g., one level) doesn't show all products under that category
        has_non_category_seeds = any(
            str((by_id.get(sid) or {}).get("node_type") or "").strip() != "category"
            for sid in seed_ids
        )
        if direct_category_ids and not has_non_category_seeds:
            cond_parts.append("(p.data->>'category_id') = ANY(%s)")
            params.append(list(direct_category_ids))
        if expanded_ids:
            cond_parts.append("(p.data->>'catalog_node_id') = ANY(%s)")
            params.append(list(expanded_ids))
        if not cond_parts:
            return {
                "products": [],
                "expanded_ids": expanded_ids,
                "category_ids": category_ids,
            }

        query = f"""
            SELECT DISTINCT ON (p.id) p.id, p.company_id, p.region_id, p.manager_id, p.name,
                   p.production_term_days, p.data, p.created_at, p.updated_at
            FROM products p
            WHERE p.company_id=%s
              AND ({' OR '.join(cond_parts)})
        """
        if source_mid:
            query += " AND p.manager_id=%s"
            params.append(source_mid)
        query += " ORDER BY p.id ASC, p.updated_at DESC, p.created_at DESC"

        with self._pg().cursor() as cur:
            cur.execute(query, params)
            rows = cur.fetchall() or []
        return {
            "products": [r for r in rows if isinstance(r, dict)],
            "expanded_ids": expanded_ids,
            "category_ids": category_ids,
        }

    def _get_manager_role_slug(self, manager_id: str) -> str:
        mid = str(manager_id or "").strip()
        if not self._use_postgres() or not mid:
            return ""
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT role FROM public.managers WHERE id=%s LIMIT 1",
                    (mid,),
                )
                row = cur.fetchone() or {}
            return str((row or {}).get("role") or "").strip().lower().replace(" ", "")
        return ""

    def _get_manager_visible_scope_context(
        self,
        company_id: str,
        manager_id: str,
        region_id: str | None = None,
    ) -> dict:
        context = {
            "restricted": False,
            "product_ids": set(),
            "supplier_ids": set(),
            "packaging_ids": set(),
            "order_ids": set(),
            "group_ids": set(),
            "category_ids": set(),
            "node_ids": set(),
        }
        if not self._use_postgres():
            return context
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        rid = str(region_id or "").strip()
        if not cid or not mid:
            return context

        _sc_key = f"mgr_scope_{cid}_{mid}_{rid}"
        _cached = self._session_cache.get(_sc_key)
        if _cached is not None:
            return _cached

        scope_node_ids = {
            str(x)
            for x in self.get_manager_scope_node_ids(
                mid, company_id=cid, permission="view"
            )
            if str(x).strip()
        }
        category_ids = {
            str(x)
            for x in self.get_manager_category_ids(
                mid, company_id=cid, region_id=(rid or None)
            )
            if str(x).strip()
        }
        # If canonical scope nodes exist, use them exclusively so that only the
        # explicitly assigned nodes (and their children) are visible — NOT the
        # entire ancestor categories that are written to category_access for
        # region-lookup purposes.  Fall back to category_ids only when there are
        # no specific scope nodes (legacy assignment path).
        if scope_node_ids:
            effective_node_ids = set(scope_node_ids)
        else:
            effective_node_ids = set(category_ids)
        if not effective_node_ids:
            role_slug = self._get_manager_role_slug(mid)
            if role_slug in {
                "адмін",
                "админ",
                "admin",
                "суперадмін",
                "суперадмин",
                "superadmin",
            }:
                self._session_cache[_sc_key] = context
                return context
            # No scope nodes → manager has no access.  Return restricted-empty so
            # every filtered query returns zero rows.  We intentionally do NOT fall
            # back to entity_owners here: that table may contain stale entries from
            # before access was removed, and reading it would break the access model.
            context["restricted"] = True
            self._session_cache[_sc_key] = context
            return context

        scope_info = self._collect_scope_product_rows(
            cid, list(effective_node_ids), source_manager_id=None
        )
        product_rows = [
            r for r in (scope_info.get("products") or []) if isinstance(r, dict)
        ]
        if rid:
            product_rows = [
                r for r in product_rows if str(r.get("region_id") or "").strip() == rid
            ]

        product_ids = {
            str(r.get("id") or "").strip()
            for r in product_rows
            if str(r.get("id") or "").strip()
        }
        supplier_ids = {
            str((r.get("data") or {}).get("supplier_id") or "").strip()
            for r in product_rows
            if isinstance(r.get("data"), dict)
        }
        packaging_ids = {
            str((r.get("data") or {}).get("packaging_id") or "").strip()
            for r in product_rows
            if isinstance(r.get("data"), dict)
        }
        supplier_ids.discard("")
        packaging_ids.discard("")

        # Union packaging from entity_owners so newly created packaging by this manager is visible
        # (before they're linked to products)
        if mid and cid:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT DISTINCT entity_id
                    FROM entity_owners
                    WHERE company_id=%s AND manager_id=%s AND entity_type='packaging'
                    """,
                    (cid, mid),
                )
                for row in cur.fetchall() or []:
                    eid = str(
                        (row.get("entity_id") if isinstance(row, dict) else row[0])
                        or ""
                    ).strip()
                    if eid:
                        packaging_ids.add(eid)

        # NOTE: We intentionally do NOT union entity_owners here for suppliers.  Supplier and
        # packaging visibility must be derived exclusively from which products are
        # in scope for this manager (node-ownership → products → linked entities).
        # Unioning entity_owners can surface stale rows from before access removal.

        order_ids: set[str] = set()
        group_ids: set[str] = set()
        if product_ids:
            with self._pg().cursor() as cur:
                order_query = """
                    SELECT id
                    FROM orders o
                    WHERE o.company_id=%s AND o.manager_id=%s
                """
                order_params: list[Any] = [cid, mid]
                if rid:
                    order_query += " AND o.region_id=%s"
                    order_params.append(rid)
                order_query += """
                      AND EXISTS (
                          SELECT 1
                          FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) AS it
                          WHERE (it->>'product_id') = ANY(%s)
                      )
                """
                order_params.append(list(product_ids))
                cur.execute(order_query, order_params)
                order_ids = {
                    str(r.get("id") or "").strip()
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and str(r.get("id") or "").strip()
                }

                with contextlib.suppress(Exception):
                    group_query = """
                        SELECT id
                        FROM order_schedule_groups
                        WHERE company_id=%s AND manager_id=%s
                    """
                    group_params: list[Any] = [cid, mid]
                    if rid:
                        group_query += " AND region_id=%s"
                        group_params.append(rid)
                    group_query += " AND product_ids ?| %s"
                    group_params.append(list(product_ids))
                    cur.execute(group_query, group_params)
                    group_ids = {
                        str(r.get("id") or "").strip()
                        for r in (cur.fetchall() or [])
                        if isinstance(r, dict) and str(r.get("id") or "").strip()
                    }

            order_ids.update(self.get_entity_owner_entity_ids(cid, mid, "order") or [])
            # Note: order_ids from entity_owners is kept for now because orders can
            # span multiple product scopes and entity_owners is the canonical record.
            # Suppliers and packaging are computed purely from in-scope products above.

        context.update(
            {
                "restricted": True,
                "product_ids": product_ids,
                "supplier_ids": supplier_ids,
                "packaging_ids": packaging_ids,
                "order_ids": order_ids,
                "group_ids": group_ids,
                "category_ids": set(scope_info.get("category_ids") or []),
                "node_ids": effective_node_ids,
            }
        )
        self._session_cache[_sc_key] = context
        return context

    def _copy_manager_scope_data(
        self,
        to_manager_id: str,
        company_id: str,
        node_ids: list,
        source_manager_id: str | None = None,
    ) -> dict:
        result = {
            "suppliers": 0,
            "packaging": 0,
            "products": 0,
            "orders": 0,
            "payments": 0,
            "media_plan": 0,
            "schedule_groups": 0,
            "schedule_tasks": 0,
            "cost_stock": 0,
            "cost_orders": 0,
            "packaging_contexts": 0,
            "packaging_openings": 0,
            "packaging_orders": 0,
        }
        if not self._use_postgres():
            return result
        target_mid = str(to_manager_id or "").strip()
        cid = str(company_id or "").strip()
        source_mid = str(source_manager_id or "").strip()
        node_ids = [str(x) for x in (node_ids or []) if str(x).strip()]
        if not target_mid or not cid or not node_ids:
            return result

        scope_info = self._collect_scope_product_rows(
            cid, node_ids, source_manager_id=(source_mid or None)
        )
        source_products = scope_info.get("products") or []
        if not source_products:
            return result

        def _json_dict(value) -> dict:
            return value if isinstance(value, dict) else {}

        def _json_list(value) -> list:
            if isinstance(value, list):
                return value
            if isinstance(value, str):
                with contextlib.suppress(Exception):
                    parsed = json.loads(value)
                    if isinstance(parsed, list):
                        return parsed
            return []

        def _canon_json(value) -> str:
            with contextlib.suppress(Exception):
                return json.dumps(value, ensure_ascii=False, sort_keys=True)
            return str(value)

        def _item_signature(item: dict) -> tuple:
            if not isinstance(item, dict):
                return ("", "", "", "", "", "", "")
            return (
                str(item.get("product_id") or "").strip(),
                str(item.get("supplier_id") or "").strip(),
                str(item.get("qty") or item.get("quantity") or "").strip(),
                str(item.get("unit_price") or item.get("price") or "").strip(),
                str(item.get("currency") or item.get("ccy") or "").upper().strip(),
                str(item.get("amount") or item.get("sum") or "").strip(),
                str(item.get("line_idx") or "").strip(),
            )

        def _order_signature(data: dict) -> tuple:
            payload = _json_dict(data)
            items = [
                _item_signature(it)
                for it in _json_list(payload.get("items"))
                if isinstance(it, dict)
            ]
            items.sort()
            return (
                str(payload.get("order_date") or "").strip(),
                str(payload.get("invoice_no") or "").strip().lower(),
                str(payload.get("status") or "").strip().lower(),
                str(payload.get("submission_status") or "").strip().lower(),
                str(payload.get("mode") or "").strip().lower(),
                tuple(items),
            )

        def _media_signature(
            product_ids: list,
            comment: str,
            not_relevant: bool,
            post_dates: list,
        ) -> tuple:
            norm_pids = sorted(
                {
                    str(x or "").strip()
                    for x in (product_ids or [])
                    if str(x or "").strip()
                }
            )
            norm_dates = sorted(
                {
                    str(x or "").strip()
                    for x in self._normalize_json_list(post_dates)
                    if str(x or "").strip()
                }
            )
            return (
                tuple(norm_pids),
                str(comment or "").strip(),
                bool(not_relevant),
                tuple(norm_dates),
            )

        def _schedule_group_signature(row: dict) -> tuple:
            product_ids = sorted(
                {
                    str(x or "").strip()
                    for x in self._normalize_json_list((row or {}).get("product_ids"))
                    if str(x or "").strip()
                }
            )
            return (
                str((row or {}).get("category_id") or "").strip(),
                str((row or {}).get("item_type") or "product").strip() or "product",
                str((row or {}).get("display_mode") or "name").strip() or "name",
                str((row or {}).get("display_label") or "").strip(),
                tuple(product_ids),
                _canon_json(
                    self._normalize_json_dict((row or {}).get("level_node_ids"))
                ),
            )

        source_product_ids = [
            str(row.get("id"))
            for row in source_products
            if str(row.get("id") or "").strip()
        ]
        source_supplier_ids = {
            str((_json_dict(row.get("data")).get("supplier_id") or "")).strip()
            for row in source_products
        }
        source_supplier_ids.discard("")
        source_packaging_ids = {
            str((_json_dict(row.get("data")).get("packaging_id") or "")).strip()
            for row in source_products
        }
        source_packaging_ids.discard("")

        now = self._now_ts()
        supplier_map: dict[str, str] = {}
        packaging_map: dict[str, str] = {}
        product_map: dict[str, str] = {}
        order_map: dict[str, str] = {}
        schedule_group_map: dict[str, str] = {}
        packaging_context_map: dict[str, str] = {}

        with self._pg().cursor() as cur:
            supplier_rows: list[dict] = []
            if source_supplier_ids:
                cur.execute(
                    """
                    SELECT id, company_id, region_id, manager_id, name, data, created_at, updated_at
                    FROM suppliers
                    WHERE company_id=%s AND id = ANY(%s)
                    ORDER BY updated_at DESC, created_at DESC, id ASC
                    """,
                    (cid, list(source_supplier_ids)),
                )
                supplier_rows = [
                    r for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]

            for row in supplier_rows:
                source_id = str(row.get("id") or "").strip()
                source_data = dict(_json_dict(row.get("data")))
                target_region_id = str(row.get("region_id") or "").strip()
                target_name = str(row.get("name") or "").strip() or "Постачальник"
                target_data = dict(source_data)
                target_data.update(
                    {
                        "company_id": cid,
                        "region_id": target_region_id,
                        "manager_id": target_mid,
                        "name": target_name,
                    }
                )
                cur.execute(
                    """
                    SELECT id FROM suppliers
                    WHERE company_id=%s AND region_id=%s AND manager_id=%s
                      AND lower(trim(name))=lower(trim(%s))
                    LIMIT 1
                    """,
                    (
                        cid,
                        target_region_id,
                        target_mid,
                        target_name,
                    ),
                )
                existing = cur.fetchone() or {}
                target_id = str(existing.get("id") or "").strip()
                if not target_id:
                    target_id = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO suppliers
                          (id, company_id, region_id, manager_id, name, data, created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                        """,
                        (
                            target_id,
                            cid,
                            target_region_id,
                            target_mid,
                            target_name,
                            psycopg.types.json.Jsonb(target_data),
                            now,
                            now,
                        ),
                    )
                    result["suppliers"] += 1
                supplier_map[source_id] = target_id

            packaging_rows: list[dict] = []
            if source_packaging_ids:
                cur.execute(
                    """
                    SELECT id, company_id, region_id, manager_id, name, data, created_at, updated_at
                    FROM packaging
                    WHERE company_id=%s AND id = ANY(%s)
                    ORDER BY updated_at DESC, created_at DESC, id ASC
                    """,
                    (cid, list(source_packaging_ids)),
                )
                packaging_rows = [
                    r for r in (cur.fetchall() or []) if isinstance(r, dict)
                ]

            for row in packaging_rows:
                source_id = str(row.get("id") or "").strip()
                source_data = dict(_json_dict(row.get("data")))
                source_supplier_id = str(source_data.get("supplier_id") or "").strip()
                target_supplier_id = supplier_map.get(
                    source_supplier_id, source_supplier_id
                )
                target_region_id = str(row.get("region_id") or "").strip()
                target_name = str(row.get("name") or "").strip() or "Пакування"
                target_data = dict(source_data)
                target_data.update(
                    {
                        "company_id": cid,
                        "region_id": target_region_id,
                        "manager_id": target_mid,
                        "name": target_name,
                        "supplier_id": target_supplier_id,
                    }
                )
                cur.execute(
                    """
                    SELECT id FROM packaging
                    WHERE company_id=%s AND region_id=%s AND manager_id=%s
                      AND lower(trim(name))=lower(trim(%s))
                                            AND COALESCE(data->>'supplier_id','')=%s
                    LIMIT 1
                    """,
                    (
                        cid,
                        target_region_id,
                        target_mid,
                        target_name,
                        target_supplier_id,
                    ),
                )
                existing = cur.fetchone() or {}
                target_id = str(existing.get("id") or "").strip()
                if not target_id:
                    target_id = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO packaging
                          (id, company_id, region_id, manager_id, name, data, created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                        """,
                        (
                            target_id,
                            cid,
                            target_region_id,
                            target_mid,
                            target_name,
                            psycopg.types.json.Jsonb(target_data),
                            now,
                            now,
                        ),
                    )
                    result["packaging"] += 1
                packaging_map[source_id] = target_id

            for row in source_products:
                source_id = str(row.get("id") or "").strip()
                source_data = dict(_json_dict(row.get("data")))
                target_region_id = str(row.get("region_id") or "").strip()
                target_name = str(row.get("name") or "").strip()
                target_data = dict(source_data)
                source_supplier_id = str(source_data.get("supplier_id") or "").strip()
                source_packaging_id = str(source_data.get("packaging_id") or "").strip()
                if source_supplier_id:
                    target_data["supplier_id"] = supplier_map.get(
                        source_supplier_id, source_supplier_id
                    )
                if source_packaging_id:
                    target_data["packaging_id"] = packaging_map.get(
                        source_packaging_id, source_packaging_id
                    )
                target_data.update(
                    {
                        "company_id": cid,
                        "region_id": target_region_id,
                        "manager_id": target_mid,
                        "name": target_name,
                    }
                )
                production_term_days = row.get("production_term_days")
                cur.execute(
                    """
                    SELECT id FROM products
                    WHERE company_id=%s AND region_id=%s AND manager_id=%s
                      AND lower(trim(name))=lower(trim(%s))
                                            AND COALESCE(data->>'category_id','')=%s
                                            AND COALESCE(data->>'catalog_node_id','')=%s
                                            AND COALESCE(data->>'supplier_id','')=%s
                    LIMIT 1
                    """,
                    (
                        cid,
                        target_region_id,
                        target_mid,
                        target_name,
                        str(target_data.get("category_id") or "").strip(),
                        str(target_data.get("catalog_node_id") or "").strip(),
                        str(target_data.get("supplier_id") or "").strip(),
                    ),
                )
                existing = cur.fetchone() or {}
                target_id = str(existing.get("id") or "").strip()
                if not target_id:
                    target_id = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO products
                          (id, company_id, region_id, manager_id, name, production_term_days, data, created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                        """,
                        (
                            target_id,
                            cid,
                            target_region_id,
                            target_mid,
                            target_name,
                            production_term_days,
                            psycopg.types.json.Jsonb(target_data),
                            now,
                            now,
                        ),
                    )
                    result["products"] += 1
                product_map[source_id] = target_id

            order_query = """
                SELECT id, company_id, region_id, manager_id, supplier_id, data, created_at, updated_at
                FROM orders o
                WHERE o.company_id=%s
                  AND EXISTS (
                      SELECT 1
                      FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) AS it
                      WHERE (it->>'product_id') = ANY(%s)
                  )
            """
            order_params: list[Any] = [cid, source_product_ids]
            if source_mid:
                order_query += " AND o.manager_id=%s"
                order_params.append(source_mid)
            order_query += " ORDER BY o.updated_at DESC, o.created_at DESC, o.id ASC"
            cur.execute(order_query, order_params)
            order_rows = [r for r in (cur.fetchall() or []) if isinstance(r, dict)]
            source_order_ids: list[str] = []
            for row in order_rows:
                source_order_id = str(row.get("id") or "").strip()
                source_data = dict(_json_dict(row.get("data")))
                source_items = _json_list(source_data.get("items"))
                filtered_items = []
                for item in source_items:
                    if not isinstance(item, dict):
                        continue
                    source_product_id = str(item.get("product_id") or "").strip()
                    target_product_id = product_map.get(source_product_id)
                    if not target_product_id:
                        continue
                    target_item = dict(item)
                    target_item["product_id"] = target_product_id
                    source_item_supplier = str(item.get("supplier_id") or "").strip()
                    if source_item_supplier:
                        target_item["supplier_id"] = supplier_map.get(
                            source_item_supplier, source_item_supplier
                        )
                    filtered_items.append(target_item)
                if not filtered_items:
                    continue
                target_data = dict(source_data)
                target_data["items"] = filtered_items
                source_order_supplier = str(row.get("supplier_id") or "").strip()
                if source_order_supplier:
                    target_data["supplier_id"] = supplier_map.get(
                        source_order_supplier, source_order_supplier
                    )
                target_supplier_id = supplier_map.get(
                    source_order_supplier, source_order_supplier
                )
                target_region_id = str(row.get("region_id") or "").strip()
                target_order_id = ""
                target_sig = _order_signature(target_data)
                cur.execute(
                    """
                    SELECT id, data FROM orders
                    WHERE company_id=%s AND region_id=%s AND manager_id=%s
                      AND supplier_id=%s
                    ORDER BY updated_at DESC, created_at DESC, id ASC
                    """,
                    (
                        cid,
                        target_region_id,
                        target_mid,
                        target_supplier_id,
                    ),
                )
                for existing in cur.fetchall() or []:
                    if not isinstance(existing, dict):
                        continue
                    if _order_signature(existing.get("data")) != target_sig:
                        continue
                    target_order_id = str(existing.get("id") or "").strip()
                    if target_order_id:
                        break
                if not target_order_id:
                    target_order_id = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO orders
                          (id, company_id, region_id, manager_id, supplier_id, data, created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                        """,
                        (
                            target_order_id,
                            cid,
                            target_region_id,
                            target_mid,
                            target_supplier_id,
                            psycopg.types.json.Jsonb(target_data),
                            now,
                            now,
                        ),
                    )
                    result["orders"] += 1
                order_map[source_order_id] = target_order_id
                source_order_ids.append(source_order_id)

            if source_product_ids:
                stock_query = """
                    SELECT product_id, region_id, qty, amount, amount_ccy, new_price, new_price_ccy
                    FROM cost_price_stock_inputs
                    WHERE company_id=%s AND product_id = ANY(%s)
                """
                stock_params: list[Any] = [cid, source_product_ids]
                if source_mid:
                    stock_query += " AND manager_id=%s"
                    stock_params.append(source_mid)
                cur.execute(stock_query, stock_params)
                stock_rows = []
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    source_product_id = str(row.get("product_id") or "").strip()
                    target_product_id = product_map.get(source_product_id)
                    if not target_product_id:
                        continue
                    stock_rows.append(
                        (
                            cid,
                            target_mid,
                            str(row.get("region_id") or "").strip(),
                            target_product_id,
                            row.get("qty"),
                            row.get("amount"),
                            str(row.get("amount_ccy") or "USD").upper().strip()
                            or "USD",
                            row.get("new_price"),
                            str(row.get("new_price_ccy") or "USD").upper().strip()
                            or "USD",
                            now,
                        )
                    )
                # Batched multi-row upsert instead of one execute() per
                # product — copying a manager's scope can cover hundreds.
                CHUNK = 500
                for i in range(0, len(stock_rows), CHUNK):
                    chunk = stock_rows[i : i + CHUNK]
                    placeholders = ", ".join(["(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)"] * len(chunk))
                    flat_params = [v for row_ in chunk for v in row_]
                    cur.execute(
                        f"""
                        INSERT INTO cost_price_stock_inputs
                            (company_id, manager_id, region_id, product_id, qty, amount, amount_ccy, new_price, new_price_ccy, updated_at)
                        VALUES {placeholders}
                        ON CONFLICT (company_id, manager_id, region_id, product_id)
                        DO UPDATE SET
                            qty = COALESCE(EXCLUDED.qty, cost_price_stock_inputs.qty),
                            amount = COALESCE(EXCLUDED.amount, cost_price_stock_inputs.amount),
                            amount_ccy = COALESCE(NULLIF(EXCLUDED.amount_ccy, ''), cost_price_stock_inputs.amount_ccy),
                            new_price = COALESCE(EXCLUDED.new_price, cost_price_stock_inputs.new_price),
                            new_price_ccy = COALESCE(NULLIF(EXCLUDED.new_price_ccy, ''), cost_price_stock_inputs.new_price_ccy),
                            updated_at = EXCLUDED.updated_at
                        """,
                        flat_params,
                    )
                result["cost_stock"] += len(stock_rows)

            if source_order_ids:
                order_input_query = """
                    SELECT order_id, region_id, line_idx, unit_cost_usd, unit_cost_currency, new_price, new_price_ccy
                    FROM cost_price_order_inputs
                    WHERE company_id=%s AND order_id = ANY(%s)
                """
                order_input_params: list[Any] = [cid, source_order_ids]
                if source_mid:
                    order_input_query += " AND manager_id=%s"
                    order_input_params.append(source_mid)
                cur.execute(order_input_query, order_input_params)
                order_input_rows = []
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    source_order_id = str(row.get("order_id") or "").strip()
                    target_order_id = order_map.get(source_order_id)
                    if not target_order_id:
                        continue
                    order_input_rows.append(
                        (
                            cid,
                            target_mid,
                            str(row.get("region_id") or "").strip(),
                            target_order_id,
                            int(row.get("line_idx") or 0),
                            row.get("unit_cost_usd"),
                            str(row.get("unit_cost_currency") or "USD").upper().strip()
                            or "USD",
                            row.get("new_price"),
                            str(row.get("new_price_ccy") or "USD").upper().strip()
                            or "USD",
                            now,
                        )
                    )
                # Batched multi-row upsert instead of one execute() per
                # order line.
                CHUNK = 500
                for i in range(0, len(order_input_rows), CHUNK):
                    chunk = order_input_rows[i : i + CHUNK]
                    placeholders = ", ".join(["(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)"] * len(chunk))
                    flat_params = [v for row_ in chunk for v in row_]
                    cur.execute(
                        f"""
                        INSERT INTO cost_price_order_inputs
                            (company_id, manager_id, region_id, order_id, line_idx, unit_cost_usd, unit_cost_currency, new_price, new_price_ccy, updated_at)
                        VALUES {placeholders}
                        ON CONFLICT (company_id, manager_id, region_id, order_id, line_idx)
                        DO UPDATE SET
                            unit_cost_usd = COALESCE(EXCLUDED.unit_cost_usd, cost_price_order_inputs.unit_cost_usd),
                            unit_cost_currency = COALESCE(NULLIF(EXCLUDED.unit_cost_currency, ''), cost_price_order_inputs.unit_cost_currency),
                            new_price = COALESCE(EXCLUDED.new_price, cost_price_order_inputs.new_price),
                            new_price_ccy = COALESCE(NULLIF(EXCLUDED.new_price_ccy, ''), cost_price_order_inputs.new_price_ccy),
                            updated_at = EXCLUDED.updated_at
                        """,
                        flat_params,
                    )
                result["cost_orders"] += len(order_input_rows)

            media_query = """
                SELECT id, company_id, manager_id, region_id, product_ids, product_names,
                       comment, not_relevant, post_dates, created_at, updated_at
                FROM media_plan_entries
                WHERE company_id=%s AND product_ids ?| %s
            """
            media_params: list[Any] = [cid, source_product_ids]
            if source_mid:
                media_query += " AND manager_id=%s"
                media_params.append(source_mid)
            media_query += " ORDER BY created_at ASC, id ASC"
            with contextlib.suppress(Exception):
                cur.execute(media_query, media_params)
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    src_pids = _json_list(row.get("product_ids"))
                    src_names = _json_list(row.get("product_names"))
                    target_pids = []
                    target_names = []
                    for idx, source_product_id in enumerate(src_pids):
                        mapped_id = product_map.get(
                            str(source_product_id or "").strip()
                        )
                        if not mapped_id:
                            continue
                        target_pids.append(mapped_id)
                        target_names.append(
                            src_names[idx]
                            if idx < len(src_names)
                            else src_names[-1] if src_names else ""
                        )
                    if not target_pids:
                        continue
                    target_post_dates = self._normalize_json_list(row.get("post_dates"))
                    target_region_id = str(row.get("region_id") or "").strip()
                    target_media_sig = _media_signature(
                        target_pids,
                        str(row.get("comment") or ""),
                        bool(row.get("not_relevant", False)),
                        target_post_dates,
                    )
                    exists = False
                    cur.execute(
                        """
                        SELECT id, product_ids, comment, not_relevant, post_dates
                        FROM media_plan_entries
                        WHERE company_id=%s AND manager_id=%s AND region_id=%s
                        ORDER BY created_at ASC, id ASC
                        """,
                        (cid, target_mid, target_region_id),
                    )
                    for existing in cur.fetchall() or []:
                        if not isinstance(existing, dict):
                            continue
                        existing_sig = _media_signature(
                            self._normalize_json_list(existing.get("product_ids")),
                            str(existing.get("comment") or ""),
                            bool(existing.get("not_relevant", False)),
                            self._normalize_json_list(existing.get("post_dates")),
                        )
                        if existing_sig == target_media_sig:
                            exists = True
                            break
                    if exists:
                        continue
                    cur.execute(
                        """
                        INSERT INTO media_plan_entries
                          (id, company_id, manager_id, region_id,
                           product_ids, product_names, comment, not_relevant, post_dates,
                           created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                        """,
                        (
                            uuid.uuid4().hex,
                            cid,
                            target_mid,
                            target_region_id,
                            psycopg.types.json.Jsonb(target_pids),
                            psycopg.types.json.Jsonb(target_names),
                            str(row.get("comment") or ""),
                            bool(row.get("not_relevant", False)),
                            psycopg.types.json.Jsonb(target_post_dates),
                            now,
                            now,
                        ),
                    )
                    result["media_plan"] += 1

            group_query = """
                SELECT id, company_id, manager_id, region_id, category_id,
                       item_type, display_mode, display_label,
                       product_ids, product_names, level_node_ids,
                       created_at, updated_at
                FROM order_schedule_groups
                WHERE company_id=%s AND product_ids ?| %s
            """
            group_params: list[Any] = [cid, source_product_ids]
            if source_mid:
                group_query += " AND manager_id=%s"
                group_params.append(source_mid)
            group_query += " ORDER BY created_at ASC, id ASC"
            with contextlib.suppress(Exception):
                cur.execute(group_query, group_params)
                group_rows = [r for r in (cur.fetchall() or []) if isinstance(r, dict)]
            source_group_ids: list[str] = []
            for row in group_rows:
                src_pids = self._normalize_json_list(row.get("product_ids"))
                src_names = self._normalize_json_list(row.get("product_names"))
                target_pids = []
                target_names = []
                for idx, source_product_id in enumerate(src_pids):
                    mapped_id = product_map.get(str(source_product_id or "").strip())
                    if not mapped_id:
                        continue
                    target_pids.append(mapped_id)
                    target_names.append(
                        src_names[idx]
                        if idx < len(src_names)
                        else src_names[-1] if src_names else ""
                    )
                if not target_pids:
                    continue
                level_node_ids = self._normalize_json_dict(row.get("level_node_ids"))
                target_region_id = str(row.get("region_id") or "").strip()
                target_group_id = ""
                target_group_sig = _schedule_group_signature(
                    {
                        "category_id": str(row.get("category_id") or "").strip(),
                        "item_type": str(row.get("item_type") or "product").strip()
                        or "product",
                        "display_mode": str(row.get("display_mode") or "name").strip()
                        or "name",
                        "display_label": str(row.get("display_label") or "").strip(),
                        "product_ids": target_pids,
                        "level_node_ids": level_node_ids,
                    }
                )
                cur.execute(
                    """
                    SELECT id, category_id, item_type, display_mode, display_label,
                           product_ids, level_node_ids
                    FROM order_schedule_groups
                    WHERE company_id=%s AND manager_id=%s AND region_id=%s
                    ORDER BY created_at ASC, id ASC
                    """,
                    (cid, target_mid, target_region_id),
                )
                for existing in cur.fetchall() or []:
                    if not isinstance(existing, dict):
                        continue
                    existing_sig = _schedule_group_signature(existing)
                    if existing_sig != target_group_sig:
                        continue
                    target_group_id = str(existing.get("id") or "").strip()
                    if target_group_id:
                        break
                if not target_group_id:
                    target_group_id = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO order_schedule_groups
                          (id, company_id, manager_id, region_id, category_id,
                           item_type, display_mode, display_label,
                           product_ids, product_names, level_node_ids,
                           created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                        """,
                        (
                            target_group_id,
                            cid,
                            target_mid,
                            target_region_id,
                            str(row.get("category_id") or "").strip(),
                            str(row.get("item_type") or "product").strip() or "product",
                            str(row.get("display_mode") or "name").strip() or "name",
                            str(row.get("display_label") or "").strip(),
                            psycopg.types.json.Jsonb(target_pids),
                            psycopg.types.json.Jsonb(target_names),
                            psycopg.types.json.Jsonb(level_node_ids),
                            now,
                            now,
                        ),
                    )
                    result["schedule_groups"] += 1
                source_group_id = str(row.get("id") or "").strip()
                schedule_group_map[source_group_id] = target_group_id
                source_group_ids.append(source_group_id)

            if source_group_ids:
                task_query = """
                    SELECT id, group_id, company_id, manager_id, region_id,
                           month_anchor, date_from, date_to,
                           planned_qty, planned_amount, planned_currency, planned_amount_usd,
                           actual_qty, actual_amount, actual_currency, actual_amount_usd,
                           delivery_type_id, delivery_type_name,
                           status, archived, sort_index, created_at, updated_at
                    FROM order_schedule_tasks
                    WHERE company_id=%s AND group_id = ANY(%s)
                """
                task_params: list[Any] = [cid, source_group_ids]
                if source_mid:
                    task_query += " AND manager_id=%s"
                    task_params.append(source_mid)
                task_query += " ORDER BY month_anchor ASC, sort_index ASC, id ASC"
                cur.execute(task_query, task_params)
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    target_group_id = schedule_group_map.get(
                        str(row.get("group_id") or "").strip()
                    )
                    if not target_group_id:
                        continue
                    target_region_id = str(row.get("region_id") or "").strip()
                    cur.execute(
                        """
                        SELECT id FROM order_schedule_tasks
                        WHERE group_id=%s AND company_id=%s AND manager_id=%s AND region_id=%s
                          AND month_anchor=%s AND date_from IS NOT DISTINCT FROM %s
                          AND date_to IS NOT DISTINCT FROM %s AND planned_qty IS NOT DISTINCT FROM %s
                          AND planned_amount IS NOT DISTINCT FROM %s AND planned_currency=%s
                          AND planned_amount_usd IS NOT DISTINCT FROM %s AND actual_qty IS NOT DISTINCT FROM %s
                          AND actual_amount IS NOT DISTINCT FROM %s AND actual_currency=%s
                          AND actual_amount_usd IS NOT DISTINCT FROM %s AND delivery_type_id=%s
                          AND delivery_type_name=%s AND status=%s AND archived=%s AND sort_index=%s
                        LIMIT 1
                        """,
                        (
                            target_group_id,
                            cid,
                            target_mid,
                            target_region_id,
                            row.get("month_anchor"),
                            row.get("date_from"),
                            row.get("date_to"),
                            row.get("planned_qty"),
                            row.get("planned_amount"),
                            str(row.get("planned_currency") or "USD").strip() or "USD",
                            row.get("planned_amount_usd"),
                            row.get("actual_qty"),
                            row.get("actual_amount"),
                            str(row.get("actual_currency") or "USD").strip() or "USD",
                            row.get("actual_amount_usd"),
                            str(row.get("delivery_type_id") or "").strip(),
                            str(row.get("delivery_type_name") or "").strip(),
                            str(row.get("status") or "not_ordered").strip()
                            or "not_ordered",
                            bool(row.get("archived", False)),
                            int(row.get("sort_index") or 0),
                        ),
                    )
                    existing = cur.fetchone() or {}
                    if str(existing.get("id") or "").strip():
                        continue
                    cur.execute(
                        """
                        INSERT INTO order_schedule_tasks
                          (id, group_id, company_id, manager_id, region_id,
                           month_anchor, date_from, date_to,
                           planned_qty, planned_amount, planned_currency, planned_amount_usd,
                           actual_qty, actual_amount, actual_currency, actual_amount_usd,
                           delivery_type_id, delivery_type_name,
                           status, archived, sort_index, created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                        """,
                        (
                            uuid.uuid4().hex,
                            target_group_id,
                            cid,
                            target_mid,
                            target_region_id,
                            row.get("month_anchor"),
                            row.get("date_from"),
                            row.get("date_to"),
                            row.get("planned_qty"),
                            row.get("planned_amount"),
                            str(row.get("planned_currency") or "USD").strip() or "USD",
                            row.get("planned_amount_usd"),
                            row.get("actual_qty"),
                            row.get("actual_amount"),
                            str(row.get("actual_currency") or "USD").strip() or "USD",
                            row.get("actual_amount_usd"),
                            str(row.get("delivery_type_id") or "").strip(),
                            str(row.get("delivery_type_name") or "").strip(),
                            str(row.get("status") or "not_ordered").strip()
                            or "not_ordered",
                            bool(row.get("archived", False)),
                            int(row.get("sort_index") or 0),
                            now,
                            now,
                        ),
                    )
                    result["schedule_tasks"] += 1

            with contextlib.suppress(Exception):
                cur.execute(
                    """
                    SELECT column_name
                    FROM information_schema.columns
                    WHERE table_schema='public' AND table_name='supplier_settlements'
                    """,
                )
                settlement_cols = {
                    str(r.get("column_name") or "")
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict)
                }
                has_manager = "manager_id" in settlement_cols
                has_type = "type" in settlement_cols
                has_note = "note" in settlement_cols
                has_comment = "comment" in settlement_cols
                has_data = "data" in settlement_cols
                has_ts = "ts" in settlement_cols
                if source_supplier_ids:
                    settlement_query = [
                        "SELECT * FROM supplier_settlements WHERE company_id=%s AND supplier_id = ANY(%s)"
                    ]
                    settlement_params: list[Any] = [cid, list(source_supplier_ids)]
                    if source_mid and has_manager:
                        settlement_query.append("AND manager_id=%s")
                        settlement_params.append(source_mid)
                    cur.execute(" ".join(settlement_query), settlement_params)
                    for row in cur.fetchall() or []:
                        if not isinstance(row, dict):
                            continue
                        source_supplier_id = str(row.get("supplier_id") or "").strip()
                        target_supplier_id = supplier_map.get(source_supplier_id)
                        if not target_supplier_id:
                            continue
                        target_region_id = str(row.get("region_id") or "").strip()
                        target_comment = str(
                            row.get("comment") or row.get("note") or ""
                        ).strip()
                        target_currency = str(row.get("currency") or "").upper().strip()
                        target_data = (
                            dict(_json_dict(row.get("data"))) if has_data else {}
                        )
                        if target_data.get("product_id"):
                            mapped_product_id = product_map.get(
                                str(target_data.get("product_id") or "").strip()
                            )
                            if mapped_product_id:
                                target_data["product_id"] = mapped_product_id
                        if target_data.get("supplier_id"):
                            target_data["supplier_id"] = target_supplier_id
                        existing_sql = [
                            "SELECT id FROM supplier_settlements WHERE company_id=%s AND region_id=%s AND supplier_id=%s AND amount IS NOT DISTINCT FROM %s AND currency=%s"
                        ]
                        existing_params: list[Any] = [
                            cid,
                            target_region_id,
                            target_supplier_id,
                            row.get("amount"),
                            target_currency,
                        ]
                        if has_manager:
                            existing_sql.append("AND manager_id=%s")
                            existing_params.append(target_mid)
                        if has_type:
                            existing_sql.append("AND type=%s")
                            existing_params.append(
                                str(row.get("type") or "opening_balance")
                            )
                        if has_ts:
                            existing_sql.append("AND ts=%s")
                            existing_params.append(row.get("ts"))
                        if has_note:
                            existing_sql.append("AND note=%s")
                            existing_params.append(target_comment)
                        if has_comment:
                            existing_sql.append("AND comment=%s")
                            existing_params.append(target_comment)
                        if has_data:
                            existing_sql.append("AND data=%s::jsonb")
                            existing_params.append(
                                psycopg.types.json.Jsonb(target_data)
                            )
                        existing_sql.append("LIMIT 1")
                        cur.execute(" ".join(existing_sql), existing_params)
                        existing = cur.fetchone() or {}
                        if str(existing.get("id") or "").strip():
                            continue
                        cols = [
                            "id",
                            "company_id",
                            "region_id",
                            "supplier_id",
                            "amount",
                            "currency",
                        ]
                        vals: list[Any] = [
                            uuid.uuid4().hex,
                            cid,
                            target_region_id,
                            target_supplier_id,
                            row.get("amount"),
                            target_currency,
                        ]
                        if has_manager:
                            cols.append("manager_id")
                            vals.append(target_mid)
                        if has_type:
                            cols.append("type")
                            vals.append(str(row.get("type") or "opening_balance"))
                        if has_note:
                            cols.append("note")
                            vals.append(target_comment)
                        if has_comment:
                            cols.append("comment")
                            vals.append(target_comment)
                        if has_data:
                            cols.append("data")
                            vals.append(psycopg.types.json.Jsonb(target_data))
                        if has_ts:
                            cols.append("ts")
                            vals.append(row.get("ts") or now)
                        cols.extend(["created_at", "updated_at"])
                        vals.extend([now, now])
                        cur.execute(
                            f"INSERT INTO supplier_settlements ({', '.join(cols)}) VALUES ({', '.join(['%s'] * len(cols))})",
                            vals,
                        )
                        result["payments"] += 1

            with contextlib.suppress(Exception):
                self._pg_with_packaging_supply_schema()
                if source_packaging_ids and source_supplier_ids:
                    cur.execute(
                        """
                        SELECT id, company_id, region_id, packaging_id, packaging_supplier_id,
                               goods_supplier_id, linked_product_ids, updated_at
                        FROM packaging_supply_contexts
                        WHERE company_id=%s
                          AND packaging_id = ANY(%s)
                          AND goods_supplier_id = ANY(%s)
                        ORDER BY id ASC
                        """,
                        (cid, list(source_packaging_ids), list(source_supplier_ids)),
                    )
                    source_context_rows = [
                        r for r in (cur.fetchall() or []) if isinstance(r, dict)
                    ]
                    for row in source_context_rows:
                        source_context_id = str(row.get("id") or "").strip()
                        target_packaging_id = packaging_map.get(
                            str(row.get("packaging_id") or "").strip()
                        )
                        target_goods_supplier_id = supplier_map.get(
                            str(row.get("goods_supplier_id") or "").strip()
                        )
                        if not target_packaging_id or not target_goods_supplier_id:
                            continue
                        linked_target_product_ids = [
                            product_map.get(str(product_id or "").strip())
                            for product_id in self._normalize_json_list(
                                row.get("linked_product_ids")
                            )
                        ]
                        linked_target_product_ids = [
                            pid for pid in linked_target_product_ids if pid
                        ]
                        if not linked_target_product_ids:
                            continue
                        target_region_id = str(row.get("region_id") or "").strip()
                        cur.execute(
                            """
                            SELECT id, linked_product_ids
                            FROM packaging_supply_contexts
                            WHERE company_id=%s AND region_id=%s AND packaging_id=%s AND goods_supplier_id=%s
                            LIMIT 1
                            """,
                            (
                                cid,
                                target_region_id,
                                target_packaging_id,
                                target_goods_supplier_id,
                            ),
                        )
                        existing = cur.fetchone() or {}
                        target_context_id = str(existing.get("id") or "").strip()
                        merged_linked_ids = sorted(
                            {
                                str(x)
                                for x in (
                                    self._normalize_json_list(
                                        existing.get("linked_product_ids")
                                    )
                                    + linked_target_product_ids
                                )
                                if str(x).strip()
                            }
                        )
                        target_packaging_supplier_id = supplier_map.get(
                            str(row.get("packaging_supplier_id") or "").strip(),
                            str(row.get("packaging_supplier_id") or "").strip(),
                        )
                        if target_context_id:
                            cur.execute(
                                """
                                UPDATE packaging_supply_contexts
                                   SET packaging_supplier_id=%s,
                                       linked_product_ids=%s::jsonb,
                                       updated_at=%s
                                 WHERE id=%s
                                """,
                                (
                                    target_packaging_supplier_id,
                                    psycopg.types.json.Jsonb(merged_linked_ids),
                                    now,
                                    target_context_id,
                                ),
                            )
                        else:
                            target_context_id = uuid.uuid4().hex
                            cur.execute(
                                """
                                INSERT INTO packaging_supply_contexts
                                  (id, company_id, region_id, packaging_id, packaging_supplier_id, goods_supplier_id, linked_product_ids, updated_at)
                                VALUES (%s,%s,%s,%s,%s,%s,%s::jsonb,%s)
                                """,
                                (
                                    target_context_id,
                                    cid,
                                    target_region_id,
                                    target_packaging_id,
                                    target_packaging_supplier_id,
                                    target_goods_supplier_id,
                                    psycopg.types.json.Jsonb(merged_linked_ids),
                                    now,
                                ),
                            )
                            result["packaging_contexts"] += 1
                        packaging_context_map[source_context_id] = target_context_id

                    if packaging_context_map:
                        cur.execute(
                            """
                            SELECT context_id, stock_packaging_supplier_qty, stock_goods_supplier_qty,
                                   balance_amount, balance_currency, opening_shipped_goods_qty,
                                   balance_paid_amount, updated_at
                            FROM packaging_supply_openings
                            WHERE context_id = ANY(%s)
                            """,
                            (list(packaging_context_map.keys()),),
                        )
                        for row in cur.fetchall() or []:
                            if not isinstance(row, dict):
                                continue
                            target_context_id = packaging_context_map.get(
                                str(row.get("context_id") or "").strip()
                            )
                            if not target_context_id:
                                continue
                            cur.execute(
                                """
                                INSERT INTO packaging_supply_openings
                                  (context_id, stock_packaging_supplier_qty, stock_goods_supplier_qty,
                                   balance_amount, balance_currency, opening_shipped_goods_qty,
                                   balance_paid_amount, updated_at)
                                VALUES (%s,%s,%s,%s,%s,%s,%s,%s)
                                ON CONFLICT (context_id) DO UPDATE SET
                                  stock_packaging_supplier_qty=EXCLUDED.stock_packaging_supplier_qty,
                                  stock_goods_supplier_qty=EXCLUDED.stock_goods_supplier_qty,
                                  balance_amount=EXCLUDED.balance_amount,
                                  balance_currency=EXCLUDED.balance_currency,
                                  opening_shipped_goods_qty=EXCLUDED.opening_shipped_goods_qty,
                                  balance_paid_amount=EXCLUDED.balance_paid_amount,
                                  updated_at=EXCLUDED.updated_at
                                """,
                                (
                                    target_context_id,
                                    row.get("stock_packaging_supplier_qty"),
                                    row.get("stock_goods_supplier_qty"),
                                    row.get("balance_amount"),
                                    str(row.get("balance_currency") or "USD")
                                    .upper()
                                    .strip()
                                    or "USD",
                                    row.get("opening_shipped_goods_qty"),
                                    row.get("balance_paid_amount"),
                                    now,
                                ),
                            )
                            result["packaging_openings"] += 1

                        cur.execute(
                            """
                            SELECT id, context_id, seq_no, order_date, invoice_no, invoice_date,
                                   eta_date, shipped_packaging_supplier_qty, shipped_goods_supplier_qty,
                                   payment_amount, payment_currency, row_kind, row_label,
                                   goods_supplier_payment_amount, goods_supplier_payment_ccy,
                                   linked_order_id, source_kind, meta, created_at, updated_at
                            FROM packaging_supply_orders
                            WHERE context_id = ANY(%s)
                            ORDER BY order_date ASC, seq_no ASC, id ASC
                            """,
                            (list(packaging_context_map.keys()),),
                        )
                        for row in cur.fetchall() or []:
                            if not isinstance(row, dict):
                                continue
                            target_context_id = packaging_context_map.get(
                                str(row.get("context_id") or "").strip()
                            )
                            if not target_context_id:
                                continue
                            linked_order_id = order_map.get(
                                str(row.get("linked_order_id") or "").strip(),
                                str(row.get("linked_order_id") or "").strip(),
                            )
                            target_meta = dict(_json_dict(row.get("meta")))
                            if target_meta.get("linked_order_id"):
                                target_meta["linked_order_id"] = linked_order_id
                            cur.execute(
                                """
                                SELECT id FROM packaging_supply_orders
                                WHERE context_id=%s AND seq_no=%s AND order_date IS NOT DISTINCT FROM %s
                                  AND invoice_no=%s AND invoice_date IS NOT DISTINCT FROM %s
                                  AND eta_date IS NOT DISTINCT FROM %s
                                  AND shipped_packaging_supplier_qty IS NOT DISTINCT FROM %s
                                  AND shipped_goods_supplier_qty IS NOT DISTINCT FROM %s
                                  AND payment_amount IS NOT DISTINCT FROM %s AND payment_currency=%s
                                  AND row_kind=%s AND row_label=%s
                                  AND goods_supplier_payment_amount IS NOT DISTINCT FROM %s
                                  AND goods_supplier_payment_ccy=%s
                                  AND linked_order_id=%s AND source_kind=%s AND meta=%s::jsonb
                                LIMIT 1
                                """,
                                (
                                    target_context_id,
                                    int(row.get("seq_no") or 0),
                                    row.get("order_date"),
                                    str(row.get("invoice_no") or "").strip(),
                                    row.get("invoice_date"),
                                    row.get("eta_date"),
                                    row.get("shipped_packaging_supplier_qty"),
                                    row.get("shipped_goods_supplier_qty"),
                                    row.get("payment_amount"),
                                    str(row.get("payment_currency") or "USD")
                                    .upper()
                                    .strip()
                                    or "USD",
                                    str(row.get("row_kind") or "supply").strip()
                                    or "supply",
                                    str(row.get("row_label") or "").strip(),
                                    row.get("goods_supplier_payment_amount"),
                                    str(row.get("goods_supplier_payment_ccy") or "USD")
                                    .upper()
                                    .strip()
                                    or "USD",
                                    linked_order_id,
                                    str(row.get("source_kind") or "").strip(),
                                    psycopg.types.json.Jsonb(target_meta),
                                ),
                            )
                            existing = cur.fetchone() or {}
                            if str(existing.get("id") or "").strip():
                                continue
                            cur.execute(
                                """
                                INSERT INTO packaging_supply_orders
                                  (id, context_id, seq_no, order_date, invoice_no, invoice_date,
                                   eta_date, shipped_packaging_supplier_qty, shipped_goods_supplier_qty,
                                   payment_amount, payment_currency, row_kind, row_label,
                                   goods_supplier_payment_amount, goods_supplier_payment_ccy,
                                   linked_order_id, source_kind, meta, created_at, updated_at)
                                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                                """,
                                (
                                    uuid.uuid4().hex,
                                    target_context_id,
                                    int(row.get("seq_no") or 0),
                                    row.get("order_date"),
                                    str(row.get("invoice_no") or "").strip(),
                                    row.get("invoice_date"),
                                    row.get("eta_date"),
                                    row.get("shipped_packaging_supplier_qty"),
                                    row.get("shipped_goods_supplier_qty"),
                                    row.get("payment_amount"),
                                    str(row.get("payment_currency") or "USD")
                                    .upper()
                                    .strip()
                                    or "USD",
                                    str(row.get("row_kind") or "supply").strip()
                                    or "supply",
                                    str(row.get("row_label") or "").strip(),
                                    row.get("goods_supplier_payment_amount"),
                                    str(row.get("goods_supplier_payment_ccy") or "USD")
                                    .upper()
                                    .strip()
                                    or "USD",
                                    linked_order_id,
                                    str(row.get("source_kind") or "").strip(),
                                    psycopg.types.json.Jsonb(target_meta),
                                    now,
                                    now,
                                ),
                            )
                            result["packaging_orders"] += 1

        if any(result.values()):
            for pulse_key in (
                "products",
                "suppliers",
                "packaging",
                "orders",
                "payments",
                "media_plan",
                "order_schedule",
            ):
                with contextlib.suppress(Exception):
                    self._pulse(cid, pulse_key)
        return result

    def _remove_manager_scope_data(
        self,
        manager_id: str,
        company_id: str,
        node_ids: list,
    ) -> dict:
        result = {
            "products_deleted": 0,
            "orders_deleted": 0,
            "orders_updated": 0,
            "media_deleted": 0,
            "media_updated": 0,
            "schedule_groups_deleted": 0,
            "schedule_groups_updated": 0,
            "schedule_tasks_deleted": 0,
            "cost_stock_deleted": 0,
            "cost_order_deleted": 0,
            "packaging_contexts_deleted": 0,
            "packaging_contexts_updated": 0,
            "suppliers_deleted": 0,
            "packaging_deleted": 0,
            "payments_deleted": 0,
        }
        if not self._use_postgres():
            return result
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        scope_ids = [str(x) for x in (node_ids or []) if str(x).strip()]
        if not mid or not cid or not scope_ids:
            return result

        scope_info = self._collect_scope_product_rows(
            cid, scope_ids, source_manager_id=mid
        )
        product_rows = [
            r for r in (scope_info.get("products") or []) if isinstance(r, dict)
        ]
        remove_product_ids = {
            str(r.get("id") or "").strip()
            for r in product_rows
            if str(r.get("id") or "").strip()
        }
        if not remove_product_ids:
            return result

        removed_supplier_ids = {
            str((r.get("data") or {}).get("supplier_id") or "").strip()
            for r in product_rows
            if isinstance(r.get("data"), dict)
        }
        removed_packaging_ids = {
            str((r.get("data") or {}).get("packaging_id") or "").strip()
            for r in product_rows
            if isinstance(r.get("data"), dict)
        }
        removed_supplier_ids.discard("")
        removed_packaging_ids.discard("")

        now = self._now_ts()
        remove_pid_list = list(remove_product_ids)

        def _map_pid_list(values: list[str]) -> tuple[list[str], bool]:
            changed = False
            out: list[str] = []
            seen: set[str] = set()
            for raw in values or []:
                pid = str(raw or "").strip()
                if not pid or pid in remove_product_ids:
                    changed = True
                    continue
                if pid in seen:
                    changed = True
                    continue
                seen.add(pid)
                out.append(pid)
            return out, changed

        with self._pg().cursor() as cur:
            # Orders: remove moved products from items; remove empty orders.
            cur.execute(
                """
                SELECT id, data
                FROM orders o
                WHERE o.company_id=%s AND o.manager_id=%s
                  AND EXISTS (
                      SELECT 1
                      FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) AS it
                      WHERE (it->>'product_id') = ANY(%s)
                  )
                """,
                (cid, mid, remove_pid_list),
            )
            touched_order_ids: list[str] = []
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                oid = str(row.get("id") or "").strip()
                data = self._normalize_json_dict(row.get("data"))
                items = self._normalize_json_list(data.get("items"))
                new_items = []
                changed = False
                for item in items:
                    if not isinstance(item, dict):
                        changed = True
                        continue
                    pid = str(item.get("product_id") or "").strip()
                    if pid in remove_product_ids:
                        changed = True
                        continue
                    new_items.append(item)
                if not changed:
                    continue
                touched_order_ids.append(oid)
                if not new_items:
                    cur.execute("DELETE FROM orders WHERE id=%s", (oid,))
                    result["orders_deleted"] += 1
                else:
                    data["items"] = new_items
                    cur.execute(
                        "UPDATE orders SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                        (psycopg.types.json.Jsonb(data), now, oid),
                    )
                    result["orders_updated"] += 1

            if touched_order_ids:
                cur.execute(
                    "DELETE FROM cost_price_order_inputs WHERE company_id=%s AND manager_id=%s AND order_id = ANY(%s)",
                    (cid, mid, touched_order_ids),
                )
                result["cost_order_deleted"] += int(cur.rowcount or 0)

            cur.execute(
                "DELETE FROM cost_price_stock_inputs WHERE company_id=%s AND manager_id=%s AND product_id = ANY(%s)",
                (cid, mid, remove_pid_list),
            )
            result["cost_stock_deleted"] += int(cur.rowcount or 0)

            cur.execute(
                """
                SELECT id, product_ids, product_names
                FROM media_plan_entries
                WHERE company_id=%s AND manager_id=%s AND product_ids ?| %s
                """,
                (cid, mid, remove_pid_list),
            )
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                eid = str(row.get("id") or "").strip()
                src_ids = self._normalize_json_list(row.get("product_ids"))
                src_names = self._normalize_json_list(row.get("product_names"))
                new_ids: list[str] = []
                new_names: list[str] = []
                seen: set[str] = set()
                changed = False
                for idx, raw_pid in enumerate(src_ids):
                    pid = str(raw_pid or "").strip()
                    if not pid or pid in remove_product_ids:
                        changed = True
                        continue
                    if pid in seen:
                        changed = True
                        continue
                    seen.add(pid)
                    new_ids.append(pid)
                    new_names.append(
                        str(src_names[idx] if idx < len(src_names) else "")
                    )
                if not changed:
                    continue
                if not new_ids:
                    cur.execute("DELETE FROM media_plan_entries WHERE id=%s", (eid,))
                    result["media_deleted"] += 1
                else:
                    cur.execute(
                        "UPDATE media_plan_entries SET product_ids=%s::jsonb, product_names=%s::jsonb, updated_at=%s WHERE id=%s",
                        (
                            psycopg.types.json.Jsonb(new_ids),
                            psycopg.types.json.Jsonb(new_names),
                            now,
                            eid,
                        ),
                    )
                    result["media_updated"] += 1

            cur.execute(
                """
                SELECT id, product_ids, product_names
                FROM order_schedule_groups
                WHERE company_id=%s AND manager_id=%s AND product_ids ?| %s
                """,
                (cid, mid, remove_pid_list),
            )
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                gid = str(row.get("id") or "").strip()
                src_ids = self._normalize_json_list(row.get("product_ids"))
                src_names = self._normalize_json_list(row.get("product_names"))
                new_ids: list[str] = []
                new_names: list[str] = []
                seen: set[str] = set()
                changed = False
                for idx, raw_pid in enumerate(src_ids):
                    pid = str(raw_pid or "").strip()
                    if not pid or pid in remove_product_ids:
                        changed = True
                        continue
                    if pid in seen:
                        changed = True
                        continue
                    seen.add(pid)
                    new_ids.append(pid)
                    new_names.append(
                        str(src_names[idx] if idx < len(src_names) else "")
                    )
                if not changed:
                    continue
                if not new_ids:
                    cur.execute(
                        "DELETE FROM order_schedule_tasks WHERE group_id=%s",
                        (gid,),
                    )
                    result["schedule_tasks_deleted"] += int(cur.rowcount or 0)
                    cur.execute("DELETE FROM order_schedule_groups WHERE id=%s", (gid,))
                    result["schedule_groups_deleted"] += 1
                else:
                    cur.execute(
                        "UPDATE order_schedule_groups SET product_ids=%s::jsonb, product_names=%s::jsonb, updated_at=%s WHERE id=%s",
                        (
                            psycopg.types.json.Jsonb(new_ids),
                            psycopg.types.json.Jsonb(new_names),
                            now,
                            gid,
                        ),
                    )
                    result["schedule_groups_updated"] += 1

            with contextlib.suppress(Exception):
                cur.execute(
                    """
                    SELECT id, linked_product_ids
                    FROM packaging_supply_contexts
                    WHERE company_id=%s AND linked_product_ids ?| %s
                    """,
                    (cid, remove_pid_list),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    ctx_id = str(row.get("id") or "").strip()
                    src_ids = self._normalize_json_list(row.get("linked_product_ids"))
                    new_ids, changed = _map_pid_list(src_ids)
                    if not changed:
                        continue
                    if not new_ids:
                        cur.execute(
                            "DELETE FROM packaging_supply_openings WHERE context_id=%s",
                            (ctx_id,),
                        )
                        cur.execute(
                            "DELETE FROM packaging_supply_orders WHERE context_id=%s",
                            (ctx_id,),
                        )
                        cur.execute(
                            "DELETE FROM packaging_supply_contexts WHERE id=%s",
                            (ctx_id,),
                        )
                        result["packaging_contexts_deleted"] += 1
                    else:
                        cur.execute(
                            "UPDATE packaging_supply_contexts SET linked_product_ids=%s::jsonb, updated_at=%s WHERE id=%s",
                            (psycopg.types.json.Jsonb(new_ids), now, ctx_id),
                        )
                        result["packaging_contexts_updated"] += 1

            # Remove products from moved scope.
            cur.execute(
                "DELETE FROM products WHERE company_id=%s AND manager_id=%s AND id = ANY(%s)",
                (cid, mid, remove_pid_list),
            )
            result["products_deleted"] += int(cur.rowcount or 0)

            # Delete manager-owned suppliers/packaging only if no remaining products refer to them.
            cur.execute(
                """
                SELECT COALESCE(data->>'supplier_id','') AS supplier_id,
                       COALESCE(data->>'packaging_id','') AS packaging_id
                FROM products
                WHERE company_id=%s AND manager_id=%s
                """,
                (cid, mid),
            )
            remaining_supplier_ids: set[str] = set()
            remaining_packaging_ids: set[str] = set()
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                sid = str(row.get("supplier_id") or "").strip()
                pid = str(row.get("packaging_id") or "").strip()
                if sid:
                    remaining_supplier_ids.add(sid)
                if pid:
                    remaining_packaging_ids.add(pid)

            suppliers_to_delete = sorted(removed_supplier_ids - remaining_supplier_ids)
            packaging_to_delete = sorted(
                removed_packaging_ids - remaining_packaging_ids
            )

            if suppliers_to_delete:
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM supplier_settlements WHERE company_id=%s AND manager_id=%s AND supplier_id = ANY(%s)",
                        (cid, mid, suppliers_to_delete),
                    )
                    result["payments_deleted"] += int(cur.rowcount or 0)
                cur.execute(
                    "DELETE FROM suppliers WHERE company_id=%s AND manager_id=%s AND id = ANY(%s)",
                    (cid, mid, suppliers_to_delete),
                )
                result["suppliers_deleted"] += int(cur.rowcount or 0)

            if packaging_to_delete:
                cur.execute(
                    "DELETE FROM packaging WHERE company_id=%s AND manager_id=%s AND id = ANY(%s)",
                    (cid, mid, packaging_to_delete),
                )
                result["packaging_deleted"] += int(cur.rowcount or 0)

        return result

    def cleanup_manager_duplicate_products(
        self,
        company_id: str,
        manager_id: str,
        dry_run: bool = True,
    ) -> dict:
        report = {
            "company_id": str(company_id or "").strip(),
            "manager_id": str(manager_id or "").strip(),
            "duplicate_groups": 0,
            "duplicate_products": 0,
            "updated_orders": 0,
            "updated_media": 0,
            "updated_schedule_groups": 0,
            "updated_packaging_contexts": 0,
            "merged_cost_stock_rows": 0,
            "updated_settlement_data": 0,
            "deleted_products": 0,
            "dry_run": bool(dry_run),
        }
        if not self._use_postgres():
            return report
        cid = report["company_id"]
        mid = report["manager_id"]
        if not cid or not mid:
            return report

        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT lower(trim(name)) AS n,
                       region_id,
                       COALESCE(data->>'category_id','') AS category_id,
                       COALESCE(data->>'catalog_node_id','') AS node_id,
                       COALESCE(data->>'supplier_id','') AS supplier_id,
                       ARRAY_AGG(id ORDER BY updated_at DESC, created_at DESC, id ASC) AS ids
                FROM products
                WHERE company_id=%s AND manager_id=%s
                GROUP BY 1,2,3,4,5
                HAVING COUNT(*) > 1
                """,
                (cid, mid),
            )
            dup_rows = [r for r in (cur.fetchall() or []) if isinstance(r, dict)]

        if not dup_rows:
            return report

        replace_map: dict[str, str] = {}
        for row in dup_rows:
            ids = [str(x) for x in (row.get("ids") or []) if str(x).strip()]
            if len(ids) <= 1:
                continue
            keep_id = ids[0]
            for rid in ids[1:]:
                replace_map[rid] = keep_id

        report["duplicate_groups"] = len(dup_rows)
        report["duplicate_products"] = len(replace_map)
        if not replace_map:
            return report
        if dry_run:
            return report

        now = self._now_ts()
        dup_ids = list(replace_map.keys())

        def _map_pid(pid: Any) -> str:
            raw = str(pid or "").strip()
            return replace_map.get(raw, raw)

        with self._pg().cursor() as cur:
            # Orders
            cur.execute(
                """
                SELECT id, data
                FROM orders o
                WHERE o.company_id=%s AND o.manager_id=%s
                  AND EXISTS (
                      SELECT 1
                      FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) AS it
                      WHERE (it->>'product_id') = ANY(%s)
                  )
                """,
                (cid, mid, dup_ids),
            )
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                oid = str(row.get("id") or "").strip()
                data = self._normalize_json_dict(row.get("data"))
                items = self._normalize_json_list(data.get("items"))
                changed = False
                for item in items:
                    if not isinstance(item, dict):
                        continue
                    old_pid = str(item.get("product_id") or "").strip()
                    new_pid = replace_map.get(old_pid)
                    if new_pid and new_pid != old_pid:
                        item["product_id"] = new_pid
                        changed = True
                if not changed:
                    continue
                data["items"] = items
                cur.execute(
                    "UPDATE orders SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(data), now, oid),
                )
                report["updated_orders"] += 1

            # Media plan
            cur.execute(
                "SELECT id, product_ids, product_names FROM media_plan_entries WHERE company_id=%s AND manager_id=%s AND product_ids ?| %s",
                (cid, mid, dup_ids),
            )
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                eid = str(row.get("id") or "").strip()
                src_ids = self._normalize_json_list(row.get("product_ids"))
                src_names = self._normalize_json_list(row.get("product_names"))
                new_ids: list[str] = []
                new_names: list[str] = []
                seen: set[str] = set()
                changed = False
                for idx, raw_pid in enumerate(src_ids):
                    mapped = _map_pid(raw_pid)
                    if mapped != str(raw_pid or "").strip():
                        changed = True
                    if not mapped or mapped in seen:
                        if mapped in seen:
                            changed = True
                        continue
                    seen.add(mapped)
                    new_ids.append(mapped)
                    new_names.append(
                        str(src_names[idx] if idx < len(src_names) else "")
                    )
                if not changed:
                    continue
                cur.execute(
                    "UPDATE media_plan_entries SET product_ids=%s::jsonb, product_names=%s::jsonb, updated_at=%s WHERE id=%s",
                    (
                        psycopg.types.json.Jsonb(new_ids),
                        psycopg.types.json.Jsonb(new_names),
                        now,
                        eid,
                    ),
                )
                report["updated_media"] += 1

            # Schedule groups
            cur.execute(
                "SELECT id, product_ids, product_names FROM order_schedule_groups WHERE company_id=%s AND manager_id=%s AND product_ids ?| %s",
                (cid, mid, dup_ids),
            )
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                gid = str(row.get("id") or "").strip()
                src_ids = self._normalize_json_list(row.get("product_ids"))
                src_names = self._normalize_json_list(row.get("product_names"))
                new_ids: list[str] = []
                new_names: list[str] = []
                seen: set[str] = set()
                changed = False
                for idx, raw_pid in enumerate(src_ids):
                    mapped = _map_pid(raw_pid)
                    if mapped != str(raw_pid or "").strip():
                        changed = True
                    if not mapped or mapped in seen:
                        if mapped in seen:
                            changed = True
                        continue
                    seen.add(mapped)
                    new_ids.append(mapped)
                    new_names.append(
                        str(src_names[idx] if idx < len(src_names) else "")
                    )
                if not changed:
                    continue
                cur.execute(
                    "UPDATE order_schedule_groups SET product_ids=%s::jsonb, product_names=%s::jsonb, updated_at=%s WHERE id=%s",
                    (
                        psycopg.types.json.Jsonb(new_ids),
                        psycopg.types.json.Jsonb(new_names),
                        now,
                        gid,
                    ),
                )
                report["updated_schedule_groups"] += 1

            # Cost stock rows
            for old_pid, keep_pid in replace_map.items():
                cur.execute(
                    "SELECT company_id, manager_id, region_id, qty, amount, amount_ccy, new_price, new_price_ccy, updated_at FROM cost_price_stock_inputs WHERE company_id=%s AND manager_id=%s AND product_id=%s",
                    (cid, mid, old_pid),
                )
                old_rows = [r for r in (cur.fetchall() or []) if isinstance(r, dict)]
                for old_row in old_rows:
                    region_id = str(old_row.get("region_id") or "").strip()
                    cur.execute(
                        "SELECT company_id FROM cost_price_stock_inputs WHERE company_id=%s AND manager_id=%s AND region_id=%s AND product_id=%s LIMIT 1",
                        (cid, mid, region_id, keep_pid),
                    )
                    exists = bool((cur.fetchone() or {}).get("company_id"))
                    if exists:
                        cur.execute(
                            "DELETE FROM cost_price_stock_inputs WHERE company_id=%s AND manager_id=%s AND region_id=%s AND product_id=%s",
                            (cid, mid, region_id, old_pid),
                        )
                    else:
                        cur.execute(
                            "UPDATE cost_price_stock_inputs SET product_id=%s WHERE company_id=%s AND manager_id=%s AND region_id=%s AND product_id=%s",
                            (keep_pid, cid, mid, region_id, old_pid),
                        )
                    report["merged_cost_stock_rows"] += 1

            with contextlib.suppress(Exception):
                cur.execute(
                    "SELECT id, linked_product_ids FROM packaging_supply_contexts WHERE company_id=%s AND linked_product_ids ?| %s",
                    (cid, dup_ids),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    ctx_id = str(row.get("id") or "").strip()
                    src_ids = self._normalize_json_list(row.get("linked_product_ids"))
                    out: list[str] = []
                    seen: set[str] = set()
                    changed = False
                    for raw in src_ids:
                        mapped = _map_pid(raw)
                        if mapped != str(raw or "").strip():
                            changed = True
                        if not mapped or mapped in seen:
                            if mapped in seen:
                                changed = True
                            continue
                        seen.add(mapped)
                        out.append(mapped)
                    if not changed:
                        continue
                    cur.execute(
                        "UPDATE packaging_supply_contexts SET linked_product_ids=%s::jsonb, updated_at=%s WHERE id=%s",
                        (psycopg.types.json.Jsonb(out), now, ctx_id),
                    )
                    report["updated_packaging_contexts"] += 1

            with contextlib.suppress(Exception):
                cur.execute(
                    "SELECT id, data FROM supplier_settlements WHERE company_id=%s AND manager_id=%s AND data ? 'product_id'",
                    (cid, mid),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    sid = str(row.get("id") or "").strip()
                    data = self._normalize_json_dict(row.get("data"))
                    old_pid = str(data.get("product_id") or "").strip()
                    new_pid = replace_map.get(old_pid)
                    if not new_pid or new_pid == old_pid:
                        continue
                    data["product_id"] = new_pid
                    cur.execute(
                        "UPDATE supplier_settlements SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                        (psycopg.types.json.Jsonb(data), now, sid),
                    )
                    report["updated_settlement_data"] += 1

            cur.execute(
                "DELETE FROM products WHERE company_id=%s AND manager_id=%s AND id = ANY(%s)",
                (cid, mid, dup_ids),
            )
            report["deleted_products"] = int(cur.rowcount or 0)

        for pulse_key in (
            "products",
            "suppliers",
            "packaging",
            "orders",
            "payments",
            "media_plan",
            "order_schedule",
        ):
            with contextlib.suppress(Exception):
                self._pulse(cid, pulse_key)
        return report

    @staticmethod
    def _is_empty_supplier_value(value: Any) -> bool:
        if value is None:
            return True
        if isinstance(value, str):
            return not value.strip()
        if isinstance(value, (list, dict, tuple, set)):
            return len(value) == 0
        return False

    def _merge_supplier_payload_fill_missing(
        self, base_data: dict, source_data: dict
    ) -> dict:
        base = dict(base_data or {})
        src = dict(source_data or {})
        for key, value in src.items():
            if key == "payment_fields":
                continue
            if self._is_empty_supplier_value(
                base.get(key)
            ) and not self._is_empty_supplier_value(value):
                base[key] = value

        base_pf = (
            base.get("payment_fields")
            if isinstance(base.get("payment_fields"), list)
            else []
        )
        src_pf = (
            src.get("payment_fields")
            if isinstance(src.get("payment_fields"), list)
            else []
        )
        by_id: dict[str, dict] = {
            str((row or {}).get("field_id") or "").strip(): dict(row)
            for row in base_pf
            if isinstance(row, dict) and str((row or {}).get("field_id") or "").strip()
        }
        for row in src_pf:
            if not isinstance(row, dict):
                continue
            fid = str(row.get("field_id") or "").strip()
            if not fid:
                continue
            if fid not in by_id:
                by_id[fid] = dict(row)
                continue
            merged_row = dict(by_id.get(fid) or {})
            if self._is_empty_supplier_value(
                merged_row.get("text_value")
            ) and not self._is_empty_supplier_value(row.get("text_value")):
                merged_row["text_value"] = row.get("text_value")
            if self._is_empty_supplier_value(
                merged_row.get("image_url")
            ) and not self._is_empty_supplier_value(row.get("image_url")):
                merged_row["image_url"] = row.get("image_url")
            merged_row["enabled"] = bool(
                merged_row.get("enabled") or row.get("enabled")
            )
            by_id[fid] = merged_row
        if by_id:
            base["payment_fields"] = list(by_id.values())
        return base

    def _reconcile_packaging_for_scope(
        self,
        cur,
        company_id: str,
        packaging_owner_map: dict[str, set[str]],
    ) -> bool:
        """
        Merge duplicate packaging by name when managers share access (scope overlap).
        Updates product/order references to use merged packaging.
        """
        cid = str(company_id or "").strip()
        packaging_ids = sorted(
            [str(x) for x in (packaging_owner_map or {}).keys() if str(x).strip()]
        )
        if not cid or not packaging_ids:
            return False

        now = self._now_ts()
        changed = False

        cur.execute(
            """
            SELECT id, region_id, manager_id, name, data, created_at
            FROM packaging
            WHERE company_id=%s AND id = ANY(%s)
            """,
            (cid, packaging_ids),
        )
        packaging_rows = [r for r in (cur.fetchall() or []) if isinstance(r, dict)]
        by_packaging_id = {
            str(r.get("id") or "").strip(): r
            for r in packaging_rows
            if str(r.get("id") or "").strip()
        }

        # Group by (region_id, normalized_name)
        grouped: dict[tuple[str, str], list[str]] = {}
        for pkg_id, row in by_packaging_id.items():
            region_id = str(row.get("region_id") or "").strip()
            pname = str(row.get("name") or "").strip().lower()
            if not region_id or not pname:
                continue
            grouped.setdefault((region_id, pname), []).append(pkg_id)

        # Merge duplicates when ownership overlaps (shared access scenario)
        for _, ids in grouped.items():
            if len(ids) < 2:
                continue
            overlap = False
            for i in range(len(ids)):
                for j in range(i + 1, len(ids)):
                    if packaging_owner_map.get(ids[i], set()) & packaging_owner_map.get(
                        ids[j], set()
                    ):
                        overlap = True
                        break
                if overlap:
                    break
            if not overlap:
                continue

            sorted_ids = sorted(
                ids,
                key=lambda pkg_id: (
                    str((by_packaging_id.get(pkg_id) or {}).get("created_at") or ""),
                    pkg_id,
                ),
            )
            keep_id = sorted_ids[0]
            keep_row = by_packaging_id.get(keep_id) or {}
            keep_region = str(keep_row.get("region_id") or "").strip()
            keep_data = (
                keep_row.get("data") if isinstance(keep_row.get("data"), dict) else {}
            )

            for old_id in sorted_ids[1:]:
                old_row = by_packaging_id.get(old_id) or {}
                old_data = (
                    old_row.get("data") if isinstance(old_row.get("data"), dict) else {}
                )
                # Merge payload: copy missing fields from old to keep
                for k, v in old_data.items():
                    if k not in keep_data or keep_data.get(k) in (None, ""):
                        keep_data[k] = v

                # Redirect all product references
                cur.execute(
                    """
                    UPDATE products
                    SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{packaging_id}', to_jsonb(%s::text), true),
                        updated_at=%s
                    WHERE company_id=%s AND region_id=%s AND COALESCE(data->>'packaging_id','')=%s
                    """,
                    (keep_id, now, cid, keep_region, old_id),
                )

                # Redirect all order item references
                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        UPDATE orders
                        SET data=jsonb_set(
                                COALESCE(data,'{}'::jsonb),
                                '{items}',
                                COALESCE(
                                    (
                                        SELECT jsonb_agg(
                                            CASE
                                                WHEN COALESCE(it->>'packaging_id','')=%s THEN jsonb_set(it,'{packaging_id}',to_jsonb(%s::text), true)
                                                ELSE it
                                            END
                                        )
                                        FROM jsonb_array_elements(COALESCE(data->'items','[]'::jsonb)) it
                                    ),
                                    '[]'::jsonb
                                ),
                                true
                            ),
                            updated_at=%s
                        WHERE company_id=%s AND region_id=%s
                          AND EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(COALESCE(data->'items','[]'::jsonb)) it
                            WHERE COALESCE(it->>'packaging_id','')=%s
                          )
                        """,
                        (old_id, keep_id, now, cid, keep_region, old_id),
                    )

                # Delete old packaging
                cur.execute(
                    "DELETE FROM packaging WHERE company_id=%s AND id=%s",
                    (cid, old_id),
                )
                changed = True

            # Update keep packaging data
            cur.execute(
                "UPDATE packaging SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                (psycopg.types.json.Jsonb(keep_data), now, keep_id),
            )

        return changed

    def _reconcile_suppliers_for_scope(
        self,
        cur,
        company_id: str,
        product_owner_map: dict[str, set[str]],
    ) -> bool:
        cid = str(company_id or "").strip()
        product_ids = sorted(
            [str(x) for x in (product_owner_map or {}).keys() if str(x).strip()]
        )
        if not cid or not product_ids:
            return False

        now = self._now_ts()
        changed = False

        def _read_scope_products() -> list[dict]:
            cur.execute(
                """
                SELECT id, region_id, manager_id, data
                FROM products
                WHERE company_id=%s AND id = ANY(%s)
                """,
                (cid, product_ids),
            )
            return [r for r in (cur.fetchall() or []) if isinstance(r, dict)]

        product_rows = _read_scope_products()

        supplier_to_products: dict[str, list[dict]] = {}
        for row in product_rows:
            pid = str(row.get("id") or "").strip()
            data = row.get("data") if isinstance(row.get("data"), dict) else {}
            sid = str((data or {}).get("supplier_id") or "").strip()
            if not pid or not sid:
                continue
            supplier_to_products.setdefault(sid, []).append(row)

        supplier_ids = sorted(supplier_to_products.keys())
        if not supplier_ids:
            return False

        cur.execute(
            """
            SELECT id, region_id, manager_id, name, data, created_at
            FROM suppliers
            WHERE company_id=%s AND id = ANY(%s)
            """,
            (cid, supplier_ids),
        )
        supplier_rows = [r for r in (cur.fetchall() or []) if isinstance(r, dict)]
        by_supplier_id = {
            str(r.get("id") or "").strip(): r
            for r in supplier_rows
            if str(r.get("id") or "").strip()
        }

        supplier_owner_map: dict[str, set[str]] = {}
        for sid, rows in supplier_to_products.items():
            owners: set[str] = set()
            for prow in rows:
                pid = str(prow.get("id") or "").strip()
                owners.update(product_owner_map.get(pid, set()))
            supplier_owner_map[sid] = owners

        grouped: dict[tuple[str, str], list[str]] = {}
        for sid, row in by_supplier_id.items():
            region_id = str(row.get("region_id") or "").strip()
            nname = self._normalize_supplier_name(row.get("name"))
            if not region_id or not nname:
                continue
            grouped.setdefault((region_id, nname), []).append(sid)

        # Merge duplicates when ownership overlaps (shared access scenario).
        for _, ids in grouped.items():
            if len(ids) < 2:
                continue
            overlap = False
            for i in range(len(ids)):
                for j in range(i + 1, len(ids)):
                    if supplier_owner_map.get(ids[i], set()) & supplier_owner_map.get(
                        ids[j], set()
                    ):
                        overlap = True
                        break
                if overlap:
                    break
            if not overlap:
                continue

            sorted_ids = sorted(
                ids,
                key=lambda sid: (
                    str((by_supplier_id.get(sid) or {}).get("created_at") or ""),
                    sid,
                ),
            )
            keep_id = sorted_ids[0]
            keep_row = by_supplier_id.get(keep_id) or {}
            keep_region = str(keep_row.get("region_id") or "").strip()
            keep_data = (
                keep_row.get("data") if isinstance(keep_row.get("data"), dict) else {}
            )

            for old_id in sorted_ids[1:]:
                old_row = by_supplier_id.get(old_id) or {}
                old_data = (
                    old_row.get("data") if isinstance(old_row.get("data"), dict) else {}
                )
                keep_data = self._merge_supplier_payload_fill_missing(
                    keep_data, old_data
                )

                cur.execute(
                    """
                    UPDATE products
                    SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                        updated_at=%s
                    WHERE company_id=%s AND region_id=%s AND COALESCE(data->>'supplier_id','')=%s
                    """,
                    (keep_id, now, cid, keep_region, old_id),
                )

                cur.execute(
                    """
                    UPDATE packaging
                    SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                        updated_at=%s
                    WHERE company_id=%s AND region_id=%s AND COALESCE(data->>'supplier_id','')=%s
                    """,
                    (keep_id, now, cid, keep_region, old_id),
                )

                cur.execute(
                    """
                    UPDATE orders o
                    SET supplier_id=%s,
                        data=jsonb_set(
                            jsonb_set(COALESCE(o.data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                            '{items}',
                            COALESCE(
                                (
                                    SELECT jsonb_agg(
                                        CASE
                                            WHEN COALESCE(it->>'supplier_id','')=%s THEN jsonb_set(it,'{supplier_id}',to_jsonb(%s::text), true)
                                            ELSE it
                                        END
                                    )
                                    FROM jsonb_array_elements(COALESCE(o.data->'items','[]'::jsonb)) it
                                ),
                                '[]'::jsonb
                            ),
                            true
                        ),
                        updated_at=%s
                    WHERE o.company_id=%s AND o.region_id=%s
                      AND (
                        o.supplier_id=%s
                        OR COALESCE(o.data->>'supplier_id','')=%s
                        OR EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(COALESCE(o.data->'items','[]'::jsonb)) it
                            WHERE COALESCE(it->>'supplier_id','')=%s
                        )
                      )
                    """,
                    (
                        keep_id,
                        keep_id,
                        old_id,
                        keep_id,
                        now,
                        cid,
                        keep_region,
                        old_id,
                        old_id,
                        old_id,
                    ),
                )

                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        UPDATE supplier_settlements
                        SET supplier_id=%s,
                            data=CASE
                                WHEN data IS NULL THEN NULL
                                WHEN COALESCE(data->>'supplier_id','')=%s
                                  THEN jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true)
                                ELSE data
                            END,
                            updated_at=%s
                        WHERE company_id=%s AND region_id=%s AND supplier_id=%s
                        """,
                        (keep_id, old_id, keep_id, now, cid, keep_region, old_id),
                    )

                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        UPDATE packaging_supply_contexts
                           SET goods_supplier_id=CASE WHEN goods_supplier_id=%s THEN %s ELSE goods_supplier_id END,
                               packaging_supplier_id=CASE WHEN packaging_supplier_id=%s THEN %s ELSE packaging_supplier_id END,
                               updated_at=%s
                         WHERE company_id=%s AND region_id=%s
                           AND (goods_supplier_id=%s OR packaging_supplier_id=%s)
                        """,
                        (
                            old_id,
                            keep_id,
                            old_id,
                            keep_id,
                            now,
                            cid,
                            keep_region,
                            old_id,
                            old_id,
                        ),
                    )

                cur.execute(
                    "DELETE FROM suppliers WHERE company_id=%s AND id=%s",
                    (cid, old_id),
                )
                changed = True

            cur.execute(
                "UPDATE suppliers SET data=%s::jsonb, updated_at=%s WHERE id=%s",
                (psycopg.types.json.Jsonb(keep_data), now, keep_id),
            )

        if changed:
            product_rows = _read_scope_products()

        # Split shared supplier into manager-local copies for manager-exclusive products.
        supplier_to_products = {}
        for row in product_rows:
            pid = str(row.get("id") or "").strip()
            data = row.get("data") if isinstance(row.get("data"), dict) else {}
            sid = str((data or {}).get("supplier_id") or "").strip()
            if not pid or not sid:
                continue
            supplier_to_products.setdefault(sid, []).append(row)

        if supplier_to_products:
            cur.execute(
                """
                SELECT id, region_id, manager_id, name, data
                FROM suppliers
                WHERE company_id=%s AND id = ANY(%s)
                """,
                (cid, sorted(supplier_to_products.keys())),
            )
            by_supplier_id = {
                str(r.get("id") or "").strip(): r
                for r in (cur.fetchall() or [])
                if isinstance(r, dict) and str(r.get("id") or "").strip()
            }

        for sid, rows in supplier_to_products.items():
            sup_row = by_supplier_id.get(sid) or {}
            if not sup_row:
                continue
            region_id = str(sup_row.get("region_id") or "").strip()
            supplier_name = str(sup_row.get("name") or "").strip() or "Постачальник"
            supplier_data = (
                sup_row.get("data") if isinstance(sup_row.get("data"), dict) else {}
            )
            base_manager_id = str(sup_row.get("manager_id") or "").strip()

            owner_union: set[str] = set()
            exclusive_by_manager: dict[str, list[str]] = {}
            for prow in rows:
                pid = str(prow.get("id") or "").strip()
                owners = {x for x in product_owner_map.get(pid, set()) if x}
                owner_union.update(owners)
                if len(owners) == 1:
                    mid = next(iter(owners))
                    exclusive_by_manager.setdefault(mid, []).append(pid)
            if len(owner_union) <= 1:
                continue

            for mid, pids in exclusive_by_manager.items():
                if not pids or mid == base_manager_id:
                    continue
                cur.execute(
                    """
                    SELECT id FROM suppliers
                    WHERE company_id=%s AND region_id=%s AND manager_id=%s
                      AND lower(trim(name))=lower(trim(%s))
                    LIMIT 1
                    """,
                    (cid, region_id, mid, supplier_name),
                )
                existing = cur.fetchone() or {}
                target_sid = str(existing.get("id") or "").strip()
                if not target_sid:
                    target_sid = uuid.uuid4().hex
                    copy_data = dict(supplier_data)
                    copy_data.update(
                        {
                            "company_id": cid,
                            "region_id": region_id,
                            "manager_id": mid,
                            "name": supplier_name,
                        }
                    )
                    cur.execute(
                        """
                        INSERT INTO suppliers
                          (id, company_id, region_id, manager_id, name, data, created_at, updated_at)
                        VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s,%s)
                        """,
                        (
                            target_sid,
                            cid,
                            region_id,
                            mid,
                            supplier_name,
                            psycopg.types.json.Jsonb(copy_data),
                            now,
                            now,
                        ),
                    )
                changed = True

                cur.execute(
                    """
                    UPDATE products
                    SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                        updated_at=%s
                    WHERE company_id=%s AND id = ANY(%s)
                    """,
                    (target_sid, now, cid, pids),
                )

                cur.execute(
                    """
                    SELECT DISTINCT COALESCE(data->>'packaging_id','') AS packaging_id
                    FROM products
                    WHERE company_id=%s AND id = ANY(%s)
                    """,
                    (cid, pids),
                )
                pack_ids = [
                    str(r.get("packaging_id") or "").strip()
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and str(r.get("packaging_id") or "").strip()
                ]
                if pack_ids:
                    cur.execute(
                        """
                        UPDATE packaging
                        SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                            updated_at=%s
                        WHERE company_id=%s AND region_id=%s AND manager_id=%s
                          AND id = ANY(%s)
                          AND COALESCE(data->>'supplier_id','')=%s
                        """,
                        (target_sid, now, cid, region_id, mid, pack_ids, sid),
                    )

                cur.execute(
                    """
                    SELECT id, supplier_id, data
                    FROM orders
                    WHERE company_id=%s AND region_id=%s AND manager_id=%s
                      AND (
                        supplier_id=%s
                        OR EXISTS (
                            SELECT 1
                            FROM jsonb_array_elements(COALESCE(data->'items','[]'::jsonb)) it
                            WHERE (it->>'product_id') = ANY(%s)
                        )
                      )
                    """,
                    (cid, region_id, mid, sid, pids),
                )
                for orow in cur.fetchall() or []:
                    if not isinstance(orow, dict):
                        continue
                    oid = str(orow.get("id") or "").strip()
                    odata = self._normalize_json_dict(orow.get("data"))
                    items = self._normalize_json_list(odata.get("items"))
                    o_changed = False
                    for item in items:
                        if not isinstance(item, dict):
                            continue
                        pid = str(item.get("product_id") or "").strip()
                        if (
                            pid in pids
                            and str(item.get("supplier_id") or "").strip() == sid
                        ):
                            item["supplier_id"] = target_sid
                            o_changed = True
                    if str(orow.get("supplier_id") or "").strip() == sid:
                        o_changed = True
                    if o_changed:
                        odata["items"] = items
                        odata["supplier_id"] = target_sid
                        cur.execute(
                            "UPDATE orders SET supplier_id=%s, data=%s::jsonb, updated_at=%s WHERE id=%s",
                            (
                                target_sid,
                                psycopg.types.json.Jsonb(odata),
                                now,
                                oid,
                            ),
                        )

                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        UPDATE supplier_settlements
                        SET supplier_id=%s,
                            data=CASE
                                WHEN data IS NULL THEN NULL
                                WHEN COALESCE(data->>'supplier_id','')=%s
                                    THEN jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true)
                                ELSE data
                            END,
                            updated_at=%s
                        WHERE company_id=%s AND region_id=%s AND manager_id=%s AND supplier_id=%s
                        """,
                        (target_sid, sid, target_sid, now, cid, region_id, mid, sid),
                    )

                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        SELECT id, linked_product_ids
                        FROM packaging_supply_contexts
                        WHERE company_id=%s AND region_id=%s
                          AND (goods_supplier_id=%s OR packaging_supplier_id=%s)
                          AND linked_product_ids ?| %s
                        """,
                        (cid, region_id, sid, sid, pids),
                    )
                    for crow in cur.fetchall() or []:
                        if not isinstance(crow, dict):
                            continue
                        ctx_id = str(crow.get("id") or "").strip()
                        linked_ids = [
                            str(x or "").strip()
                            for x in self._normalize_json_list(
                                crow.get("linked_product_ids")
                            )
                            if str(x or "").strip()
                        ]
                        if not linked_ids:
                            continue
                        if any(lp not in set(pids) for lp in linked_ids):
                            continue
                        cur.execute(
                            """
                            UPDATE packaging_supply_contexts
                               SET goods_supplier_id=CASE WHEN goods_supplier_id=%s THEN %s ELSE goods_supplier_id END,
                                   packaging_supplier_id=CASE WHEN packaging_supplier_id=%s THEN %s ELSE packaging_supplier_id END,
                                   updated_at=%s
                             WHERE id=%s
                            """,
                            (sid, target_sid, sid, target_sid, now, ctx_id),
                        )

        return changed

    def recompute_entity_owners_for_scope(
        self, company_id: str, node_ids: list
    ) -> dict:
        result = {
            "entity_owner_rows": 0,
            "products": 0,
            "suppliers": 0,
            "packaging": 0,
            "orders": 0,
            "media_plan": 0,
            "schedule_groups": 0,
            "schedule_tasks": 0,
            "cost_stock": 0,
            "cost_orders": 0,
            "packaging_contexts": 0,
        }
        if not self._use_postgres():
            return result
        cid = str(company_id or "").strip()
        scope_ids = sorted({str(x) for x in (node_ids or []) if str(x).strip()})
        if not cid or not scope_ids:
            return result

        scope_info = self._collect_scope_product_rows(
            cid, scope_ids, source_manager_id=None
        )
        product_rows = [
            r for r in (scope_info.get("products") or []) if isinstance(r, dict)
        ]
        if not product_rows:
            return result

        all_nodes = [
            n
            for n in (self.get_company_catalog_nodes(cid, force_refresh=False) or [])
            if isinstance(n, dict) and n.get("id")
        ]
        by_id = {str(n.get("id")): n for n in all_nodes}

        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT node_id, manager_id FROM node_owners WHERE company_id=%s",
                (cid,),
            )
            owners_by_node: dict[str, set[str]] = {}
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                nid = str(row.get("node_id") or "").strip()
                mid = str(row.get("manager_id") or "").strip()
                if nid and mid:
                    owners_by_node.setdefault(nid, set()).add(mid)

            product_owner_map: dict[str, set[str]] = {}
            supplier_owner_map: dict[str, set[str]] = {}
            packaging_owner_map: dict[str, set[str]] = {}

            for row in product_rows:
                pid = str(row.get("id") or "").strip()
                if not pid:
                    continue
                data = row.get("data") if isinstance(row.get("data"), dict) else {}
                node_id = str((data or {}).get("catalog_node_id") or "").strip()
                owners: set[str] = set()
                current = by_id.get(node_id)
                seen: set[str] = set()
                while current and current.get("id"):
                    current_id = str(current.get("id") or "").strip()
                    if not current_id or current_id in seen:
                        break
                    seen.add(current_id)
                    owners.update(owners_by_node.get(current_id, set()))
                    current = by_id.get(str(current.get("parent_id") or "").strip())

                if not owners and str(row.get("manager_id") or "").strip():
                    owners.add(str(row.get("manager_id") or "").strip())
                if not owners:
                    continue

                product_owner_map[pid] = set(owners)
                sid = str((data or {}).get("supplier_id") or "").strip()
                pkg_id = str((data or {}).get("packaging_id") or "").strip()
                if sid:
                    supplier_owner_map.setdefault(sid, set()).update(owners)
                if pkg_id:
                    packaging_owner_map.setdefault(pkg_id, set()).update(owners)

            if self._reconcile_suppliers_for_scope(cur, cid, product_owner_map):
                cur.execute(
                    "SELECT id, data FROM products WHERE company_id=%s AND id = ANY(%s)",
                    (cid, sorted(product_owner_map.keys())),
                )
                supplier_owner_map = {}
                packaging_owner_map = {}
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    pid = str(row.get("id") or "").strip()
                    owners = set(product_owner_map.get(pid, set()))
                    if not owners:
                        continue
                    data = row.get("data") if isinstance(row.get("data"), dict) else {}
                    sid = str((data or {}).get("supplier_id") or "").strip()
                    pkg_id = str((data or {}).get("packaging_id") or "").strip()
                    if sid:
                        supplier_owner_map.setdefault(sid, set()).update(owners)
                    if pkg_id:
                        packaging_owner_map.setdefault(pkg_id, set()).update(owners)

            # Reconcile packaging duplicates when managers share access
            if packaging_owner_map:
                self._reconcile_packaging_for_scope(cur, cid, packaging_owner_map)

            def _write_entity_owners(
                entity_type: str, owner_map: dict[str, set[str]]
            ) -> int:
                # Was DELETE + INSERT per (entity, manager) pair — batched
                # into one DELETE (ANY) and one multi-row INSERT, since a
                # scope recompute can touch hundreds of products/suppliers/
                # packaging entries at once.
                written = 0
                now = self._now_ts()
                eids = [eid for eid in owner_map.keys() if eid]
                if not eids:
                    return 0
                cur.execute(
                    "DELETE FROM entity_owners WHERE company_id=%s AND entity_type=%s AND entity_id = ANY(%s)",
                    (cid, entity_type, eids),
                )
                pairs = [
                    (eid, omid)
                    for eid, mids in owner_map.items()
                    if eid
                    for omid in sorted({m for m in mids if m})
                ]
                CHUNK = 500
                for i in range(0, len(pairs), CHUNK):
                    chunk = pairs[i : i + CHUNK]
                    placeholders = ", ".join(["(%s,%s,%s,%s,%s)"] * len(chunk))
                    flat_params = [
                        v
                        for eid, omid in chunk
                        for v in (cid, entity_type, eid, omid, now)
                    ]
                    cur.execute(
                        f"INSERT INTO entity_owners (company_id, entity_type, entity_id, manager_id, created_at) VALUES {placeholders} ON CONFLICT DO NOTHING",
                        flat_params,
                    )
                    written += int(cur.rowcount or 0)
                return written

            result["products"] = len(product_owner_map)
            result["suppliers"] = len(supplier_owner_map)
            result["packaging"] = len(packaging_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "product", product_owner_map
            )
            result["entity_owner_rows"] += _write_entity_owners(
                "supplier", supplier_owner_map
            )
            result["entity_owner_rows"] += _write_entity_owners(
                "packaging", packaging_owner_map
            )

            product_ids = sorted(product_owner_map.keys())
            order_owner_map: dict[str, set[str]] = {}
            if product_ids:
                cur.execute(
                    """
                    SELECT id, data FROM orders o
                    WHERE o.company_id=%s
                      AND EXISTS (
                          SELECT 1
                          FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) it
                          WHERE (it->>'product_id') = ANY(%s)
                      )
                    """,
                    (cid, product_ids),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    oid = str(row.get("id") or "").strip()
                    data = row.get("data") if isinstance(row.get("data"), dict) else {}
                    items = self._normalize_json_list((data or {}).get("items"))
                    mids: set[str] = set()
                    for item in items:
                        if not isinstance(item, dict):
                            continue
                        mids.update(
                            product_owner_map.get(
                                str(item.get("product_id") or "").strip(), set()
                            )
                        )
                    if mids:
                        order_owner_map[oid] = mids

            result["orders"] = len(order_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "order", order_owner_map
            )

            cur.execute(
                "SELECT id, product_ids FROM media_plan_entries WHERE company_id=%s",
                (cid,),
            )
            media_owner_map: dict[str, set[str]] = {}
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                eid = str(row.get("id") or "").strip()
                mids: set[str] = set()
                for pid in self._normalize_json_list(row.get("product_ids")):
                    mids.update(product_owner_map.get(str(pid or "").strip(), set()))
                if mids:
                    media_owner_map[eid] = mids
            result["media_plan"] = len(media_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "media_plan", media_owner_map
            )

            cur.execute(
                "SELECT id, product_ids FROM order_schedule_groups WHERE company_id=%s",
                (cid,),
            )
            group_owner_map: dict[str, set[str]] = {}
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                gid = str(row.get("id") or "").strip()
                mids: set[str] = set()
                for pid in self._normalize_json_list(row.get("product_ids")):
                    mids.update(product_owner_map.get(str(pid or "").strip(), set()))
                if mids:
                    group_owner_map[gid] = mids
            result["schedule_groups"] = len(group_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "schedule_group", group_owner_map
            )

            cur.execute(
                "SELECT id, group_id FROM order_schedule_tasks WHERE company_id=%s",
                (cid,),
            )
            task_owner_map: dict[str, set[str]] = {}
            for row in cur.fetchall() or []:
                if not isinstance(row, dict):
                    continue
                tid = str(row.get("id") or "").strip()
                gid = str(row.get("group_id") or "").strip()
                mids = group_owner_map.get(gid, set())
                if mids:
                    task_owner_map[tid] = set(mids)
            result["schedule_tasks"] = len(task_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "schedule_task", task_owner_map
            )

            stock_owner_map: dict[str, set[str]] = {}
            if product_ids:
                cur.execute(
                    "SELECT region_id, product_id FROM cost_price_stock_inputs WHERE company_id=%s AND product_id = ANY(%s)",
                    (cid, product_ids),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    key = f"{str(row.get('region_id') or '').strip()}:{str(row.get('product_id') or '').strip()}"
                    stock_owner_map.setdefault(key, set()).update(
                        product_owner_map.get(
                            str(row.get("product_id") or "").strip(), set()
                        )
                    )
            result["cost_stock"] = len(stock_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "cost_stock", stock_owner_map
            )

            order_cost_owner_map: dict[str, set[str]] = {}
            if order_owner_map:
                cur.execute(
                    "SELECT region_id, order_id, line_idx FROM cost_price_order_inputs WHERE company_id=%s AND order_id = ANY(%s)",
                    (cid, sorted(order_owner_map.keys())),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    key = f"{str(row.get('region_id') or '').strip()}:{str(row.get('order_id') or '').strip()}:{int(row.get('line_idx') or 0)}"
                    order_cost_owner_map.setdefault(key, set()).update(
                        order_owner_map.get(
                            str(row.get("order_id") or "").strip(), set()
                        )
                    )
            result["cost_orders"] = len(order_cost_owner_map)
            result["entity_owner_rows"] += _write_entity_owners(
                "cost_order", order_cost_owner_map
            )

            with contextlib.suppress(Exception):
                cur.execute(
                    "SELECT id, linked_product_ids FROM packaging_supply_contexts WHERE company_id=%s",
                    (cid,),
                )
                ctx_owner_map: dict[str, set[str]] = {}
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    ctx_id = str(row.get("id") or "").strip()
                    mids: set[str] = set()
                    for pid in self._normalize_json_list(row.get("linked_product_ids")):
                        mids.update(
                            product_owner_map.get(str(pid or "").strip(), set())
                        )
                    if mids:
                        ctx_owner_map[ctx_id] = mids
                result["packaging_contexts"] = len(ctx_owner_map)
                result["entity_owner_rows"] += _write_entity_owners(
                    "packaging_context", ctx_owner_map
                )

        # Ownership just changed (assign/remove/replace_scope_owner all funnel
        # through here) -- drop the cached per-manager scope context so the
        # next read (including settlement-visibility partitioning in
        # get_supplier_settlements) sees the new owner set immediately
        # instead of a stale pre-transfer scope for the rest of this process's
        # session cache lifetime.
        self._invalidate_product_scope_cache(cid)
        return result

    def assign_scope_owner(
        self, manager_id: str, company_id: str, node_ids: list
    ) -> tuple[bool, str]:
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        ids = sorted({str(x) for x in (node_ids or []) if str(x).strip()})
        if not self._use_postgres() or not mid or not cid or not ids:
            return False, "Некоректні дані"
        added, skipped = self._assign_owner_to_nodes(mid, cid, ids)
        rec = self.recompute_entity_owners_for_scope(cid, ids)
        return True, (
            f"Додано власника на {added} вузлів"
            + (f" (пропущено {skipped} через ліміт 5)" if skipped else "")
            + f". Оновлено owner-зв'язків: {int(rec.get('entity_owner_rows', 0) or 0)}"
        )

    def remove_scope_owner(
        self, manager_id: str, company_id: str, node_ids: list
    ) -> tuple[bool, str]:
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        ids = sorted({str(x) for x in (node_ids or []) if str(x).strip()})
        if not self._use_postgres() or not mid or not cid or not ids:
            return False, "Некоректні дані"
        removed = self._remove_owner_from_nodes(mid, cid, ids)
        rec = self.recompute_entity_owners_for_scope(cid, ids)
        return True, (
            f"Знято власника з {removed} вузлів. "
            f"Оновлено owner-зв'язків: {int(rec.get('entity_owner_rows', 0) or 0)}"
        )

    def replace_scope_owner(
        self,
        from_manager_id: str,
        to_manager_id: str,
        company_id: str,
        node_ids: list,
    ) -> tuple[bool, str]:
        fid = str(from_manager_id or "").strip()
        tid = str(to_manager_id or "").strip()
        cid = str(company_id or "").strip()
        ids = sorted({str(x) for x in (node_ids or []) if str(x).strip()})
        if (
            not self._use_postgres()
            or not fid
            or not tid
            or not cid
            or not ids
            or fid == tid
        ):
            return False, "Некоректні дані"
        added, skipped = self._assign_owner_to_nodes(tid, cid, ids)
        removed = self._remove_owner_from_nodes(fid, cid, ids)
        rec = self.recompute_entity_owners_for_scope(cid, ids)
        return True, (
            f"Передача завершена: +{added} вузлів новому власнику, -{removed} у попереднього"
            + (f", пропущено {skipped} через ліміт 5" if skipped else "")
            + f". Оновлено owner-зв'язків: {int(rec.get('entity_owner_rows', 0) or 0)}"
        )

    def cleanup_company_duplicate_products(
        self, company_id: str, dry_run: bool = True
    ) -> dict:
        cid = str(company_id or "").strip()
        out = {
            "company_id": cid,
            "dry_run": bool(dry_run),
            "manager_reports": [],
            "totals": {
                "duplicate_groups": 0,
                "duplicate_products": 0,
                "deleted_products": 0,
            },
        }
        if not self._use_postgres() or not cid:
            return out
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT DISTINCT manager_id FROM products WHERE company_id=%s",
                (cid,),
            )
            manager_ids = [
                str(r.get("manager_id") or "").strip()
                for r in (cur.fetchall() or [])
                if isinstance(r, dict) and str(r.get("manager_id") or "").strip()
            ]
        for mid in manager_ids:
            rep = self.cleanup_manager_duplicate_products(cid, mid, dry_run=dry_run)
            out["manager_reports"].append(rep)
            out["totals"]["duplicate_groups"] += int(rep.get("duplicate_groups") or 0)
            out["totals"]["duplicate_products"] += int(
                rep.get("duplicate_products") or 0
            )
            out["totals"]["deleted_products"] += int(rep.get("deleted_products") or 0)
        return out

    def transfer_manager_access(
        self,
        from_manager_id: str,
        to_manager_id: str,
        node_ids: list | None = None,
        remove_from_source: bool = True,
    ) -> tuple[bool, str]:
        """
        Transfer access via owner assignments only (no entity copy).
        - remove_from_source=True  -> replace owner (move ownership)
        - remove_from_source=False -> add owner (shared ownership)
        Returns (success, summary).
        """
        if not self._use_postgres():
            return False, "Потрібен PostgreSQL"
        fid = str(from_manager_id or "").strip()
        tid = str(to_manager_id or "").strip()
        selected_node_ids = [str(x) for x in (node_ids or []) if str(x).strip()]
        if not fid or not tid or fid == tid:
            return False, "Некоректні ID менеджерів"
        try:
            company_id = ""
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT company_id FROM public.managers WHERE id=%s LIMIT 1",
                    (fid,),
                )
                company_id = str((cur.fetchone() or {}).get("company_id") or "").strip()
            if not company_id:
                return False, "Не знайдено компанію джерельного менеджера"

            effective_node_ids = selected_node_ids or self.get_manager_scope_node_ids(
                fid, company_id=company_id, permission="view"
            )
            effective_node_ids = [
                str(x) for x in (effective_node_ids or []) if str(x).strip()
            ]
            if not effective_node_ids:
                return False, "Немає вузлів для передачі"

            # Ensure target can operate in needed regions.
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO manager_allowed_regions (manager_id, company_id, region_id, created_at)
                    WITH RECURSIVE scoped_nodes AS (
                        SELECT n.id, n.parent_node_id, n.region_id
                        FROM catalog_nodes n
                        WHERE n.company_id=%s AND n.id = ANY(%s)
                        UNION
                        SELECT p.id, p.parent_node_id, p.region_id
                        FROM catalog_nodes p
                        JOIN scoped_nodes s ON s.parent_node_id = p.id
                        WHERE p.company_id=%s
                    )
                    SELECT DISTINCT %s, %s, s.region_id, %s::timestamp without time zone
                    FROM scoped_nodes s
                    WHERE COALESCE(s.region_id, '') <> ''
                    ON CONFLICT DO NOTHING
                    """,
                    (
                        company_id,
                        effective_node_ids,
                        company_id,
                        tid,
                        company_id,
                        self._now_ts(),
                    ),
                )

            if remove_from_source:
                ok, msg = self.replace_scope_owner(
                    fid,
                    tid,
                    company_id,
                    effective_node_ids,
                )
            else:
                ok, msg = self.assign_scope_owner(
                    tid,
                    company_id,
                    effective_node_ids,
                )
            if not ok:
                return False, msg
            return True, msg
        except Exception as exc:
            logger.exception("transfer_manager_access failed")
            return False, f"Помилка: {exc}"

    def get_suppliers_for_transfer_preview(
        self,
        from_manager_id: str,
        to_manager_id: str,
        node_ids: list,
    ) -> dict:
        """
        Read-only preview for the admin's manual supplier-merge dialog: the
        suppliers referenced by products in the scope being transferred
        ("source"), and the suppliers the target manager already owns
        ("target") - so the admin can see both lists and decide by hand
        which ones are actually the same supplier before the transfer runs.
        """
        empty = {"source": [], "target": []}
        if not self._use_postgres():
            return empty
        fid = str(from_manager_id or "").strip()
        tid = str(to_manager_id or "").strip()
        scope_ids = [str(x) for x in (node_ids or []) if str(x).strip()]
        if not fid or not scope_ids:
            return empty

        company_id = ""
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT company_id FROM public.managers WHERE id=%s LIMIT 1",
                (fid,),
            )
            company_id = str((cur.fetchone() or {}).get("company_id") or "").strip()
        if not company_id:
            return empty

        scope_info = self._collect_scope_product_rows(company_id, scope_ids)
        product_rows = [
            r for r in (scope_info.get("products") or []) if isinstance(r, dict)
        ]
        source_supplier_ids: dict[str, int] = {}
        for row in product_rows:
            data = row.get("data") if isinstance(row.get("data"), dict) else {}
            sid = str((data or {}).get("supplier_id") or "").strip()
            if sid:
                source_supplier_ids[sid] = source_supplier_ids.get(sid, 0) + 1

        with self._pg().cursor() as cur:
            source_list: list[dict] = []
            if source_supplier_ids:
                cur.execute(
                    """
                    SELECT id, name, region_id
                    FROM suppliers
                    WHERE company_id=%s AND id = ANY(%s)
                    """,
                    (company_id, sorted(source_supplier_ids.keys())),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    sid = str(row.get("id") or "").strip()
                    if not sid:
                        continue
                    source_list.append(
                        {
                            "id": sid,
                            "name": row.get("name") or "",
                            "region_id": row.get("region_id") or "",
                            "products_count": source_supplier_ids.get(sid, 0),
                        }
                    )

            target_list: list[dict] = []
            if tid:
                cur.execute(
                    """
                    SELECT DISTINCT s.id, s.name, s.region_id
                    FROM suppliers s
                    JOIN entity_owners eo
                      ON eo.entity_id = s.id AND eo.entity_type = 'supplier'
                    WHERE eo.company_id=%s AND eo.manager_id=%s
                    """,
                    (company_id, tid),
                )
                for row in cur.fetchall() or []:
                    if not isinstance(row, dict):
                        continue
                    sid = str(row.get("id") or "").strip()
                    if not sid:
                        continue
                    target_list.append(
                        {
                            "id": sid,
                            "name": row.get("name") or "",
                            "region_id": row.get("region_id") or "",
                        }
                    )

        source_list.sort(key=lambda r: self._normalize_supplier_name(r.get("name")))
        target_list.sort(key=lambda r: self._normalize_supplier_name(r.get("name")))
        return {"source": source_list, "target": target_list}

    def apply_supplier_merge_groups(
        self,
        company_id: str,
        groups: list,
        node_ids: list | None = None,
    ) -> dict:
        """
        Apply admin-confirmed supplier merge decisions from the manual merge
        dialog. `groups` is a list of
        {"member_ids": [supplier_id, ...], "final_name": str} - for each
        group, the FIRST id is kept, every other id's products/packaging/
        orders/settlements/packaging_supply_contexts are repointed to it,
        the kept row is renamed to `final_name`, and the other rows are
        deleted. This is deliberately separate from (and does not touch)
        the automatic by-name matching in `_reconcile_suppliers_for_scope` -
        every merge here is something the admin explicitly picked, never a
        guess.
        """
        result = {"merged_groups": 0, "suppliers_removed": 0}
        if not self._use_postgres():
            return result
        cid = str(company_id or "").strip()
        if not cid or not groups:
            return result

        now = self._now_ts()
        with self._pg().cursor() as cur:
            for group in groups:
                if not isinstance(group, dict):
                    continue
                member_ids = [
                    str(x).strip()
                    for x in (group.get("member_ids") or [])
                    if str(x or "").strip()
                ]
                final_name = str(group.get("final_name") or "").strip()
                if len(member_ids) < 2 or not final_name:
                    continue

                cur.execute(
                    "SELECT id, name, data, created_at FROM suppliers WHERE company_id=%s AND id = ANY(%s)",
                    (cid, member_ids),
                )
                by_id = {
                    str(r.get("id") or "").strip(): r
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and str(r.get("id") or "").strip()
                }
                present_ids = [mid for mid in member_ids if mid in by_id]
                if len(present_ids) < 2:
                    continue

                keep_id = present_ids[0]
                keep_data = (
                    by_id[keep_id].get("data")
                    if isinstance(by_id[keep_id].get("data"), dict)
                    else {}
                )

                for old_id in present_ids[1:]:
                    old_data = (
                        by_id[old_id].get("data")
                        if isinstance(by_id[old_id].get("data"), dict)
                        else {}
                    )
                    keep_data = self._merge_supplier_payload_fill_missing(
                        keep_data, old_data
                    )

                    cur.execute(
                        """
                        UPDATE products
                        SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                            updated_at=%s
                        WHERE company_id=%s AND COALESCE(data->>'supplier_id','')=%s
                        """,
                        (keep_id, now, cid, old_id),
                    )

                    cur.execute(
                        """
                        UPDATE packaging
                        SET data=jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                            updated_at=%s
                        WHERE company_id=%s AND COALESCE(data->>'supplier_id','')=%s
                        """,
                        (keep_id, now, cid, old_id),
                    )

                    cur.execute(
                        """
                        UPDATE orders o
                        SET supplier_id=%s,
                            data=jsonb_set(
                                jsonb_set(COALESCE(o.data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true),
                                '{items}',
                                COALESCE(
                                    (
                                        SELECT jsonb_agg(
                                            CASE
                                                WHEN COALESCE(it->>'supplier_id','')=%s THEN jsonb_set(it,'{supplier_id}',to_jsonb(%s::text), true)
                                                ELSE it
                                            END
                                        )
                                        FROM jsonb_array_elements(COALESCE(o.data->'items','[]'::jsonb)) it
                                    ),
                                    '[]'::jsonb
                                ),
                                true
                            ),
                            updated_at=%s
                        WHERE o.company_id=%s
                          AND (
                            o.supplier_id=%s
                            OR COALESCE(o.data->>'supplier_id','')=%s
                            OR EXISTS (
                                SELECT 1
                                FROM jsonb_array_elements(COALESCE(o.data->'items','[]'::jsonb)) it
                                WHERE COALESCE(it->>'supplier_id','')=%s
                            )
                          )
                        """,
                        (
                            keep_id,
                            keep_id,
                            old_id,
                            keep_id,
                            now,
                            cid,
                            old_id,
                            old_id,
                            old_id,
                        ),
                    )

                    with contextlib.suppress(Exception):
                        cur.execute(
                            """
                            UPDATE supplier_settlements
                            SET supplier_id=%s,
                                data=CASE
                                    WHEN data IS NULL THEN NULL
                                    WHEN COALESCE(data->>'supplier_id','')=%s
                                      THEN jsonb_set(COALESCE(data,'{}'::jsonb), '{supplier_id}', to_jsonb(%s::text), true)
                                    ELSE data
                                END,
                                updated_at=%s
                            WHERE company_id=%s AND supplier_id=%s
                            """,
                            (keep_id, old_id, keep_id, now, cid, old_id),
                        )

                    with contextlib.suppress(Exception):
                        cur.execute(
                            """
                            UPDATE packaging_supply_contexts
                               SET goods_supplier_id=CASE WHEN goods_supplier_id=%s THEN %s ELSE goods_supplier_id END,
                                   packaging_supplier_id=CASE WHEN packaging_supplier_id=%s THEN %s ELSE packaging_supplier_id END,
                                   updated_at=%s
                             WHERE company_id=%s
                               AND (goods_supplier_id=%s OR packaging_supplier_id=%s)
                            """,
                            (old_id, keep_id, old_id, keep_id, now, cid, old_id, old_id),
                        )

                    cur.execute(
                        "DELETE FROM entity_owners WHERE company_id=%s AND entity_type='supplier' AND entity_id=%s",
                        (cid, old_id),
                    )
                    cur.execute(
                        "DELETE FROM suppliers WHERE company_id=%s AND id=%s",
                        (cid, old_id),
                    )
                    result["suppliers_removed"] += 1

                cur.execute(
                    "UPDATE suppliers SET name=%s, data=%s::jsonb, updated_at=%s WHERE id=%s",
                    (final_name, psycopg.types.json.Jsonb(keep_data), now, keep_id),
                )
                result["merged_groups"] += 1

        scope_ids = [str(x) for x in (node_ids or []) if str(x).strip()]
        if scope_ids:
            with contextlib.suppress(Exception):
                self.recompute_entity_owners_for_scope(cid, scope_ids)

        return result

    def set_manager_approval(self, manager_id: str, approved: bool) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/managers/set_approval",
                    {"id": manager_id, "approved": bool(approved)},
                )
                or False
            )
        manager_id = str(manager_id or "").strip()
        if approved:
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT company_id FROM public.managers WHERE id=%s", (manager_id,)
                )
                row = cur.fetchone()
            company_id = str((row or {}).get("company_id") or "")
            ok, _reason = self.check_can_add_approved_manager(company_id)
            if not ok:
                return False
        with self._general_pg().cursor() as cur:
            cur.execute(
                "UPDATE public.managers SET is_approved=%s, updated_at=%s WHERE id=%s",
                (bool(approved), self._now_ts(), manager_id),
            )
        return True

    def _cleanup_orphaned_catalog_branches(
        self, company_id: str, candidate_ids: list[str]
    ) -> None:
        """
        Best-effort sweep run after a manager's node_owners rows are removed
        (delete_manager_profile). Any candidate node/category that manager
        used to own and that is now owned by nobody at all, AND whose whole
        subtree is likewise unowned, is dead: no restricted (non-bypass)
        manager will ever see it again, so it would just accumulate as an
        invisible artifact. Removes those branches via the same safety-
        checked delete_level_node/delete_category paths the UI uses — both
        refuse (no-op) if any product anywhere in the subtree still
        references it, so real data is never touched. Branches that still
        have another owner are left untouched.
        """
        cid = str(company_id or "").strip()
        ids = {str(x) for x in (candidate_ids or []) if str(x or "").strip()}
        if not self._use_postgres() or not cid or not ids:
            return
        try:
            with self._pg().cursor() as cur:
                cur.execute("SELECT id FROM categories WHERE company_id=%s", (cid,))
                cat_ids = {
                    str(r.get("id"))
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and r.get("id")
                }
                if not cat_ids:
                    return
                cur.execute(
                    "SELECT id, category_id, parent_node_id FROM level_nodes WHERE category_id = ANY(%s)",
                    (list(cat_ids),),
                )
                nodes = cur.fetchall() or []
                cur.execute(
                    "SELECT DISTINCT node_id FROM node_owners WHERE company_id=%s",
                    (cid,),
                )
                owned_ids = {
                    str(r.get("node_id"))
                    for r in (cur.fetchall() or [])
                    if isinstance(r, dict) and r.get("node_id")
                }

            children_by_scope: dict[tuple[str, str], list[str]] = {}
            node_category: dict[str, str] = {}
            for n in nodes:
                nid = str(n.get("id"))
                catid = str(n.get("category_id"))
                parent = str(n.get("parent_node_id") or "root")
                node_category[nid] = catid
                children_by_scope.setdefault((catid, parent), []).append(nid)

            def is_dead(catid: str, node_id: str) -> bool:
                if node_id in owned_ids:
                    return False
                return all(
                    is_dead(catid, child)
                    for child in children_by_scope.get((catid, node_id), [])
                )

            for candidate in ids:
                try:
                    if candidate in cat_ids:
                        if candidate in owned_ids:
                            continue
                        top_nodes = children_by_scope.get((candidate, "root"), [])
                        if all(is_dead(candidate, n) for n in top_nodes):
                            ok, msg = self.delete_category(cid, candidate)
                            logger.info(
                                "delete_manager_profile cleanup: delete_category %s -> %s (%s)",
                                candidate, ok, msg,
                            )
                    elif candidate in node_category:
                        catid = node_category[candidate]
                        if is_dead(catid, candidate):
                            ok, msg = self.delete_level_node(candidate)
                            logger.info(
                                "delete_manager_profile cleanup: delete_level_node %s -> %s (%s)",
                                candidate, ok, msg,
                            )
                except Exception:
                    logger.exception(
                        "delete_manager_profile cleanup failed for node %s", candidate
                    )
        except Exception:
            logger.exception("_cleanup_orphaned_catalog_branches failed")

    # Entities that participate in the shared-ownership model (entity_owners,
    # derived from node_owners): plain `id` primary key, most also have their
    # own `manager_id` column. cost_price_order_inputs/cost_price_stock_inputs
    # use composite natural keys instead of `id` and are intentionally excluded
    # — handled by the plain unconditional per-manager delete in
    # delete_manager_profile, same as before.
    _SHARED_OWNERSHIP_ENTITY_SPECS: tuple[tuple[str, str, bool], ...] = (
        ("schedule_task", "order_schedule_tasks", True),
        ("schedule_group", "order_schedule_groups", True),
        ("media_plan", "media_plan_entries", True),
        ("packaging_context", "packaging_supply_contexts", False),
        ("order", "orders", True),
        ("product", "products", True),
        ("packaging", "packaging", True),
        ("supplier", "suppliers", True),
    )

    def _cascade_or_strip_manager_entities(
        self, company_id: str, manager_id: str
    ) -> dict:
        """
        Deleting a manager should not leave their sole-owned data behind as
        dead weight, but must not touch anything genuinely shared with a
        remaining manager either. For every entity type in
        _SHARED_OWNERSHIP_ENTITY_SPECS: if `manager_id` is the ONLY real
        owner (per entity_owners — the same shared-ownership table
        recompute_entity_owners_for_scope maintains — falling back to the
        row's own manager_id column when no entity_owners rows exist for it
        yet), the row is hard-deleted outright (products, orders, packaging,
        suppliers, schedule/media-plan entries — everything under it). If
        another manager still co-owns it (shared catalog-node access), the
        row is kept and its manager_id column is reassigned to one of the
        remaining owners instead of being left pointing at a manager that no
        longer exists; that manager's own entity_owners row for it still
        gets removed by the unconditional cleanup at the end of
        delete_manager_profile, so remaining owners are correctly preserved.
        """
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        counts: dict = {"deleted": {}, "reassigned": {}}
        if not self._use_postgres() or not cid or not mid:
            return counts
        with self._pg().cursor() as cur:
            for entity_type, table, has_manager_col in self._SHARED_OWNERSHIP_ENTITY_SPECS:
                try:
                    direct_ids: set[str] = set()
                    if has_manager_col:
                        cur.execute(
                            f"SELECT id FROM {table} WHERE company_id=%s AND manager_id=%s",
                            (cid, mid),
                        )
                        direct_ids = {
                            str(r.get("id"))
                            for r in (cur.fetchall() or [])
                            if isinstance(r, dict) and r.get("id")
                        }
                    cur.execute(
                        "SELECT DISTINCT entity_id FROM entity_owners WHERE company_id=%s AND entity_type=%s AND manager_id=%s",
                        (cid, entity_type, mid),
                    )
                    owner_ids = {
                        str(r.get("entity_id"))
                        for r in (cur.fetchall() or [])
                        if isinstance(r, dict) and r.get("entity_id")
                    }
                    entity_ids = direct_ids | owner_ids
                    if not entity_ids:
                        continue

                    cur.execute(
                        "SELECT entity_id, manager_id FROM entity_owners WHERE company_id=%s AND entity_type=%s AND entity_id = ANY(%s)",
                        (cid, entity_type, list(entity_ids)),
                    )
                    owners_by_entity: dict[str, set[str]] = {}
                    for r in cur.fetchall() or []:
                        if not isinstance(r, dict):
                            continue
                        eid = str(r.get("entity_id"))
                        om = str(r.get("manager_id"))
                        if eid and om:
                            owners_by_entity.setdefault(eid, set()).add(om)

                    to_delete: list[str] = []
                    to_reassign: dict[str, str] = {}
                    for eid in entity_ids:
                        owners = set(owners_by_entity.get(eid, set()))
                        if not owners and eid in direct_ids:
                            # No entity_owners rows at all yet — its only tie
                            # is the manager_id column itself.
                            owners = {mid}
                        remaining = owners - {mid}
                        if remaining:
                            if has_manager_col and eid in direct_ids:
                                to_reassign[eid] = sorted(remaining)[0]
                        else:
                            to_delete.append(eid)

                    if to_delete:
                        cur.execute(
                            f"DELETE FROM {table} WHERE company_id=%s AND id = ANY(%s)",
                            (cid, to_delete),
                        )
                        cur.execute(
                            "DELETE FROM entity_owners WHERE company_id=%s AND entity_type=%s AND entity_id = ANY(%s)",
                            (cid, entity_type, to_delete),
                        )
                        counts["deleted"][entity_type] = len(to_delete)

                    for eid, new_mid in to_reassign.items():
                        cur.execute(
                            f"UPDATE {table} SET manager_id=%s WHERE company_id=%s AND id=%s",
                            (new_mid, cid, eid),
                        )
                    if to_reassign:
                        counts["reassigned"][entity_type] = len(to_reassign)
                except Exception:
                    logger.exception(
                        "_cascade_or_strip_manager_entities failed for %s", entity_type
                    )
        logger.info(
            "_cascade_or_strip_manager_entities manager=%s company=%s -> %s",
            mid, cid, counts,
        )
        return counts

    def delete_manager_profile(self, manager_id: str) -> bool:
        """
        Delete manager and ALL their data: orders, suppliers, products, packaging,
        settlements, cost-price inputs, scheduling, media plans, ownership rows.

        Anything the manager solely owned is fully deleted (see
        _cascade_or_strip_manager_entities / _cleanup_orphaned_catalog_branches).
        Anything genuinely shared with another manager (still has another
        owner after this one is removed) is kept — this manager is simply
        dropped from it, and the remaining owner(s) keep full access.
        """
        if not self._use_postgres():
            return bool(
                self._delete("/managers/delete_profile", {"manager_id": manager_id})
                or False
            )
        mid = str(manager_id or "").strip()
        if not mid:
            return False
        try:
            with self._general_pg().cursor() as _gcur:
                _gcur.execute(
                    "SELECT company_id FROM public.managers WHERE id=%s LIMIT 1", (mid,)
                )
                row = _gcur.fetchone() or {}
                company_id = str(row.get("company_id") or "").strip()

            # Business tables below live in the company's OWN dedicated database
            # — pass manager_id so Компанія-Локал routes to THIS manager's own
            # cluster (see _resolve_company_dsn), not whichever cluster the
            # target company's row happens to point at.
            if company_id:
                self.set_company(company_id, manager_id=mid)

            # Sole-vs-shared cascade for the entities that support shared
            # ownership (products/orders/packaging/suppliers/schedule/media
            # plan) — must run BEFORE node_owners/entity_owners for this
            # manager are wiped below, since that's the data the sole-vs-
            # shared decision is based on.
            if company_id:
                with contextlib.suppress(Exception):
                    self._cascade_or_strip_manager_entities(company_id, mid)

            with self._pg().cursor() as cur:
                # === DATA TABLES (order matters for any implicit FKs) ===
                # Cost price inputs use composite natural keys (no plain id),
                # so they're not part of the shared-ownership cascade above —
                # always tied 1:1 to this manager, unconditional delete.
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM cost_price_order_inputs WHERE manager_id=%s",
                        (mid,),
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM cost_price_stock_inputs WHERE manager_id=%s",
                        (mid,),
                    )
                # Settlements / write-offs are personal transaction logs, not
                # part of the shared-ownership model — unconditional delete.
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM supplier_settlements WHERE manager_id=%s", (mid,)
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM packaging_writeoffs WHERE manager_id=%s", (mid,)
                    )
                # Ownership — capture what this manager owned BEFORE removing
                # their node_owners rows, so we can sweep for now-fully-
                # orphaned catalog branches afterward (see cleanup call below).
                owned_node_ids: list[str] = []
                with contextlib.suppress(Exception):
                    cur.execute(
                        "SELECT node_id FROM node_owners WHERE manager_id=%s", (mid,)
                    )
                    owned_node_ids = [
                        str(r.get("node_id"))
                        for r in (cur.fetchall() or [])
                        if isinstance(r, dict) and r.get("node_id")
                    ]
                with contextlib.suppress(Exception):
                    cur.execute("DELETE FROM node_owners WHERE manager_id=%s", (mid,))
                with contextlib.suppress(Exception):
                    cur.execute("DELETE FROM entity_owners WHERE manager_id=%s", (mid,))

                # === ACCESS CONTROL / SETTINGS ===
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_payment_field_overrides WHERE manager_id=%s",
                        (mid,),
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_region_price_tiers_overrides WHERE manager_id=%s",
                        (mid,),
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_allowed_regions WHERE manager_id=%s",
                        (mid,),
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_access_scopes WHERE manager_id=%s", (mid,)
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_supervisors WHERE manager_id=%s OR supervisor_id=%s",
                        (mid, mid),
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM category_access WHERE manager_id=%s", (mid,)
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_workspace_state WHERE manager_id=%s",
                        (mid,),
                    )
                with contextlib.suppress(Exception):
                    cur.execute(
                        "DELETE FROM manager_delivery_overrides WHERE manager_id=%s",
                        (mid,),
                    )
                with contextlib.suppress(Exception):
                    cur.execute("DELETE FROM edit_locks WHERE manager_id=%s", (mid,))

            # Catalog hierarchy is normally preserved on manager deletion (it
            # may be shared with other managers, or with admins who bypass
            # ownership entirely) — but a branch this manager was the LAST
            # owner of, with zero products anywhere in it, is now invisible
            # to every restricted manager and would just accumulate as dead
            # weight forever. Sweep those specific branches away.
            if company_id and owned_node_ids:
                with contextlib.suppress(Exception):
                    self._cleanup_orphaned_catalog_branches(company_id, owned_node_ids)

            # === MANAGER RECORD (general database) ===
            with self._general_pg().cursor() as _gcur:
                _gcur.execute("DELETE FROM public.managers WHERE id=%s", (mid,))
                _gcur.execute(
                    "DELETE FROM public.manager_local_db WHERE manager_id=%s", (mid,)
                )

            if company_id:
                self._pulse(company_id, "users")
            logger.info("delete_manager_profile: deleted all data for manager %s", mid)
            return True
        except Exception:
            logger.exception("delete_manager_profile failed")
            return False

    def reset_manager_password(self, manager_id: str, new_password: str) -> bool:
        """Set a new password for any manager (admin/superadmin action)."""
        if not self._use_postgres():
            return False
        mid = str(manager_id or "").strip()
        pw = str(new_password or "").strip()
        if not mid or not pw:
            return False
        try:
            pw_hash = self._hash_password(pw)
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.managers SET password_hash=%s, updated_at=%s WHERE id=%s",
                    (pw_hash, now, mid),
                )
            logger.info("reset_manager_password: password updated for manager %s", mid)
            return True
        except Exception:
            logger.exception("reset_manager_password failed")
            return False

    def restore_company_manager_account(
        self,
        *,
        company_name: str,
        full_name: str,
        email: str,
        phone: str,
        password: str,
        role: str = "Категорійний менеджер",
        is_approved: bool = True,
    ) -> tuple[bool, str]:
        """Відновити або створити менеджера в компанії за email + пароль (після випадкового видалення з UI)."""
        if not self._use_postgres():
            return False, "Потрібен PostgreSQL (DATABASE_URL)"
        cn = str(company_name or "").strip()
        email_norm = str(email or "").strip().lower()
        pwd = str(password or "")
        if not cn:
            return False, "Потрібна назва компанії"
        if not email_norm:
            return False, "Потрібен email"
        if not pwd:
            return False, "Потрібен пароль"
        role_final = str(role or "").strip() or "Категорійний менеджер"
        fn = str(full_name or "").strip() or "Користувач"
        ph = str(phone or "").strip()
        now = self._now_ts()
        pw_hash = self._hash_password(pwd)
        try:
            cid = self._get_company_id_by_name(cn) or self.create_company(cn)
            with contextlib.suppress(Exception):
                if not self.get_company_regions(cid):
                    self.create_region_with_defaults(cid, "Default")
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id FROM public.managers
                    WHERE company_id=%s AND lower(trim(email))=%s
                    ORDER BY updated_at DESC NULLS LAST
                    LIMIT 1
                    """,
                    (cid, email_norm),
                )
                ex = cur.fetchone() or {}
            mid_existing = str((ex or {}).get("id") or "").strip()
            if mid_existing:
                with self._general_pg().cursor() as cur:
                    cur.execute(
                        """
                        UPDATE public.managers
                        SET full_name=%s, phone=%s, password_hash=%s, role=%s, is_approved=%s, updated_at=%s
                        WHERE id=%s
                        """,
                        (
                            fn,
                            ph,
                            pw_hash,
                            role_final,
                            bool(is_approved),
                            now,
                            mid_existing,
                        ),
                    )
                with contextlib.suppress(Exception):
                    self._pulse(cid, "users")
                return True, f"Оновлено менеджера {email_norm} у компанії «{cn}»"
            self.create_manager(
                {
                    "company_id": cid,
                    "full_name": fn,
                    "email": email_norm,
                    "phone": ph,
                    "password": pwd,
                    "role": role_final,
                    "is_approved": bool(is_approved),
                }
            )
            with contextlib.suppress(Exception):
                self._pulse(cid, "users")
            return True, f"Створено менеджера {email_norm} у компанії «{cn}»"
        except Exception as exc:
            logger.exception("restore_company_manager_account failed")
            return False, str(exc)

    def get_pending_managers(self, force_refresh: bool | None = None):  # noqa: ARG002
        if not self._use_postgres():
            try:
                return self._get("/managers/pending") or []
            except httpx.HTTPStatusError as e:
                if e.response is not None and e.response.status_code == 404:
                    return []
                logger.exception("get_pending_managers failed")
                return []
            except Exception:
                logger.exception("get_pending_managers failed")
                return []
        with self._general_pg().cursor() as cur:
            cur.execute("""
                SELECT id, company_id, full_name, email, phone, role, is_approved, is_blocked, meta, created_at, updated_at
                FROM public.managers
                WHERE is_approved = FALSE
                ORDER BY created_at ASC
                """)
            rows = cur.fetchall() or []
        return rows

    # ----------------- Telegram bot conversations mirror -----------------
    # See Telegram Боти/forward_bot.py (writes 'in'/'out' rows here) and
    # [[project_telegram_site_bot]] memory. Superadmin dashboard / CatMan
    # SupAdm read/reply through these instead of talking to Telegram directly
    # on every read.

    def _get_bot_token(self, bot_name: str) -> tuple[str, int] | tuple[None, None]:
        if not self._use_postgres():
            return None, None
        with self._general_pg().cursor() as cur:
            cur.execute(
                "SELECT token_enc, owner_chat_id FROM public.bot_config WHERE bot_name = %s",
                (bot_name,),
            )
            row = cur.fetchone()
        if not row:
            return None, None
        return self._decrypt_db_password(row["token_enc"]), row["owner_chat_id"]

    def get_bot_conversation_threads(self, bot_name: str) -> list:
        """One row per tg_user_id: latest message + unread count, newest first."""
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT ON (tg_user_id)
                    tg_user_id, tg_username, tg_full_name,
                    message_text AS last_message, direction AS last_direction,
                    created_at AS last_at,
                    (SELECT count(*) FROM public.bot_conversations c2
                        WHERE c2.bot_name = c1.bot_name AND c2.tg_user_id = c1.tg_user_id
                        AND c2.direction = 'in' AND c2.is_read = FALSE) AS unread_count
                FROM public.bot_conversations c1
                WHERE bot_name = %s
                ORDER BY tg_user_id, created_at DESC
                """,
                (bot_name,),
            )
            rows = cur.fetchall() or []
        return sorted(rows, key=lambda r: r["last_at"], reverse=True)

    def get_bot_conversation_messages(self, bot_name: str, tg_user_id: int) -> list:
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, direction, message_text, created_at
                FROM public.bot_conversations
                WHERE bot_name = %s AND tg_user_id = %s
                ORDER BY created_at ASC
                """,
                (bot_name, tg_user_id),
            )
            return cur.fetchall() or []

    def mark_bot_conversation_read(self, bot_name: str, tg_user_id: int) -> None:
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                UPDATE public.bot_conversations SET is_read = TRUE
                WHERE bot_name = %s AND tg_user_id = %s AND direction = 'in' AND is_read = FALSE
                """,
                (bot_name, tg_user_id),
            )

    def count_unread_bot_conversations(self, bot_name: str) -> int:
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                SELECT count(DISTINCT tg_user_id) AS n FROM public.bot_conversations
                WHERE bot_name = %s AND direction = 'in' AND is_read = FALSE
                """,
                (bot_name,),
            )
            row = cur.fetchone()
        return int(row["n"]) if row else 0

    def send_bot_reply(self, bot_name: str, tg_user_id: int, text: str) -> bool:
        """Send `text` to a visitor via the given bot's Telegram API, and mirror
        it as an 'out' row (same as forward_bot.py's handle_owner_reply)."""
        token, _owner_chat_id = self._get_bot_token(bot_name)
        if not token:
            logger.warning("send_bot_reply: no token configured for bot_name=%s", bot_name)
            return False
        try:
            resp = requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={"chat_id": tg_user_id, "text": text},
                timeout=15,
            )
        except Exception:
            logger.exception("send_bot_reply: Telegram request failed")
            return False
        if not resp.ok:
            logger.warning("send_bot_reply: Telegram rejected message: %s %s", resp.status_code, resp.text[:300])
            return False
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.bot_conversations
                    (bot_name, tg_user_id, direction, message_text)
                VALUES (%s, %s, 'out', %s)
                """,
                (bot_name, tg_user_id, text),
            )
        return True

    def _notify_new_registration(
        self, company_name: str, manager_name: str, email: str
    ) -> None:
        """Ping the owner via the 'registrations' bot the moment a new
        self-registered manager lands as is_approved=FALSE — see save_setup()
        and Phase 3 of [[project_telegram_site_bot]]."""
        token, owner_chat_id = self._get_bot_token("registrations")
        if not token or not owner_chat_id:
            return
        text = (
            "Нова реєстрація очікує підтвердження:\n"
            f"Компанія: {company_name}\n"
            f"Ім'я: {manager_name}\n"
            f"Email: {email}"
        )
        try:
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                json={"chat_id": owner_chat_id, "text": text},
                timeout=10,
            )
        except Exception:
            logger.exception("_notify_new_registration: Telegram request failed")

    def check_auth(
        self,
        company_name: str,
        manager_name: str,
        password: str,
        email: str,
        phone: str,
    ):
        """
        Returns a user_data dict on success, else None.
        """
        if not self._use_postgres():
            # backend mode (if available)
            try:
                res = self._post(
                    "/auth/check",
                    {
                        "company": company_name,
                        "manager": manager_name,
                        "password": password,
                        "email": email,
                        "phone": phone,
                    },
                )
                return res if isinstance(res, dict) else None
            except Exception:
                logger.exception("check_auth via api failed")
                return None

        company_name = (company_name or "").strip()
        manager_name = (manager_name or "").strip()
        email_norm = (email or "").strip().lower()
        phone_norm = (phone or "").strip()
        phone_digits = "".join(ch for ch in phone_norm if ch.isdigit())

        # Bootstrap path: empty DB -> create company + superadmin manager on first login attempt.
        with self._general_pg().cursor() as cur:
            cur.execute("SELECT COUNT(*) AS c FROM public.managers")
            c = int((cur.fetchone() or {}).get("c") or 0)
        if c == 0:
            cid = self._get_company_id_by_name(company_name) or self.create_company(
                company_name or "CatMan"
            )
            mid = self.create_manager(
                {
                    "company_id": cid,
                    "full_name": manager_name or "СуперАдмін",
                    "email": email_norm,
                    "phone": phone_norm,
                    "password": password,
                    "role": "superadmin",
                }
            )
            # ensure at least one region exists for smoother UI
            with contextlib.suppress(Exception):
                self.create_region_with_defaults(cid, "Default")
            return {
                "id": mid,
                "company_id": cid,
                "company_name": company_name or "CatMan",
                "full_name": manager_name or "СуперАдмін",
                "email": email_norm,
                "phone": phone_norm,
                "role": "СуперАдмін",
                "is_approved": True,
                "password": password,
                "account_kind": "company",
                "storage_mode": "vps",
                "superadmin_explicit_mode": True,
            }

        # Normal auth:
        # - Заповнена назва компанії — звичайний вхід (будь-яка затверджена роль у межах компанії).
        # - Порожня назва компанії — лише СуперАдмін (глобальний пошук без company_id scope).
        #   Інші ролі зобовʼязані вказувати компанію — інакше вхід не дозволяється.
        #
        # ВАЖЛИВО: якщо в формі вказано email — матчимо ТІЛЬКИ за email (без OR по телефону).
        # Інакше два менеджери в одній компанії з одним номером, але різною поштою й роллю,
        # зливалися б у один пул і сортування за пріоритетом ролі пускало б «не того» користувача.
        # Телефон — лише резерв, якщо поле пошти порожнє.
        company_name = (company_name or "").strip()
        rows: list[Any] = []
        force_recovery_sa = False
        if company_name:
            cid = self._get_company_id_by_name(company_name)
            if not cid:
                return None
            if not email_norm and not phone_digits:
                return None
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT is_blocked, db_pending FROM public.companies WHERE id=%s", (cid,)
                )
                company_row = cur.fetchone() or {}
            if bool(company_row.get("is_blocked")):
                return {"__company_blocked__": True}
            if bool(company_row.get("db_pending")):
                return {"__company_pending__": True}
            if self.is_backup_locked(cid):
                return {"__backup_in_progress__": True}
            with self._general_pg().cursor() as cur:
                if email_norm:
                    cur.execute(
                        """
                                                SELECT id, company_id, full_name, email, phone, role, password_hash, is_approved, is_blocked, meta, created_at
                        FROM public.managers
                        WHERE company_id=%s
                          AND lower(trim(email)) = lower(trim(%s))
                        ORDER BY created_at ASC
                        """,
                        (cid, email_norm),
                    )
                else:
                    cur.execute(
                        """
                                                SELECT id, company_id, full_name, email, phone, role, password_hash, is_approved, is_blocked, meta, created_at
                        FROM public.managers
                        WHERE company_id=%s
                          AND regexp_replace(COALESCE(trim(phone), ''), '[^0-9]', '', 'g') = %s
                        ORDER BY created_at ASC
                        """,
                        (cid, phone_digits),
                    )
                rows = cur.fetchall() or []
            # Один email/телефон — кілька рядків у компанії: не брати запис superadmin «поряд» із звичайною роллю (ті самі креденшали)
            if len(rows) > 1:
                tenant_only = [
                    r
                    for r in rows
                    if self._normalize_role(str((r or {}).get("role") or ""))
                    != "superadmin"
                ]
                if tenant_only:
                    rows = tenant_only
        else:
            raw_global: list[Any] = []
            if email_norm:
                with self._general_pg().cursor() as cur:
                    cur.execute(
                        """
                        SELECT id, company_id, full_name, email, phone, role, password_hash, is_approved, is_blocked, meta, created_at, account_kind
                        FROM public.managers
                        WHERE lower(trim(email)) = lower(trim(%s))
                        ORDER BY created_at ASC
                        """,
                        (email_norm,),
                    )
                    raw_global = cur.fetchall() or []
            elif phone_digits:
                with self._general_pg().cursor() as cur:
                    cur.execute(
                        """
                        SELECT id, company_id, full_name, email, phone, role, password_hash, is_approved, is_blocked, meta, created_at, account_kind
                        FROM public.managers
                        WHERE regexp_replace(COALESCE(trim(phone), ''), '[^0-9]', '', 'g') = %s
                        ORDER BY created_at ASC
                        """,
                        (phone_digits,),
                    )
                    raw_global = cur.fetchall() or []
            else:
                return None

            # Для входу без компанії один email не може вказувати одночасно на SA і на іншу роль (спільний пароль інакше пускав би «вище» по ролі)
            if email_norm:
                has_sa = any(
                    self._normalize_role(str((r or {}).get("role") or ""))
                    == "superadmin"
                    for r in raw_global
                )
                has_non_sa = any(
                    self._normalize_role(str((r or {}).get("role") or ""))
                    != "superadmin"
                    for r in raw_global
                )
                if has_sa and has_non_sa:
                    return None

            rows_sa_only = [
                r
                for r in raw_global
                if self._normalize_role(str((r or {}).get("role") or ""))
                == "superadmin"
            ]
            # Індивідуал (account_kind='individual') не вказує назву компанії при
            # вході — email тут гарантовано унікальний серед індивідуалів
            # (partial unique index, database.py _ensure_general_schema), тому
            # цей матч однозначний. Тільки за email — телефон не гарантує
            # унікальності серед індивідуалів.
            rows_individual = (
                [
                    r
                    for r in raw_global
                    if str((r or {}).get("account_kind") or "") == "individual"
                ]
                if (email_norm and not rows_sa_only)
                else []
            )
            if rows_sa_only:
                rows = rows_sa_only
            elif rows_individual:
                rows = rows_individual
            elif self._recovery_superadmin_login_allowed(email_norm):
                # Лише збіг пошти з whitelist (без recovery «за одним телефоном» — дві різні обліковки).
                rows = list(raw_global)
                force_recovery_sa = bool(rows)
            else:
                rows = []

        if not rows:
            return None

        mn = manager_name.strip()
        if mn:
            narrowed = [
                r
                for r in rows
                if self._auth_names_equal((r or {}).get("full_name"), mn)
            ]
            if narrowed:
                rows = narrowed

        rows.sort(
            key=lambda r: (
                self._auth_role_priority(str((r or {}).get("role") or "")),
                str((r or {}).get("created_at") or ""),
            )
        )

        row = None
        for cand in rows:
            if self._verify_password(
                password, str((cand or {}).get("password_hash") or "")
            ):
                row = cand
                break

        if row is None:
            return None

        if bool(row.get("is_blocked")):
            return {"__blocked__": True, "full_name": str(row.get("full_name") or "")}

        if force_recovery_sa:
            self._heal_manager_to_superadmin(str(row.get("id") or ""))
            role_label = "СуперАдмін"
            is_ok = True
        else:
            role_slug = str(row.get("role") or "")
            role_label = (
                "СуперАдмін"
                if role_slug == "superadmin"
                else ("Адмін" if role_slug == "admin" else role_slug)
            )
            is_ok = bool(row.get("is_approved"))
        # Look up company name for schema naming (company_name var may be empty
        # in superadmin global-login path; fetch it from DB) — and always fetch
        # account_kind/storage_mode so downstream dashboards/views can adapt
        # UI for Індивідуал/Локал accounts without an extra query.
        returned_company_name = company_name
        returned_account_kind = "company"
        returned_storage_mode = "vps"
        try:
            _cid_lookup = str(row.get("company_id") or "").strip()
            if _cid_lookup:
                with self._general_pg().cursor() as _cur:
                    _cur.execute(
                        "SELECT name, account_kind, storage_mode FROM public.companies WHERE id = %s",
                        (_cid_lookup,),
                    )
                    _crow = _cur.fetchone()
                    if _crow:
                        if not returned_company_name:
                            returned_company_name = str(_crow.get("name") or "").strip()
                        returned_account_kind = str(_crow.get("account_kind") or "company")
                        returned_storage_mode = str(_crow.get("storage_mode") or "vps")
        except Exception:
            pass
        _cid_log = str(row.get("company_id") or "")
        logger.info(
            "[AUTH] login OK  |  user: %s  |  company: %s  |  id: %s...",
            row.get("full_name"),
            returned_company_name or "?",
            _cid_log[:12],
        )
        return {
            "id": row.get("id"),
            "company_id": row.get("company_id"),
            "company_name": returned_company_name,
            "full_name": row.get("full_name"),
            "email": row.get("email"),
            "phone": row.get("phone"),
            "role": role_label,
            "is_approved": is_ok,
            "password": password,
            "account_kind": returned_account_kind,
            "storage_mode": returned_storage_mode,
        }

    def force_superadmin_credentials(
        self,
        *,
        email: str,
        password: str,
        full_name: str | None = None,
        phone: str | None = None,
    ) -> tuple[bool, str]:
        """
        Аварійно: виставити bcrypt-пароль, роль superadmin, is_approved; оновити ПІБ/телефон за email (lower).
        Якщо запису немає — створюється менеджер у першій компанії (або нова компанія CatMan + регіон).
        """
        if not self._use_postgres():
            return False, "PostgreSQL вимкнено (немає DATABASE_URL)"
        email_norm = str(email or "").strip().lower()
        pw = str(password or "")
        if not email_norm or not pw:
            return False, "Потрібні email і пароль"
        fn = str(full_name or "").strip()
        ph = str(phone or "").strip()
        pw_hash = self._hash_password(pw)
        now = self._now_ts()
        try:
            sets = [
                "role='superadmin'",
                "is_approved=TRUE",
                "password_hash=%s",
                "updated_at=%s",
            ]
            params: list[Any] = [pw_hash, now]
            if fn:
                sets.append("full_name=%s")
                params.append(fn)
            if ph:
                sets.append("phone=%s")
                params.append(ph)
            sql_set = ", ".join(sets)
            with self._general_pg().cursor() as cur:
                cur.execute(
                    f"UPDATE public.managers SET {sql_set} WHERE lower(trim(email))=%s",
                    (*params, email_norm),
                )
                n = int(cur.rowcount or 0)
            if n > 0:
                cid_heal = ""
                with self._general_pg().cursor() as cur:
                    cur.execute(
                        "SELECT company_id FROM public.managers WHERE lower(trim(email))=%s LIMIT 1",
                        (email_norm,),
                    )
                    rr = cur.fetchone() or {}
                    cid_heal = str((rr or {}).get("company_id") or "").strip()
                if cid_heal:
                    with contextlib.suppress(Exception):
                        self.sync_company_catalog_nodes(cid_heal)
                        self._pulse(cid_heal, "managers")
                return True, f"Оновлено записів менеджера: {n}"

            with self._general_pg().cursor() as cur:
                cur.execute("""
                    SELECT id FROM public.companies
                    ORDER BY created_at ASC NULLS LAST
                    LIMIT 1
                    """)
                cr = cur.fetchone() or {}
            cid = str((cr or {}).get("id") or "").strip()
            if not cid:
                cid = self.create_company("CatMan")
                with contextlib.suppress(Exception):
                    self.create_region_with_defaults(cid, "Default")
            self.create_manager(
                {
                    "company_id": cid,
                    "full_name": fn or "СуперАдмін",
                    "email": email_norm,
                    "phone": ph,
                    "password": pw,
                    "role": "superadmin",
                    "is_approved": True,
                }
            )
            with contextlib.suppress(Exception):
                self.sync_company_catalog_nodes(cid)
                self._pulse(cid, "managers")
            return True, "Створено нового СуперАдміна (email раніше не зустрічався)"
        except Exception as exc:
            logger.exception("force_superadmin_credentials failed")
            return False, str(exc)

    # ----------------- config / catalog minimal -----------------
    def get_company_catalog_config(self, company_id: str, region_id: str | None = None):
        if not self._use_postgres():
            return (
                self._get(
                    "/catalog/config",
                    {"company_id": company_id, "region_id": region_id or ""},
                )
                or {}
            )
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        if not company_id:
            return {}
        # When UI passes "all regions" (None), fall back to the first region config.
        if not region_id:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM regions WHERE company_id=%s ORDER BY name ASC LIMIT 1",
                    (company_id,),
                )
                r = cur.fetchone()
            fallback_rid = str((r or {}).get("id") or "").strip()
            if fallback_rid:
                region_id = fallback_rid
            else:
                return {"levels": [], "nodes": []}
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT id, company_id, region_id, config, updated_at FROM catalog_config WHERE company_id=%s AND region_id=%s LIMIT 1",
                (company_id, region_id),
            )
            row = cur.fetchone()
        cfg = None
        if row and isinstance(row.get("config"), dict):
            cfg = row.get("config") or {}
        elif row and row.get("config"):
            cfg = row.get("config")

        # Ensure defaults so UI never shows an empty gray block.
        if not isinstance(cfg, dict):
            cfg = {}
        levels = cfg.get("levels")
        if not isinstance(levels, list) or not levels:
            cfg["levels"] = self._default_catalog_levels()
        if "nodes" not in cfg or not isinstance(cfg.get("nodes"), list):
            cfg["nodes"] = []

        # Persist ensured defaults if record missing or incomplete.
        now = self._now_ts()
        if row and row.get("id"):
            with self._pg().cursor() as cur:
                cur.execute(
                    "UPDATE catalog_config SET config=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(cfg), now, str(row["id"])),
                )
            return cfg

        cfg_id = uuid.uuid4().hex
        with self._pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO catalog_config (id, company_id, region_id, config, updated_at)
                VALUES (%s,%s,%s,%s::jsonb,%s)
                """,
                (cfg_id, company_id, region_id, psycopg.types.json.Jsonb(cfg), now),
            )
        return cfg

    # ----------------- catalog nodes (company tree) -----------------
    def sync_company_catalog_nodes(self, company_id: str) -> bool:
        """
        Build/refresh `catalog_nodes` from canonical tables:
        - categories -> node_type=category, level_position=0, parent_node_id NULL
        - level_nodes -> node_type=level_{position}, parent_node_id maps "root" -> category_id
        """
        if not self._use_postgres():
            return bool(
                self._post("/catalog/nodes/sync", {"company_id": company_id}) or False
            )
        cid = str(company_id or "").strip()
        if not cid:
            return False
        now = self._now_ts()
        try:
            with self._pg().cursor() as cur:
                # Categories (root nodes)
                cur.execute(
                    """
                    SELECT id, company_id, region_id, name, data
                    FROM categories
                    WHERE company_id=%s
                    """,
                    (cid,),
                )
                cats = cur.fetchall() or []

                # Collect every upsert row first, then write them in a handful
                # of multi-row INSERTs instead of one execute() per node — a
                # company with hundreds/thousands of categories+levels used to
                # mean that many individual round trips, invisible on
                # localhost but a multi-second stall over a remote Postgres
                # connection (this runs on most category/product tab loads).
                rows: list[tuple] = []

                for c in cats:
                    if (
                        not isinstance(c, dict)
                        or not c.get("id")
                        or not c.get("region_id")
                    ):
                        continue
                    cat_id = str(c.get("id"))
                    region_id = str(c.get("region_id"))
                    name = str(c.get("name") or "Категорія")
                    data = c.get("data") if isinstance(c.get("data"), dict) else {}
                    node_data = {
                        "node_type": "category",
                        "category_id": cat_id,
                        "source": "categories",
                        **(data or {}),
                    }
                    rows.append(
                        (
                            cat_id,
                            cid,
                            region_id,
                            None,
                            0,
                            name,
                            psycopg.types.json.Jsonb(node_data),
                            now,
                            now,
                        )
                    )

                # Level nodes (children)
                cur.execute(
                    """
                    SELECT ln.id, ln.category_id, ln.position, ln.parent_node_id, ln.name, ln.data,
                           c.region_id
                    FROM level_nodes ln
                    JOIN categories c ON c.id = ln.category_id
                    WHERE c.company_id=%s
                    """,
                    (cid,),
                )
                lvl_rows = cur.fetchall() or []
                for ln in lvl_rows:
                    if (
                        not isinstance(ln, dict)
                        or not ln.get("id")
                        or not ln.get("category_id")
                        or not ln.get("region_id")
                    ):
                        continue
                    node_id = str(ln.get("id"))
                    cat_id = str(ln.get("category_id"))
                    region_id = str(ln.get("region_id"))
                    try:
                        pos = int(ln.get("position") or 0)
                    except Exception:
                        pos = 0
                    if pos < 1 or pos > 6:
                        continue
                    parent = str(ln.get("parent_node_id") or "").strip()
                    # Map legacy "root" marker to category node id
                    parent_id = (
                        cat_id
                        if parent.lower() in {"root", "0", "none", ""}
                        else parent
                    )
                    name = str(ln.get("name") or "")
                    data = ln.get("data") if isinstance(ln.get("data"), dict) else {}
                    node_data = {
                        "node_type": f"level_{pos}",
                        "category_id": cat_id,
                        "source": "level_nodes",
                        **(data or {}),
                    }
                    rows.append(
                        (
                            node_id,
                            cid,
                            region_id,
                            parent_id,
                            pos,
                            name,
                            psycopg.types.json.Jsonb(node_data),
                            now,
                            now,
                        )
                    )

                CHUNK = 500
                for i in range(0, len(rows), CHUNK):
                    chunk = rows[i : i + CHUNK]
                    placeholders = ", ".join(
                        ["(%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s)"] * len(chunk)
                    )
                    flat_params = [v for row in chunk for v in row]
                    cur.execute(
                        f"""
                        INSERT INTO catalog_nodes
                          (id, company_id, region_id, parent_node_id, level_position, name, data, created_at, updated_at)
                        VALUES
                          {placeholders}
                        ON CONFLICT (id) DO UPDATE SET
                          company_id=EXCLUDED.company_id,
                          region_id=EXCLUDED.region_id,
                          parent_node_id=EXCLUDED.parent_node_id,
                          level_position=EXCLUDED.level_position,
                          name=EXCLUDED.name,
                          data=EXCLUDED.data,
                          updated_at=EXCLUDED.updated_at
                        """,
                        flat_params,
                    )

                # Cleanup: remove stale catalog_nodes that no longer exist in categories/level_nodes.
                # Without this, deleted series/levels keep showing up in UI lists built from catalog_nodes.
                cur.execute(
                    """
                    DELETE FROM catalog_nodes cn
                    WHERE cn.company_id=%s
                      AND NOT EXISTS (
                        SELECT 1 FROM categories c
                        WHERE c.company_id=%s AND c.id = cn.id
                      )
                      AND NOT EXISTS (
                        SELECT 1
                        FROM level_nodes ln
                        JOIN categories c2 ON c2.id = ln.category_id
                        WHERE c2.company_id=%s AND ln.id = cn.id
                      )
                    """,
                    (cid, cid, cid),
                )
            return True
        except Exception:
            logger.exception("sync_company_catalog_nodes failed")
            return False

    def get_company_catalog_nodes(
        self, company_id: str, force_refresh: bool | None = None
    ):  # noqa: ARG002
        if not self._use_postgres():
            return self._get("/catalog/nodes", {"company_id": company_id}) or []
        cid_key = str(company_id or "").strip()
        _cn_cache_key = f"catalog_nodes_{cid_key}"
        if not force_refresh and _cn_cache_key in self._session_cache:
            return self._session_cache[_cn_cache_key]
        # Ensure nodes exist on first open (common for "Всі регіони" dialogs).
        # If the table is empty or incomplete for this company, build it from categories/level_nodes.
        with contextlib.suppress(Exception):
            if force_refresh:
                self.sync_company_catalog_nodes(company_id)
                self._session_cache.pop(_cn_cache_key, None)
            else:
                with self._pg().cursor() as cur:
                    cur.execute(
                        "SELECT 1 FROM catalog_nodes WHERE company_id=%s LIMIT 1",
                        (str(company_id or "").strip(),),
                    )
                    has_any = bool(cur.fetchone())
                if not has_any:
                    self.sync_company_catalog_nodes(company_id)
                else:
                    # If new categories were added after initial sync, catalog_nodes may be stale.
                    # Re-sync when category root nodes count is behind.
                    with self._pg().cursor() as cur:
                        cur.execute(
                            "SELECT COUNT(*) AS n FROM categories WHERE company_id=%s",
                            (str(company_id or "").strip(),),
                        )
                        cat_cnt = int((cur.fetchone() or {}).get("n") or 0)
                        cur.execute(
                            """
                            SELECT COUNT(*) AS n
                            FROM catalog_nodes
                            WHERE company_id=%s AND level_position=0
                            """,
                            (str(company_id or "").strip(),),
                        )
                        node_cnt = int((cur.fetchone() or {}).get("n") or 0)
                    if cat_cnt and node_cnt < cat_cnt:
                        self.sync_company_catalog_nodes(company_id)
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT id, company_id, region_id, parent_node_id, level_position, name, data, created_at, updated_at
                FROM catalog_nodes
                WHERE company_id=%s
                ORDER BY region_id ASC, level_position ASC, name ASC
                """,
                (str(company_id or "").strip(),),
            )
            rows = cur.fetchall() or []
        # Normalize to UI contract used in views (parent_id/node_type keys)
        out = []
        for r in rows:
            if not isinstance(r, dict):
                continue
            data = r.get("data") if isinstance(r.get("data"), dict) else {}
            node_type = r.get("node_type") or (
                data.get("node_type") if isinstance(data, dict) else None
            )
            legacy_id = r.get("legacy_id")
            if not legacy_id and node_type == "category" and r.get("id"):
                # UI legacy mapping expects "cat:<category_id>"
                legacy_id = f"cat:{r.get('id')}"
            out.append(
                {
                    **r,
                    "parent_id": r.get("parent_node_id"),
                    "node_type": node_type,
                    "legacy_id": legacy_id,
                }
            )
        self._session_cache[_cn_cache_key] = out
        return out

    def get_node_path(self, node_id: str) -> list:
        if not self._use_postgres():
            return self._get("/catalog/node_path", {"node_id": node_id}) or []
        node_id = str(node_id or "").strip()
        if not node_id:
            return []
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT id, company_id, region_id, parent_node_id, level_position, name, data FROM catalog_nodes WHERE id=%s LIMIT 1",
                (node_id,),
            )
            cur_node = cur.fetchone()

        # Fallback: some installations have `level_nodes` but `catalog_nodes` not yet synced.
        # Try to resolve the company_id from level_nodes -> categories, sync, then retry.
        if not cur_node:
            with contextlib.suppress(Exception):
                with self._pg().cursor() as cur:
                    cur.execute(
                        """
                        SELECT ln.id, ln.category_id, ln.position, ln.name, (ln.data->>'parent_node_id') AS parent_node_id
                        FROM level_nodes ln
                        WHERE ln.id=%s
                        LIMIT 1
                        """,
                        (node_id,),
                    )
                    ln = cur.fetchone() or {}
                cat_id = str((ln or {}).get("category_id") or "").strip()
                if cat_id:
                    with self._pg().cursor() as cur:
                        cur.execute(
                            "SELECT company_id FROM categories WHERE id=%s LIMIT 1",
                            (cat_id,),
                        )
                        crow = cur.fetchone() or {}
                    cid = str((crow or {}).get("company_id") or "").strip()
                    if cid:
                        self.sync_company_catalog_nodes(cid)
                        with self._pg().cursor() as cur:
                            cur.execute(
                                "SELECT id, company_id, region_id, parent_node_id, level_position, name, data FROM catalog_nodes WHERE id=%s LIMIT 1",
                                (node_id,),
                            )
                            cur_node = cur.fetchone()

        if not cur_node:
            return []
        path = [cur_node]
        seen = {node_id}
        while True:
            pid = str(path[0].get("parent_node_id") or "").strip()
            if not pid or pid in seen:
                break
            seen.add(pid)
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT id, company_id, region_id, parent_node_id, level_position, name, data FROM catalog_nodes WHERE id=%s LIMIT 1",
                    (pid,),
                )
                parent = cur.fetchone()
            if not parent:
                break
            path.insert(0, parent)
        # UI compatibility: many views expect `position` key.
        for p in path:
            if isinstance(p, dict) and "position" not in p:
                p["position"] = p.get("level_position")
        return path

    def get_product_catalog_node_ids(
        self, company_id: str, region_id: str | None = None
    ):  # noqa: ARG002
        if not self._use_postgres():
            return (
                self._get(
                    "/products/catalog_node_ids",
                    {"company_id": company_id, "region_id": region_id or ""},
                )
                or []
            )
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT (data->>'catalog_node_id') AS catalog_node_id
                FROM products
                WHERE company_id=%s
                """,
                (str(company_id or "").strip(),),
            )
            rows = cur.fetchall() or []
        return [
            r.get("catalog_node_id")
            for r in rows
            if isinstance(r, dict) and r.get("catalog_node_id")
        ]

    # ----------------- access control tables -----------------
    def get_manager_allowed_region_ids(self, manager_id: str) -> list[str]:
        if not self._use_postgres():
            return (
                self._get("/managers/allowed_regions", {"manager_id": manager_id}) or []
            )
        mid = str(manager_id or "").strip()
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT region_id FROM manager_allowed_regions WHERE manager_id=%s",
                (mid,),
            )
            rows = cur.fetchall() or []
        return [
            str(r.get("region_id"))
            for r in rows
            if isinstance(r, dict) and r.get("region_id")
        ]

    def save_manager_allowed_region_ids(
        self, manager_id: str, region_ids: list
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/managers/allowed_regions/save",
                    {"manager_id": manager_id, "region_ids": region_ids},
                )
                or False
            )
        mid = str(manager_id or "").strip()
        region_ids = [str(x) for x in (region_ids or []) if str(x).strip()]
        with self._general_pg().cursor() as _gcur:
            _gcur.execute(
                "SELECT company_id FROM public.managers WHERE id=%s LIMIT 1", (mid,)
            )
            row = _gcur.fetchone()
            cid = str((row or {}).get("company_id") or "").strip()
        if cid:
            self.set_company(cid, manager_id=mid)
        with self._pg().cursor() as cur:
            cur.execute(
                "DELETE FROM manager_allowed_regions WHERE manager_id=%s", (mid,)
            )
            if region_ids:
                now = self._now_ts()
                placeholders = ", ".join(["(%s,%s,%s,%s)"] * len(region_ids))
                flat_params = [
                    v for rid in region_ids for v in (mid, cid, rid, now)
                ]
                cur.execute(
                    f"INSERT INTO manager_allowed_regions (manager_id, company_id, region_id, created_at) VALUES {placeholders}",
                    flat_params,
                )
        return True

    def _sync_legacy_scope_access(self, company_id: str, manager_id: str) -> None:
        """Keep legacy scope/category tables mirrored from canonical node_owners."""
        if not self._use_postgres():
            return
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        if not cid or not mid:
            return
        now = self._now_ts()
        with self._pg().cursor() as cur:
            cur.execute(
                "DELETE FROM manager_access_scopes WHERE manager_id=%s AND company_id=%s AND permission='view'",
                (mid, cid),
            )
            cur.execute(
                """
                INSERT INTO manager_access_scopes (manager_id, company_id, permission, node_id, created_at)
                SELECT manager_id, company_id, 'view', node_id, %s::timestamp without time zone
                FROM node_owners
                WHERE company_id=%s AND manager_id=%s
                ON CONFLICT DO NOTHING
                """,
                (now, cid, mid),
            )

            cur.execute(
                """
                DELETE FROM category_access ca
                USING categories c
                WHERE ca.manager_id=%s AND ca.category_id=c.id AND c.company_id=%s
                """,
                (mid, cid),
            )
            cur.execute(
                """
                INSERT INTO category_access (category_id, manager_id, created_at)
                WITH RECURSIVE owned_nodes AS (
                    SELECT n.id, n.parent_node_id, n.level_position
                    FROM catalog_nodes n
                    JOIN node_owners no ON no.node_id = n.id
                    WHERE no.company_id=%s AND no.manager_id=%s AND n.company_id=%s
                    UNION
                    SELECT p.id, p.parent_node_id, p.level_position
                    FROM catalog_nodes p
                    JOIN owned_nodes o ON o.parent_node_id = p.id
                    WHERE p.company_id=%s
                )
                SELECT DISTINCT o.id, %s, %s::timestamp without time zone
                FROM owned_nodes o
                WHERE o.level_position=0
                ON CONFLICT DO NOTHING
                """,
                (cid, mid, cid, cid, mid, now),
            )

            cur.execute(
                """
                INSERT INTO manager_allowed_regions (manager_id, company_id, region_id, created_at)
                WITH RECURSIVE owned_nodes AS (
                    SELECT n.id, n.parent_node_id, n.region_id
                    FROM catalog_nodes n
                    JOIN node_owners no ON no.node_id = n.id
                    WHERE no.company_id=%s AND no.manager_id=%s AND n.company_id=%s
                    UNION
                    SELECT p.id, p.parent_node_id, p.region_id
                    FROM catalog_nodes p
                    JOIN owned_nodes o ON o.parent_node_id = p.id
                    WHERE p.company_id=%s
                )
                SELECT DISTINCT %s, %s, o.region_id, %s::timestamp without time zone
                FROM owned_nodes o
                WHERE COALESCE(o.region_id, '') <> ''
                ON CONFLICT DO NOTHING
                """,
                (cid, mid, cid, cid, mid, cid, now),
            )

    def _assign_owner_to_nodes(
        self,
        manager_id: str,
        company_id: str,
        node_ids: list[str],
    ) -> tuple[int, int]:
        """Assign manager as node owner; max 5 owners per node."""
        if not self._use_postgres():
            return (0, 0)
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        ids = sorted({str(x) for x in (node_ids or []) if str(x).strip()})
        if not mid or not cid or not ids:
            return (0, 0)
        inserted = 0
        skipped_limit = 0
        now = self._now_ts()
        with self._pg().cursor() as cur:
            # Two batched lookups (owner counts + this manager's existing
            # memberships) instead of 2 round trips PER node — a scope save
            # can cover dozens/hundreds of nodes at once.
            cur.execute(
                "SELECT node_id, COUNT(*) AS n FROM node_owners WHERE company_id=%s AND node_id = ANY(%s) GROUP BY node_id",
                (cid, ids),
            )
            owners_by_node = {
                str(r.get("node_id")): int(r.get("n") or 0)
                for r in (cur.fetchall() or [])
                if isinstance(r, dict)
            }
            cur.execute(
                "SELECT node_id FROM node_owners WHERE company_id=%s AND node_id = ANY(%s) AND manager_id=%s",
                (cid, ids, mid),
            )
            already_owned = {
                str(r.get("node_id"))
                for r in (cur.fetchall() or [])
                if isinstance(r, dict)
            }

            to_insert = []
            for nid in ids:
                if nid in already_owned:
                    continue
                if owners_by_node.get(nid, 0) >= 5:
                    skipped_limit += 1
                    continue
                to_insert.append((cid, nid, mid, now))

            CHUNK = 500
            for i in range(0, len(to_insert), CHUNK):
                chunk = to_insert[i : i + CHUNK]
                placeholders = ", ".join(["(%s,%s,%s,%s)"] * len(chunk))
                flat_params = [v for row in chunk for v in row]
                cur.execute(
                    f"INSERT INTO node_owners (company_id, node_id, manager_id, created_at) VALUES {placeholders}",
                    flat_params,
                )
            inserted = len(to_insert)
        self._sync_legacy_scope_access(cid, mid)
        return (inserted, skipped_limit)

    def add_node_owner(self, manager_id: str, company_id: str, node_id: str) -> bool:
        """Register a manager as owner of a single catalog node (level_node)."""
        inserted, _ = self._assign_owner_to_nodes(manager_id, company_id, [node_id])
        return inserted > 0

    def _remove_owner_from_nodes(
        self,
        manager_id: str,
        company_id: str,
        node_ids: list[str],
    ) -> int:
        if not self._use_postgres():
            return 0
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        ids = sorted({str(x) for x in (node_ids or []) if str(x).strip()})
        if not mid or not cid or not ids:
            return 0
        with self._pg().cursor() as cur:
            cur.execute(
                "DELETE FROM node_owners WHERE company_id=%s AND manager_id=%s AND node_id = ANY(%s)",
                (cid, mid, ids),
            )
            removed = int(cur.rowcount or 0)
            # Also clean legacy category_access entries so the removal is complete.
            with contextlib.suppress(Exception):
                cur.execute(
                    "DELETE FROM category_access WHERE manager_id=%s AND category_id = ANY(%s)",
                    (mid, ids),
                )
        self._sync_legacy_scope_access(cid, mid)
        # Recompute entity_owners for the affected nodes so that the removed
        # manager's entries are cleaned up from all downstream tables
        # (products, suppliers, packaging, orders, media_plan, schedule_groups, etc.).
        with contextlib.suppress(Exception):
            self.recompute_entity_owners_for_scope(cid, ids)
        # Additionally, purge any remaining entity_owners rows for this manager
        # that might not be covered by recompute (e.g. if no products were found
        # under those nodes but stale rows still exist).
        with contextlib.suppress(Exception):
            remaining_node_ids = {
                str(x)
                for x in self.get_manager_scope_node_ids(
                    mid, company_id=cid, permission="view"
                )
                if str(x).strip()
            }
            if not remaining_node_ids:
                # Manager has zero remaining scope — purge ALL their entity_owners.
                with self._pg().cursor() as cur:
                    cur.execute(
                        "DELETE FROM entity_owners WHERE company_id=%s AND manager_id=%s",
                        (cid, mid),
                    )
        return removed

    def get_manager_scope_node_ids(
        self, manager_id: str, company_id: str, permission: str = "view"
    ) -> list[str]:
        if not self._use_postgres():
            return (
                self._get(
                    "/managers/scopes",
                    {
                        "manager_id": manager_id,
                        "company_id": company_id,
                        "permission": permission,
                    },
                )
                or []
            )
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        with self._pg().cursor() as cur:
            # Canonical owner source.
            cur.execute(
                "SELECT node_id FROM node_owners WHERE manager_id=%s AND company_id=%s",
                (mid, cid),
            )
            rows = cur.fetchall() or []
            with contextlib.suppress(Exception):
                cur.execute(
                    """
                    SELECT DISTINCT ca.category_id AS node_id
                    FROM category_access ca
                    JOIN categories c ON c.id = ca.category_id
                    WHERE ca.manager_id=%s AND c.company_id=%s
                    ORDER BY ca.category_id
                    """,
                    (mid, cid),
                )
                legacy_rows = cur.fetchall() or []
                if legacy_rows:
                    rows = list(rows) + list(legacy_rows)
            if not rows:
                cur.execute(
                    "SELECT node_id FROM manager_access_scopes WHERE manager_id=%s AND company_id=%s AND permission=%s",
                    (mid, cid, str(permission or "view")),
                )
                rows = cur.fetchall() or []
        return [
            str(r.get("node_id"))
            for r in rows
            if isinstance(r, dict) and r.get("node_id")
        ]

    def manager_has_category_access_in_region(
        self, manager_id: str, company_id: str, region_id: str | None
    ) -> bool:
        """Whether this manager can create/edit anything in region_id right now.

        Region access and category access are granted separately (a manager
        can be allowed into a region via manager_allowed_regions without
        owning a single category node there) -- creating/editing a product,
        order, packaging item, etc. always requires assigning it to a
        category, so a manager with zero owned nodes in this specific
        region should only be able to view, never add/edit.

        get_manager_scope_node_ids() is NOT region-scoped (it returns every
        node this manager owns company-wide), so this cross-references
        those node ids against catalog_nodes.region_id to get a true
        per-region answer. Admin/superadmin roles are never scope-restricted.
        """
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        rid = str(region_id or "").strip()
        if not mid or not cid:
            return False
        role_slug = self._get_manager_role_slug(mid)
        if role_slug in {
            "адмін", "админ", "admin", "суперадмін", "суперадмин", "superadmin",
        }:
            return True
        if not rid:
            return False
        node_ids = [
            str(x) for x in (self.get_manager_scope_node_ids(mid, cid, "view") or [])
            if str(x or "").strip()
        ]
        if not node_ids:
            return False
        if not self._use_postgres():
            return True  # HTTP-backend mode: no local cross-reference available.
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT 1 FROM catalog_nodes WHERE company_id=%s AND region_id=%s AND id = ANY(%s) LIMIT 1",
                    (cid, rid, list(set(node_ids))),
                )
                return bool(cur.fetchone())
        except Exception:
            logger.exception("manager_has_category_access_in_region failed")
            return True  # fail open -- never block on an unrelated query error

    def has_shared_node_ownership(
        self, company_id: str, manager_a: str, manager_b: str
    ) -> bool:
        if not self._use_postgres():
            return False
        cid = str(company_id or "").strip()
        a = str(manager_a or "").strip()
        b = str(manager_b or "").strip()
        if not cid or not a or not b or a == b:
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT 1
                FROM node_owners n1
                JOIN node_owners n2
                  ON n2.company_id = n1.company_id
                 AND n2.node_id = n1.node_id
                WHERE n1.company_id=%s
                  AND n1.manager_id=%s
                  AND n2.manager_id=%s
                LIMIT 1
                """,
                (cid, a, b),
            )
            return bool(cur.fetchone())

    def has_entity_owner(
        self, company_id: str, manager_id: str, entity_type: str, entity_id: str
    ) -> bool:
        if not self._use_postgres():
            return False
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        etype = str(entity_type or "").strip()
        eid = str(entity_id or "").strip()
        if not cid or not mid or not etype or not eid:
            return False
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT 1
                FROM entity_owners
                WHERE company_id=%s AND manager_id=%s AND entity_type=%s AND entity_id=%s
                LIMIT 1
                """,
                (cid, mid, etype, eid),
            )
            return bool(cur.fetchone())

    def has_shared_entity_ownership(
        self,
        company_id: str,
        manager_a: str,
        manager_b: str,
        entity_types: list[str] | None = None,
    ) -> bool:
        if not self._use_postgres():
            return False
        cid = str(company_id or "").strip()
        a = str(manager_a or "").strip()
        b = str(manager_b or "").strip()
        if not cid or not a or not b or a == b:
            return False
        types = [str(x).strip() for x in (entity_types or []) if str(x).strip()]
        with self._pg().cursor() as cur:
            if types:
                cur.execute(
                    """
                    SELECT 1
                    FROM entity_owners e1
                    JOIN entity_owners e2
                      ON e2.company_id = e1.company_id
                     AND e2.entity_type = e1.entity_type
                     AND e2.entity_id = e1.entity_id
                    WHERE e1.company_id=%s
                      AND e1.manager_id=%s
                      AND e2.manager_id=%s
                      AND e1.entity_type = ANY(%s)
                    LIMIT 1
                    """,
                    (cid, a, b, types),
                )
            else:
                cur.execute(
                    """
                    SELECT 1
                    FROM entity_owners e1
                    JOIN entity_owners e2
                      ON e2.company_id = e1.company_id
                     AND e2.entity_type = e1.entity_type
                     AND e2.entity_id = e1.entity_id
                    WHERE e1.company_id=%s
                      AND e1.manager_id=%s
                      AND e2.manager_id=%s
                    LIMIT 1
                    """,
                    (cid, a, b),
                )
            return bool(cur.fetchone())

    def get_entity_owner_entity_ids(
        self, company_id: str, manager_id: str, entity_type: str
    ) -> list[str]:
        if not self._use_postgres():
            return []
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        etype = str(entity_type or "").strip()
        if not cid or not mid or not etype:
            return []
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT entity_id
                FROM entity_owners
                WHERE company_id=%s AND manager_id=%s AND entity_type=%s
                """,
                (cid, mid, etype),
            )
            rows = cur.fetchall() or []
        return [
            str(r.get("entity_id"))
            for r in rows
            if isinstance(r, dict) and r.get("entity_id")
        ]

    def count_entity_owner_entity_ids(
        self, company_id: str, manager_id: str, entity_type: str
    ) -> int:
        if not self._use_postgres():
            return -1
        cid = str(company_id or "").strip()
        mid = str(manager_id or "").strip()
        etype = str(entity_type or "").strip()
        if not cid or not mid or not etype:
            return -1
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT COUNT(DISTINCT entity_id) AS cnt
                    FROM entity_owners
                    WHERE company_id=%s AND manager_id=%s AND entity_type=%s
                    """,
                    (cid, mid, etype),
                )
                row = cur.fetchone()
            return int((row or {}).get("cnt") or 0)
        except Exception:
            return -1

    def get_assigned_category_ids(self, company_id: str) -> list[str]:
        """Get all category IDs (level_position=0) that are already assigned to any manager."""
        if not self._use_postgres():
            return []
        cid = str(company_id or "").strip()
        if not cid:
            return []
        with self._pg().cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT n.id
                FROM node_owners no
                JOIN catalog_nodes n ON n.id = no.node_id
                WHERE no.company_id=%s AND n.level_position=0
                """,
                (cid,),
            )
            rows = cur.fetchall() or []
        return [str(r.get("id")) for r in rows if isinstance(r, dict) and r.get("id")]

    def get_category_and_descendants_ids(
        self, company_id: str, category_id: str
    ) -> list[str]:
        """Get category ID and all its descendant node IDs (for assigning full category access)."""
        if not self._use_postgres():
            return []
        cid = str(company_id or "").strip()
        cat_id = str(category_id or "").strip()
        if not cid or not cat_id:
            return []

        result = [cat_id]
        with self._pg().cursor() as cur:
            # Get all descendants recursively
            cur.execute(
                """
                WITH RECURSIVE descendants AS (
                    SELECT id, parent_node_id
                    FROM catalog_nodes
                    WHERE id=%s AND company_id=%s
                    UNION ALL
                    SELECT n.id, n.parent_node_id
                    FROM catalog_nodes n
                    INNER JOIN descendants d ON n.parent_node_id = d.id
                    WHERE n.company_id=%s
                )
                SELECT id FROM descendants WHERE id != %s
                """,
                (cat_id, cid, cid, cat_id),
            )
            rows = cur.fetchall() or []
        result.extend(
            [str(r.get("id")) for r in rows if isinstance(r, dict) and r.get("id")]
        )
        return result

    def replace_manager_access_scopes(
        self,
        manager_id: str,
        company_id: str,
        node_ids: list,
        permission: str = "view",
        inherit_to_children: bool = True,  # noqa: ARG002
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/managers/scopes/replace",
                    {
                        "manager_id": manager_id,
                        "company_id": company_id,
                        "node_ids": node_ids,
                        "permission": permission,
                    },
                )
                or False
            )
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        perm = str(permission or "view")
        node_ids = [str(x) for x in (node_ids or []) if str(x).strip()]
        if perm == "view":
            with self._pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM node_owners WHERE company_id=%s AND manager_id=%s",
                    (cid, mid),
                )
            self._assign_owner_to_nodes(mid, cid, node_ids)

        with self._pg().cursor() as cur:
            cur.execute(
                "DELETE FROM manager_access_scopes WHERE manager_id=%s AND company_id=%s AND permission=%s",
                (mid, cid, perm),
            )
            # Batched multi-row INSERT instead of one execute() per node —
            # a broad scope grant can cover hundreds of nodes at once.
            _mas_now = self._now_ts()
            CHUNK = 500
            for i in range(0, len(node_ids), CHUNK):
                chunk = node_ids[i : i + CHUNK]
                placeholders = ", ".join(["(%s,%s,%s,%s,%s)"] * len(chunk))
                flat_params = [
                    v for nid in chunk for v in (mid, cid, perm, nid, _mas_now)
                ]
                cur.execute(
                    f"INSERT INTO manager_access_scopes (manager_id, company_id, permission, node_id, created_at) VALUES {placeholders}",
                    flat_params,
                )

            # Keep legacy `category_access` in sync so UI doesn't "re-check" old entries
            # when scopes are empty/incomplete.
            #
            # In our Postgres model, category root node_id == category_id.
            cat_ids = []
            if perm == "view":
                with contextlib.suppress(Exception):
                    # Ensure nodes exist (so node_ids can be resolved to categories reliably)
                    self.sync_company_catalog_nodes(cid)
                cats = self.get_company_categories(cid, None)
                cat_id_set = {
                    str(c.get("id"))
                    for c in (cats or [])
                    if isinstance(c, dict) and c.get("id")
                }
                cat_ids = [nid for nid in node_ids if nid in cat_id_set]

            # Remove all existing legacy access rows for this manager within this company
            cur.execute(
                """
                DELETE FROM category_access ca
                USING categories c
                WHERE ca.manager_id=%s AND ca.category_id=c.id AND c.company_id=%s
                """,
                (mid, cid),
            )
            # Reinsert legacy access for selected categories (if any) —
            # batched instead of one execute() per category.
            if cat_ids:
                _ca_now = self._now_ts()
                placeholders = ", ".join(["(%s,%s,%s)"] * len(cat_ids))
                flat_params = [
                    v for cat_id in cat_ids for v in (cat_id, mid, _ca_now)
                ]
                cur.execute(
                    f"INSERT INTO category_access (category_id, manager_id, created_at) VALUES {placeholders}",
                    flat_params,
                )

        # Access assignment should only change visibility scopes.
        # Business data is shared by scope and must not be duplicated on grant.
        return True

    def reassign_manager_ownership_for_scope_nodes(
        self, manager_id: str, company_id: str, node_ids: list
    ) -> bool:
        if not self._use_postgres():
            return False
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        seed_ids = {str(x) for x in (node_ids or []) if str(x).strip()}
        if not mid or not cid or not seed_ids:
            return False

        self.sync_company_catalog_nodes(cid)
        all_nodes = [
            n
            for n in (self.get_company_catalog_nodes(cid, force_refresh=False) or [])
            if isinstance(n, dict) and n.get("id")
        ]
        if not all_nodes:
            return False

        by_id = {str(n.get("id")): n for n in all_nodes}
        children_of = {}
        for n in all_nodes:
            pid = str(n.get("parent_id") or "").strip()
            nid = str(n.get("id") or "").strip()
            if pid and nid:
                children_of.setdefault(pid, []).append(nid)

        expanded_ids = set()
        stack = list(seed_ids)
        while stack:
            cur = str(stack.pop() or "").strip()
            if not cur or cur in expanded_ids:
                continue
            expanded_ids.add(cur)
            stack.extend(children_of.get(cur, []))

        category_ids = set()
        for nid in expanded_ids:
            node = by_id.get(nid) or {}
            ntype = str(node.get("node_type") or "").strip()
            if ntype == "category":
                category_ids.add(nid)
                continue
            cur = node
            visited = set()
            while cur and cur.get("id") and cur.get("id") not in visited:
                visited.add(cur.get("id"))
                if str(cur.get("node_type") or "") == "category":
                    category_ids.add(str(cur.get("id")))
                    break
                parent_id = str(cur.get("parent_id") or "").strip()
                cur = by_id.get(parent_id)

        if not expanded_ids and not category_ids:
            return False

        cond_parts = []
        params = []
        if category_ids:
            cond_parts.append("(p.data->>'category_id') = ANY(%s)")
            params.append(list(category_ids))
        if expanded_ids:
            cond_parts.append("(p.data->>'catalog_node_id') = ANY(%s)")
            params.append(list(expanded_ids))
        if not cond_parts:
            return False

        where_products = " OR ".join(cond_parts)
        now = self._now_ts()

        with self._pg().cursor() as cur:
            cur.execute(
                f"""
                UPDATE products p
                   SET manager_id=%s,
                       updated_at=%s
                 WHERE p.company_id=%s
                   AND ({where_products})
                """,
                (mid, now, cid, *params),
            )

            cur.execute(
                f"""
                SELECT p.id,
                       p.data->>'supplier_id' AS supplier_id,
                       p.data->>'packaging_id' AS packaging_id
                  FROM products p
                 WHERE p.company_id=%s
                   AND ({where_products})
                """,
                (cid, *params),
            )
            rows = cur.fetchall() or []

            product_ids = [str(r.get("id")) for r in rows if r.get("id")]
            supplier_ids = [
                str(r.get("supplier_id"))
                for r in rows
                if str(r.get("supplier_id") or "").strip()
            ]
            packaging_ids = [
                str(r.get("packaging_id"))
                for r in rows
                if str(r.get("packaging_id") or "").strip()
            ]

            if supplier_ids:
                cur.execute(
                    """
                    UPDATE suppliers
                       SET manager_id=%s,
                           updated_at=%s
                     WHERE company_id=%s
                       AND id = ANY(%s)
                    """,
                    (mid, now, cid, supplier_ids),
                )

            if packaging_ids:
                cur.execute(
                    """
                    UPDATE packaging
                       SET manager_id=%s,
                           updated_at=%s
                     WHERE company_id=%s
                       AND id = ANY(%s)
                    """,
                    (mid, now, cid, packaging_ids),
                )

            if product_ids:
                cur.execute(
                    """
                    UPDATE orders o
                       SET manager_id=%s,
                           updated_at=%s
                     WHERE o.company_id=%s
                       AND EXISTS (
                           SELECT 1
                             FROM jsonb_array_elements(COALESCE(o.data->'items', '[]'::jsonb)) AS it
                            WHERE (it->>'product_id') = ANY(%s)
                       )
                    """,
                    (mid, now, cid, product_ids),
                )

                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        UPDATE media_plan_entries
                           SET manager_id=%s,
                               updated_at=%s
                         WHERE company_id=%s
                           AND product_ids ?| %s
                        """,
                        (mid, now, cid, product_ids),
                    )

                with contextlib.suppress(Exception):
                    cur.execute(
                        """
                        UPDATE order_schedule_groups
                           SET manager_id=%s,
                               updated_at=%s
                         WHERE company_id=%s
                           AND product_ids ?| %s
                        """,
                        (mid, now, cid, product_ids),
                    )

            if supplier_ids:
                with contextlib.suppress(Exception):
                    cur.execute("""
                        SELECT EXISTS (
                            SELECT 1
                              FROM information_schema.columns
                             WHERE table_schema='public'
                               AND table_name='supplier_settlements'
                               AND column_name='manager_id'
                        ) AS has_manager
                        """)
                    has_manager = bool((cur.fetchone() or {}).get("has_manager"))
                    if has_manager:
                        cur.execute(
                            """
                            UPDATE supplier_settlements
                               SET manager_id=%s,
                                   updated_at=%s
                             WHERE company_id=%s
                               AND supplier_id = ANY(%s)
                            """,
                            (mid, now, cid, supplier_ids),
                        )

        return True

    def get_manager_supervisor_ids(self, manager_id: str) -> list[str]:
        if not self._use_postgres():
            return self._get("/managers/supervisors", {"manager_id": manager_id}) or []
        mid = str(manager_id or "").strip()
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT supervisor_id FROM manager_supervisors WHERE manager_id=%s",
                (mid,),
            )
            rows = cur.fetchall() or []
        return [
            str(r.get("supervisor_id"))
            for r in rows
            if isinstance(r, dict) and r.get("supervisor_id")
        ]

    def replace_manager_supervisors(
        self, manager_id: str, supervisor_ids: list, company_id: str
    ) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/managers/supervisors/replace",
                    {
                        "manager_id": manager_id,
                        "supervisor_ids": supervisor_ids,
                        "company_id": company_id,
                    },
                )
                or False
            )
        mid = str(manager_id or "").strip()
        cid = str(company_id or "").strip()
        supervisor_ids = [str(x) for x in (supervisor_ids or []) if str(x).strip()]
        with self._pg().cursor() as cur:
            cur.execute("DELETE FROM manager_supervisors WHERE manager_id=%s", (mid,))
            if supervisor_ids:
                now = self._now_ts()
                placeholders = ", ".join(["(%s,%s,%s,%s)"] * len(supervisor_ids))
                flat_params = [
                    v for sid in supervisor_ids for v in (mid, sid, cid, now)
                ]
                cur.execute(
                    f"INSERT INTO manager_supervisors (manager_id, supervisor_id, company_id, created_at) VALUES {placeholders}",
                    flat_params,
                )
        return True

    def get_all_subordinates_recursive(
        self, supervisor_id: str, company_id: str
    ) -> list[dict]:
        """Return all managers (at any depth) supervised by supervisor_id.
        Uses a recursive CTE so it captures direct + indirect subordinates.
        Returns list of manager dicts (id, full_name, ...) same shape as get_visible_managers.
        """
        if not self._use_postgres():
            # REST fallback: iterate get_visible_managers level by level
            seen: set = set()
            queue = [str(supervisor_id or "").strip()]
            result = []
            while queue:
                current_sup = queue.pop(0)
                try:
                    subs = (
                        self._get(
                            "/managers/visible",
                            {
                                "company_id": company_id,
                                "requester_manager_id": current_sup,
                                "requester_role": "manager",
                            },
                        )
                        or []
                    )
                except Exception:
                    subs = []
                for m in subs:
                    if not isinstance(m, dict):
                        continue
                    mid = str(m.get("id") or "").strip()
                    if mid and mid not in seen:
                        seen.add(mid)
                        result.append(m)
                        queue.append(mid)
            return result

        sid = str(supervisor_id or "").strip()
        cid = str(company_id or "").strip()
        if not sid or not cid:
            return []
        # manager_supervisors is company-scoped (own database); public.managers is
        # general (shared database) — resolve the subordinate-id tree first, then
        # fetch manager details from the general DB. No cross-DB join possible.
        with self._pg().cursor() as cur:
            cur.execute(
                """
                WITH RECURSIVE sub_tree AS (
                    SELECT ms.manager_id
                    FROM manager_supervisors ms
                    WHERE ms.supervisor_id = %s AND ms.company_id = %s
                    UNION
                    SELECT ms2.manager_id
                    FROM manager_supervisors ms2
                    JOIN sub_tree st ON ms2.supervisor_id = st.manager_id
                    WHERE ms2.company_id = %s
                )
                SELECT manager_id FROM sub_tree
                """,
                (sid, cid, cid),
            )
            sub_ids = [
                str(r["manager_id"])
                for r in (cur.fetchall() or [])
                if r.get("manager_id")
            ]
        if not sub_ids:
            return []
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                SELECT m.*
                FROM public.managers m
                WHERE m.id = ANY(%s)
                  AND m.company_id = %s
                  AND lower(coalesce(m.role,'')) NOT IN ('admin','superadmin','super_admin','super admin')
                ORDER BY m.full_name
                """,
                (sub_ids, cid),
            )
            rows = cur.fetchall() or []
        return [dict(r) for r in rows if isinstance(r, dict)]

    def replace_category_access(self, category_id: str, manager_ids: list) -> bool:
        if not self._use_postgres():
            return bool(
                self._post(
                    "/categories/access/replace",
                    {"category_id": category_id, "manager_ids": manager_ids},
                )
                or False
            )
        cat_id = str(category_id or "").strip()
        manager_ids = [str(x) for x in (manager_ids or []) if str(x).strip()]
        with self._pg().cursor() as cur:
            cur.execute("DELETE FROM category_access WHERE category_id=%s", (cat_id,))
            if manager_ids:
                now = self._now_ts()
                placeholders = ", ".join(["(%s,%s,%s)"] * len(manager_ids))
                flat_params = [v for mid in manager_ids for v in (cat_id, mid, now)]
                cur.execute(
                    f"INSERT INTO category_access (category_id, manager_id, created_at) VALUES {placeholders}",
                    flat_params,
                )
        return True

    def get_manager_category_ids(
        self,
        manager_id: str,
        company_id: str | None = None,
        region_id: str | None = None,
    ):
        """
        Returns list of category ids assigned to manager via `category_access`.
        Optional filters:
        - company_id: only categories from this company
        - region_id: only categories from this region
        """
        if not self._use_postgres():
            return (
                self._get(
                    "/categories/access/manager_category_ids",
                    {
                        "manager_id": manager_id,
                        "company_id": company_id or "",
                        "region_id": region_id or "",
                    },
                )
                or []
            )
        mid = str(manager_id or "").strip()
        if not mid:
            return []
        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        with self._pg().cursor() as cur:
            if company_id or region_id:
                q = """
                SELECT ca.category_id
                FROM category_access ca
                JOIN categories c ON c.id = ca.category_id
                WHERE ca.manager_id=%s
                """
                params: list[Any] = [mid]
                if company_id:
                    q += " AND c.company_id=%s"
                    params.append(company_id)
                if region_id:
                    q += " AND c.region_id=%s"
                    params.append(region_id)
                q += " ORDER BY ca.category_id"
                cur.execute(q, params)
            else:
                cur.execute(
                    "SELECT category_id FROM category_access WHERE manager_id=%s ORDER BY category_id",
                    (mid,),
                )
            rows = cur.fetchall() or []
        out: list[str] = []
        for r in rows:
            if isinstance(r, dict) and r.get("category_id"):
                out.append(str(r.get("category_id")))
            elif isinstance(r, (list, tuple)) and r and r[0]:
                out.append(str(r[0]))
        return out

    # ----------------- app update policy (avoid startup crash) -----------------
    def get_app_update_policy(self) -> dict:
        """
        main.py expects a dict with optional keys: min_required, latest.
        In local/offline mode return permissive defaults.
        """
        if not self._use_postgres():
            return {}
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT policy FROM public.app_update_policy WHERE id=%s LIMIT 1",
                    ("default",),
                )
                row = cur.fetchone()
            if row and isinstance(row.get("policy"), dict):
                return row["policy"]
        return {}

    def set_app_update_policy(
        self, payload: dict | str, download_url: str | None = None
    ) -> bool:
        """
        Backward compatible setter.
        UI may call: set_app_update_policy(min_required, download_url)
        Or code may call: set_app_update_policy({"min_required": "...", "download_url": "..."})
        """
        if not self._use_postgres():
            return True
        if isinstance(payload, dict):
            policy = payload
        else:
            policy = {
                "min_required": str(payload or "").strip(),
                "download_url": str(download_url or "").strip(),
            }
        if not isinstance(policy, dict):
            return False
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.app_update_policy (id, policy, updated_at)
                VALUES (%s, %s::jsonb, %s)
                ON CONFLICT (id) DO UPDATE SET policy=EXCLUDED.policy, updated_at=EXCLUDED.updated_at
                """,
                ("default", psycopg.types.json.Jsonb(policy), self._now_ts()),
            )
        return True

    def get_infrastructure_settings(self) -> dict:
        """
        Global infrastructure settings for switching Local/VPS without code changes.
        Stored in app_update_policy table under id='infrastructure'.
        """
        _live = self.get_general_db_location()
        _live_dsn = str(self._pg_dsn or "").strip()
        defaults = {
            "mode": "local" if _live.get("is_local") else "vps",
            "local_db_dsn": _live_dsn if _live.get("is_local") else "",
            "vps_db_dsn": "" if _live.get("is_local") else _live_dsn,
            "extensions_db_dsn": "",
            "parser_db_dsn": "",
            "auto_migrate_on_switch": True,
        }
        if not self._use_postgres():
            return defaults
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT policy FROM public.app_update_policy WHERE id=%s LIMIT 1",
                    ("infrastructure",),
                )
                row = cur.fetchone() or {}
            policy = row.get("policy") if isinstance(row.get("policy"), dict) else {}
            out = dict(defaults)
            out.update(policy or {})
            out["mode"] = (
                "vps"
                if str(out.get("mode") or "").strip().lower() == "vps"
                else "local"
            )
            out["auto_migrate_on_switch"] = bool(
                out.get("auto_migrate_on_switch", True)
            )
            # Single-DB mode: parser/extensions always use current active mode DSN.
            active_dsn = (
                str(out.get("vps_db_dsn") or "").strip()
                if out["mode"] == "vps"
                else str(out.get("local_db_dsn") or "").strip()
            )
            out["parser_db_dsn"] = active_dsn
            out["extensions_db_dsn"] = active_dsn
            return out
        return defaults

    def set_infrastructure_settings(self, payload: dict) -> bool:
        if not isinstance(payload, dict):
            return False
        current = self.get_infrastructure_settings()
        merged = dict(current)
        merged.update(payload)
        merged["mode"] = (
            "vps" if str(merged.get("mode") or "").strip().lower() == "vps" else "local"
        )
        for key in [
            "local_db_dsn",
            "vps_db_dsn",
            "extensions_db_dsn",
            "parser_db_dsn",
        ]:
            merged[key] = str(merged.get(key) or "").strip()
        merged["auto_migrate_on_switch"] = bool(
            merged.get("auto_migrate_on_switch", True)
        )

        # Single-DB mode: always mirror parser/extensions to active DSN.
        active_dsn = (
            str(merged.get("vps_db_dsn") or "").strip()
            if merged["mode"] == "vps"
            else str(merged.get("local_db_dsn") or "").strip()
        )
        merged["parser_db_dsn"] = active_dsn
        merged["extensions_db_dsn"] = active_dsn

        if not self._use_postgres():
            return True
        with self._general_pg().cursor() as cur:
            cur.execute(
                """
                INSERT INTO public.app_update_policy (id, policy, updated_at)
                VALUES (%s, %s::jsonb, %s)
                ON CONFLICT (id) DO UPDATE SET policy=EXCLUDED.policy, updated_at=EXCLUDED.updated_at
                """,
                ("infrastructure", psycopg.types.json.Jsonb(merged), self._now_ts()),
            )
        return True

    def migrate_local_to_vps(
        self,
        target_dsn: str,
        progress_callback=None,
        source_dsn: str | None = None,
    ) -> tuple[bool, str]:
        """
        Copies all data from source DB (local) to target DB (VPS).
        Does NOT delete source data — full safe copy.
        Returns (success, summary_message).
        """
        src_dsn = str(source_dsn or self._pg_dsn or "").strip()
        tgt_dsn = str(target_dsn or "").strip()

        if not src_dsn:
            return False, "Джерельний DSN порожній."
        if not tgt_dsn:
            return False, "Цільовий (VPS) DSN порожній."
        if src_dsn == tgt_dsn:
            return False, "Джерельна і цільова бази однакові."

        def _log(msg: str):
            logger.info("migrate_local_to_vps: %s", msg)
            if progress_callback:
                with contextlib.suppress(Exception):
                    progress_callback(msg)

        try:
            src_conn = psycopg.connect(src_dsn, autocommit=True, row_factory=dict_row)
        except Exception as exc:
            return False, f"Не вдалося підключитися до джерела (локальна): {exc}"

        try:
            tgt_conn = psycopg.connect(tgt_dsn, autocommit=True, row_factory=dict_row)
        except Exception as exc:
            with contextlib.suppress(Exception):
                src_conn.close()
            return False, f"Не вдалося підключитися до VPS: {exc}"

        try:
            # Bootstrap schema on target
            _log("Перевіряю/створюю схему на VPS...")
            try:
                tmp_dm: "DataManager" = DataManager.__new__(DataManager)
                tmp_dm._pg_dsn = tgt_dsn
                tmp_dm._general_pg_conn = tgt_conn
                tmp_dm._general_schema_ready = False
                tmp_dm._http = self._http
                tmp_dm.base_url = self.base_url
                tmp_dm._timeout_s = self._timeout_s
                tmp_dm._ensure_general_schema()
            except Exception as exc:
                _log(f"Увага при перевірці схеми: {exc} — продовжую копіювання.")

            # Try to disable FK/trigger checks on target (requires superuser; skip if denied)
            try:
                with tgt_conn.cursor() as cur:
                    cur.execute("SET session_replication_role = 'replica'")
                _log("Тригери/FK на VPS тимчасово вимкнено.")
                fk_disabled = True
            except Exception:
                fk_disabled = False
                _log(
                    "Без прав суперкористувача — FK активні; при помилці таблиця буде пропущена."
                )

            # Get all tables in public schema from source
            with src_conn.cursor() as cur:
                cur.execute("""
                    SELECT t.tablename
                    FROM pg_tables t
                    WHERE t.schemaname = 'public'
                    ORDER BY t.tablename
                    """)
                tables = [row["tablename"] for row in cur.fetchall()]

            _log(f"Знайдено {len(tables)} таблиць для копіювання.")

            total_rows = 0
            errors: list[str] = []

            for tbl in tables:
                try:
                    # Get column names
                    with src_conn.cursor() as cur:
                        cur.execute(f'SELECT * FROM public."{tbl}" LIMIT 0')
                        col_names = [desc.name for desc in cur.description]

                    # Read all rows from source
                    with src_conn.cursor() as cur:
                        cur.execute(f'SELECT * FROM public."{tbl}"')
                        rows = cur.fetchall()

                    if not rows:
                        _log(f"  {tbl}: порожня, пропускаю.")
                        continue

                    cols_sql = ", ".join(f'"{c}"' for c in col_names)
                    placeholders = ", ".join(["%s"] * len(col_names))
                    insert_sql = (
                        f'INSERT INTO public."{tbl}" ({cols_sql}) '
                        f"VALUES ({placeholders}) ON CONFLICT DO NOTHING"
                    )

                    batch = [tuple(row[c] for c in col_names) for row in rows]

                    with tgt_conn.cursor() as cur:
                        cur.executemany(insert_sql, batch)

                    total_rows += len(rows)
                    _log(f"  {tbl}: {len(rows)} рядків скопійовано.")

                except Exception as exc:
                    err = f"  {tbl}: ПОМИЛКА — {exc}"
                    _log(err)
                    errors.append(err)

            # Re-enable FK/trigger checks
            if fk_disabled:
                with contextlib.suppress(Exception):
                    with tgt_conn.cursor() as cur:
                        cur.execute("SET session_replication_role = 'origin'")

            summary = (
                f"Міграція завершена. Скопійовано ~{total_rows} рядків "
                f"з {len(tables)} таблиць."
            )
            if errors:
                summary += f" Помилок (таблиць пропущено): {len(errors)}."
            _log(summary)
            return (len(errors) == 0), summary

        finally:
            with contextlib.suppress(Exception):
                src_conn.close()
            with contextlib.suppress(Exception):
                tgt_conn.close()

    def drop_database_contents(self, target_dsn: str) -> tuple[bool, str]:
        """Delete all rows from all public tables in target_dsn. Schema is kept."""
        dsn = str(target_dsn or "").strip()
        if not dsn:
            return False, "DSN порожній."
        active = str(self._pg_dsn or "").strip()
        if dsn == active:
            return False, "Не можна видалити дані з поточної активної БД."
        try:
            conn = psycopg.connect(dsn, autocommit=True, row_factory=dict_row)
        except Exception as exc:
            return False, f"Не вдалося підключитися: {exc}"
        try:
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename"
                )
                tables = [r["tablename"] for r in cur.fetchall()]
            deleted = 0
            errors: list[str] = []
            for tbl in tables:
                try:
                    with conn.cursor() as cur:
                        cur.execute(f'DELETE FROM public."{tbl}"')
                        deleted += 1
                except Exception as exc:
                    errors.append(f"{tbl}: {exc}")
            msg = f"Видалено дані з {deleted} таблиць."
            if errors:
                msg += f" Помилок: {len(errors)}."
            return len(errors) == 0, msg
        finally:
            with contextlib.suppress(Exception):
                conn.close()

    def apply_infrastructure_switch(self) -> tuple[bool, str]:
        """
        Reads saved infrastructure settings, determines the active DSN (local vs vps),
        reconnects DataManager live, and writes the new DSN to .env for persistence.
        Returns (success, message).
        """
        cfg = self.get_infrastructure_settings()
        mode = str(cfg.get("mode") or "local").strip().lower()
        if mode == "vps":
            new_dsn = str(cfg.get("vps_db_dsn") or "").strip()
            if not new_dsn:
                return (
                    False,
                    "VPS DSN порожній — заповніть поле VPS БД (DSN) та збережіть ще раз.",
                )
        else:
            new_dsn = str(cfg.get("local_db_dsn") or "").strip()
            if not new_dsn:
                return (
                    False,
                    "Локальний DSN порожній — заповніть поле Локальна БД (DSN) та збережіть ще раз.",
                )

        if new_dsn == str(self._pg_dsn or "").strip():
            return (
                True,
                f"Вже підключено до {'VPS' if mode == 'vps' else 'локальної'} бази. Зміни не потрібні.",
            )

        # Try connecting to new DSN before switching
        try:
            test_conn = psycopg.connect(new_dsn, autocommit=True, row_factory=dict_row)
            test_conn.close()
        except Exception as exc:
            return False, f"Не вдалося підключитися до нової бази: {exc}"

        # Close current connection(s) and switch
        self._evict_general_connections()
        self._pg_dsn = new_dsn

        # Persist to .env file so it survives restart
        try:
            env_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".env")
            lines: list[str] = []
            if os.path.exists(env_path):
                with open(env_path, "r", encoding="utf-8") as f:
                    lines = f.readlines()
            # Replace or append CATMAN_DATABASE_URL
            key_found = False
            new_line = f"CATMAN_DATABASE_URL={new_dsn}\n"
            for i, line in enumerate(lines):
                if (
                    line.strip().startswith("CATMAN_DATABASE_URL=")
                    or line.strip().startswith("DATABASE_URL=")
                    or line.strip().startswith("POSTGRES_DSN=")
                ):
                    if not key_found:
                        lines[i] = new_line
                        key_found = True
                    else:
                        lines[i] = ""  # remove duplicates
            if not key_found:
                lines.append(new_line)
            with open(env_path, "w", encoding="utf-8") as f:
                f.writelines(lines)
        except Exception as exc:
            logger.warning("apply_infrastructure_switch: could not write .env: %s", exc)

        label = "VPS" if mode == "vps" else "Локальна"
        return True, f"Підключено до {label} бази. DSN збережено в .env."

    # ----------------- setup wizard (bootstrap) -----------------
    def save_setup(self, payload: dict) -> bool:
        """
        Called from AuthScreen setup flow.
        Minimal implementation: ensure company exists, ensure at least one manager exists.
        """
        try:
            if not isinstance(payload, dict):
                return False

            if not self._use_postgres():
                # If DATABASE_URL not configured, do not hang the UI here.
                with contextlib.suppress(Exception):
                    logger.error(
                        "save_setup skipped: DATABASE_URL not set (payload role=%s)",
                        (payload or {}).get("role"),
                    )
                return False

            role_raw = str(payload.get("role") or "").strip()
            role_slug = self._normalize_role(role_raw) or "manager"
            is_superadmin = role_slug == "superadmin"

            company_name = str(
                payload.get("company") or payload.get("company_name") or ""
            ).strip()
            if is_superadmin and not company_name:
                company_name = "CatMan"
            if not company_name:
                return False

            manager_name = (
                str(
                    payload.get("manager")
                    or payload.get("manager_name")
                    or payload.get("full_name")
                    or ""
                ).strip()
                or "Користувач"
            )
            email = str(payload.get("email") or "").strip().lower()
            phone = str(payload.get("phone") or "").strip()
            password = str(payload.get("password") or "")

            if not email or not phone or not password:
                return False

            logger.info(
                "save_setup:start company=%s role=%s email=%s phone=%s",
                company_name,
                role_slug,
                email,
                phone,
            )

            cid = self._get_company_id_by_name(company_name) or self.create_company(
                company_name,
                storage_mode="local" if payload.get("storage_mode") == "local" else "vps",
            )

            # Ensure at least one region exists.
            with contextlib.suppress(Exception):
                if not self.get_company_regions(cid):
                    self.create_region_with_defaults(cid, "Default")

            # If manager exists -> ok
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM public.managers WHERE company_id=%s AND (email=%s OR phone=%s) LIMIT 1",
                    (cid, email, phone),
                )
                row = cur.fetchone()
            if row and row.get("id"):
                logger.info("save_setup:manager_exists id=%s", row.get("id"))
                return True

            self.create_manager(
                {
                    "company_id": cid,
                    "full_name": manager_name,
                    "email": email,
                    "phone": phone,
                    "password": password,
                    "role": role_slug,
                    # Registration should create a pending request (except superadmin bootstrap).
                    "is_approved": bool(is_superadmin),
                }
            )
            logger.info("save_setup:created company_id=%s", cid)
            if not is_superadmin:
                with contextlib.suppress(Exception):
                    self._notify_new_registration(company_name, manager_name, email)
            return True
        except Exception:
            logger.exception("save_setup failed")
            return False

    def save_individual_setup(self, payload: dict) -> tuple[bool, str]:
        """
        Self-registration for a solo "Індивідуал" account (no company): a
        de-facto one-person company (account_kind='individual', see
        create_company) with a single, immediately-approved admin manager —
        there's no admin to wait on, so unlike save_setup() this never
        creates a pending request.

        Returns (ok, error_message). error_message is empty on success and
        is meant to be shown to the user directly (e.g. duplicate email).
        """
        try:
            if not isinstance(payload, dict):
                return False, "Внутрішня помилка"
            if not self._use_postgres():
                return False, "PostgreSQL вимкнено (немає DATABASE_URL)"

            full_name = str(payload.get("full_name") or "").strip()
            email = str(payload.get("email") or "").strip().lower()
            phone = str(payload.get("phone") or "").strip()
            password = str(payload.get("password") or "")
            storage_mode = "local" if payload.get("storage_mode") == "local" else "vps"

            if not full_name or not email or not phone or not password:
                return False, "Заповніть усі поля"

            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM public.managers WHERE account_kind='individual' "
                    "AND lower(trim(email))=lower(trim(%s)) LIMIT 1",
                    (email,),
                )
                if cur.fetchone():
                    return False, "Індивідуальний акаунт з таким e-mail вже існує"

            # Display-only label for superadmin's company list — never looked
            # up by name (individuals are excluded from _get_company_id_by_name,
            # login resolves by email — see check_auth's empty-company branch).
            company_label = f"{full_name} — {email}"
            cid = self.create_company(
                company_label, account_kind="individual", storage_mode=storage_mode
            )
            # Індивідуал = рівно 1 користувач за визначенням — без цього
            # ліміту admin_dashboard.py дозволив би йому самому додати ще
            # людей у свою "компанію на одного", оминаючи тарифи компанії.
            self.update_company_profile(cid, {"max_users": 1})
            mid = self.create_manager(
                {
                    "company_id": cid,
                    "full_name": full_name,
                    "email": email,
                    "phone": phone,
                    "password": password,
                    "role": "admin",
                    "is_approved": True,
                }
            )
            with contextlib.suppress(Exception):
                self.create_region_with_defaults(cid, "Default")
            logger.info(
                "save_individual_setup:created company_id=%s manager_id=%s storage_mode=%s",
                cid,
                mid,
                storage_mode,
            )
            return True, ""
        except Exception:
            logger.exception("save_individual_setup failed")
            return False, "Помилка при реєстрації"

    def save_region_price_setup(
        self,
        company_id: str,
        region_id: str,
        region_name: str | None = None,  # noqa: ARG002
        tiers_payload: list | None = None,
        *,
        prices: list | None = None,
        catalog_config: dict | None = None,
    ):
        """
        Legacy UI uses this method for two independent things:
        - Save region price tiers (tiers_payload/prices) into `region_price_tiers`
        - Save default catalog levels/config into `catalog_config` (catalog_config={"levels": [...]})

        Returns truthy value on success (id for tiers write, or True for config-only write).
        """
        if not self._use_postgres():
            payload = {
                "company_id": company_id,
                "region_id": region_id,
                "tiers": tiers_payload or prices or [],
            }
            if isinstance(catalog_config, dict):
                payload["catalog_config"] = catalog_config
            return self._post("/regions/price_setup", payload) or ""

        company_id = str(company_id or "").strip()
        region_id = str(region_id or "").strip()
        if not company_id or not region_id:
            return ""
        now = self._now_ts()

        # 1) catalog_config (default levels, etc.)
        if isinstance(catalog_config, dict):
            # Merge with existing config to avoid wiping other keys (nodes/use_products)
            existing = (
                self.get_company_catalog_config(company_id, region_id)
                if company_id and region_id
                else {}
            )
            merged = dict(existing or {})
            if "levels" in catalog_config and isinstance(
                catalog_config.get("levels"), list
            ):
                merged["levels"] = catalog_config.get("levels")
            for k in ("use_products", "nodes"):
                if k in catalog_config:
                    merged[k] = catalog_config.get(k)
            with self._pg().cursor() as cur:
                cur.execute(
                    "SELECT id FROM catalog_config WHERE company_id=%s AND region_id=%s LIMIT 1",
                    (company_id, region_id),
                )
                row = cur.fetchone()
                if row and row.get("id"):
                    cur.execute(
                        "UPDATE catalog_config SET config=%s::jsonb, updated_at=%s WHERE id=%s",
                        (psycopg.types.json.Jsonb(merged), now, str(row.get("id"))),
                    )
                else:
                    cfg_id = uuid.uuid4().hex
                    cur.execute(
                        """
                        INSERT INTO catalog_config (id, company_id, region_id, config, updated_at)
                        VALUES (%s,%s,%s,%s::jsonb,%s)
                        """,
                        (
                            cfg_id,
                            company_id,
                            region_id,
                            psycopg.types.json.Jsonb(merged),
                            now,
                        ),
                    )
            self._pulse(company_id, "catalog")

        # 2) region price tiers
        tiers = prices if isinstance(prices, list) else tiers_payload
        if tiers is None:
            # config-only path
            return True
        tiers = tiers if isinstance(tiers, list) else []
        # Preserve existing tier ids when user renames tiers:
        # products.sales_prices_json uses tier_id as foreign key for price values.
        existing_tiers = self.get_region_price_tiers(region_id) or []
        existing_by_name = {
            str(t.get("name") or "").strip().lower(): t.get("id")
            for t in (existing_tiers or [])
            if isinstance(t, dict) and (t.get("name") is not None) and t.get("id")
        }
        existing_by_idx = [
            str(t.get("id")).strip()
            for t in (existing_tiers or [])
            if isinstance(t, dict) and t.get("id")
        ]

        # Normalize tiers to always include stable `id` (needed by product sales pricing).
        norm_tiers = []
        for idx, t in enumerate(tiers or []):
            if not isinstance(t, dict):
                continue
            name = str(t.get("name") or "").strip()
            currency = str(t.get("currency") or "USD").upper()
            tid = t.get("id")
            if not tid:
                # Prefer matching by old name (deletions where remaining tiers keep same name).
                if name:
                    tid = existing_by_name.get(name.lower())
                # Fallback: preserve by index (renames).
                if not tid and idx < len(existing_by_idx):
                    tid = existing_by_idx[idx]
                # Final: deterministic id for new tier.
                if not tid:
                    seed = f"{region_id}:tier_idx:{idx}"
                    tid = uuid.uuid5(uuid.NAMESPACE_URL, seed).hex
            norm_tiers.append({**t, "id": str(tid), "name": name, "currency": currency})
        tiers = norm_tiers
        with self._pg().cursor() as cur:
            cur.execute(
                "SELECT id FROM region_price_tiers WHERE company_id=%s AND region_id=%s LIMIT 1",
                (company_id, region_id),
            )
            row = cur.fetchone()
            if row and row.get("id"):
                cur.execute(
                    "UPDATE region_price_tiers SET tiers=%s::jsonb, updated_at=%s WHERE id=%s",
                    (psycopg.types.json.Jsonb(tiers), now, str(row["id"])),
                )
                self._pulse(company_id, "pricing")
                return str(row["id"])
            pid = uuid.uuid4().hex
            cur.execute(
                "INSERT INTO region_price_tiers (id, company_id, region_id, tiers, updated_at) VALUES (%s,%s,%s,%s::jsonb,%s)",
                (pid, company_id, region_id, psycopg.types.json.Jsonb(tiers), now),
            )
            self._pulse(company_id, "pricing")
            return pid

    def get_companies_sync_pulses(
        self,
        company_ids: list[str] | None = None,
        scopes: list[str] | None = None,
        force_refresh: bool | None = None,  # noqa: ARG002
    ):
        # Compatibility no-op: some builds poll this; do not crash if backend down.
        company_ids = company_ids or []
        out: dict[str, Any] = {}
        for cid in company_ids:
            out[cid] = {}
        try:
            if not company_ids:
                return out

            if self._use_postgres():
                scopes_list = [str(s) for s in (scopes or []) if str(s).strip()]
                params: list[Any] = []
                conds = []
                conds.append("company_id = ANY(%s)")
                params.append(company_ids)
                if scopes_list:
                    conds.append("scope = ANY(%s)")
                    params.append(scopes_list)
                where = " AND ".join(conds)
                q = f"SELECT company_id, scope, MAX(ts) AS ts FROM public.sync_pulses WHERE {where} GROUP BY company_id, scope"
                with self._general_pg().cursor() as cur:
                    cur.execute(q, params)
                    rows = cur.fetchall() or []
                for r in rows:
                    cid = str(r.get("company_id") or "")
                    sc = str(r.get("scope") or "")
                    ts = int(r.get("ts") or 0)
                    if cid and sc:
                        out.setdefault(cid, {})[sc] = ts
                return out

            scopes_q = ",".join(scopes or [])
            for cid in company_ids:
                out[cid] = (
                    self._get("/sync/pulses", {"company_id": cid, "scopes": scopes_q})
                    or {}
                )
            return out
        except Exception:
            logger.exception("get_companies_sync_pulses failed")
        return out

    def get_reference_data_pulse(self, company_id: str) -> int:
        """Returns max UNIX epoch (seconds) across updated_at of suppliers / products /
        packaging / categories for the given company.  Used by views to detect when
        reference-data tabs (Постачальники, Товари, Пакування, Категорії) changed so
        that other tabs can refresh their lookups without a full reload."""
        cid = str(company_id or "").strip()
        if not cid:
            return 0
        if not self._use_postgres():
            return 0
        try:
            with self._pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT COALESCE(MAX(ts), 0) AS max_ts FROM (
                        SELECT COALESCE(MAX(EXTRACT(EPOCH FROM updated_at)::bigint), 0) AS ts
                          FROM suppliers WHERE company_id = %s
                        UNION ALL
                        SELECT COALESCE(MAX(EXTRACT(EPOCH FROM updated_at)::bigint), 0)
                          FROM products WHERE company_id = %s
                        UNION ALL
                        SELECT COALESCE(MAX(EXTRACT(EPOCH FROM updated_at)::bigint), 0)
                          FROM packaging WHERE company_id = %s
                        UNION ALL
                        SELECT COALESCE(MAX(EXTRACT(EPOCH FROM updated_at)::bigint), 0)
                          FROM categories WHERE company_id = %s
                    ) _ref_sub
                    """,
                    (cid, cid, cid, cid),
                )
                row = cur.fetchone()
                return int((row or {}).get("max_ts") or 0)
        except Exception:
            return 0

    def invalidate_scope_cache(
        self, company_id: str, scope: str
    ) -> None:  # noqa: ARG002
        # Cache layer is not implemented in direct Postgres mode yet.
        return None

    # ------------------------------------------------------------------ #
    #  User Files — per manager per region file storage                  #
    # ------------------------------------------------------------------ #

    def _ensure_user_files_tables(self):
        with self._general_pg().cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.user_file_groups (
                    id          character varying NOT NULL,
                    company_id  character varying NOT NULL,
                    manager_id  character varying NOT NULL,
                    region_id   character varying NOT NULL DEFAULT '',
                    name        character varying(200) NOT NULL,
                    parent_id   character varying NULL,
                    sort_order  integer NOT NULL DEFAULT 0,
                    created_at  timestamp without time zone NOT NULL,
                    updated_at  timestamp without time zone NOT NULL,
                    PRIMARY KEY (id)
                )
                """)
            # Migrate: add parent_id if missing (existing installs)
            cur.execute("""
                ALTER TABLE public.user_file_groups
                    ADD COLUMN IF NOT EXISTS parent_id character varying NULL
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_ufg_manager ON public.user_file_groups (company_id, manager_id, region_id)"
            )
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_ufg_parent ON public.user_file_groups (parent_id)"
            )
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.user_files (
                    id                character varying NOT NULL,
                    group_id          character varying NOT NULL,
                    company_id        character varying NOT NULL,
                    manager_id        character varying NOT NULL,
                    region_id         character varying NOT NULL DEFAULT '',
                    original_filename character varying(500) NOT NULL,
                    file_size         bigint NOT NULL DEFAULT 0,
                    mime_type         character varying(200) NOT NULL DEFAULT '',
                    file_data         bytea NOT NULL,
                    created_at        timestamp without time zone NOT NULL,
                    updated_at        timestamp without time zone NOT NULL,
                    PRIMARY KEY (id)
                )
                """)
            cur.execute(
                "CREATE INDEX IF NOT EXISTS idx_uf_group ON public.user_files (group_id)"
            )
        self._general_pg().commit()

    def get_user_file_groups(
        self, company_id: str, manager_id: str, region_id: str
    ) -> list[dict]:
        """Return all folders for manager. region_id='' means all regions (no filter)."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            self._ensure_user_files_tables()
            with self._general_pg().cursor() as cur:
                if str(region_id or "") == "":
                    cur.execute(
                        """
                        SELECT id, name, parent_id, region_id, sort_order, created_at, updated_at
                        FROM public.user_file_groups
                        WHERE company_id=%s AND manager_id=%s
                        ORDER BY region_id ASC, sort_order ASC, created_at ASC
                        """,
                        (str(company_id), str(manager_id)),
                    )
                else:
                    cur.execute(
                        """
                        SELECT id, name, parent_id, region_id, sort_order, created_at, updated_at
                        FROM public.user_file_groups
                        WHERE company_id=%s AND manager_id=%s AND region_id=%s
                        ORDER BY sort_order ASC, created_at ASC
                        """,
                        (str(company_id), str(manager_id), str(region_id)),
                    )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def create_user_file_group(
        self,
        company_id: str,
        manager_id: str,
        region_id: str,
        name: str,
        parent_id: str | None = None,
    ) -> str | None:
        import uuid as _uuid

        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            self._ensure_user_files_tables()
            now = self._now_ts()
            gid = f"ufg_{_uuid.uuid4().hex}"
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.user_file_groups
                        (id, company_id, manager_id, region_id, name, parent_id, sort_order, created_at, updated_at)
                    VALUES (%s, %s, %s, %s, %s, %s, 0, %s, %s)
                    """,
                    (
                        gid,
                        str(company_id),
                        str(manager_id),
                        str(region_id or ""),
                        str(name),
                        str(parent_id) if parent_id else None,
                        now,
                        now,
                    ),
                )
            self._general_pg().commit()
            return gid
        return None

    def rename_user_file_group(self, group_id: str, name: str) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.user_file_groups SET name=%s, updated_at=%s WHERE id=%s",
                    (str(name), now, str(group_id)),
                )
            self._general_pg().commit()
            return True
        return False

    def delete_user_file_group(self, group_id: str) -> bool:
        """Delete folder and all its descendants (files + subfolders) recursively."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                # Collect all descendant folder ids via recursive CTE
                cur.execute(
                    """
                    WITH RECURSIVE sub AS (
                        SELECT id FROM public.user_file_groups WHERE id=%s
                        UNION ALL
                        SELECT g.id FROM public.user_file_groups g
                        INNER JOIN sub ON g.parent_id = sub.id
                    )
                    SELECT id FROM sub
                    """,
                    (str(group_id),),
                )
                all_ids = [
                    r["id"] if isinstance(r, dict) else r[0]
                    for r in (cur.fetchall() or [])
                ]
                if not all_ids:
                    return False
                for fid in all_ids:
                    cur.execute(
                        "DELETE FROM public.user_files WHERE group_id=%s", (str(fid),)
                    )
                for fid in reversed(all_ids):  # children first
                    cur.execute(
                        "DELETE FROM public.user_file_groups WHERE id=%s", (str(fid),)
                    )
            self._general_pg().commit()
            return True
        return False

    def move_user_file(self, file_id: str, new_group_id: str) -> bool:
        """Move a file to a different folder."""
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.user_files SET group_id=%s, updated_at=%s WHERE id=%s",
                    (str(new_group_id), now, str(file_id)),
                )
            self._general_pg().commit()
            return True
        return False

    def get_user_files_meta(self, group_id: str) -> list[dict]:
        """Return file metadata (no file_data) for a group."""
        if not self._use_postgres():
            return []
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    SELECT id, original_filename, file_size, mime_type, created_at
                    FROM public.user_files
                    WHERE group_id=%s
                    ORDER BY created_at ASC
                    """,
                    (str(group_id),),
                )
                return [dict(r) for r in (cur.fetchall() or []) if isinstance(r, dict)]
        return []

    def upload_user_file(
        self,
        group_id: str,
        company_id: str,
        manager_id: str,
        region_id: str,
        filename: str,
        file_data: bytes,
        mime_type: str = "",
    ) -> str | None:
        import uuid as _uuid

        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            self._ensure_user_files_tables()
            now = self._now_ts()
            fid = f"uf_{_uuid.uuid4().hex}"
            with self._general_pg().cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO public.user_files
                        (id, group_id, company_id, manager_id, region_id,
                         original_filename, file_size, mime_type, file_data,
                         created_at, updated_at)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """,
                    (
                        fid,
                        str(group_id),
                        str(company_id),
                        str(manager_id),
                        str(region_id or ""),
                        str(filename),
                        len(file_data),
                        str(mime_type),
                        file_data,
                        now,
                        now,
                    ),
                )
            self._general_pg().commit()
            return fid
        return None

    def get_user_file_data(self, file_id: str) -> bytes | None:
        if not self._use_postgres():
            return None
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "SELECT file_data FROM public.user_files WHERE id=%s LIMIT 1",
                    (str(file_id),),
                )
                row = cur.fetchone()
                if row:
                    data = row.get("file_data") if isinstance(row, dict) else None
                    return bytes(data) if data is not None else None
        return None

    def delete_user_file(self, file_id: str) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "DELETE FROM public.user_files WHERE id=%s", (str(file_id),)
                )
            self._general_pg().commit()
            return True
        return False

    def rename_user_file(self, file_id: str, name: str) -> bool:
        if not self._use_postgres():
            return False
        with contextlib.suppress(Exception):
            now = self._now_ts()
            with self._general_pg().cursor() as cur:
                cur.execute(
                    "UPDATE public.user_files SET original_filename=%s, updated_at=%s WHERE id=%s",
                    (str(name), now, str(file_id)),
                )
            self._general_pg().commit()
            return True
        return False

    # ----------------- safe fallback -----------------
    def __getattr__(self, name: str):
        def _missing(*args, **kwargs):
            with contextlib.suppress(Exception):
                logger.error("Missing DataManager method: %s", name)
            n = (name or "").lower()
            if n.startswith(("get_", "list_", "search_")):
                return []
            if n.startswith(("is_", "has_", "can_", "exists_", "name_exists")):
                return False
            if n.startswith(("create_", "find_or_create_", "save_")):
                return ""
            if n.startswith(
                (
                    "add_",
                    "update_",
                    "delete_",
                    "set_",
                    "replace_",
                    "sync_",
                    "acquire_",
                    "release_",
                    "heartbeat_",
                )
            ):
                return False
            return None

        return _missing
